//! Phase 55-72 + Phase D native method registrations.

use std::sync::atomic::{fence, Ordering};

use rustjvm_types::ClassId;
use rustjvm_types::error::{MethodCallFailed, MethodCallResult, RuntimeError};
use rustjvm_native_api::{NativeContext, NativeMethodRegistry};
use rustjvm_types::{ObjectRef, Value};

use crate::{native_noop, native_noop_with_this, obj_arg, alloc_concurrent_synthetic};
use crate::{FUT_FIELD_RESULT, FUT_FIELD_DONE, BI_FIELD_VALUE, BI_FIELD_SIGNUM};
use crate::{native_cf_then_apply, native_cf_then_accept};

// Helpers defined in lib.rs that we need
use crate::normalize_charset_name;
use crate::bi_alloc;
use crate::bi_read;
use crate::{hmac_sha256, hmac_sha384, hmac_sha512, hmac_sha1, hmac_md5};
#[cfg(feature = "legacy-synthetic-crypto")]
use crate::crypto::crypto_impl;

// Re-use register functions from other modules (already pub(crate))
use crate::lang_invoke::{register_p60_callsite, register_p63_method_handles_lookup, register_p65_method_handles_extra, register_p68_invoke_extras};
use crate::lang_misc::register_p60_record;
// register_javax_annotation removed (was Spring Boot stub)

pub(crate) fn register_phase55_natives(registry: &mut NativeMethodRegistry) {
    register_phase55_charset(registry);
    register_phase55_executors(registry);
    register_phase55_reflect(registry);
    register_phase55_collection_extras(registry);
}

// ---------------------------------------------------------------------------
// WP0.2 — ObjectStreamClass native-method group.
// ---------------------------------------------------------------------------
//
// The roadmap's WP0.2 scope put the `objectstreamclass_natives` entry
// point in this file. The actual registrations live in
// `crate::serialization` (alongside ObjectOutputStream / ObjectInputStream
// which share helpers and wire-format constants) — this forwarder exists
// so the roadmap's anchored grep for `objectstreamclass_natives` resolves
// to real code, and so any future caller wanting "just the OSC natives
// without the I/O-stream natives" has a single entry point.
//
// Callers must still go through `register_serialization_natives` in
// normal registry bring-up to get the full set (OOS + OIS + OSC +
// OSField + exceptions). This function is a narrower subset intended
// for future uses that register natives in sharded groups.
#[allow(dead_code)]
#[cfg(feature = "experimental-serialization")]
pub(crate) fn objectstreamclass_natives(registry: &mut NativeMethodRegistry) {
    crate::serialization::register_object_stream_class_for_phases_late(registry);
}

/// Stub when the `experimental-serialization` feature is not enabled —
/// the OSC natives live with the rest of the serialization surface.
#[allow(dead_code)]
#[cfg(not(feature = "experimental-serialization"))]
pub(crate) fn objectstreamclass_natives(_registry: &mut NativeMethodRegistry) {}

// ---------------------------------------------------------------------------
// WP1.2 — Unsafe full coverage sharded-registration entry point.
// ---------------------------------------------------------------------------
//
// Mirrors the `objectstreamclass_natives` forwarder above — the real
// registrations happen inside `register_essential_natives` in `lib.rs`
// (which calls `unsafe_natives::register_unsafe_wp1_2` after the
// baseline Unsafe set). This entry point lets future callers that
// want *just* the WP1.2 delta (e.g. an agent running under a test
// harness that builds a custom registry) pull it in without paying
// for the rest of `register_essential_natives`.
//
// Ordering hazard: WP1.2 overwrites a few stubs from `lib.rs`
// (freeMemory, defineClass, staticFieldBase). A caller using this
// entry point MUST install the baseline registrations first, then
// call this — same order as `register_essential_natives`.
#[allow(dead_code)]
pub(crate) fn unsafe_wp1_2_natives(registry: &mut NativeMethodRegistry) {
    crate::unsafe_natives::register_unsafe_wp1_2(registry);
}

// ---------------------------------------------------------------------------
// java.nio.charset — Charset, StandardCharsets
// ---------------------------------------------------------------------------
pub(crate) fn register_phase55_charset(r: &mut NativeMethodRegistry) {
    // Charset = 1-field synthetic (name=0)
    let cs = "java/nio/charset/Charset";
    r.register(
        cs,
        "forName",
        "(Ljava/lang/String;)Ljava/nio/charset/Charset;",
        |ctx, args| {
            let name_ref = obj_arg(args, 0)?;
            let raw_name = ctx.read_string(name_ref).unwrap_or_default();
            let normalized = normalize_charset_name(&raw_name);
            if normalized.is_empty() {
                return Err(RuntimeError::IllegalArgumentException {
                    message: format!("Unsupported charset: {}", raw_name),
                }
                .into());
            }
            let obj = alloc_concurrent_synthetic(ctx, "java/nio/charset/Charset", 1);
            let canon = ctx.create_string(&normalized);
            ctx.set_field(obj, 0, Value::Object(Some(canon)));
            Ok(Some(Value::Object(Some(obj))))
        },
    );
    r.register(cs, "name", "()Ljava/lang/String;", |ctx, args| {
        let this = obj_arg(args, 0)?;
        Ok(Some(ctx.get_field(this, 0)))
    });
    r.register(cs, "displayName", "()Ljava/lang/String;", |ctx, args| {
        let this = obj_arg(args, 0)?;
        Ok(Some(ctx.get_field(this, 0)))
    });
    r.register(
        cs,
        "defaultCharset",
        "()Ljava/nio/charset/Charset;",
        |ctx, _args| {
            let obj = alloc_concurrent_synthetic(ctx, "java/nio/charset/Charset", 1);
            let name = ctx.create_string("UTF-8");
            ctx.set_field(obj, 0, Value::Object(Some(name)));
            Ok(Some(Value::Object(Some(obj))))
        },
    );
    r.register(cs, "isSupported", "(Ljava/lang/String;)Z", |ctx, args| {
        let name_ref = obj_arg(args, 0)?;
        let name = ctx.read_string(name_ref).unwrap_or_default();
        let supported = !normalize_charset_name(&name).is_empty();
        Ok(Some(Value::Int(if supported { 1 } else { 0 })))
    });
    r.register(cs, "toString", "()Ljava/lang/String;", |ctx, args| {
        let this = obj_arg(args, 0)?;
        Ok(Some(ctx.get_field(this, 0)))
    });
    r.register(cs, "equals", "(Ljava/lang/Object;)Z", |ctx, args| {
        let this = obj_arg(args, 0)?;
        if let Value::Object(Some(other)) = args[1] {
            let n1 = if let Value::Object(Some(s)) = ctx.get_field(this, 0) {
                ctx.read_string(s).unwrap_or_default()
            } else {
                String::new()
            };
            let n2 = if let Value::Object(Some(s)) = ctx.get_field(other, 0) {
                ctx.read_string(s).unwrap_or_default()
            } else {
                String::new()
            };
            Ok(Some(Value::Int(if n1.eq_ignore_ascii_case(&n2) {
                1
            } else {
                0
            })))
        } else {
            Ok(Some(Value::Int(0)))
        }
    });
    r.register(cs, "hashCode", "()I", |ctx, args| {
        let this = obj_arg(args, 0)?;
        if let Value::Object(Some(s)) = ctx.get_field(this, 0) {
            let name = ctx.read_string(s).unwrap_or_default().to_lowercase();
            let mut h: i32 = 0;
            for b in name.bytes() {
                h = h.wrapping_mul(31).wrapping_add(b as i32);
            }
            Ok(Some(Value::Int(h)))
        } else {
            Ok(Some(Value::Int(0)))
        }
    });

    // StandardCharsets — static fields returning Charset objects
    let sc = "java/nio/charset/StandardCharsets";
    r.register(sc, "UTF_8", "Ljava/nio/charset/Charset;", |ctx, _args| {
        let obj = alloc_concurrent_synthetic(ctx, "java/nio/charset/Charset", 1);
        let name = ctx.create_string("UTF-8");
        ctx.set_field(obj, 0, Value::Object(Some(name)));
        Ok(Some(Value::Object(Some(obj))))
    });
    r.register(
        sc,
        "US_ASCII",
        "Ljava/nio/charset/Charset;",
        |ctx, _args| {
            let obj = alloc_concurrent_synthetic(ctx, "java/nio/charset/Charset", 1);
            let name = ctx.create_string("US-ASCII");
            ctx.set_field(obj, 0, Value::Object(Some(name)));
            Ok(Some(Value::Object(Some(obj))))
        },
    );
    r.register(
        sc,
        "ISO_8859_1",
        "Ljava/nio/charset/Charset;",
        |ctx, _args| {
            let obj = alloc_concurrent_synthetic(ctx, "java/nio/charset/Charset", 1);
            let name = ctx.create_string("ISO-8859-1");
            ctx.set_field(obj, 0, Value::Object(Some(name)));
            Ok(Some(Value::Object(Some(obj))))
        },
    );
    r.register(sc, "UTF_16", "Ljava/nio/charset/Charset;", |ctx, _args| {
        let obj = alloc_concurrent_synthetic(ctx, "java/nio/charset/Charset", 1);
        let name = ctx.create_string("UTF-16");
        ctx.set_field(obj, 0, Value::Object(Some(name)));
        Ok(Some(Value::Object(Some(obj))))
    });
    r.register(
        sc,
        "UTF_16BE",
        "Ljava/nio/charset/Charset;",
        |ctx, _args| {
            let obj = alloc_concurrent_synthetic(ctx, "java/nio/charset/Charset", 1);
            let name = ctx.create_string("UTF-16BE");
            ctx.set_field(obj, 0, Value::Object(Some(name)));
            Ok(Some(Value::Object(Some(obj))))
        },
    );
    r.register(
        sc,
        "UTF_16LE",
        "Ljava/nio/charset/Charset;",
        |ctx, _args| {
            let obj = alloc_concurrent_synthetic(ctx, "java/nio/charset/Charset", 1);
            let name = ctx.create_string("UTF-16LE");
            ctx.set_field(obj, 0, Value::Object(Some(name)));
            Ok(Some(Value::Object(Some(obj))))
        },
    );
}

// ---------------------------------------------------------------------------
// java.util.concurrent — Executors, Future, Callable, ExecutorService
// ExecutorService = 4-field synthetic:
//   0 = shutdown (Int: 0=running, 1=shutdown)
//   1 = pool_size (Int)
//   2 = task_queue (Reference[] array of Callable/Runnable objects)
//   3 = task_count (Int: number of pending tasks in queue)
// Future = 4-field synthetic:
//   0 = result (Object)
//   1 = done (Int: 0=pending, 1=done)
//   2 = cancelled (Int: 0=no, 1=yes)
//   3 = task (Object: the original Callable/Runnable for lazy execution)
// CompletableFuture = 3-field: result=0, done=1, exception=2
// ---------------------------------------------------------------------------
pub(crate) fn register_phase55_executors(r: &mut NativeMethodRegistry) {
    // --- Callable<V> interface ---
    let callable = "java/util/concurrent/Callable";
    r.register(callable, "call", "()Ljava/lang/Object;", |ctx, args| {
        let this = obj_arg(args, 0)?;
        ctx.invoke_virtual(this, "call", "()Ljava/lang/Object;", &[])
    });

    // --- Future<V> — 4-field synthetic (result=0, done=1, cancelled=2, task=3) ---
    let future = "java/util/concurrent/Future";

    // get() — lazy execution: if not done and not cancelled, execute the stored task
    r.register(future, "get", "()Ljava/lang/Object;", |ctx, args| {
        let this = obj_arg(args, 0)?;
        let cancelled = ctx.get_field(this, 2).as_int().unwrap_or(0);
        if cancelled != 0 {
            return Err(RuntimeError::IllegalStateException {
                message: "Task was cancelled".into(),
            }.into());
        }
        let done = ctx.get_field(this, 1).as_int().unwrap_or(0);
        if done == 0 {
            // Lazy execution: run the stored task now
            if let Value::Object(Some(task)) = ctx.get_field(this, 3) {
                // Try Callable.call() first, fall back to Runnable.run()
                let result = ctx.invoke_virtual(task, "call", "()Ljava/lang/Object;", &[]);
                match result {
                    Ok(val) => {
                        ctx.set_field(this, 0, val.unwrap_or(Value::Object(None)));
                    }
                    Err(_) => {
                        // Might be a Runnable, not a Callable
                        let _ = ctx.invoke_virtual(task, "run", "()V", &[]);
                        ctx.set_field(this, 0, Value::Object(None));
                    }
                }
            }
            ctx.set_field(this, 1, Value::Int(1)); // mark done
        }
        Ok(Some(ctx.get_field(this, 0)))
    });
    r.register(future, "get", "(JLjava/util/concurrent/TimeUnit;)Ljava/lang/Object;", |ctx, args| {
        let this = obj_arg(args, 0)?;
        let cancelled = ctx.get_field(this, 2).as_int().unwrap_or(0);
        if cancelled != 0 {
            return Err(RuntimeError::IllegalStateException {
                message: "Task was cancelled".into(),
            }.into());
        }
        let done = ctx.get_field(this, 1).as_int().unwrap_or(0);
        if done == 0 {
            if let Value::Object(Some(task)) = ctx.get_field(this, 3) {
                let result = ctx.invoke_virtual(task, "call", "()Ljava/lang/Object;", &[]);
                match result {
                    Ok(val) => ctx.set_field(this, 0, val.unwrap_or(Value::Object(None))),
                    Err(_) => {
                        let _ = ctx.invoke_virtual(task, "run", "()V", &[]);
                        ctx.set_field(this, 0, Value::Object(None));
                    }
                }
            }
            ctx.set_field(this, 1, Value::Int(1));
        }
        Ok(Some(ctx.get_field(this, 0)))
    });
    r.register(future, "isDone", "()Z", |ctx, args| {
        let this = obj_arg(args, 0)?;
        let done = ctx.get_field(this, 1).as_int().unwrap_or(0);
        let cancelled = ctx.get_field(this, 2).as_int().unwrap_or(0);
        Ok(Some(Value::Int(if done != 0 || cancelled != 0 { 1 } else { 0 })))
    });
    r.register(future, "isCancelled", "()Z", |ctx, args| {
        let this = obj_arg(args, 0)?;
        Ok(Some(ctx.get_field(this, 2)))
    });
    r.register(future, "cancel", "(Z)Z", |ctx, args| {
        let this = obj_arg(args, 0)?;
        let done = ctx.get_field(this, 1).as_int().unwrap_or(0);
        if done != 0 {
            // Already completed — cannot cancel
            return Ok(Some(Value::Int(0)));
        }
        let already_cancelled = ctx.get_field(this, 2).as_int().unwrap_or(0);
        if already_cancelled != 0 {
            return Ok(Some(Value::Int(1))); // already cancelled
        }
        // Cancel the task
        ctx.set_field(this, 2, Value::Int(1));
        ctx.set_field(this, 1, Value::Int(1)); // mark done (cancelled is a terminal state)
        Ok(Some(Value::Int(1)))
    });

    // --- CompletableFuture extra methods ---
    let cf = "java/util/concurrent/CompletableFuture";
    r.register(
        cf,
        "supplyAsync",
        "(Ljava/util/function/Supplier;)Ljava/util/concurrent/CompletableFuture;",
        |ctx, args| {
            let supplier = obj_arg(args, 0)?;
            let result = ctx.invoke_virtual(supplier, "get", "()Ljava/lang/Object;", &[]);
            let future =
                alloc_concurrent_synthetic(ctx, "java/util/concurrent/CompletableFuture", 3);
            match result {
                Ok(val) => {
                    ctx.set_field(future, 0, val.unwrap_or(Value::Object(None)));
                    ctx.set_field(future, 2, Value::Object(None));
                }
                Err(e) => {
                    ctx.set_field(future, 0, Value::Object(None));
                    let err_str = ctx.create_string(&format!("{:?}", e));
                    ctx.set_field(future, 2, Value::Object(Some(err_str)));
                }
            }
            ctx.set_field(future, 1, Value::Int(1));
            Ok(Some(Value::Object(Some(future))))
        },
    );
    r.register(
        cf,
        "supplyAsync",
        "(Ljava/util/function/Supplier;Ljava/util/concurrent/Executor;)Ljava/util/concurrent/CompletableFuture;",
        |ctx, args| {
            let supplier = obj_arg(args, 0)?;
            // Executor argument ignored — execute eagerly
            let result = ctx.invoke_virtual(supplier, "get", "()Ljava/lang/Object;", &[]);
            let future =
                alloc_concurrent_synthetic(ctx, "java/util/concurrent/CompletableFuture", 3);
            match result {
                Ok(val) => {
                    ctx.set_field(future, 0, val.unwrap_or(Value::Object(None)));
                    ctx.set_field(future, 2, Value::Object(None));
                }
                Err(e) => {
                    ctx.set_field(future, 0, Value::Object(None));
                    let err_str = ctx.create_string(&format!("{:?}", e));
                    ctx.set_field(future, 2, Value::Object(Some(err_str)));
                }
            }
            ctx.set_field(future, 1, Value::Int(1));
            Ok(Some(Value::Object(Some(future))))
        },
    );
    r.register(
        cf,
        "runAsync",
        "(Ljava/lang/Runnable;)Ljava/util/concurrent/CompletableFuture;",
        |ctx, args| {
            let runnable = obj_arg(args, 0)?;
            let result = ctx.invoke_virtual(runnable, "run", "()V", &[]);
            let future =
                alloc_concurrent_synthetic(ctx, "java/util/concurrent/CompletableFuture", 3);
            ctx.set_field(future, 0, Value::Object(None));
            ctx.set_field(future, 1, Value::Int(1));
            match result {
                Ok(_) => ctx.set_field(future, 2, Value::Object(None)),
                Err(e) => {
                    let err_str = ctx.create_string(&format!("{:?}", e));
                    ctx.set_field(future, 2, Value::Object(Some(err_str)));
                }
            }
            Ok(Some(Value::Object(Some(future))))
        },
    );
    r.register(
        cf,
        "runAsync",
        "(Ljava/lang/Runnable;Ljava/util/concurrent/Executor;)Ljava/util/concurrent/CompletableFuture;",
        |ctx, args| {
            let runnable = obj_arg(args, 0)?;
            let result = ctx.invoke_virtual(runnable, "run", "()V", &[]);
            let future =
                alloc_concurrent_synthetic(ctx, "java/util/concurrent/CompletableFuture", 3);
            ctx.set_field(future, 0, Value::Object(None));
            ctx.set_field(future, 1, Value::Int(1));
            match result {
                Ok(_) => ctx.set_field(future, 2, Value::Object(None)),
                Err(e) => {
                    let err_str = ctx.create_string(&format!("{:?}", e));
                    ctx.set_field(future, 2, Value::Object(Some(err_str)));
                }
            }
            Ok(Some(Value::Object(Some(future))))
        },
    );
    r.register(
        cf,
        "allOf",
        "([Ljava/util/concurrent/CompletableFuture;)Ljava/util/concurrent/CompletableFuture;",
        |ctx, args| {
            let future =
                alloc_concurrent_synthetic(ctx, "java/util/concurrent/CompletableFuture", 3);
            // Check if any constituent CF has an exception
            let mut has_exception = false;
            if let Some(Value::Object(Some(arr))) = args.first() {
                let len = ctx.array_length(*arr);
                for i in 0..len {
                    if let Value::Object(Some(cf_ref)) = ctx.get_array_element(*arr, i) {
                        if let Value::Object(Some(_)) = ctx.get_field(cf_ref, 2) {
                            has_exception = true;
                            break;
                        }
                    }
                }
            }
            ctx.set_field(future, 0, Value::Object(None));
            ctx.set_field(future, 1, Value::Int(1));
            if has_exception {
                let err = ctx.create_string("One or more CompletableFutures failed");
                ctx.set_field(future, 2, Value::Object(Some(err)));
            } else {
                ctx.set_field(future, 2, Value::Object(None));
            }
            Ok(Some(Value::Object(Some(future))))
        },
    );
    r.register(
        cf,
        "anyOf",
        "([Ljava/util/concurrent/CompletableFuture;)Ljava/util/concurrent/CompletableFuture;",
        |ctx, args| {
            let arr = obj_arg(args, 0)?;
            let len = ctx.array_length(arr);
            if len > 0 {
                // Return the result of the first completed CF
                let first = ctx.get_array_element(arr, 0);
                if let Value::Object(Some(cf_ref)) = first {
                    let result = ctx.get_field(cf_ref, 0);
                    let exc = ctx.get_field(cf_ref, 2);
                    let future = alloc_concurrent_synthetic(
                        ctx,
                        "java/util/concurrent/CompletableFuture",
                        3,
                    );
                    ctx.set_field(future, 0, result);
                    ctx.set_field(future, 1, Value::Int(1));
                    ctx.set_field(future, 2, exc);
                    return Ok(Some(Value::Object(Some(future))));
                }
            }
            let future =
                alloc_concurrent_synthetic(ctx, "java/util/concurrent/CompletableFuture", 3);
            ctx.set_field(future, 0, Value::Object(None));
            ctx.set_field(future, 1, Value::Int(1));
            ctx.set_field(future, 2, Value::Object(None));
            Ok(Some(Value::Object(Some(future))))
        },
    );
    r.register(
        cf,
        "completedFuture",
        "(Ljava/lang/Object;)Ljava/util/concurrent/CompletableFuture;",
        |ctx, args| {
            let value = args[0];
            let future =
                alloc_concurrent_synthetic(ctx, "java/util/concurrent/CompletableFuture", 3);
            ctx.set_field(future, 0, value);
            ctx.set_field(future, 1, Value::Int(1));
            ctx.set_field(future, 2, Value::Object(None));
            Ok(Some(Value::Object(Some(future))))
        },
    );
    r.register(
        cf,
        "failedFuture",
        "(Ljava/lang/Throwable;)Ljava/util/concurrent/CompletableFuture;",
        |ctx, args| {
            let exc = args[0];
            let future =
                alloc_concurrent_synthetic(ctx, "java/util/concurrent/CompletableFuture", 3);
            ctx.set_field(future, 0, Value::Object(None));
            ctx.set_field(future, 1, Value::Int(1));
            ctx.set_field(future, 2, exc); // store exception
            Ok(Some(Value::Object(Some(future))))
        },
    );
    // complete(value) — complete the CF with a value if not already done
    r.register(cf, "complete", "(Ljava/lang/Object;)Z", |ctx, args| {
        let this = obj_arg(args, 0)?;
        let done = ctx.get_field(this, 1).as_int().unwrap_or(0);
        if done != 0 {
            return Ok(Some(Value::Int(0))); // already completed
        }
        ctx.set_field(this, 0, args.get(1).copied().unwrap_or(Value::Object(None)));
        ctx.set_field(this, 1, Value::Int(1));
        ctx.set_field(this, 2, Value::Object(None));
        Ok(Some(Value::Int(1)))
    });
    // completeExceptionally(Throwable) — complete with exception
    r.register(cf, "completeExceptionally", "(Ljava/lang/Throwable;)Z", |ctx, args| {
        let this = obj_arg(args, 0)?;
        let done = ctx.get_field(this, 1).as_int().unwrap_or(0);
        if done != 0 {
            return Ok(Some(Value::Int(0)));
        }
        ctx.set_field(this, 0, Value::Object(None));
        ctx.set_field(this, 1, Value::Int(1));
        ctx.set_field(this, 2, args.get(1).copied().unwrap_or(Value::Object(None)));
        Ok(Some(Value::Int(1)))
    });
    // isCompletedExceptionally()
    r.register(cf, "isCompletedExceptionally", "()Z", |ctx, args| {
        let this = obj_arg(args, 0)?;
        let exc = ctx.get_field(this, 2);
        Ok(Some(Value::Int(if matches!(exc, Value::Object(Some(_))) { 1 } else { 0 })))
    });
    // thenCompose — chains a CompletableFuture-returning function
    r.register(
        cf,
        "thenCompose",
        "(Ljava/util/function/Function;)Ljava/util/concurrent/CompletableFuture;",
        |ctx, args| {
            let this = obj_arg(args, 0)?;
            let func = obj_arg(args, 1)?;
            // Check if this CF has an exception — propagate it
            if let Value::Object(Some(_)) = ctx.get_field(this, 2) {
                let new_cf = alloc_concurrent_synthetic(ctx, "java/util/concurrent/CompletableFuture", 3);
                ctx.set_field(new_cf, 0, Value::Object(None));
                ctx.set_field(new_cf, 1, Value::Int(1));
                ctx.set_field(new_cf, 2, ctx.get_field(this, 2));
                return Ok(Some(Value::Object(Some(new_cf))));
            }
            let val = ctx.get_field(this, 0);
            let result = ctx.invoke_virtual(func, "apply", "(Ljava/lang/Object;)Ljava/lang/Object;", &[val])?;
            // The result should be a CompletableFuture — return it directly
            Ok(result)
        },
    );
    // exceptionally — handle exceptions
    r.register(
        cf,
        "exceptionally",
        "(Ljava/util/function/Function;)Ljava/util/concurrent/CompletableFuture;",
        |ctx, args| {
            let this = obj_arg(args, 0)?;
            let func = obj_arg(args, 1)?;
            if let Value::Object(Some(exc)) = ctx.get_field(this, 2) {
                // Has exception — apply the handler
                let result = ctx.invoke_virtual(func, "apply", "(Ljava/lang/Object;)Ljava/lang/Object;", &[Value::Object(Some(exc))])?;
                let new_cf = alloc_concurrent_synthetic(ctx, "java/util/concurrent/CompletableFuture", 3);
                ctx.set_field(new_cf, 0, result.unwrap_or(Value::Object(None)));
                ctx.set_field(new_cf, 1, Value::Int(1));
                ctx.set_field(new_cf, 2, Value::Object(None));
                Ok(Some(Value::Object(Some(new_cf))))
            } else {
                // No exception — pass through
                Ok(Some(Value::Object(Some(this))))
            }
        },
    );
    // handle — BiFunction that gets both result and exception
    r.register(
        cf,
        "handle",
        "(Ljava/util/function/BiFunction;)Ljava/util/concurrent/CompletableFuture;",
        |ctx, args| {
            let this = obj_arg(args, 0)?;
            let func = obj_arg(args, 1)?;
            let val = ctx.get_field(this, 0);
            let exc = ctx.get_field(this, 2);
            let result = ctx.invoke_virtual(func, "apply", "(Ljava/lang/Object;Ljava/lang/Object;)Ljava/lang/Object;", &[val, exc])?;
            let new_cf = alloc_concurrent_synthetic(ctx, "java/util/concurrent/CompletableFuture", 3);
            ctx.set_field(new_cf, 0, result.unwrap_or(Value::Object(None)));
            ctx.set_field(new_cf, 1, Value::Int(1));
            ctx.set_field(new_cf, 2, Value::Object(None));
            Ok(Some(Value::Object(Some(new_cf))))
        },
    );
    // join() — same as get() but wraps in CompletionException
    r.register(cf, "join", "()Ljava/lang/Object;", |ctx, args| {
        let this = obj_arg(args, 0)?;
        if let Value::Object(Some(_)) = ctx.get_field(this, 2) {
            return Err(RuntimeError::IllegalStateException {
                message: "CompletableFuture completed exceptionally".into(),
            }.into());
        }
        Ok(Some(ctx.get_field(this, 0)))
    });
    // getNow(defaultValue) — return result if done, else default
    r.register(cf, "getNow", "(Ljava/lang/Object;)Ljava/lang/Object;", |ctx, args| {
        let this = obj_arg(args, 0)?;
        let done = ctx.get_field(this, 1).as_int().unwrap_or(0);
        if done != 0 {
            Ok(Some(ctx.get_field(this, 0)))
        } else {
            Ok(Some(args.get(1).copied().unwrap_or(Value::Object(None))))
        }
    });

    // --- Executors (static factory) ---
    let execs = "java/util/concurrent/Executors";
    // All executors return an ExecutorService with pool_size tracking
    r.register(
        execs,
        "newSingleThreadExecutor",
        "()Ljava/util/concurrent/ExecutorService;",
        |ctx, _args| {
            let es = alloc_concurrent_synthetic(ctx, "java/util/concurrent/ExecutorService", 4);
            ctx.set_field(es, 0, Value::Int(0)); // not shutdown
            ctx.set_field(es, 1, Value::Int(1)); // pool size = 1
            let queue = ctx.new_array(rustjvm_types::ArrayElementType::Reference, 64);
            ctx.set_field(es, 2, Value::Object(Some(queue)));
            ctx.set_field(es, 3, Value::Int(0)); // task count
            Ok(Some(Value::Object(Some(es))))
        },
    );
    r.register(
        execs,
        "newFixedThreadPool",
        "(I)Ljava/util/concurrent/ExecutorService;",
        |ctx, args| {
            let pool_size = args.first().and_then(|v| v.as_int()).unwrap_or(4);
            let es = alloc_concurrent_synthetic(ctx, "java/util/concurrent/ExecutorService", 4);
            ctx.set_field(es, 0, Value::Int(0));
            ctx.set_field(es, 1, Value::Int(pool_size));
            let queue = ctx.new_array(rustjvm_types::ArrayElementType::Reference, 64);
            ctx.set_field(es, 2, Value::Object(Some(queue)));
            ctx.set_field(es, 3, Value::Int(0));
            Ok(Some(Value::Object(Some(es))))
        },
    );
    r.register(
        execs,
        "newCachedThreadPool",
        "()Ljava/util/concurrent/ExecutorService;",
        |ctx, _args| {
            let es = alloc_concurrent_synthetic(ctx, "java/util/concurrent/ExecutorService", 4);
            ctx.set_field(es, 0, Value::Int(0));
            ctx.set_field(es, 1, Value::Int(i32::MAX)); // unbounded
            let queue = ctx.new_array(rustjvm_types::ArrayElementType::Reference, 64);
            ctx.set_field(es, 2, Value::Object(Some(queue)));
            ctx.set_field(es, 3, Value::Int(0));
            Ok(Some(Value::Object(Some(es))))
        },
    );
    r.register(
        execs,
        "newScheduledThreadPool",
        "(I)Ljava/util/concurrent/ScheduledExecutorService;",
        |ctx, args| {
            let pool_size = args.first().and_then(|v| v.as_int()).unwrap_or(1);
            let es =
                alloc_concurrent_synthetic(ctx, "java/util/concurrent/ScheduledExecutorService", 4);
            ctx.set_field(es, 0, Value::Int(0));
            ctx.set_field(es, 1, Value::Int(pool_size));
            let queue = ctx.new_array(rustjvm_types::ArrayElementType::Reference, 64);
            ctx.set_field(es, 2, Value::Object(Some(queue)));
            ctx.set_field(es, 3, Value::Int(0));
            Ok(Some(Value::Object(Some(es))))
        },
    );
    r.register(
        execs,
        "newVirtualThreadPerTaskExecutor",
        "()Ljava/util/concurrent/ExecutorService;",
        |ctx, _args| {
            let es = alloc_concurrent_synthetic(ctx, "java/util/concurrent/ExecutorService", 4);
            ctx.set_field(es, 0, Value::Int(0));
            ctx.set_field(es, 1, Value::Int(i32::MAX));
            let queue = ctx.new_array(rustjvm_types::ArrayElementType::Reference, 64);
            ctx.set_field(es, 2, Value::Object(Some(queue)));
            ctx.set_field(es, 3, Value::Int(0));
            Ok(Some(Value::Object(Some(es))))
        },
    );

    // --- ExecutorService ---
    let es = "java/util/concurrent/ExecutorService";
    r.register(es, "shutdown", "()V", |ctx, args| {
        let this = obj_arg(args, 0)?;
        ctx.set_field(this, 0, Value::Int(1));
        // Execute all pending tasks before shutdown
        let task_count = ctx.get_field(this, 3).as_int().unwrap_or(0);
        if task_count > 0 {
            if let Value::Object(Some(queue)) = ctx.get_field(this, 2) {
                for i in 0..(task_count as usize) {
                    if let Value::Object(Some(task)) = ctx.get_array_element(queue, i) {
                        let _: MethodCallResult = ctx.invoke_virtual(task, "call", "()Ljava/lang/Object;", &[])
                            .or_else(|_| {
                                ctx.invoke_virtual(task, "run", "()V", &[])?;
                                Ok(None)
                            });
                    }
                }
            }
            ctx.set_field(this, 3, Value::Int(0));
        }
        Ok(Some(Value::Object(None)))
    });
    r.register(es, "shutdownNow", "()Ljava/util/List;", |ctx, args| {
        let this = obj_arg(args, 0)?;
        ctx.set_field(this, 0, Value::Int(1));
        // Return list of pending (unexecuted) tasks
        let task_count = ctx.get_field(this, 3).as_int().unwrap_or(0) as usize;
        let pending = ctx.new_array(rustjvm_types::ArrayElementType::Reference, task_count);
        if task_count > 0 {
            if let Value::Object(Some(queue)) = ctx.get_field(this, 2) {
                for i in 0..task_count {
                    let task = ctx.get_array_element(queue, i);
                    ctx.set_array_element(pending, i, task);
                }
            }
        }
        ctx.set_field(this, 3, Value::Int(0));
        let list = alloc_concurrent_synthetic(ctx, "java/util/ArrayList", 2);
        ctx.set_field(list, 0, Value::Object(Some(pending)));
        ctx.set_field(list, 1, Value::Int(task_count as i32));
        Ok(Some(Value::Object(Some(list))))
    });
    r.register(es, "isShutdown", "()Z", |ctx, args| {
        let this = obj_arg(args, 0)?;
        Ok(Some(ctx.get_field(this, 0)))
    });
    r.register(es, "isTerminated", "()Z", |ctx, args| {
        let this = obj_arg(args, 0)?;
        let shutdown = ctx.get_field(this, 0).as_int().unwrap_or(0);
        let tasks = ctx.get_field(this, 3).as_int().unwrap_or(0);
        Ok(Some(Value::Int(if shutdown != 0 && tasks == 0 { 1 } else { 0 })))
    });
    r.register(
        es,
        "awaitTermination",
        "(JLjava/util/concurrent/TimeUnit;)Z",
        |ctx, args| {
            let this = obj_arg(args, 0)?;
            // Execute any pending tasks
            let task_count = ctx.get_field(this, 3).as_int().unwrap_or(0);
            if task_count > 0 {
                if let Value::Object(Some(queue)) = ctx.get_field(this, 2) {
                    for i in 0..(task_count as usize) {
                        if let Value::Object(Some(task)) = ctx.get_array_element(queue, i) {
                            let _: Result<Option<Value>, MethodCallFailed> = ctx.invoke_virtual(task, "call", "()Ljava/lang/Object;", &[])
                                .or_else(|_| {
                                    ctx.invoke_virtual(task, "run", "()V", &[])?;
                                    Ok(None)
                                });
                        }
                    }
                }
                ctx.set_field(this, 3, Value::Int(0));
            }
            Ok(Some(Value::Int(1)))
        },
    );
    r.register(
        es,
        "submit",
        "(Ljava/util/concurrent/Callable;)Ljava/util/concurrent/Future;",
        |ctx, args| {
            let this = obj_arg(args, 0)?;
            let callable = obj_arg(args, 1)?;
            let shutdown = ctx.get_field(this, 0).as_int().unwrap_or(0);
            if shutdown != 0 {
                return Err(RuntimeError::IllegalStateException {
                    message: "ExecutorService has been shut down".into(),
                }.into());
            }
            // Create a Future with the task stored for lazy execution
            let future = alloc_concurrent_synthetic(ctx, "java/util/concurrent/Future", 4);
            ctx.set_field(future, 0, Value::Object(None)); // result (not yet computed)
            ctx.set_field(future, 1, Value::Int(0)); // not done
            ctx.set_field(future, 2, Value::Int(0)); // not cancelled
            ctx.set_field(future, 3, Value::Object(Some(callable))); // store task
            // Also queue the task in the executor
            let task_count = ctx.get_field(this, 3).as_int().unwrap_or(0) as usize;
            if let Value::Object(Some(queue)) = ctx.get_field(this, 2) {
                let queue_len = ctx.array_length(queue);
                if task_count < queue_len {
                    ctx.set_array_element(queue, task_count, Value::Object(Some(callable)));
                    ctx.set_field(this, 3, Value::Int((task_count + 1) as i32));
                }
            }
            Ok(Some(Value::Object(Some(future))))
        },
    );
    r.register(
        es,
        "submit",
        "(Ljava/lang/Runnable;)Ljava/util/concurrent/Future;",
        |ctx, args| {
            let this = obj_arg(args, 0)?;
            let runnable = obj_arg(args, 1)?;
            let shutdown = ctx.get_field(this, 0).as_int().unwrap_or(0);
            if shutdown != 0 {
                return Err(RuntimeError::IllegalStateException {
                    message: "ExecutorService has been shut down".into(),
                }.into());
            }
            let future = alloc_concurrent_synthetic(ctx, "java/util/concurrent/Future", 4);
            ctx.set_field(future, 0, Value::Object(None));
            ctx.set_field(future, 1, Value::Int(0));
            ctx.set_field(future, 2, Value::Int(0));
            ctx.set_field(future, 3, Value::Object(Some(runnable)));
            let task_count = ctx.get_field(this, 3).as_int().unwrap_or(0) as usize;
            if let Value::Object(Some(queue)) = ctx.get_field(this, 2) {
                let queue_len = ctx.array_length(queue);
                if task_count < queue_len {
                    ctx.set_array_element(queue, task_count, Value::Object(Some(runnable)));
                    ctx.set_field(this, 3, Value::Int((task_count + 1) as i32));
                }
            }
            Ok(Some(Value::Object(Some(future))))
        },
    );
    r.register(es, "execute", "(Ljava/lang/Runnable;)V", |ctx, args| {
        let this = obj_arg(args, 0)?;
        let runnable = obj_arg(args, 1)?;
        let shutdown = ctx.get_field(this, 0).as_int().unwrap_or(0);
        if shutdown != 0 {
            return Err(RuntimeError::IllegalStateException {
                message: "ExecutorService has been shut down".into(),
            }.into());
        }
        // execute() runs immediately (fire-and-forget)
        let _ = ctx.invoke_virtual(runnable, "run", "()V", &[]);
        Ok(Some(Value::Object(None)))
    });

    // --- TimeUnit enum (1-field: ordinal=0) ---
    let tu = "java/util/concurrent/TimeUnit";
    r.register(tu, "toMillis", "(J)J", |ctx, args| {
        let this = obj_arg(args, 0)?;
        let ord = ctx.get_field(this, 0).as_int().unwrap_or(0);
        let dur = args[1].as_long().unwrap_or(0);
        let millis = match ord {
            0 => dur / 1_000_000,  // NANOSECONDS
            1 => dur / 1000,       // MICROSECONDS
            2 => dur,              // MILLISECONDS
            3 => dur * 1000,       // SECONDS
            4 => dur * 60_000,     // MINUTES
            5 => dur * 3_600_000,  // HOURS
            6 => dur * 86_400_000, // DAYS
            _ => dur,
        };
        Ok(Some(Value::Long(millis)))
    });
    r.register(tu, "toNanos", "(J)J", |ctx, args| {
        let this = obj_arg(args, 0)?;
        let ord = ctx.get_field(this, 0).as_int().unwrap_or(0);
        let dur = args[1].as_long().unwrap_or(0);
        let nanos = match ord {
            0 => dur,                      // NANOSECONDS
            1 => dur * 1000,               // MICROSECONDS
            2 => dur * 1_000_000,          // MILLISECONDS
            3 => dur * 1_000_000_000,      // SECONDS
            4 => dur * 60_000_000_000,     // MINUTES
            5 => dur * 3_600_000_000_000,  // HOURS
            6 => dur * 86_400_000_000_000, // DAYS
            _ => dur,
        };
        Ok(Some(Value::Long(nanos)))
    });
    r.register(tu, "toSeconds", "(J)J", |ctx, args| {
        let this = obj_arg(args, 0)?;
        let ord = ctx.get_field(this, 0).as_int().unwrap_or(0);
        let dur = args[1].as_long().unwrap_or(0);
        let secs = match ord {
            0 => dur / 1_000_000_000,
            1 => dur / 1_000_000,
            2 => dur / 1000,
            3 => dur,
            4 => dur * 60,
            5 => dur * 3600,
            6 => dur * 86400,
            _ => dur,
        };
        Ok(Some(Value::Long(secs)))
    });
    r.register(
        tu,
        "convert",
        "(JLjava/util/concurrent/TimeUnit;)J",
        |_ctx, args| {
            let _this = obj_arg(args, 0)?;
            // Simplified: just return the value
            Ok(Some(args[1]))
        },
    );
    // TimeUnit static constants (ordinals)
    r.register(
        tu,
        "NANOSECONDS",
        "Ljava/util/concurrent/TimeUnit;",
        |ctx, _args| {
            let obj = alloc_concurrent_synthetic(ctx, "java/util/concurrent/TimeUnit", 1);
            ctx.set_field(obj, 0, Value::Int(0));
            Ok(Some(Value::Object(Some(obj))))
        },
    );
    r.register(
        tu,
        "MICROSECONDS",
        "Ljava/util/concurrent/TimeUnit;",
        |ctx, _args| {
            let obj = alloc_concurrent_synthetic(ctx, "java/util/concurrent/TimeUnit", 1);
            ctx.set_field(obj, 0, Value::Int(1));
            Ok(Some(Value::Object(Some(obj))))
        },
    );
    r.register(
        tu,
        "MILLISECONDS",
        "Ljava/util/concurrent/TimeUnit;",
        |ctx, _args| {
            let obj = alloc_concurrent_synthetic(ctx, "java/util/concurrent/TimeUnit", 1);
            ctx.set_field(obj, 0, Value::Int(2));
            Ok(Some(Value::Object(Some(obj))))
        },
    );
    r.register(
        tu,
        "SECONDS",
        "Ljava/util/concurrent/TimeUnit;",
        |ctx, _args| {
            let obj = alloc_concurrent_synthetic(ctx, "java/util/concurrent/TimeUnit", 1);
            ctx.set_field(obj, 0, Value::Int(3));
            Ok(Some(Value::Object(Some(obj))))
        },
    );
    r.register(
        tu,
        "MINUTES",
        "Ljava/util/concurrent/TimeUnit;",
        |ctx, _args| {
            let obj = alloc_concurrent_synthetic(ctx, "java/util/concurrent/TimeUnit", 1);
            ctx.set_field(obj, 0, Value::Int(4));
            Ok(Some(Value::Object(Some(obj))))
        },
    );
    r.register(
        tu,
        "HOURS",
        "Ljava/util/concurrent/TimeUnit;",
        |ctx, _args| {
            let obj = alloc_concurrent_synthetic(ctx, "java/util/concurrent/TimeUnit", 1);
            ctx.set_field(obj, 0, Value::Int(5));
            Ok(Some(Value::Object(Some(obj))))
        },
    );
    r.register(
        tu,
        "DAYS",
        "Ljava/util/concurrent/TimeUnit;",
        |ctx, _args| {
            let obj = alloc_concurrent_synthetic(ctx, "java/util/concurrent/TimeUnit", 1);
            ctx.set_field(obj, 0, Value::Int(6));
            Ok(Some(Value::Object(Some(obj))))
        },
    );
}

// ---------------------------------------------------------------------------
// java.lang.reflect extras: Parameter, Executable
// ---------------------------------------------------------------------------
pub(crate) fn register_phase55_reflect(r: &mut NativeMethodRegistry) {
    // --- java.lang.reflect.Parameter (3-field: name=0, modifiers=1, type=2) ---
    let param = "java/lang/reflect/Parameter";
    r.register(param, "getName", "()Ljava/lang/String;", |ctx, args| {
        let this = obj_arg(args, 0)?;
        Ok(Some(ctx.get_field(this, 0)))
    });
    r.register(param, "getModifiers", "()I", |ctx, args| {
        let this = obj_arg(args, 0)?;
        Ok(Some(ctx.get_field(this, 1)))
    });
    r.register(param, "getType", "()Ljava/lang/Class;", |ctx, args| {
        let this = obj_arg(args, 0)?;
        Ok(Some(ctx.get_field(this, 2)))
    });
    r.register(param, "isNamePresent", "()Z", |_ctx, _args| {
        Ok(Some(Value::Int(1)))
    });
    r.register(param, "toString", "()Ljava/lang/String;", |ctx, args| {
        let this = obj_arg(args, 0)?;
        Ok(Some(ctx.get_field(this, 0)))
    });

    // --- java.lang.reflect.Modifier (static utility) ---
    let modifier = "java/lang/reflect/Modifier";
    r.register(modifier, "isPublic", "(I)Z", |_ctx, args| {
        let flags = args[0].as_int().unwrap_or(0);
        Ok(Some(Value::Int(if flags & 0x0001 != 0 { 1 } else { 0 })))
    });
    r.register(modifier, "isPrivate", "(I)Z", |_ctx, args| {
        let flags = args[0].as_int().unwrap_or(0);
        Ok(Some(Value::Int(if flags & 0x0002 != 0 { 1 } else { 0 })))
    });
    r.register(modifier, "isProtected", "(I)Z", |_ctx, args| {
        let flags = args[0].as_int().unwrap_or(0);
        Ok(Some(Value::Int(if flags & 0x0004 != 0 { 1 } else { 0 })))
    });
    r.register(modifier, "isStatic", "(I)Z", |_ctx, args| {
        let flags = args[0].as_int().unwrap_or(0);
        Ok(Some(Value::Int(if flags & 0x0008 != 0 { 1 } else { 0 })))
    });
    r.register(modifier, "isFinal", "(I)Z", |_ctx, args| {
        let flags = args[0].as_int().unwrap_or(0);
        Ok(Some(Value::Int(if flags & 0x0010 != 0 { 1 } else { 0 })))
    });
    r.register(modifier, "isSynchronized", "(I)Z", |_ctx, args| {
        let flags = args[0].as_int().unwrap_or(0);
        Ok(Some(Value::Int(if flags & 0x0020 != 0 { 1 } else { 0 })))
    });
    r.register(modifier, "isVolatile", "(I)Z", |_ctx, args| {
        let flags = args[0].as_int().unwrap_or(0);
        Ok(Some(Value::Int(if flags & 0x0040 != 0 { 1 } else { 0 })))
    });
    r.register(modifier, "isTransient", "(I)Z", |_ctx, args| {
        let flags = args[0].as_int().unwrap_or(0);
        Ok(Some(Value::Int(if flags & 0x0080 != 0 { 1 } else { 0 })))
    });
    r.register(modifier, "isNative", "(I)Z", |_ctx, args| {
        let flags = args[0].as_int().unwrap_or(0);
        Ok(Some(Value::Int(if flags & 0x0100 != 0 { 1 } else { 0 })))
    });
    r.register(modifier, "isAbstract", "(I)Z", |_ctx, args| {
        let flags = args[0].as_int().unwrap_or(0);
        Ok(Some(Value::Int(if flags & 0x0400 != 0 { 1 } else { 0 })))
    });
    r.register(modifier, "isInterface", "(I)Z", |_ctx, args| {
        let flags = args[0].as_int().unwrap_or(0);
        Ok(Some(Value::Int(if flags & 0x0200 != 0 { 1 } else { 0 })))
    });
    r.register(modifier, "isStrict", "(I)Z", |_ctx, args| {
        let flags = args[0].as_int().unwrap_or(0);
        Ok(Some(Value::Int(if flags & 0x0800 != 0 { 1 } else { 0 })))
    });
    r.register(
        modifier,
        "toString",
        "(I)Ljava/lang/String;",
        |ctx, args| {
            let flags = args[0].as_int().unwrap_or(0);
            let mut parts = Vec::new();
            if flags & 0x0001 != 0 {
                parts.push("public");
            }
            if flags & 0x0002 != 0 {
                parts.push("private");
            }
            if flags & 0x0004 != 0 {
                parts.push("protected");
            }
            if flags & 0x0008 != 0 {
                parts.push("static");
            }
            if flags & 0x0010 != 0 {
                parts.push("final");
            }
            if flags & 0x0020 != 0 {
                parts.push("synchronized");
            }
            if flags & 0x0040 != 0 {
                parts.push("volatile");
            }
            if flags & 0x0080 != 0 {
                parts.push("transient");
            }
            if flags & 0x0100 != 0 {
                parts.push("native");
            }
            if flags & 0x0200 != 0 {
                parts.push("interface");
            }
            if flags & 0x0400 != 0 {
                parts.push("abstract");
            }
            let s = ctx.create_string(&parts.join(" "));
            Ok(Some(Value::Object(Some(s))))
        },
    );

    // --- Proxy --- (real implementation in lib.rs::register_reflect_proxy_natives)
}

// ---------------------------------------------------------------------------
// Collection extras: IdentityHashMap, Collections.unmodifiableX, etc.
// ---------------------------------------------------------------------------
pub(crate) fn register_phase55_collection_extras(r: &mut NativeMethodRegistry) {
    // --- IdentityHashMap (same 3-field layout as HashMap) ---
    let ihm = "java/util/IdentityHashMap";
    r.register(ihm, "<init>", "()V", native_al_init_default_for_map);
    r.register(ihm, "<init>", "(I)V", native_al_init_default_for_map);
    r.register(ihm, "size", "()I", |ctx, args| {
        let this = obj_arg(args, 0)?;
        Ok(Some(ctx.get_field(this, 1)))
    });
    r.register(ihm, "isEmpty", "()Z", |ctx, args| {
        let this = obj_arg(args, 0)?;
        let sz = ctx.get_field(this, 1).as_int().unwrap_or(0);
        Ok(Some(Value::Int(if sz == 0 { 1 } else { 0 })))
    });

    // --- Collections extras (unmodifiable/synchronized already in collections.rs) ---
    let coll = "java/util/Collections";
    r.register(
        coll,
        "synchronizedList",
        "(Ljava/util/List;)Ljava/util/List;",
        |_ctx, args| Ok(Some(args[0])),
    );
    r.register(
        coll,
        "synchronizedSet",
        "(Ljava/util/Set;)Ljava/util/Set;",
        |_ctx, args| Ok(Some(args[0])),
    );
    r.register(
        coll,
        "synchronizedMap",
        "(Ljava/util/Map;)Ljava/util/Map;",
        |_ctx, args| Ok(Some(args[0])),
    );
    r.register(
        coll,
        "synchronizedCollection",
        "(Ljava/util/Collection;)Ljava/util/Collection;",
        |_ctx, args| Ok(Some(args[0])),
    );
    r.register(
        coll,
        "checkedList",
        "(Ljava/util/List;Ljava/lang/Class;)Ljava/util/List;",
        |_ctx, args| Ok(Some(args[0])),
    );
    r.register(
        coll,
        "checkedSet",
        "(Ljava/util/Set;Ljava/lang/Class;)Ljava/util/Set;",
        |_ctx, args| Ok(Some(args[0])),
    );
    r.register(
        coll,
        "checkedMap",
        "(Ljava/util/Map;Ljava/lang/Class;Ljava/lang/Class;)Ljava/util/Map;",
        |_ctx, args| Ok(Some(args[0])),
    );
    r.register(
        coll,
        "singleton",
        "(Ljava/lang/Object;)Ljava/util/Set;",
        |ctx, args| {
            let elem = args[0];
            let set = alloc_concurrent_synthetic(ctx, "java/util/HashSet", 3);
            let arr = ctx.new_array(rustjvm_types::ArrayElementType::Reference, 16);
            ctx.set_field(set, 0, Value::Object(Some(arr)));
            ctx.set_field(set, 1, Value::Int(0));
            ctx.set_field(set, 2, Value::Int(16));
            // Just store element — we'll use the standard HashSet native_set_add internally
            // But we can't call it directly here. Just allocate and put manually:
            ctx.set_array_element(arr, 0, elem);
            ctx.set_field(set, 1, Value::Int(1));
            Ok(Some(Value::Object(Some(set))))
        },
    );
    r.register(
        coll,
        "singletonList",
        "(Ljava/lang/Object;)Ljava/util/List;",
        |ctx, args| {
            let elem = args[0];
            let list = alloc_concurrent_synthetic(ctx, "java/util/ArrayList", 2);
            let arr = ctx.new_array(rustjvm_types::ArrayElementType::Reference, 1);
            ctx.set_array_element(arr, 0, elem);
            ctx.set_field(list, 0, Value::Object(Some(arr)));
            ctx.set_field(list, 1, Value::Int(1));
            Ok(Some(Value::Object(Some(list))))
        },
    );
    r.register(
        coll,
        "singletonMap",
        "(Ljava/lang/Object;Ljava/lang/Object;)Ljava/util/Map;",
        |ctx, args| {
            let key = args[0];
            let val = args[1];
            let map = alloc_concurrent_synthetic(ctx, "java/util/HashMap", 3);
            let arr = ctx.new_array(rustjvm_types::ArrayElementType::Reference, 16);
            ctx.set_field(map, 0, Value::Object(Some(arr)));
            ctx.set_field(map, 1, Value::Int(0));
            ctx.set_field(map, 2, Value::Int(16));
            // Simple: put at bucket 0
            let node = alloc_concurrent_synthetic(ctx, "java/util/HashMap$Node", 4);
            ctx.set_field(node, 0, key);
            ctx.set_field(node, 1, val);
            ctx.set_field(node, 2, Value::Int(0)); // hash
            ctx.set_field(node, 3, Value::Object(None)); // next
            ctx.set_array_element(arr, 0, Value::Object(Some(node)));
            ctx.set_field(map, 1, Value::Int(1));
            Ok(Some(Value::Object(Some(map))))
        },
    );
    r.register(
        coll,
        "nCopies",
        "(ILjava/lang/Object;)Ljava/util/List;",
        |ctx, args| {
            let n = args[0].as_int().unwrap_or(0) as usize;
            let elem = args[1];
            let list = alloc_concurrent_synthetic(ctx, "java/util/ArrayList", 2);
            let arr = ctx.new_array(rustjvm_types::ArrayElementType::Reference, n);
            for i in 0..n {
                ctx.set_array_element(arr, i, elem);
            }
            ctx.set_field(list, 0, Value::Object(Some(arr)));
            ctx.set_field(list, 1, Value::Int(n as i32));
            Ok(Some(Value::Object(Some(list))))
        },
    );
    r.register(
        coll,
        "frequency",
        "(Ljava/util/Collection;Ljava/lang/Object;)I",
        |ctx, args| {
            // Collection is typically an ArrayList with backing array at field 0, size at field 1
            let col = obj_arg(args, 1)?;
            let target = args.get(2).copied().unwrap_or(Value::Object(None));
            let arr_val = ctx.get_field(col, 0);
            let size = match ctx.get_field(col, 1) {
                Value::Int(n) => n as usize,
                _ => 0,
            };
            let mut count = 0i32;
            if let Value::Object(Some(arr)) = arr_val {
                let len = ctx.array_length(arr).min(size);
                for i in 0..len {
                    let elem = ctx.get_array_element(arr, i);
                    if values_equal(&elem, &target) {
                        count += 1;
                    }
                }
            }
            Ok(Some(Value::Int(count)))
        },
    );
    r.register(
        coll,
        "disjoint",
        "(Ljava/util/Collection;Ljava/util/Collection;)Z",
        |_ctx, _args| {
            Ok(Some(Value::Int(1))) // assume disjoint
        },
    );
}

/// Helper to init a map-like object with 3 fields (buckets, size, capacity)
fn native_al_init_default_for_map(ctx: &mut dyn NativeContext, args: &[Value]) -> MethodCallResult {
    let this = obj_arg(args, 0)?;
    let cap = 16;
    let arr = ctx.new_array(rustjvm_types::ArrayElementType::Reference, cap);
    ctx.set_field(this, 0, Value::Object(Some(arr)));
    ctx.set_field(this, 1, Value::Int(0));
    ctx.set_field(this, 2, Value::Int(cap as i32));
    Ok(Some(Value::Object(None)))
}

// ============================================================================
// Phase 56: Stream enhancements, Collectors expansion, java.util.function,
//           Summary Statistics, Stream factories
// ============================================================================

pub(crate) fn register_phase56_natives(registry: &mut NativeMethodRegistry) {
    register_phase56_stream_extras(registry);
    register_phase56_collectors_extras(registry);
    register_phase56_summary_stats(registry);
    register_phase56_function_extras(registry);
}

// ---------------------------------------------------------------------------
