    r.register(path, "hashCode", "()I", |ctx, args| {
        let this = obj_arg(args, 0)?;
        let p = p57_read_path(ctx, this);
        // Simple hash matching Java's hashCode() contract
        let mut h: i32 = 0;
        for b in p.bytes() {
            h = h.wrapping_mul(31).wrapping_add(b as i32);
        }
        Ok(Some(Value::Int(h)))
    });

