    // Phase B (RB.8): helper — scan an OpenOption[] looking for APPEND.
    fn open_options_include_append(ctx: &dyn NativeContext, val: Option<&Value>) -> bool {
        let arr = match val {
            Some(Value::Object(Some(a))) => *a,
            _ => return false,
        };
        let len = ctx.array_length(arr);
        for i in 0..len {
            if let Value::Object(Some(opt)) = ctx.get_array_element(arr, i) {
                // OpenOption subclass — StandardOpenOption has an
                // `ordinal()` surrogate via its `name()` String.
                if let Some(n) = ctx.read_string(opt) {
                    if n.eq_ignore_ascii_case("APPEND") {
                        return true;
                    }
                }
                // Enum constants expose their name as field 0 (name)
                // in our synthetic layout.
                if let Value::Object(Some(ns)) = ctx.get_field(opt, 0) {
                    if let Some(n) = ctx.read_string(ns) {
                        if n.eq_ignore_ascii_case("APPEND") {
                            return true;
                        }
                    }
                }
            }
        }
        false
    }

    // Phase B (RB.8): Files.newBufferedWriter — open the path for
    // writing via the fd_table and return a synthetic BufferedWriter
    // (3-field: fd, write-buffer index, write-buffer char[]).  The
    // minimal BufferedWriter natives registered below forward
    // write/flush/close/newLine to the fd. Charset argument is
    // currently honoured via UTF-8 output (matching the JDK default).
    fn open_buffered_writer(
        ctx: &mut dyn NativeContext,
        path_obj: ObjectRef,
        append: bool,
    ) -> MethodCallResult {
        let p = p57_read_path(ctx, path_obj);
        match ctx.fd_table().open_write(&p, append) {
            Ok(fd) => {
                let bw = alloc_concurrent_synthetic(ctx, "java/io/BufferedWriter", 3);
                ctx.set_field(bw, 0, Value::Int(fd as i32));
                // slot 1 (bufferedchar count), slot 2 (charset name) left 0/null —
                // pending_chars/carry buffer unused in this direct-fd mode.
                ctx.set_field(bw, 1, Value::Int(0));
                ctx.set_field(bw, 2, Value::Object(None));
                Ok(Some(Value::Object(Some(bw))))
            }
            Err(e) => Err(RuntimeError::IOException {
                message: format!("newBufferedWriter({}): {}", p, e),
            }
            .into()),
        }
    }

    r.register(
        files,
        "newBufferedWriter",
        "(Ljava/nio/file/Path;[Ljava/nio/file/OpenOption;)Ljava/io/BufferedWriter;",
        |ctx, args| {
            let path_obj = obj_arg(args, 0)?;
            let append = open_options_include_append(ctx, args.get(1));
            open_buffered_writer(ctx, path_obj, append)
        },
    );
    r.register(
        files,
        "newBufferedWriter",
        "(Ljava/nio/file/Path;Ljava/nio/charset/Charset;[Ljava/nio/file/OpenOption;)Ljava/io/BufferedWriter;",
        |ctx, args| {
            let path_obj = obj_arg(args, 0)?;
            let append = open_options_include_append(ctx, args.get(2));
            open_buffered_writer(ctx, path_obj, append)
        },
    );

    // Minimal BufferedWriter natives backed by the fd stored at slot 0.
    // These are also registered in synthetic-jdk mode by phases_late, but
    // the registry dedups on (class, name, desc) so re-registering is
    // safe and keeps the contract explicit for Files.newBufferedWriter.
    let bw_class = "java/io/BufferedWriter";
    r.register(
        bw_class,
        "write",
        "(Ljava/lang/String;II)V",
        |ctx, args| {
            let this = obj_arg(args, 0)?;
            let text = match args.get(1) {
                Some(Value::Object(Some(s))) => ctx.read_string(*s).unwrap_or_default(),
                _ => String::new(),
            };
            let off = args.get(2).and_then(|v| v.as_int()).unwrap_or(0) as usize;
            let len = args.get(3).and_then(|v| v.as_int()).unwrap_or_default() as usize;
            let fd = match ctx.get_field(this, 0) {
                Value::Int(fd) => fd as u32,
                _ => return Ok(None),
            };
            let end = off.saturating_add(len).min(text.chars().count());
            let sub: String = text.chars().skip(off).take(end.saturating_sub(off)).collect();
            let _ = ctx.fd_table().write_string(fd, &sub);
            Ok(None)
        },
    );
    r.register(bw_class, "write", "(I)V", |ctx, args| {
        let this = obj_arg(args, 0)?;
        let c = args.get(1).and_then(|v| v.as_int()).unwrap_or(0) as u32;
        let fd = match ctx.get_field(this, 0) {
            Value::Int(fd) => fd as u32,
            _ => return Ok(None),
        };
        if let Some(ch) = char::from_u32(c) {
            let mut buf = [0u8; 4];
            let bytes = ch.encode_utf8(&mut buf).as_bytes();
            let _ = ctx.fd_table().write_bytes(fd, bytes);
        }
        Ok(None)
    });
    r.register(bw_class, "write", "([CII)V", |ctx, args| {
        let this = obj_arg(args, 0)?;
        let arr = match args.get(1) {
            Some(Value::Object(Some(a))) => *a,
            _ => return Ok(None),
        };
        let off = args.get(2).and_then(|v| v.as_int()).unwrap_or(0) as usize;
        let len = args.get(3).and_then(|v| v.as_int()).unwrap_or(0) as usize;
        let fd = match ctx.get_field(this, 0) {
            Value::Int(fd) => fd as u32,
            _ => return Ok(None),
        };
        let cap = ctx.array_length(arr);
        let end = off.saturating_add(len).min(cap);
        let mut chars: Vec<u16> = Vec::with_capacity(end.saturating_sub(off));
        for i in off..end {
            if let Value::Int(v) = ctx.get_array_element(arr, i) {
                chars.push((v & 0xFFFF) as u16);
            }
        }
        let s = String::from_utf16_lossy(&chars);
        let _ = ctx.fd_table().write_string(fd, &s);
        Ok(None)
    });
    r.register(bw_class, "newLine", "()V", |ctx, args| {
        let this = obj_arg(args, 0)?;
        let fd = match ctx.get_field(this, 0) {
            Value::Int(fd) => fd as u32,
            _ => return Ok(None),
        };
        let sep = ctx
            .get_system_property("line.separator")
            .unwrap_or_else(|| if cfg!(windows) { "\r\n" } else { "\n" }.to_string());
        let _ = ctx.fd_table().write_string(fd, &sep);
        Ok(None)
    });
    r.register(bw_class, "flush", "()V", |ctx, args| {
        let _this = obj_arg(args, 0)?;
        // BufWriter<File> flushes automatically on drop; explicit
        // flush is a no-op in the direct-fd mode since each write
        // already hits the buffered writer inside fd_table.
        Ok(None)
    });
    r.register(bw_class, "close", "()V", |ctx, args| {
        let this = obj_arg(args, 0)?;
        let fd = match ctx.get_field(this, 0) {
            Value::Int(fd) => fd as u32,
            _ => return Ok(None),
        };
        let _ = ctx.fd_table().close(fd);
        ctx.set_field(this, 0, Value::Int(-1));
        Ok(None)
    });

