    // --- Path additional methods ---
    let path = "java/nio/file/Path";
    r.register(path, "toAbsolutePath", "()Ljava/nio/file/Path;", |ctx, args| {
        let this = obj_arg(args, 0)?;
        let p = p57_read_path(ctx, this);
        let abs = std::path::Path::new(&p)
            .canonicalize()
            .map(|c| c.to_string_lossy().replace('\\', "/"))
            .unwrap_or_else(|_| {
                if p.starts_with('/') || (p.len() > 2 && p.as_bytes()[1] == b':') {
                    p.clone()
                } else {
                    format!("{}/{}", std::env::current_dir().unwrap_or_default().to_string_lossy().replace('\\', "/"), p)
                }
            });
        let result = p57_alloc_path(ctx, &abs);
        Ok(Some(Value::Object(Some(result))))
    });

    r.register(path, "normalize", "()Ljava/nio/file/Path;", |ctx, args| {
        let this = obj_arg(args, 0)?;
        let p = p57_read_path(ctx, this);
        // Simple normalize: resolve . and ..
        let mut parts: Vec<&str> = Vec::new();
        for part in p.split('/') {
            match part {
                "." | "" => {}
                ".." => { parts.pop(); }
                other => parts.push(other),
            }
        }
        let normalized = if p.starts_with('/') {
            format!("/{}", parts.join("/"))
        } else {
            parts.join("/")
        };
        let result = p57_alloc_path(ctx, &normalized);
        Ok(Some(Value::Object(Some(result))))
    });

