// =============================================================================
// java.text — ChoiceFormat, DecimalFormatSymbols, DateFormatSymbols,
//             ParsePosition, FieldPosition, Normalizer
// =============================================================================

pub(crate) fn register_p61_text_formatting(r: &mut NativeMethodRegistry) {
    // --- ParsePosition = 1-field (index=0) ---
    let pp = "java/text/ParsePosition";
    r.register(pp, "<init>", "(I)V", |ctx, args| {
        let this = obj_arg(args, 0)?;
        let idx = match args.get(1) {
            Some(Value::Int(v)) => *v,
            _ => 0,
        };
        ctx.set_field(this, 0, Value::Int(idx));
        Ok(None)
    });
    r.register(pp, "getIndex", "()I", |ctx, args| {
        let this = obj_arg(args, 0)?;
        Ok(Some(ctx.get_field(this, 0)))
    });
    r.register(pp, "setIndex", "(I)V", |ctx, args| {
        let this = obj_arg(args, 0)?;
        let idx = match args.get(1) {
            Some(Value::Int(v)) => *v,
            _ => 0,
        };
        ctx.set_field(this, 0, Value::Int(idx));
        Ok(None)
    });
    r.register(pp, "getErrorIndex", "()I", |ctx, args| {
        let this = obj_arg(args, 0)?;
        // errorIndex is field 1 if the object has ≥2 fields; otherwise default -1
        if ctx.object_num_fields(this) > 1 {
            Ok(Some(ctx.get_field(this, 1)))
        } else {
            Ok(Some(Value::Int(-1)))
        }
    });
    r.register(pp, "setErrorIndex", "(I)V", |ctx, args| {
        let this = obj_arg(args, 0)?;
        let idx = args.get(1).and_then(|v| v.as_int()).unwrap_or(-1);
        if ctx.object_num_fields(this) > 1 {
            ctx.set_field(this, 1, Value::Int(idx));
        }
        Ok(None)
    });

    // --- FieldPosition = 2-field (field=0, endIndex=1) ---
    let fp = "java/text/FieldPosition";
    r.register(fp, "<init>", "(I)V", |ctx, args| {
        let this = obj_arg(args, 0)?;
        let field = match args.get(1) {
            Some(Value::Int(v)) => *v,
            _ => 0,
        };
        ctx.set_field(this, 0, Value::Int(field));
        ctx.set_field(this, 1, Value::Int(0));
        Ok(None)
    });
    r.register(fp, "getField", "()I", |ctx, args| {
        let this = obj_arg(args, 0)?;
        Ok(Some(ctx.get_field(this, 0)))
    });
    r.register(fp, "getBeginIndex", "()I", |_ctx, _args| {
        Ok(Some(Value::Int(0)))
    });
    r.register(fp, "getEndIndex", "()I", |ctx, args| {
        let this = obj_arg(args, 0)?;
        Ok(Some(ctx.get_field(this, 1)))
    });

    // --- DecimalFormatSymbols = 6-field ---
    // (decimalSep=0 Int(char), groupSep=1, percent=2, currency=3 String, intlCurrency=4 String, minus=5 Int(char))
    let dfs = "java/text/DecimalFormatSymbols";
    r.register(dfs, "<init>", "()V", p61_dfs_init_default);
    r.register(dfs, "<init>", "(Ljava/util/Locale;)V", |ctx, args| {
        let this = obj_arg(args, 0)?;
        p61_dfs_init(ctx, this);
        Ok(None)
    });
    r.register(dfs, "getDecimalSeparator", "()C", |ctx, args| {
        let this = obj_arg(args, 0)?;
        Ok(Some(ctx.get_field(this, 0)))
    });
    r.register(dfs, "getGroupingSeparator", "()C", |ctx, args| {
        let this = obj_arg(args, 0)?;
        Ok(Some(ctx.get_field(this, 1)))
    });
    r.register(dfs, "getPercent", "()C", |ctx, args| {
        let this = obj_arg(args, 0)?;
        Ok(Some(ctx.get_field(this, 2)))
    });
    r.register(
        dfs,
        "getCurrencySymbol",
        "()Ljava/lang/String;",
        |ctx, args| {
            let this = obj_arg(args, 0)?;
            Ok(Some(ctx.get_field(this, 3)))
        },
    );
    r.register(
        dfs,
        "getInternationalCurrencySymbol",
        "()Ljava/lang/String;",
        |ctx, args| {
            let this = obj_arg(args, 0)?;
            Ok(Some(ctx.get_field(this, 4)))
        },
    );
    r.register(dfs, "getMinusSign", "()C", |ctx, args| {
        let this = obj_arg(args, 0)?;
        Ok(Some(ctx.get_field(this, 5)))
    });
    r.register(dfs, "setDecimalSeparator", "(C)V", |ctx, args| {
        let this = obj_arg(args, 0)?;
        ctx.set_field(
            this,
            0,
            args.get(1).copied().unwrap_or(Value::Int('.' as i32)),
        );
        Ok(None)
    });
    r.register(dfs, "setGroupingSeparator", "(C)V", |ctx, args| {
        let this = obj_arg(args, 0)?;
        ctx.set_field(
            this,
            1,
            args.get(1).copied().unwrap_or(Value::Int(',' as i32)),
        );
        Ok(None)
    });

    // --- DateFormatSymbols = 5-field ---
    // (weekdays=0 String[], shortWeekdays=1, months=2, shortMonths=3, amPm=4)
    let dfsy = "java/text/DateFormatSymbols";
    r.register(dfsy, "<init>", "()V", p61_dfsy_init);
    r.register(dfsy, "<init>", "(Ljava/util/Locale;)V", |ctx, args| {
        let this = obj_arg(args, 0)?;
        p61_dfsy_fill(ctx, this);
        Ok(None)
    });
    r.register(dfsy, "getWeekdays", "()[Ljava/lang/String;", |ctx, args| {
        let this = obj_arg(args, 0)?;
        Ok(Some(ctx.get_field(this, 0)))
    });
    r.register(
        dfsy,
        "getShortWeekdays",
        "()[Ljava/lang/String;",
        |ctx, args| {
            let this = obj_arg(args, 0)?;
            Ok(Some(ctx.get_field(this, 1)))
        },
    );
    r.register(dfsy, "getMonths", "()[Ljava/lang/String;", |ctx, args| {
        let this = obj_arg(args, 0)?;
        Ok(Some(ctx.get_field(this, 2)))
    });
    r.register(
        dfsy,
        "getShortMonths",
        "()[Ljava/lang/String;",
        |ctx, args| {
            let this = obj_arg(args, 0)?;
            Ok(Some(ctx.get_field(this, 3)))
        },
    );
    r.register(
        dfsy,
        "getAmPmStrings",
        "()[Ljava/lang/String;",
        |ctx, args| {
            let this = obj_arg(args, 0)?;
            Ok(Some(ctx.get_field(this, 4)))
        },
    );

    // --- ChoiceFormat = 3-field: limits=0 (array of doubles), formats=1 (array of strings), count=2 ---
    // ChoiceFormat pattern syntax: "limit#string|limit#string|..."
    // or "limit<string|limit#string|..." where # means >= and < means >
    let cf = "java/text/ChoiceFormat";
    r.register(cf, "<init>", "(Ljava/lang/String;)V", |ctx, args| {
        let this = obj_arg(args, 0)?;
        let pattern_str = match args.get(1) {
            Some(Value::Object(Some(s))) => ctx.read_string(*s).unwrap_or_default(),
            _ => String::new(),
        };
        // Parse pattern: segments separated by '|', each is "limit#format" or "limit<format"
        let segments: Vec<&str> = pattern_str.split('|').collect();
        let count = segments.len();
        let limits_arr = ctx.new_array(rustjvm_types::ArrayElementType::Reference, count);
        let formats_arr = ctx.new_array(rustjvm_types::ArrayElementType::Reference, count);
        for (i, seg) in segments.iter().enumerate() {
            let (limit, format_str) = if let Some(pos) = seg.find('#') {
                let limit: f64 = seg[..pos].trim().parse().unwrap_or(0.0);
                (limit, &seg[pos + 1..])
            } else if let Some(pos) = seg.find('<') {
                let limit: f64 = seg[..pos].trim().parse().unwrap_or(0.0);
                // '<' means strictly greater than; we use nextUp semantics
                (limit + f64::EPSILON, &seg[pos + 1..])
            } else {
                (0.0, seg.trim())
            };
            // Store limit as a boxed Double synthetic
            let limit_obj = alloc_concurrent_synthetic(ctx, "java/lang/Double", 1);
            ctx.set_field(limit_obj, 0, Value::Double(limit));
            ctx.set_array_element(limits_arr, i, Value::Object(Some(limit_obj)));
            let fmt_s = ctx.create_string(format_str);
            ctx.set_array_element(formats_arr, i, Value::Object(Some(fmt_s)));
        }
        ctx.set_field(this, 0, Value::Object(Some(limits_arr)));
        ctx.set_field(this, 1, Value::Object(Some(formats_arr)));
        ctx.set_field(this, 2, Value::Int(count as i32));
        Ok(None)
    });
    r.register(cf, "<init>", "([D[Ljava/lang/String;)V", |ctx, args| {
        let this = obj_arg(args, 0)?;
        let limits = args.get(1).copied().unwrap_or(Value::Object(None));
        let formats = args.get(2).copied().unwrap_or(Value::Object(None));
        ctx.set_field(this, 0, limits);
        ctx.set_field(this, 1, formats);
        let count = match limits {
            Value::Object(Some(a)) => ctx.array_length(a) as i32,
            _ => 0,
        };
        ctx.set_field(this, 2, Value::Int(count));
        Ok(None)
    });
    r.register(cf, "format", "(D)Ljava/lang/String;", |ctx, args| {
        let this = obj_arg(args, 0)?;
        let d = match args.get(1) {
            Some(Value::Double(v)) => *v,
            Some(Value::Long(v)) => *v as f64,
            Some(Value::Int(v)) => *v as f64,
            _ => 0.0,
        };
        let count = match ctx.get_field(this, 2) { Value::Int(n) => n as usize, _ => 0 };
        let limits_arr = match ctx.get_field(this, 0) {
            Value::Object(Some(a)) => a,
            _ => { let s = ctx.create_string(&format!("{d}")); return Ok(Some(Value::Object(Some(s)))); }
        };
        let formats_arr = match ctx.get_field(this, 1) {
            Value::Object(Some(a)) => a,
            _ => { let s = ctx.create_string(&format!("{d}")); return Ok(Some(Value::Object(Some(s)))); }
        };
        // Find the largest limit <= d
        let mut chosen = 0;
        for i in 0..count {
            let limit = match ctx.get_array_element(limits_arr, i) {
                Value::Object(Some(obj)) => match ctx.get_field(obj, 0) {
                    Value::Double(v) => v,
                    _ => 0.0,
                },
                Value::Double(v) => v,
                _ => 0.0,
            };
            if d >= limit {
                chosen = i;
            } else {
                break;
            }
        }
        if count > 0 {
            let fmt = ctx.get_array_element(formats_arr, chosen);
            Ok(Some(fmt))
        } else {
            let s = ctx.create_string(&format!("{d}"));
            Ok(Some(Value::Object(Some(s))))
        }
    });

    // --- Normalizer — real Unicode normalization via unicode-normalization crate ---
    let norm = "java/text/Normalizer";
    r.register(
        norm,
        "normalize",
        "(Ljava/lang/CharSequence;Ljava/text/Normalizer$Form;)Ljava/lang/String;",
        |ctx, args| {
            use unicode_normalization::UnicodeNormalization;
            let input = match args.first() {
                Some(Value::Object(Some(s))) => ctx.read_string(*s).unwrap_or_default(),
                _ => return Ok(Some(Value::Object(None))),
            };
            let form_ordinal = match args.get(1) {
                Some(Value::Object(Some(f))) => ctx.get_field(*f, 0).as_int().unwrap_or(0),
                _ => 0,
            };
            let normalized = match form_ordinal {
                0 => input.nfc().collect::<String>(),   // NFC
                1 => input.nfd().collect::<String>(),   // NFD
                2 => input.nfkc().collect::<String>(),  // NFKC
                3 => input.nfkd().collect::<String>(),  // NFKD
                _ => input,
            };
            let s = ctx.create_string(&normalized);
            Ok(Some(Value::Object(Some(s))))
        },
    );
    r.register(
        norm,
        "isNormalized",
        "(Ljava/lang/CharSequence;Ljava/text/Normalizer$Form;)Z",
        |ctx, args| {
            use unicode_normalization::{
                is_nfc_quick, is_nfd_quick, is_nfkc_quick, is_nfkd_quick,
                IsNormalized,
            };
            let input = match args.first() {
                Some(Value::Object(Some(s))) => ctx.read_string(*s).unwrap_or_default(),
                _ => return Ok(Some(Value::Int(1))),
            };
            let form_ordinal = match args.get(1) {
                Some(Value::Object(Some(f))) => ctx.get_field(*f, 0).as_int().unwrap_or(0),
                _ => 0,
            };
            let result = match form_ordinal {
                0 => is_nfc_quick(input.chars()) == IsNormalized::Yes,
                1 => is_nfd_quick(input.chars()) == IsNormalized::Yes,
                2 => is_nfkc_quick(input.chars()) == IsNormalized::Yes,
                3 => is_nfkd_quick(input.chars()) == IsNormalized::Yes,
                _ => true,
            };
            Ok(Some(Value::Int(if result { 1 } else { 0 })))
        },
    );
    // Normalizer.Form enum values
    let nf = "java/text/Normalizer$Form";
    r.register(nf, "NFC", "Ljava/text/Normalizer$Form;", |ctx, _args| {
        p57_alloc_enum(ctx, "java/text/Normalizer$Form", "NFC", 0)
    });
    r.register(nf, "NFD", "Ljava/text/Normalizer$Form;", |ctx, _args| {
        p57_alloc_enum(ctx, "java/text/Normalizer$Form", "NFD", 1)
    });
    r.register(nf, "NFKC", "Ljava/text/Normalizer$Form;", |ctx, _args| {
        p57_alloc_enum(ctx, "java/text/Normalizer$Form", "NFKC", 2)
    });
    r.register(nf, "NFKD", "Ljava/text/Normalizer$Form;", |ctx, _args| {
        p57_alloc_enum(ctx, "java/text/Normalizer$Form", "NFKD", 3)
    });
}

fn p61_dfs_init_default(ctx: &mut dyn NativeContext, args: &[Value]) -> MethodCallResult {
    let this = obj_arg(args, 0)?;
    p61_dfs_init(ctx, this);
    Ok(None)
}

fn p61_dfs_init(ctx: &mut dyn NativeContext, this: ObjectRef) {
    ctx.set_field(this, 0, Value::Int('.' as i32)); // decimal separator
    ctx.set_field(this, 1, Value::Int(',' as i32)); // grouping separator
    ctx.set_field(this, 2, Value::Int('%' as i32)); // percent
    let cur = ctx.create_string("$");
    ctx.set_field(this, 3, Value::Object(Some(cur))); // currency symbol
    let intl = ctx.create_string("USD");
    ctx.set_field(this, 4, Value::Object(Some(intl))); // international currency
    ctx.set_field(this, 5, Value::Int('-' as i32)); // minus sign
}

fn p61_dfsy_init(ctx: &mut dyn NativeContext, args: &[Value]) -> MethodCallResult {
    let this = obj_arg(args, 0)?;
    p61_dfsy_fill(ctx, this);
    Ok(None)
}

fn p61_dfsy_fill(ctx: &mut dyn NativeContext, this: ObjectRef) {
    // Weekdays: index 0 = empty, 1=Sunday..7=Saturday (Java convention)
    let weekdays = [
        "",
        "Sunday",
        "Monday",
        "Tuesday",
        "Wednesday",
        "Thursday",
        "Friday",
        "Saturday",
    ];
    let wd_arr = ctx.new_array(
        rustjvm_types::ArrayElementType::Reference,
        weekdays.len(),
    );
    for (i, &w) in weekdays.iter().enumerate() {
        let s = ctx.create_string(w);
        ctx.set_array_element(wd_arr, i, Value::Object(Some(s)));
    }
    ctx.set_field(this, 0, Value::Object(Some(wd_arr)));

    let short_weekdays = ["", "Sun", "Mon", "Tue", "Wed", "Thu", "Fri", "Sat"];
    let swd_arr = ctx.new_array(
        rustjvm_types::ArrayElementType::Reference,
        short_weekdays.len(),
    );
    for (i, &w) in short_weekdays.iter().enumerate() {
        let s = ctx.create_string(w);
        ctx.set_array_element(swd_arr, i, Value::Object(Some(s)));
    }
    ctx.set_field(this, 1, Value::Object(Some(swd_arr)));

    let months = [
        "January",
        "February",
        "March",
        "April",
        "May",
        "June",
        "July",
        "August",
        "September",
        "October",
        "November",
        "December",
        "",
    ];
    let m_arr = ctx.new_array(
        rustjvm_types::ArrayElementType::Reference,
        months.len(),
    );
    for (i, &m) in months.iter().enumerate() {
        let s = ctx.create_string(m);
        ctx.set_array_element(m_arr, i, Value::Object(Some(s)));
    }
    ctx.set_field(this, 2, Value::Object(Some(m_arr)));

    let short_months = [
        "Jan", "Feb", "Mar", "Apr", "May", "Jun", "Jul", "Aug", "Sep", "Oct", "Nov", "Dec", "",
    ];
    let sm_arr = ctx.new_array(
        rustjvm_types::ArrayElementType::Reference,
        short_months.len(),
    );
    for (i, &m) in short_months.iter().enumerate() {
        let s = ctx.create_string(m);
        ctx.set_array_element(sm_arr, i, Value::Object(Some(s)));
    }
    ctx.set_field(this, 3, Value::Object(Some(sm_arr)));

    let ampm = ["AM", "PM"];
    let ap_arr = ctx.new_array(rustjvm_types::ArrayElementType::Reference, ampm.len());
    for (i, &a) in ampm.iter().enumerate() {
        let s = ctx.create_string(a);
        ctx.set_array_element(ap_arr, i, Value::Object(Some(s)));
    }
    ctx.set_field(this, 4, Value::Object(Some(ap_arr)));
}

// =============================================================================
// java.util.logging — FileHandler, StreamHandler, LogManager, Logger additions
// =============================================================================

pub(crate) fn register_p61_logging(r: &mut NativeMethodRegistry) {
    // --- Logger additions ---
    let log = "java/util/logging/Logger";
    r.register(
        log,
        "addHandler",
        "(Ljava/util/logging/Handler;)V",
        native_noop_with_this,
    );
    r.register(
        log,
        "removeHandler",
        "(Ljava/util/logging/Handler;)V",
        native_noop_with_this,
    );
    r.register(
        log,
        "getHandlers",
        "()[Ljava/util/logging/Handler;",
        |ctx, args| {
            let this = obj_arg(args, 0)?;
            // Logger field 2 = handlers ArrayList (added in Phase O).
            if ctx.object_num_fields(this) > 2 {
                if let Value::Object(Some(lst)) = ctx.get_field(this, 2) {
                    return rustjvm_native_collections::native_al_to_array(
                        ctx,
                        &[Value::Object(Some(lst))],
                    );
                }
            }
            // No handlers registered — return empty Handler[]
            let arr = ctx.new_array(rustjvm_types::ArrayElementType::Reference, 0);
            Ok(Some(Value::Object(Some(arr))))
        },
    );
    r.register(log, "setUseParentHandlers", "(Z)V", |ctx, args| {
        let this = obj_arg(args, 0)?;
        let val = args.get(1).and_then(|v| v.as_int()).unwrap_or(1);
        // Store in field 4 (Logger has fields: name=0, level=1, handlers=2, filter=3, useParent=4)
        ctx.set_field(this, 4, Value::Int(val));
        Ok(None)
    });
    r.register(log, "getUseParentHandlers", "()Z", |ctx, args| {
        let this = obj_arg(args, 0)?;
        let val = ctx.get_field(this, 4).as_int().unwrap_or(1);
        Ok(Some(Value::Int(val)))
    });
    r.register(
        log,
        "getParent",
        "()Ljava/util/logging/Logger;",
        |_ctx, _args| Ok(Some(Value::Object(None))),
    );
    r.register(
        log,
        "setParent",
        "(Ljava/util/logging/Logger;)V",
        native_noop_with_this,
    );

    // --- StreamHandler = 2-field (stream=0, formatter=1) ---
    let sh = "java/util/logging/StreamHandler";
    r.register(sh, "<init>", "()V", |ctx, args| {
        let this = obj_arg(args, 0)?;
        ctx.set_field(this, 0, Value::Object(None));
        ctx.set_field(this, 1, Value::Object(None));
        Ok(None)
    });
    r.register(
        sh,
        "<init>",
        "(Ljava/io/OutputStream;Ljava/util/logging/Formatter;)V",
        |ctx, args| {
            let this = obj_arg(args, 0)?;
            ctx.set_field(this, 0, args.get(1).copied().unwrap_or(Value::Object(None)));
            ctx.set_field(this, 1, args.get(2).copied().unwrap_or(Value::Object(None)));
            Ok(None)
        },
    );
    r.register(
        sh,
        "publish",
        "(Ljava/util/logging/LogRecord;)V",
        |ctx, args| {
            let this = obj_arg(args, 0)?;
            let stream = match ctx.get_field(this, 0) {
                Value::Object(Some(s)) => s,
                _ => return Ok(None), // no stream
            };

            // Extract level name and message from LogRecord via invoke_virtual
            let level_str = if let Some(Value::Object(Some(record))) = args.get(1) {
                // getLevel() -> Level, then Level.getName() -> String
                let level = match ctx.invoke_virtual(*record, "getLevel", "()Ljava/util/logging/Level;", &[]) {
                    Ok(Some(Value::Object(Some(l)))) => {
                        match ctx.invoke_virtual(l, "getName", "()Ljava/lang/String;", &[]) {
                            Ok(Some(Value::Object(Some(s)))) => ctx.read_string(s).unwrap_or_default(),
                            _ => "INFO".to_string(),
                        }
                    }
                    _ => "INFO".to_string(),
                };
                level
            } else {
                "INFO".to_string()
            };

            let message = if let Some(Value::Object(Some(record))) = args.get(1) {
                match ctx.invoke_virtual(*record, "getMessage", "()Ljava/lang/String;", &[]) {
                    Ok(Some(Value::Object(Some(s)))) => ctx.read_string(s).unwrap_or_default(),
                    _ => String::new(),
                }
            } else {
                String::new()
            };

            // Format and write to stream
            let formatted = format!("[{}] {}\n", level_str, message);
            for &b in formatted.as_bytes() {
                let _ = ctx.invoke_virtual(stream, "write", "(I)V", &[Value::Int(b as i32)]);
            }
            Ok(None)
        },
    );
    r.register(sh, "flush", "()V", |ctx, args| {
        let this = obj_arg(args, 0)?;
        if let Value::Object(Some(stream)) = ctx.get_field(this, 0) {
            let _ = ctx.invoke_virtual(stream, "flush", "()V", &[]);
        }
        Ok(None)
    });
    r.register(sh, "close", "()V", |ctx, args| {
        let this = obj_arg(args, 0)?;
        if let Value::Object(Some(stream)) = ctx.get_field(this, 0) {
            let _ = ctx.invoke_virtual(stream, "flush", "()V", &[]);
            let _ = ctx.invoke_virtual(stream, "close", "()V", &[]);
        }
        Ok(None)
    });

    // --- FileHandler = 3-field (filename=0, level=1, closed=2) ---
    let fh = "java/util/logging/FileHandler";
    r.register(fh, "<init>", "(Ljava/lang/String;)V", |ctx, args| {
        let this = obj_arg(args, 0)?;
        ctx.set_field(this, 0, args.get(1).copied().unwrap_or(Value::Object(None)));
        ctx.set_field(this, 1, Value::Object(None)); // level
        ctx.set_field(this, 2, Value::Int(0)); // open
        Ok(None)
    });
    r.register(
        fh,
        "publish",
        "(Ljava/util/logging/LogRecord;)V",
        |ctx, args| {
            let this = obj_arg(args, 0)?;
            // Check if closed
            let closed = ctx.get_field(this, 2).as_int().unwrap_or(0);
            if closed != 0 { return Ok(None); }

            // Get filename
            let filename = match ctx.get_field(this, 0) {
                Value::Object(Some(s)) => ctx.read_string(s).unwrap_or_default(),
                _ => return Ok(None),
            };

            // Extract level and message
            let (level_str, message) = if let Some(Value::Object(Some(record))) = args.get(1) {
                let level = match ctx.invoke_virtual(*record, "getLevel", "()Ljava/util/logging/Level;", &[]) {
                    Ok(Some(Value::Object(Some(l)))) => {
                        match ctx.invoke_virtual(l, "getName", "()Ljava/lang/String;", &[]) {
                            Ok(Some(Value::Object(Some(s)))) => ctx.read_string(s).unwrap_or_default(),
                            _ => "INFO".to_string(),
                        }
                    }
                    _ => "INFO".to_string(),
                };
                let msg = match ctx.invoke_virtual(*record, "getMessage", "()Ljava/lang/String;", &[]) {
                    Ok(Some(Value::Object(Some(s)))) => ctx.read_string(s).unwrap_or_default(),
                    _ => String::new(),
                };
                (level, msg)
            } else {
                ("INFO".to_string(), String::new())
            };

            // Append to file
            let formatted = format!("[{}] {}\n", level_str, message);
            use std::io::Write;
            if let Ok(mut file) = std::fs::OpenOptions::new().create(true).append(true).open(&filename) {
                let _ = file.write_all(formatted.as_bytes());
            }
            Ok(None)
        },
    );
    r.register(fh, "flush", "()V", |ctx, args| {
        // FileHandler flush: file I/O is auto-flushed on write
        let _ = (ctx, args);
        Ok(None)
    });
    r.register(fh, "close", "()V", |ctx, args| {
        let this = obj_arg(args, 0)?;
        ctx.set_field(this, 2, Value::Int(1));
        Ok(None)
    });

    // --- LogManager = 1-field (properties=0 HashMap-like) ---
    let lm = "java/util/logging/LogManager";
    r.register(
        lm,
        "getLogManager",
        "()Ljava/util/logging/LogManager;",
        |ctx, _args| {
            let mgr = alloc_concurrent_synthetic(ctx, "java/util/logging/LogManager", 1);
            ctx.set_field(mgr, 0, Value::Object(None));
            Ok(Some(Value::Object(Some(mgr))))
        },
    );
    r.register(lm, "reset", "()V", |ctx, args| {
        // Reset clears the LogManager's properties field.
        let this = obj_arg(args, 0)?;
        if ctx.object_num_fields(this) > 0 {
            ctx.set_field(this, 0, Value::Object(None));
        }
        Ok(None)
    });
    r.register(
        lm,
        "getProperty",
        "(Ljava/lang/String;)Ljava/lang/String;",
        |_ctx, _args| Ok(Some(Value::Object(None))),
    );
    r.register(
        lm,
        "addLogger",
        "(Ljava/util/logging/Logger;)Z",
        |_ctx, _args| Ok(Some(Value::Int(1))),
    );
    r.register(
        lm,
        "getLoggerNames",
        "()Ljava/util/Enumeration;",
        |ctx, _args| {
            // Return empty enumeration stub
            let e = alloc_concurrent_synthetic(
                ctx,
                "java/util/logging/LogManager$LoggerEnumeration",
                1,
            );
            ctx.set_field(e, 0, Value::Int(0));
            Ok(Some(Value::Object(Some(e))))
        },
    );
}

// =============================================================================
// java.nio.charset — Charset expansion, availableCharsets, aliases
// =============================================================================

pub(crate) fn register_p61_charset(r: &mut NativeMethodRegistry) {
    let cs = "java/nio/charset/Charset";
    r.register(cs, "name", "()Ljava/lang/String;", |ctx, args| {
        let this = obj_arg(args, 0)?;
        Ok(Some(ctx.get_field(this, 0))) // field 0 = name string
    });
    r.register(cs, "aliases", "()Ljava/util/Set;", |ctx, _args| {
        // Return empty HashSet
        let set = alloc_concurrent_synthetic(ctx, "java/util/HashSet", 3);
        ctx.set_field(set, 0, Value::Object(None));
        ctx.set_field(set, 1, Value::Int(0));
        ctx.set_field(set, 2, Value::Int(16));
        Ok(Some(Value::Object(Some(set))))
    });
    r.register(cs, "displayName", "()Ljava/lang/String;", |ctx, args| {
        let this = obj_arg(args, 0)?;
        Ok(Some(ctx.get_field(this, 0)))
    });
    r.register(cs, "isRegistered", "()Z", |_ctx, _args| {
        Ok(Some(Value::Int(1)))
    });
    r.register(cs, "canEncode", "()Z", |_ctx, _args| {
        Ok(Some(Value::Int(1)))
    });
    r.register(
        cs,
        "contains",
        "(Ljava/nio/charset/Charset;)Z",
        |_ctx, _args| Ok(Some(Value::Int(0))),
    );
    r.register(
        cs,
        "compareTo",
        "(Ljava/nio/charset/Charset;)I",
        |ctx, args| {
            let this = obj_arg(args, 0)?;
            let name1 = match ctx.get_field(this, 0) {
                Value::Object(Some(s)) => ctx.read_string(s).unwrap_or_default(),
                _ => String::new(),
            };
            if let Some(Value::Object(Some(other))) = args.get(1) {
                let name2 = match ctx.get_field(*other, 0) {
                    Value::Object(Some(s)) => ctx.read_string(s).unwrap_or_default(),
                    _ => String::new(),
                };
                Ok(Some(Value::Int(
                    name1.to_lowercase().cmp(&name2.to_lowercase()) as i32,
                )))
            } else {
                Ok(Some(Value::Int(0)))
            }
        },
    );
    r.register(cs, "toString", "()Ljava/lang/String;", |ctx, args| {
        let this = obj_arg(args, 0)?;
        Ok(Some(ctx.get_field(this, 0)))
    });

    // availableCharsets returns sorted map of name -> Charset
    r.register(
        cs,
        "availableCharsets",
        "()Ljava/util/SortedMap;",
        |ctx, _args| {
            // Return a TreeMap with standard charsets
            let tm = alloc_concurrent_synthetic(ctx, "java/util/TreeMap", 3);
            let charsets = [
                "ISO-8859-1",
                "US-ASCII",
                "UTF-16",
                "UTF-16BE",
                "UTF-16LE",
                "UTF-8",
            ];
            let data_arr = ctx.new_array(
                rustjvm_types::ArrayElementType::Reference,
                charsets.len() * 2,
            );
            for (i, &name) in charsets.iter().enumerate() {
                let key = ctx.create_string(name);
                ctx.set_array_element(data_arr, i * 2, Value::Object(Some(key)));
                // Create a Charset object for each
                let cs_obj = alloc_concurrent_synthetic(ctx, "java/nio/charset/Charset", 2);
                let n = ctx.create_string(name);
                ctx.set_field(cs_obj, 0, Value::Object(Some(n)));
                ctx.set_field(cs_obj, 1, Value::Int(0)); // flags
                ctx.set_array_element(data_arr, i * 2 + 1, Value::Object(Some(cs_obj)));
            }
            ctx.set_field(tm, 0, Value::Object(Some(data_arr)));
            ctx.set_field(tm, 1, Value::Int(charsets.len() as i32));
            ctx.set_field(tm, 2, Value::Object(None)); // no comparator
            Ok(Some(Value::Object(Some(tm))))
        },
    );
}

// =============================================================================
// java.lang.ClassLoader — resource loading, findResource, loadClass
// =============================================================================

pub(crate) fn register_p61_classloader(r: &mut NativeMethodRegistry) {
    let cl = "java/lang/ClassLoader";
    r.register(
        cl,
        "getResource",
        "(Ljava/lang/String;)Ljava/net/URL;",
        |ctx, args| {
            let name_obj = match args.get(1) {
                Some(Value::Object(Some(o))) => *o,
                _ => return Ok(Some(Value::Object(None))),
            };
            let name = ctx.read_string(name_obj).unwrap_or_default();
            let resource_name = name.trim_start_matches('/');
            let urls = ctx.find_all_resource_urls(resource_name);
            let url_str = if let Some(first) = urls.first() {
                first.clone()
            } else if ctx.find_resource(resource_name).is_some() {
                format!("classpath:{name}")
            } else {
                return Ok(Some(Value::Object(None)));
            };
            let url_obj = alloc_concurrent_synthetic(ctx, "java/net/URL", 6);
            let full = ctx.create_string(&url_str);
            ctx.set_field(url_obj, 0, Value::Object(Some(full)));
            ctx.set_field(url_obj, 5, Value::Object(Some(full)));
            Ok(Some(Value::Object(Some(url_obj))))
        },
    );
    r.register(
        cl,
        "getResources",
        "(Ljava/lang/String;)Ljava/util/Enumeration;",
        |ctx, args| {
            let name_obj = match args.get(1) {
                Some(Value::Object(Some(o))) => *o,
                _ => {
                    let e =
                        alloc_concurrent_synthetic(ctx, "java/util/Collections$EmptyEnumeration", 0);
                    return Ok(Some(Value::Object(Some(e))));
                }
            };
            let name = ctx.read_string(name_obj).unwrap_or_default();
            let resource_name = name.trim_start_matches('/');
            let mut urls = ctx.find_all_resource_urls(resource_name);
            if urls.is_empty() && ctx.find_resource(resource_name).is_some() {
                urls.push(format!("classpath:{name}"));
            }
            let arr = ctx.new_array(rustjvm_types::ArrayElementType::Reference, urls.len());
            for (i, u) in urls.iter().enumerate() {
                let url_obj = alloc_concurrent_synthetic(ctx, "java/net/URL", 6);
                let full = ctx.create_string(u);
                ctx.set_field(url_obj, 0, Value::Object(Some(full)));
                ctx.set_field(url_obj, 5, Value::Object(Some(full)));
                ctx.set_array_element(arr, i, Value::Object(Some(url_obj)));
            }
            let enm = alloc_concurrent_synthetic(ctx, "java/util/Enumeration$Impl", 2);
            ctx.set_field(enm, 0, Value::Object(Some(arr)));
            ctx.set_field(enm, 1, Value::Int(0));
            Ok(Some(Value::Object(Some(enm))))
        },
    );
    r.register(
        cl,
        "getResourceAsStream",
        "(Ljava/lang/String;)Ljava/io/InputStream;",
        |ctx, args| {
            let name_obj = match args.get(1) {
                Some(Value::Object(Some(o))) => *o,
                _ => return Ok(Some(Value::Object(None))),
            };
            let name = ctx.read_string(name_obj).unwrap_or_default();
            let resource_name = name.trim_start_matches('/');
            if crate::lang_class::t19_h10_validate_resource_name_pub(resource_name).is_none() {
                return Ok(Some(Value::Object(None)));
            }
            match ctx.find_resource(resource_name) {
                None => Ok(Some(Value::Object(None))),
                Some(bytes) => Ok(Some(Value::Object(Some(
                    crate::lang_class::t19_h10_alloc_byte_array_input_stream(ctx, &bytes),
                )))),
            }
        },
    );
    r.register(
        cl,
        "findResource",
        "(Ljava/lang/String;)Ljava/net/URL;",
        |ctx, args| {
            // Mirror getResource semantics for callers that invoke the protected method directly.
            let name_obj = match args.get(1) {
                Some(Value::Object(Some(o))) => *o,
                _ => return Ok(Some(Value::Object(None))),
            };
            let name = ctx.read_string(name_obj).unwrap_or_default();
            let resource_name = name.trim_start_matches('/');
            let urls = ctx.find_all_resource_urls(resource_name);
            let url_str = if let Some(first) = urls.first() {
                first.clone()
            } else if ctx.find_resource(resource_name).is_some() {
                format!("classpath:{name}")
            } else {
                return Ok(Some(Value::Object(None)));
            };
            let url_obj = alloc_concurrent_synthetic(ctx, "java/net/URL", 6);
            let full = ctx.create_string(&url_str);
            ctx.set_field(url_obj, 0, Value::Object(Some(full)));
            ctx.set_field(url_obj, 5, Value::Object(Some(full)));
            Ok(Some(Value::Object(Some(url_obj))))
        },
    );
    r.register(
        cl,
        "findLoadedClass",
        "(Ljava/lang/String;)Ljava/lang/Class;",
        |ctx, args| {
            let name_obj = match args.get(1) {
                Some(Value::Object(Some(o))) => *o,
                _ => return Ok(Some(Value::Object(None))),
            };
            let name = ctx
                .read_string(name_obj)
                .unwrap_or_default()
                .replace('.', "/");
            match ctx.class_id_by_name(&name) {
                Some(cid) => {
                    let mirror = ctx.get_class_mirror(cid);
                    Ok(Some(Value::Object(Some(mirror))))
                }
                None => Ok(Some(Value::Object(None))),
            }
        },
    );
    r.register(
        cl,
        "loadClass",
        "(Ljava/lang/String;)Ljava/lang/Class;",
        |ctx, args| {
            let name_obj = match args.get(1) {
                Some(Value::Object(Some(o))) => *o,
                _ => return Ok(Some(Value::Object(None))),
            };
            let name = ctx
                .read_string(name_obj)
                .unwrap_or_default()
                .replace('.', "/");
            match ctx.ensure_class_initialized(&name) {
                Ok(cid) => {
                    let mirror = ctx.get_class_mirror(cid);
                    Ok(Some(Value::Object(Some(mirror))))
                }
                Err(_) => Ok(Some(Value::Object(None))),
            }
        },
    );
    r.register(
        cl,
        "loadClass",
        "(Ljava/lang/String;Z)Ljava/lang/Class;",
        |ctx, args| {
            let name_obj = match args.get(1) {
                Some(Value::Object(Some(o))) => *o,
                _ => return Ok(Some(Value::Object(None))),
            };
            let name = ctx
                .read_string(name_obj)
                .unwrap_or_default()
                .replace('.', "/");
            match ctx.ensure_class_initialized(&name) {
                Ok(cid) => {
                    let mirror = ctx.get_class_mirror(cid);
                    Ok(Some(Value::Object(Some(mirror))))
                }
                Err(_) => Ok(Some(Value::Object(None))),
            }
        },
    );
    r.register(
        cl,
        "getPlatformClassLoader",
        "()Ljava/lang/ClassLoader;",
        |ctx, _args| {
            let loader = alloc_concurrent_synthetic(ctx, "java/lang/ClassLoader", 1);
            ctx.set_field(loader, 0, Value::Object(None));
            Ok(Some(Value::Object(Some(loader))))
        },
    );
    r.register(cl, "getName", "()Ljava/lang/String;", |ctx, _args| {
        let s = ctx.create_string("app");
        Ok(Some(Value::Object(Some(s))))
    });
    r.register(cl, "isRegisteredAsParallelCapable", "()Z", |_ctx, _args| {
        Ok(Some(Value::Int(0)))
    });
}

// =============================================================================
