// =============================================================================
// java.nio.file — Files.exists/isDirectory, Path expansion
// =============================================================================

pub(crate) fn register_p61_files_path(r: &mut NativeMethodRegistry) {
    let files = "java/nio/file/Files";
    r.register(
        files,
        "exists",
        "(Ljava/nio/file/Path;[Ljava/nio/file/LinkOption;)Z",
        |ctx, args| {
            if let Some(Value::Object(Some(path_ref))) = args.first() {
                let path_str = match ctx.get_field(*path_ref, 0) {
                    Value::Object(Some(s)) => ctx.read_string(s).unwrap_or_default(),
                    _ => return Ok(Some(Value::Int(0))),
                };
                let exists = std::path::Path::new(&path_str).exists();
                Ok(Some(Value::Int(if exists { 1 } else { 0 })))
            } else {
                Ok(Some(Value::Int(0)))
            }
        },
    );
    r.register(
        files,
        "notExists",
        "(Ljava/nio/file/Path;[Ljava/nio/file/LinkOption;)Z",
        |ctx, args| {
            if let Some(Value::Object(Some(path_ref))) = args.first() {
                let path_str = match ctx.get_field(*path_ref, 0) {
                    Value::Object(Some(s)) => ctx.read_string(s).unwrap_or_default(),
                    _ => return Ok(Some(Value::Int(1))),
                };
                let not_exists = !std::path::Path::new(&path_str).exists();
                Ok(Some(Value::Int(if not_exists { 1 } else { 0 })))
            } else {
                Ok(Some(Value::Int(1)))
            }
        },
    );
    r.register(
        files,
        "isDirectory",
        "(Ljava/nio/file/Path;[Ljava/nio/file/LinkOption;)Z",
        |ctx, args| {
            if let Some(Value::Object(Some(path_ref))) = args.first() {
                let path_str = match ctx.get_field(*path_ref, 0) {
                    Value::Object(Some(s)) => ctx.read_string(s).unwrap_or_default(),
                    _ => return Ok(Some(Value::Int(0))),
                };
                let is_dir = std::path::Path::new(&path_str).is_dir();
                Ok(Some(Value::Int(if is_dir { 1 } else { 0 })))
            } else {
                Ok(Some(Value::Int(0)))
            }
        },
    );
    r.register(
        files,
        "isRegularFile",
        "(Ljava/nio/file/Path;[Ljava/nio/file/LinkOption;)Z",
        |ctx, args| {
            if let Some(Value::Object(Some(path_ref))) = args.first() {
                let path_str = match ctx.get_field(*path_ref, 0) {
                    Value::Object(Some(s)) => ctx.read_string(s).unwrap_or_default(),
                    _ => return Ok(Some(Value::Int(0))),
                };
                let is_file = std::path::Path::new(&path_str).is_file();
                Ok(Some(Value::Int(if is_file { 1 } else { 0 })))
            } else {
                Ok(Some(Value::Int(0)))
            }
        },
    );
    r.register(files, "size", "(Ljava/nio/file/Path;)J", |ctx, args| {
        if let Some(Value::Object(Some(path_ref))) = args.first() {
            let path_str = match ctx.get_field(*path_ref, 0) {
                Value::Object(Some(s)) => ctx.read_string(s).unwrap_or_default(),
                _ => return Ok(Some(Value::Long(0))),
            };
            let size = std::fs::metadata(&path_str)
                .map(|m| m.len() as i64)
                .unwrap_or(0);
            Ok(Some(Value::Long(size)))
        } else {
            Ok(Some(Value::Long(0)))
        }
    });
    r.register(
        files,
        "isReadable",
        "(Ljava/nio/file/Path;)Z",
        |ctx, args| {
            if let Some(Value::Object(Some(path_ref))) = args.first() {
                let path_str = match ctx.get_field(*path_ref, 0) {
                    Value::Object(Some(s)) => ctx.read_string(s).unwrap_or_default(),
                    _ => return Ok(Some(Value::Int(0))),
                };
                let readable = std::path::Path::new(&path_str).exists();
                Ok(Some(Value::Int(if readable { 1 } else { 0 })))
            } else {
                Ok(Some(Value::Int(0)))
            }
        },
    );
    r.register(
        files,
        "isWritable",
        "(Ljava/nio/file/Path;)Z",
        |ctx, args| {
            if let Some(Value::Object(Some(path_ref))) = args.first() {
                let path_str = match ctx.get_field(*path_ref, 0) {
                    Value::Object(Some(s)) => ctx.read_string(s).unwrap_or_default(),
                    _ => return Ok(Some(Value::Int(0))),
                };
                let writable = std::fs::metadata(&path_str)
                    .map(|m| !m.permissions().readonly())
                    .unwrap_or(false);
                Ok(Some(Value::Int(if writable { 1 } else { 0 })))
            } else {
                Ok(Some(Value::Int(0)))
            }
        },
    );

    // --- Path expansion ---
    let path = "java/nio/file/Path";
    r.register(
        path,
        "getFileName",
        "()Ljava/nio/file/Path;",
        |ctx, args| {
            let this = obj_arg(args, 0)?;
            let path_str = match ctx.get_field(this, 0) {
                Value::Object(Some(s)) => ctx.read_string(s).unwrap_or_default(),
                _ => return Ok(Some(Value::Object(None))),
            };
            let fname = std::path::Path::new(&path_str)
                .file_name()
                .and_then(|n| n.to_str())
                .unwrap_or("");
            let p = alloc_concurrent_synthetic(ctx, "java/nio/file/Path", 1);
            let s = ctx.create_string(fname);
            ctx.set_field(p, 0, Value::Object(Some(s)));
            Ok(Some(Value::Object(Some(p))))
        },
    );
    r.register(path, "getParent", "()Ljava/nio/file/Path;", |ctx, args| {
        let this = obj_arg(args, 0)?;
        let path_str = match ctx.get_field(this, 0) {
            Value::Object(Some(s)) => ctx.read_string(s).unwrap_or_default(),
            _ => return Ok(Some(Value::Object(None))),
        };
        if let Some(parent) = std::path::Path::new(&path_str)
            .parent()
            .and_then(|p| p.to_str())
        {
            if parent.is_empty() {
                return Ok(Some(Value::Object(None)));
            }
            let p = alloc_concurrent_synthetic(ctx, "java/nio/file/Path", 1);
            let s = ctx.create_string(parent);
            ctx.set_field(p, 0, Value::Object(Some(s)));
            Ok(Some(Value::Object(Some(p))))
        } else {
            Ok(Some(Value::Object(None)))
        }
    });
    r.register(
        path,
        "toAbsolutePath",
        "()Ljava/nio/file/Path;",
        |ctx, args| {
            let this = obj_arg(args, 0)?;
            let path_str = match ctx.get_field(this, 0) {
                Value::Object(Some(s)) => ctx.read_string(s).unwrap_or_default(),
                _ => return Ok(Some(Value::Object(Some(this)))),
            };
            let abs = std::fs::canonicalize(&path_str)
                .map(|p| p.to_string_lossy().into_owned())
                .unwrap_or(path_str);
            let p = alloc_concurrent_synthetic(ctx, "java/nio/file/Path", 1);
            let s = ctx.create_string(&abs);
            ctx.set_field(p, 0, Value::Object(Some(s)));
            Ok(Some(Value::Object(Some(p))))
        },
    );
    r.register(
        path,
        "resolve",
        "(Ljava/lang/String;)Ljava/nio/file/Path;",
        |ctx, args| {
            let this = obj_arg(args, 0)?;
            let base = match ctx.get_field(this, 0) {
                Value::Object(Some(s)) => ctx.read_string(s).unwrap_or_default(),
                _ => String::new(),
            };
            let other = match args.get(1) {
                Some(Value::Object(Some(s))) => ctx.read_string(*s).unwrap_or_default(),
                _ => String::new(),
            };
            let resolved = std::path::Path::new(&base)
                .join(&other)
                .to_string_lossy()
                .into_owned();
            let p = alloc_concurrent_synthetic(ctx, "java/nio/file/Path", 1);
            let s = ctx.create_string(&resolved);
            ctx.set_field(p, 0, Value::Object(Some(s)));
            Ok(Some(Value::Object(Some(p))))
        },
    );
    r.register(
        path,
        "resolve",
        "(Ljava/nio/file/Path;)Ljava/nio/file/Path;",
        |ctx, args| {
            let this = obj_arg(args, 0)?;
            let base = match ctx.get_field(this, 0) {
                Value::Object(Some(s)) => ctx.read_string(s).unwrap_or_default(),
                _ => String::new(),
            };
            let other = if let Some(Value::Object(Some(o))) = args.get(1) {
                match ctx.get_field(*o, 0) {
                    Value::Object(Some(s)) => ctx.read_string(s).unwrap_or_default(),
                    _ => String::new(),
                }
            } else {
                String::new()
            };
            let resolved = std::path::Path::new(&base)
                .join(&other)
                .to_string_lossy()
                .into_owned();
            let p = alloc_concurrent_synthetic(ctx, "java/nio/file/Path", 1);
            let s = ctx.create_string(&resolved);
            ctx.set_field(p, 0, Value::Object(Some(s)));
            Ok(Some(Value::Object(Some(p))))
        },
    );
    r.register(path, "getNameCount", "()I", |ctx, args| {
        let this = obj_arg(args, 0)?;
        let path_str = match ctx.get_field(this, 0) {
            Value::Object(Some(s)) => ctx.read_string(s).unwrap_or_default(),
            _ => return Ok(Some(Value::Int(0))),
        };
        let count = std::path::Path::new(&path_str).components().count() as i32;
        Ok(Some(Value::Int(count.max(0))))
    });
}

// URI/URL already fully implemented in earlier phases — no additions needed
pub(crate) fn register_p61_net(r: &mut NativeMethodRegistry) {
    // NetworkInterface = 5-field synthetic (name=0, displayName=1, addresses=2, index=3, flags=4)
    // flags: bit 0 = up, bit 1 = loopback, bit 2 = supportsMulticast
    let ni = "java/net/NetworkInterface";

    r.register(ni, "getNetworkInterfaces", "()Ljava/util/Enumeration;", |ctx, _args| {
        let interfaces = p61_build_network_interfaces(ctx);
        // Wrap in Enumeration (2-field: arr=0, pos=1)
        let enum_obj = alloc_concurrent_synthetic(ctx, "java/util/Enumeration", 2);
        let arr = ctx.new_array(rustjvm_types::ArrayElementType::Reference, interfaces.len());
        for (i, iface) in interfaces.iter().enumerate() {
            ctx.set_array_element(arr, i, Value::Object(Some(*iface)));
        }
        ctx.set_field(enum_obj, 0, Value::Object(Some(arr)));
        ctx.set_field(enum_obj, 1, Value::Int(0));
        Ok(Some(Value::Object(Some(enum_obj))))
    });

    r.register(ni, "getByName", "(Ljava/lang/String;)Ljava/net/NetworkInterface;", |ctx, args| {
        let name_ref = obj_arg(args, 1)?;
        let name = ctx.read_string(name_ref).unwrap_or_default();
        let interfaces = p61_build_network_interfaces(ctx);
        for iface in &interfaces {
            if let Value::Object(Some(s)) = ctx.get_field(*iface, 0) {
                if ctx.read_string(s).as_deref() == Some(&name) {
                    return Ok(Some(Value::Object(Some(*iface))));
                }
            }
        }
        Ok(Some(Value::Object(None)))
    });

    r.register(ni, "getByInetAddress", "(Ljava/net/InetAddress;)Ljava/net/NetworkInterface;", |ctx, args| {
        let addr_ref = obj_arg(args, 1)?;
        let addr_str = match ctx.get_field(addr_ref, 1) {
            Value::Object(Some(s)) => ctx.read_string(s).unwrap_or_default(),
            _ => String::new(),
        };
        let interfaces = p61_build_network_interfaces(ctx);
        for iface in &interfaces {
            if let Value::Object(Some(addrs)) = ctx.get_field(*iface, 2) {
                let len = ctx.array_length(addrs);
                for i in 0..len {
                    if let Value::Object(Some(ia)) = ctx.get_array_element(addrs, i) {
                        if let Value::Object(Some(s)) = ctx.get_field(ia, 1) {
                            if ctx.read_string(s).as_deref() == Some(&addr_str) {
                                return Ok(Some(Value::Object(Some(*iface))));
                            }
                        }
                    }
                }
            }
        }
        Ok(Some(Value::Object(None)))
    });

    r.register(ni, "getName", "()Ljava/lang/String;", |ctx, args| {
        let this = obj_arg(args, 0)?;
        Ok(Some(ctx.get_field(this, 0)))
    });
    r.register(ni, "getDisplayName", "()Ljava/lang/String;", |ctx, args| {
        let this = obj_arg(args, 0)?;
        Ok(Some(ctx.get_field(this, 1)))
    });
    r.register(ni, "getInetAddresses", "()Ljava/util/Enumeration;", |ctx, args| {
        let this = obj_arg(args, 0)?;
        let addrs = ctx.get_field(this, 2);
        let enum_obj = alloc_concurrent_synthetic(ctx, "java/util/Enumeration", 2);
        match addrs {
            Value::Object(Some(a)) => {
                ctx.set_field(enum_obj, 0, Value::Object(Some(a)));
                ctx.set_field(enum_obj, 1, Value::Int(0));
            }
            _ => {
                let empty = ctx.new_array(rustjvm_types::ArrayElementType::Reference, 0);
                ctx.set_field(enum_obj, 0, Value::Object(Some(empty)));
                ctx.set_field(enum_obj, 1, Value::Int(0));
            }
        }
        Ok(Some(Value::Object(Some(enum_obj))))
    });
    r.register(ni, "getIndex", "()I", |ctx, args| {
        let this = obj_arg(args, 0)?;
        Ok(Some(ctx.get_field(this, 3)))
    });
    r.register(ni, "isUp", "()Z", |ctx, args| {
        let this = obj_arg(args, 0)?;
        let flags = ctx.get_field(this, 4).as_int().unwrap_or(0);
        Ok(Some(Value::Int(if flags & 1 != 0 { 1 } else { 0 })))
    });
    r.register(ni, "isLoopback", "()Z", |ctx, args| {
        let this = obj_arg(args, 0)?;
        let flags = ctx.get_field(this, 4).as_int().unwrap_or(0);
        Ok(Some(Value::Int(if flags & 2 != 0 { 1 } else { 0 })))
    });
    r.register(ni, "supportsMulticast", "()Z", |ctx, args| {
        let this = obj_arg(args, 0)?;
        let flags = ctx.get_field(this, 4).as_int().unwrap_or(0);
        Ok(Some(Value::Int(if flags & 4 != 0 { 1 } else { 0 })))
    });
    r.register(ni, "isPointToPoint", "()Z", |_ctx, _args| {
        Ok(Some(Value::Int(0)))
    });
    r.register(ni, "isVirtual", "()Z", |_ctx, _args| {
        Ok(Some(Value::Int(0)))
    });
    r.register(ni, "getHardwareAddress", "()[B", |ctx, _args| {
        // Return a dummy MAC address (00:00:00:00:00:00) — real MAC requires platform APIs
        let mac = ctx.new_array(rustjvm_types::ArrayElementType::Byte, 6);
        for i in 0..6 { ctx.set_array_element(mac, i, Value::Int(0)); }
        Ok(Some(Value::Object(Some(mac))))
    });
    r.register(ni, "getMTU", "()I", |_ctx, _args| {
        Ok(Some(Value::Int(1500))) // standard ethernet MTU
    });
    r.register(ni, "getSubInterfaces", "()Ljava/util/Enumeration;", |ctx, _args| {
        let enum_obj = alloc_concurrent_synthetic(ctx, "java/util/Enumeration", 2);
        let arr = ctx.new_array(rustjvm_types::ArrayElementType::Reference, 0);
        ctx.set_field(enum_obj, 0, Value::Object(Some(arr)));
        ctx.set_field(enum_obj, 1, Value::Int(0));
        Ok(Some(Value::Object(Some(enum_obj))))
    });
    r.register(ni, "getParent", "()Ljava/net/NetworkInterface;", |_ctx, _args| {
        Ok(Some(Value::Object(None)))
    });
    r.register(ni, "equals", "(Ljava/lang/Object;)Z", |ctx, args| {
        let this = obj_arg(args, 0)?;
        let other = obj_arg(args, 1)?;
        let n1 = match ctx.get_field(this, 0) {
            Value::Object(Some(s)) => ctx.read_string(s).unwrap_or_default(),
            _ => String::new(),
        };
        let n2 = match ctx.get_field(other, 0) {
            Value::Object(Some(s)) => ctx.read_string(s).unwrap_or_default(),
            _ => String::new(),
        };
        Ok(Some(Value::Int(if n1 == n2 { 1 } else { 0 })))
    });
    r.register(ni, "hashCode", "()I", |ctx, args| {
        let this = obj_arg(args, 0)?;
        let name = match ctx.get_field(this, 0) {
            Value::Object(Some(s)) => ctx.read_string(s).unwrap_or_default(),
            _ => String::new(),
        };
        let mut hash: i32 = 0;
        for b in name.bytes() {
            hash = hash.wrapping_mul(31).wrapping_add(b as i32);
        }
        Ok(Some(Value::Int(hash)))
    });
    r.register(ni, "toString", "()Ljava/lang/String;", |ctx, args| {
        let this = obj_arg(args, 0)?;
        let name = match ctx.get_field(this, 0) {
            Value::Object(Some(s)) => ctx.read_string(s).unwrap_or_default(),
            _ => String::new(),
        };
        let s = ctx.create_string(&format!("name:{}", name));
        Ok(Some(Value::Object(Some(s))))
    });
}

/// Build the list of NetworkInterface synthetic objects for this host.
/// Returns loopback + primary interface (resolved via hostname DNS).
fn p61_build_network_interfaces(ctx: &mut dyn NativeContext) -> Vec<ObjectRef> {
    let mut result = Vec::new();

    // 1. Loopback interface
    let lo = alloc_concurrent_synthetic(ctx, "java/net/NetworkInterface", 5);
    let lo_name = ctx.create_string("lo");
    let lo_display = ctx.create_string("Loopback Interface");
    ctx.set_field(lo, 0, Value::Object(Some(lo_name)));
    ctx.set_field(lo, 1, Value::Object(Some(lo_display)));
    // InetAddress for 127.0.0.1
    let lo_addr = alloc_concurrent_synthetic(ctx, "java/net/InetAddress", 2);
    let lo_host = ctx.create_string("localhost");
    let lo_ip = ctx.create_string("127.0.0.1");
    ctx.set_field(lo_addr, 0, Value::Object(Some(lo_host)));
    ctx.set_field(lo_addr, 1, Value::Object(Some(lo_ip)));
    let lo_addrs = ctx.new_array(rustjvm_types::ArrayElementType::Reference, 1);
    ctx.set_array_element(lo_addrs, 0, Value::Object(Some(lo_addr)));
    ctx.set_field(lo, 2, Value::Object(Some(lo_addrs)));
    ctx.set_field(lo, 3, Value::Int(1)); // index
    ctx.set_field(lo, 4, Value::Int(0b111)); // up + loopback + multicast
    result.push(lo);

    // 2. Primary interface — resolve hostname to get primary IP. Use the
    //    portable hostname/IP helpers so this code path agrees with what
    //    `InetAddress.getLocalHost` returns and works identically on Linux,
    //    macOS, and Windows. (NEW-2 / C7)
    let hostname = crate::resolve_real_hostname();
    let primary_ip = crate::resolve_primary_ipv4(&hostname);

    if primary_ip != "127.0.0.1" {
        let eth = alloc_concurrent_synthetic(ctx, "java/net/NetworkInterface", 5);
        let eth_name = ctx.create_string("eth0");
        let eth_display = ctx.create_string("Primary Network Interface");
        ctx.set_field(eth, 0, Value::Object(Some(eth_name)));
        ctx.set_field(eth, 1, Value::Object(Some(eth_display)));
        let eth_addr = alloc_concurrent_synthetic(ctx, "java/net/InetAddress", 2);
        let eth_host = ctx.create_string(&hostname);
        let eth_ip = ctx.create_string(&primary_ip);
        ctx.set_field(eth_addr, 0, Value::Object(Some(eth_host)));
        ctx.set_field(eth_addr, 1, Value::Object(Some(eth_ip)));
        let eth_addrs = ctx.new_array(rustjvm_types::ArrayElementType::Reference, 1);
        ctx.set_array_element(eth_addrs, 0, Value::Object(Some(eth_addr)));
        ctx.set_field(eth, 2, Value::Object(Some(eth_addrs)));
        ctx.set_field(eth, 3, Value::Int(2)); // index
        ctx.set_field(eth, 4, Value::Int(0b101)); // up + multicast (not loopback)
        result.push(eth);
    }

    result
}

// =============================================================================
// Phase 62: CharBuffer, Time expansion (MonthDay/YearMonth/Year), NumberFormat
//           factories, Collectors expansion, NavigableMap/Set completion,
//           AbstractMap entries, StampedLock, ZipEntry
// =============================================================================

pub(crate) fn register_phase62_natives(registry: &mut NativeMethodRegistry) {
    register_p62_char_buffer(registry);
    register_p62_time_expansion(registry);
    register_p62_format_factories(registry);
    register_p62_navigable_expansion(registry);
    register_p62_abstract_map_entries(registry);
    register_p62_stamped_lock(registry);
    register_p62_zip_entry(registry);
}

// =============================================================================
// java.nio.CharBuffer = 5-field (array=0 char[], pos=1, limit=2, capacity=3, mark=4)
// =============================================================================

const CB_FIELD_ARRAY: usize = 0;
const CB_FIELD_POS: usize = 1;
const CB_FIELD_LIMIT: usize = 2;
const CB_FIELD_CAPACITY: usize = 3;
const CB_FIELD_MARK: usize = 4;

pub(crate) fn register_p62_char_buffer(r: &mut NativeMethodRegistry) {
    let cb = "java/nio/CharBuffer";
    r.register(cb, "allocate", "(I)Ljava/nio/CharBuffer;", |ctx, args| {
        let cap = match args.first() {
            Some(Value::Int(v)) => *v,
            _ => 16,
        };
        let buf = p62_alloc_char_buffer(ctx, cap.max(0) as usize);
        Ok(Some(Value::Object(Some(buf))))
    });
    r.register(cb, "wrap", "([C)Ljava/nio/CharBuffer;", |ctx, args| {
        let arr = match args.first() {
            Some(Value::Object(Some(a))) => *a,
            _ => return Ok(Some(Value::Object(None))),
        };
        let len = ctx.array_length(arr);
        let buf = alloc_concurrent_synthetic(ctx, "java/nio/CharBuffer", 5);
        ctx.set_field(buf, CB_FIELD_ARRAY, Value::Object(Some(arr)));
        ctx.set_field(buf, CB_FIELD_POS, Value::Int(0));
        ctx.set_field(buf, CB_FIELD_LIMIT, Value::Int(len as i32));
        ctx.set_field(buf, CB_FIELD_CAPACITY, Value::Int(len as i32));
        ctx.set_field(buf, CB_FIELD_MARK, Value::Int(-1));
        Ok(Some(Value::Object(Some(buf))))
    });
    r.register(
        cb,
        "wrap",
        "(Ljava/lang/CharSequence;)Ljava/nio/CharBuffer;",
        |ctx, args| {
            let s = match args.first() {
                Some(Value::Object(Some(s))) => ctx.read_string(*s).unwrap_or_default(),
                _ => String::new(),
            };
            let chars: Vec<u16> = s.encode_utf16().collect();
            let arr = ctx.new_array(rustjvm_types::ArrayElementType::Char, chars.len());
            for (i, &ch) in chars.iter().enumerate() {
                ctx.set_array_element(arr, i, Value::Int(ch as i32));
            }
            let buf = alloc_concurrent_synthetic(ctx, "java/nio/CharBuffer", 5);
            ctx.set_field(buf, CB_FIELD_ARRAY, Value::Object(Some(arr)));
            ctx.set_field(buf, CB_FIELD_POS, Value::Int(0));
            ctx.set_field(buf, CB_FIELD_LIMIT, Value::Int(chars.len() as i32));
            ctx.set_field(buf, CB_FIELD_CAPACITY, Value::Int(chars.len() as i32));
            ctx.set_field(buf, CB_FIELD_MARK, Value::Int(-1));
            Ok(Some(Value::Object(Some(buf))))
        },
    );
    r.register(cb, "get", "()C", |ctx, args| {
        let this = obj_arg(args, 0)?;
        let pos = match ctx.get_field(this, CB_FIELD_POS) {
            Value::Int(v) => v,
            _ => 0,
        };
        let lim = match ctx.get_field(this, CB_FIELD_LIMIT) {
            Value::Int(v) => v,
            _ => 0,
        };
        if pos >= lim {
            return Err(RuntimeError::IllegalStateException {
                message: "BufferUnderflowException".into(),
            }
            .into());
        }
        let arr = match ctx.get_field(this, CB_FIELD_ARRAY) {
            Value::Object(Some(a)) => a,
            _ => {
                return Err(RuntimeError::IllegalStateException {
                    message: "no backing array".into(),
                }
                .into())
            }
        };
        let ch = ctx.get_array_element(arr, pos as usize);
        ctx.set_field(this, CB_FIELD_POS, Value::Int(pos + 1));
        Ok(Some(ch))
    });
    r.register(cb, "get", "(I)C", |ctx, args| {
        let this = obj_arg(args, 0)?;
        let idx = match args.get(1) {
            Some(Value::Int(v)) => *v,
            _ => 0,
        };
        let lim = match ctx.get_field(this, CB_FIELD_LIMIT) {
            Value::Int(v) => v,
            _ => 0,
        };
        if idx < 0 || idx >= lim {
            return Err(RuntimeError::IllegalArgumentException {
                message: format!("index: {idx}"),
            }
            .into());
        }
        let arr = match ctx.get_field(this, CB_FIELD_ARRAY) {
            Value::Object(Some(a)) => a,
            _ => {
                return Err(RuntimeError::IllegalStateException {
                    message: "no backing array".into(),
                }
                .into())
            }
        };
        Ok(Some(ctx.get_array_element(arr, idx as usize)))
    });
    r.register(cb, "put", "(C)Ljava/nio/CharBuffer;", |ctx, args| {
        let this = obj_arg(args, 0)?;
        let ch = args.get(1).copied().unwrap_or(Value::Int(0));
        let pos = match ctx.get_field(this, CB_FIELD_POS) {
            Value::Int(v) => v,
            _ => 0,
        };
        let lim = match ctx.get_field(this, CB_FIELD_LIMIT) {
            Value::Int(v) => v,
            _ => 0,
        };
        if pos >= lim {
            return Err(RuntimeError::IllegalStateException {
                message: "BufferOverflowException".into(),
            }
            .into());
        }
        let arr = match ctx.get_field(this, CB_FIELD_ARRAY) {
            Value::Object(Some(a)) => a,
            _ => {
                return Err(RuntimeError::IllegalStateException {
                    message: "no backing array".into(),
                }
                .into())
            }
        };
        ctx.set_array_element(arr, pos as usize, ch);
        ctx.set_field(this, CB_FIELD_POS, Value::Int(pos + 1));
        Ok(Some(Value::Object(Some(this))))
    });
    r.register(cb, "flip", "()Ljava/nio/CharBuffer;", |ctx, args| {
        let this = obj_arg(args, 0)?;
        let pos = match ctx.get_field(this, CB_FIELD_POS) {
            Value::Int(v) => v,
            _ => 0,
        };
        ctx.set_field(this, CB_FIELD_LIMIT, Value::Int(pos));
        ctx.set_field(this, CB_FIELD_POS, Value::Int(0));
        ctx.set_field(this, CB_FIELD_MARK, Value::Int(-1));
        Ok(Some(Value::Object(Some(this))))
    });
    r.register(cb, "clear", "()Ljava/nio/CharBuffer;", |ctx, args| {
        let this = obj_arg(args, 0)?;
        let cap = match ctx.get_field(this, CB_FIELD_CAPACITY) {
            Value::Int(v) => v,
            _ => 0,
        };
        ctx.set_field(this, CB_FIELD_POS, Value::Int(0));
        ctx.set_field(this, CB_FIELD_LIMIT, Value::Int(cap));
        ctx.set_field(this, CB_FIELD_MARK, Value::Int(-1));
        Ok(Some(Value::Object(Some(this))))
    });
    r.register(cb, "rewind", "()Ljava/nio/CharBuffer;", |ctx, args| {
        let this = obj_arg(args, 0)?;
        ctx.set_field(this, CB_FIELD_POS, Value::Int(0));
        ctx.set_field(this, CB_FIELD_MARK, Value::Int(-1));
        Ok(Some(Value::Object(Some(this))))
    });
    r.register(cb, "remaining", "()I", |ctx, args| {
        let this = obj_arg(args, 0)?;
        let pos = match ctx.get_field(this, CB_FIELD_POS) {
            Value::Int(v) => v,
            _ => 0,
        };
        let lim = match ctx.get_field(this, CB_FIELD_LIMIT) {
            Value::Int(v) => v,
            _ => 0,
        };
        Ok(Some(Value::Int((lim - pos).max(0))))
    });
    r.register(cb, "hasRemaining", "()Z", |ctx, args| {
        let this = obj_arg(args, 0)?;
        let pos = match ctx.get_field(this, CB_FIELD_POS) {
            Value::Int(v) => v,
            _ => 0,
        };
        let lim = match ctx.get_field(this, CB_FIELD_LIMIT) {
            Value::Int(v) => v,
            _ => 0,
        };
        Ok(Some(Value::Int(if pos < lim { 1 } else { 0 })))
    });
    r.register(cb, "position", "()I", |ctx, args| {
        let this = obj_arg(args, 0)?;
        Ok(Some(ctx.get_field(this, CB_FIELD_POS)))
    });
    r.register(cb, "position", "(I)Ljava/nio/CharBuffer;", |ctx, args| {
        let this = obj_arg(args, 0)?;
        let new_pos = match args.get(1) {
            Some(Value::Int(v)) => *v,
            _ => 0,
        };
        ctx.set_field(this, CB_FIELD_POS, Value::Int(new_pos));
        Ok(Some(Value::Object(Some(this))))
    });
    r.register(cb, "limit", "()I", |ctx, args| {
        let this = obj_arg(args, 0)?;
        Ok(Some(ctx.get_field(this, CB_FIELD_LIMIT)))
    });
    r.register(cb, "limit", "(I)Ljava/nio/CharBuffer;", |ctx, args| {
        let this = obj_arg(args, 0)?;
        let new_lim = match args.get(1) {
            Some(Value::Int(v)) => *v,
            _ => 0,
        };
        ctx.set_field(this, CB_FIELD_LIMIT, Value::Int(new_lim));
        Ok(Some(Value::Object(Some(this))))
    });
    r.register(cb, "capacity", "()I", |ctx, args| {
        let this = obj_arg(args, 0)?;
        Ok(Some(ctx.get_field(this, CB_FIELD_CAPACITY)))
    });
    r.register(cb, "array", "()[C", |ctx, args| {
        let this = obj_arg(args, 0)?;
        Ok(Some(ctx.get_field(this, CB_FIELD_ARRAY)))
    });
    r.register(cb, "toString", "()Ljava/lang/String;", |ctx, args| {
        let this = obj_arg(args, 0)?;
        let pos = match ctx.get_field(this, CB_FIELD_POS) {
            Value::Int(v) => v as usize,
            _ => 0,
        };
        let lim = match ctx.get_field(this, CB_FIELD_LIMIT) {
            Value::Int(v) => v as usize,
            _ => 0,
        };
        let arr = match ctx.get_field(this, CB_FIELD_ARRAY) {
            Value::Object(Some(a)) => a,
            _ => {
                let s = ctx.create_string("");
                return Ok(Some(Value::Object(Some(s))));
            }
        };
        let mut chars = Vec::new();
        for i in pos..lim {
            if let Value::Int(ch) = ctx.get_array_element(arr, i) {
                chars.push(ch as u16);
            }
        }
        let text = String::from_utf16_lossy(&chars);
        let s = ctx.create_string(&text);
        Ok(Some(Value::Object(Some(s))))
    });

    // Also register under Buffer parent
    let buf = "java/nio/Buffer";
    r.register(buf, "position", "()I", |ctx, args| {
        let this = obj_arg(args, 0)?;
        Ok(Some(ctx.get_field(this, 1))) // pos field
    });
    r.register(buf, "limit", "()I", |ctx, args| {
        let this = obj_arg(args, 0)?;
        Ok(Some(ctx.get_field(this, 2)))
    });
    r.register(buf, "capacity", "()I", |ctx, args| {
        let this = obj_arg(args, 0)?;
        Ok(Some(ctx.get_field(this, 3)))
    });
}

fn p62_alloc_char_buffer(ctx: &mut dyn NativeContext, cap: usize) -> ObjectRef {
    let arr = ctx.new_array(rustjvm_types::ArrayElementType::Char, cap);
    let buf = alloc_concurrent_synthetic(ctx, "java/nio/CharBuffer", 5);
    ctx.set_field(buf, CB_FIELD_ARRAY, Value::Object(Some(arr)));
    ctx.set_field(buf, CB_FIELD_POS, Value::Int(0));
    ctx.set_field(buf, CB_FIELD_LIMIT, Value::Int(cap as i32));
    ctx.set_field(buf, CB_FIELD_CAPACITY, Value::Int(cap as i32));
    ctx.set_field(buf, CB_FIELD_MARK, Value::Int(-1));
    buf
}

// =============================================================================
// java.time expansion — MonthDay, YearMonth, Year
// =============================================================================

pub(crate) fn register_p62_time_expansion(r: &mut NativeMethodRegistry) {
    // --- Year = 1-field (year=0 Int) ---
    let yr = "java/time/Year";
    r.register(yr, "of", "(I)Ljava/time/Year;", |ctx, args| {
        let y = match args.first() {
            Some(Value::Int(v)) => *v,
            _ => 2000,
        };
        let obj = alloc_concurrent_synthetic(ctx, "java/time/Year", 1);
        ctx.set_field(obj, 0, Value::Int(y));
        Ok(Some(Value::Object(Some(obj))))
    });
    r.register(yr, "now", "()Ljava/time/Year;", |ctx, _args| {
        let obj = alloc_concurrent_synthetic(ctx, "java/time/Year", 1);
        ctx.set_field(obj, 0, Value::Int(2026));
        Ok(Some(Value::Object(Some(obj))))
    });
    r.register(yr, "getValue", "()I", |ctx, args| {
        let this = obj_arg(args, 0)?;
        Ok(Some(ctx.get_field(this, 0)))
    });
    r.register(yr, "isLeap", "()Z", |ctx, args| {
        let this = obj_arg(args, 0)?;
        let y = match ctx.get_field(this, 0) {
            Value::Int(v) => v,
            _ => 0,
        };
        let leap = (y % 4 == 0 && y % 100 != 0) || (y % 400 == 0);
        Ok(Some(Value::Int(if leap { 1 } else { 0 })))
    });
    r.register(yr, "isLeap", "(J)Z", |_ctx, args| {
        let y = match args.first() {
            Some(Value::Long(v)) => *v as i32,
            _ => 0,
        };
        let leap = (y % 4 == 0 && y % 100 != 0) || (y % 400 == 0);
        Ok(Some(Value::Int(if leap { 1 } else { 0 })))
    });
    r.register(yr, "length", "()I", |ctx, args| {
        let this = obj_arg(args, 0)?;
        let y = match ctx.get_field(this, 0) {
            Value::Int(v) => v,
            _ => 0,
        };
        let leap = (y % 4 == 0 && y % 100 != 0) || (y % 400 == 0);
        Ok(Some(Value::Int(if leap { 366 } else { 365 })))
    });
    r.register(yr, "plusYears", "(J)Ljava/time/Year;", |ctx, args| {
        let this = obj_arg(args, 0)?;
        let y = match ctx.get_field(this, 0) {
            Value::Int(v) => v,
            _ => 0,
        };
        let add = match args.get(1) {
            Some(Value::Long(v)) => *v as i32,
            _ => 0,
        };
        let obj = alloc_concurrent_synthetic(ctx, "java/time/Year", 1);
        ctx.set_field(obj, 0, Value::Int(y + add));
        Ok(Some(Value::Object(Some(obj))))
    });
    r.register(yr, "minusYears", "(J)Ljava/time/Year;", |ctx, args| {
        let this = obj_arg(args, 0)?;
        let y = match ctx.get_field(this, 0) {
            Value::Int(v) => v,
            _ => 0,
        };
        let sub = match args.get(1) {
            Some(Value::Long(v)) => *v as i32,
            _ => 0,
        };
        let obj = alloc_concurrent_synthetic(ctx, "java/time/Year", 1);
        ctx.set_field(obj, 0, Value::Int(y - sub));
        Ok(Some(Value::Object(Some(obj))))
    });
    r.register(yr, "toString", "()Ljava/lang/String;", |ctx, args| {
        let this = obj_arg(args, 0)?;
        let y = match ctx.get_field(this, 0) {
            Value::Int(v) => v,
            _ => 0,
        };
        let s = ctx.create_string(&format!("{y}"));
        Ok(Some(Value::Object(Some(s))))
    });
    r.register(yr, "compareTo", "(Ljava/time/Year;)I", |ctx, args| {
        let this = obj_arg(args, 0)?;
        let y1 = match ctx.get_field(this, 0) {
            Value::Int(v) => v,
            _ => 0,
        };
        let y2 = if let Some(Value::Object(Some(o))) = args.get(1) {
            match ctx.get_field(*o, 0) {
                Value::Int(v) => v,
                _ => 0,
            }
        } else {
            0
        };
        Ok(Some(Value::Int(y1.cmp(&y2) as i32)))
    });

    // --- YearMonth = 2-field (year=0, month=1 Int 1-12) ---
    let ym = "java/time/YearMonth";
    r.register(ym, "of", "(II)Ljava/time/YearMonth;", |ctx, args| {
        let y = match args.first() {
            Some(Value::Int(v)) => *v,
            _ => 2000,
        };
        let m = match args.get(1) {
            Some(Value::Int(v)) => *v,
            _ => 1,
        };
        let obj = alloc_concurrent_synthetic(ctx, "java/time/YearMonth", 2);
        ctx.set_field(obj, 0, Value::Int(y));
        ctx.set_field(obj, 1, Value::Int(m));
        Ok(Some(Value::Object(Some(obj))))
    });
    r.register(ym, "now", "()Ljava/time/YearMonth;", |ctx, _args| {
        let obj = alloc_concurrent_synthetic(ctx, "java/time/YearMonth", 2);
        ctx.set_field(obj, 0, Value::Int(2026));
        ctx.set_field(obj, 1, Value::Int(2));
        Ok(Some(Value::Object(Some(obj))))
    });
    r.register(ym, "getYear", "()I", |ctx, args| {
        let this = obj_arg(args, 0)?;
        Ok(Some(ctx.get_field(this, 0)))
    });
    r.register(ym, "getMonthValue", "()I", |ctx, args| {
        let this = obj_arg(args, 0)?;
        Ok(Some(ctx.get_field(this, 1)))
    });
    r.register(ym, "lengthOfMonth", "()I", |ctx, args| {
        let this = obj_arg(args, 0)?;
        let y = match ctx.get_field(this, 0) {
            Value::Int(v) => v,
            _ => 2000,
        };
        let m = match ctx.get_field(this, 1) {
            Value::Int(v) => v,
            _ => 1,
        };
        let days = p62_days_in_month(y, m);
        Ok(Some(Value::Int(days)))
    });
    r.register(ym, "plusMonths", "(J)Ljava/time/YearMonth;", |ctx, args| {
        let this = obj_arg(args, 0)?;
        let y = match ctx.get_field(this, 0) {
            Value::Int(v) => v,
            _ => 0,
        };
        let m = match ctx.get_field(this, 1) {
            Value::Int(v) => v,
            _ => 1,
        };
        let add = match args.get(1) {
            Some(Value::Long(v)) => *v as i32,
            _ => 0,
        };
        let total = (y * 12 + (m - 1)) + add;
        let new_y = total.div_euclid(12);
        let new_m = total.rem_euclid(12) + 1;
        let obj = alloc_concurrent_synthetic(ctx, "java/time/YearMonth", 2);
        ctx.set_field(obj, 0, Value::Int(new_y));
        ctx.set_field(obj, 1, Value::Int(new_m));
        Ok(Some(Value::Object(Some(obj))))
    });
    r.register(ym, "toString", "()Ljava/lang/String;", |ctx, args| {
        let this = obj_arg(args, 0)?;
        let y = match ctx.get_field(this, 0) {
            Value::Int(v) => v,
            _ => 0,
        };
        let m = match ctx.get_field(this, 1) {
            Value::Int(v) => v,
            _ => 1,
        };
        let s = ctx.create_string(&format!("{y:04}-{m:02}"));
        Ok(Some(Value::Object(Some(s))))
    });

    // --- MonthDay = 2-field (month=0, day=1) ---
    let md = "java/time/MonthDay";
    r.register(md, "of", "(II)Ljava/time/MonthDay;", |ctx, args| {
        let m = match args.first() {
            Some(Value::Int(v)) => *v,
            _ => 1,
        };
        let d = match args.get(1) {
            Some(Value::Int(v)) => *v,
            _ => 1,
        };
        let obj = alloc_concurrent_synthetic(ctx, "java/time/MonthDay", 2);
        ctx.set_field(obj, 0, Value::Int(m));
        ctx.set_field(obj, 1, Value::Int(d));
        Ok(Some(Value::Object(Some(obj))))
    });
    r.register(md, "getMonthValue", "()I", |ctx, args| {
        let this = obj_arg(args, 0)?;
        Ok(Some(ctx.get_field(this, 0)))
    });
    r.register(md, "getDayOfMonth", "()I", |ctx, args| {
        let this = obj_arg(args, 0)?;
        Ok(Some(ctx.get_field(this, 1)))
    });
    r.register(md, "isValidYear", "(I)Z", |ctx, args| {
        let this = obj_arg(args, 0)?;
        let m = match ctx.get_field(this, 0) {
            Value::Int(v) => v,
            _ => 1,
        };
        let d = match ctx.get_field(this, 1) {
            Value::Int(v) => v,
            _ => 1,
        };
        let y = match args.get(1) {
            Some(Value::Int(v)) => *v,
            _ => 2000,
        };
        let max = p62_days_in_month(y, m);
        Ok(Some(Value::Int(if d <= max { 1 } else { 0 })))
    });
    r.register(md, "toString", "()Ljava/lang/String;", |ctx, args| {
        let this = obj_arg(args, 0)?;
        let m = match ctx.get_field(this, 0) {
            Value::Int(v) => v,
            _ => 1,
        };
        let d = match ctx.get_field(this, 1) {
            Value::Int(v) => v,
            _ => 1,
        };
        let s = ctx.create_string(&format!("--{m:02}-{d:02}"));
        Ok(Some(Value::Object(Some(s))))
    });
}

fn p62_days_in_month(y: i32, m: i32) -> i32 {
    match m {
        1 | 3 | 5 | 7 | 8 | 10 | 12 => 31,
        4 | 6 | 9 | 11 => 30,
        2 => {
            if (y % 4 == 0 && y % 100 != 0) || y % 400 == 0 {
                29
            } else {
                28
            }
        }
        _ => 30,
    }
}

// =============================================================================
// java.text — NumberFormat/DateFormat static factories
// =============================================================================

pub(crate) fn register_p62_format_factories(r: &mut NativeMethodRegistry) {
    let nf = "java/text/NumberFormat";
    // NumberFormat = 3-field synthetic (like DecimalFormat: pattern=0, groupingUsed=1, maxFrac=2)
    r.register(
        nf,
        "getInstance",
        "()Ljava/text/NumberFormat;",
        p62_new_number_format,
    );
    r.register(
        nf,
        "getNumberInstance",
        "()Ljava/text/NumberFormat;",
        p62_new_number_format,
    );
    r.register(
        nf,
        "getIntegerInstance",
        "()Ljava/text/NumberFormat;",
        |ctx, _args| {
            let obj = alloc_concurrent_synthetic(ctx, "java/text/NumberFormat", 3);
            let pat = ctx.create_string("#,##0");
            ctx.set_field(obj, 0, Value::Object(Some(pat)));
            ctx.set_field(obj, 1, Value::Int(1)); // grouping used
            ctx.set_field(obj, 2, Value::Int(0)); // 0 fraction digits
            Ok(Some(Value::Object(Some(obj))))
        },
    );
    r.register(
        nf,
        "getCurrencyInstance",
        "()Ljava/text/NumberFormat;",
        |ctx, _args| {
            let obj = alloc_concurrent_synthetic(ctx, "java/text/NumberFormat", 3);
            let pat = ctx.create_string("$#,##0.00");
            ctx.set_field(obj, 0, Value::Object(Some(pat)));
            ctx.set_field(obj, 1, Value::Int(1));
            ctx.set_field(obj, 2, Value::Int(2));
            Ok(Some(Value::Object(Some(obj))))
        },
    );
    r.register(
        nf,
        "getPercentInstance",
        "()Ljava/text/NumberFormat;",
        |ctx, _args| {
            let obj = alloc_concurrent_synthetic(ctx, "java/text/NumberFormat", 3);
            let pat = ctx.create_string("#,##0%");
            ctx.set_field(obj, 0, Value::Object(Some(pat)));
            ctx.set_field(obj, 1, Value::Int(1));
            ctx.set_field(obj, 2, Value::Int(0));
            Ok(Some(Value::Object(Some(obj))))
        },
    );
    // Locale-specific variants (ignore locale, return default)
    r.register(
        nf,
        "getInstance",
        "(Ljava/util/Locale;)Ljava/text/NumberFormat;",
        p62_new_number_format,
    );
    r.register(
        nf,
        "getNumberInstance",
        "(Ljava/util/Locale;)Ljava/text/NumberFormat;",
        p62_new_number_format,
    );

    let df = "java/text/DateFormat";
    r.register(
        df,
        "getDateInstance",
        "()Ljava/text/DateFormat;",
        |ctx, _args| {
            let obj = alloc_concurrent_synthetic(ctx, "java/text/DateFormat", 3);
            let pat = ctx.create_string("MMM d, yyyy");
            ctx.set_field(obj, 0, Value::Object(Some(pat)));
            Ok(Some(Value::Object(Some(obj))))
        },
    );
    r.register(
        df,
        "getTimeInstance",
        "()Ljava/text/DateFormat;",
        |ctx, _args| {
            let obj = alloc_concurrent_synthetic(ctx, "java/text/DateFormat", 3);
            let pat = ctx.create_string("h:mm:ss a");
            ctx.set_field(obj, 0, Value::Object(Some(pat)));
            Ok(Some(Value::Object(Some(obj))))
        },
    );
    r.register(
        df,
        "getDateTimeInstance",
        "()Ljava/text/DateFormat;",
        |ctx, _args| {
            let obj = alloc_concurrent_synthetic(ctx, "java/text/DateFormat", 3);
            let pat = ctx.create_string("MMM d, yyyy h:mm:ss a");
            ctx.set_field(obj, 0, Value::Object(Some(pat)));
            Ok(Some(Value::Object(Some(obj))))
        },
    );
    r.register(
        df,
        "getDateInstance",
        "(I)Ljava/text/DateFormat;",
        |ctx, _args| {
            let obj = alloc_concurrent_synthetic(ctx, "java/text/DateFormat", 3);
            let pat = ctx.create_string("MMM d, yyyy");
            ctx.set_field(obj, 0, Value::Object(Some(pat)));
            Ok(Some(Value::Object(Some(obj))))
        },
    );
    r.register(
        df,
        "getTimeInstance",
        "(I)Ljava/text/DateFormat;",
        |ctx, _args| {
            let obj = alloc_concurrent_synthetic(ctx, "java/text/DateFormat", 3);
            let pat = ctx.create_string("h:mm:ss a");
            ctx.set_field(obj, 0, Value::Object(Some(pat)));
            Ok(Some(Value::Object(Some(obj))))
        },
    );
    r.register(
        df,
        "getDateTimeInstance",
        "(II)Ljava/text/DateFormat;",
        |ctx, _args| {
            let obj = alloc_concurrent_synthetic(ctx, "java/text/DateFormat", 3);
            let pat = ctx.create_string("MMM d, yyyy h:mm:ss a");
            ctx.set_field(obj, 0, Value::Object(Some(pat)));
            Ok(Some(Value::Object(Some(obj))))
        },
    );

    // Format base class
    let fmt = "java/text/Format";
    r.register(
        fmt,
        "format",
        "(Ljava/lang/Object;)Ljava/lang/String;",
        |ctx, args| {
            // Default: call toString on the object
            if let Some(Value::Object(Some(obj))) = args.get(1) {
                let s = ctx.create_string(&format!("{:?}", obj.as_ptr()));
                Ok(Some(Value::Object(Some(s))))
            } else {
                let s = ctx.create_string("null");
                Ok(Some(Value::Object(Some(s))))
            }
        },
    );
}

fn p62_new_number_format(ctx: &mut dyn NativeContext, _args: &[Value]) -> MethodCallResult {
    let obj = alloc_concurrent_synthetic(ctx, "java/text/NumberFormat", 3);
    let pat = ctx.create_string("#,##0.###");
    ctx.set_field(obj, 0, Value::Object(Some(pat)));
    ctx.set_field(obj, 1, Value::Int(1));
    ctx.set_field(obj, 2, Value::Int(3));
    Ok(Some(Value::Object(Some(obj))))
}

