/// Build a Java String[] from a Rust slice of &str.
fn make_string_array(ctx: &mut dyn NativeContext, items: &[&str]) -> ObjectRef {
    let arr = ctx.new_array(rustjvm_types::ArrayElementType::Reference, items.len());
    for (i, s) in items.iter().enumerate() {
        let js = ctx.create_string(s);
        ctx.set_array_element(arr, i, Value::Object(Some(js)));
    }
    arr
}

/// Put a String[] under a key into a HashMap.
fn put_arr(
    ctx: &mut dyn NativeContext,
    map: ObjectRef,
    key: &str,
    items: &[&str],
) {
    let k = ctx.create_string(key);
    let arr = make_string_array(ctx, items);
    rustjvm_native_collections::native_map_put_pub(
        ctx,
        &[
            Value::Object(Some(map)),
            Value::Object(Some(k)),
            Value::Object(Some(arr)),
        ],
    )
    .ok();
}

/// Put a String value under a key into a HashMap.
fn put_str(
    ctx: &mut dyn NativeContext,
    map: ObjectRef,
    key: &str,
    value: &str,
) {
    let k = ctx.create_string(key);
    let v = ctx.create_string(value);
    rustjvm_native_collections::native_map_put_pub(
        ctx,
        &[
            Value::Object(Some(map)),
            Value::Object(Some(k)),
            Value::Object(Some(v)),
        ],
    )
    .ok();
}

/// Populate a synthetic English-US `sun.text.resources.FormatData` bundle map.
fn populate_format_data_en(ctx: &mut dyn NativeContext, map: ObjectRef) {
    // 13 entries (12 months + empty 13th for lunar calendar slot, JDK convention).
    put_arr(
        ctx,
        map,
        "MonthNames",
        &[
            "January", "February", "March", "April", "May", "June", "July",
            "August", "September", "October", "November", "December", "",
        ],
    );
    put_arr(
        ctx,
        map,
        "MonthAbbreviations",
        &[
            "Jan", "Feb", "Mar", "Apr", "May", "Jun", "Jul", "Aug", "Sep",
            "Oct", "Nov", "Dec", "",
        ],
    );
    put_arr(
        ctx,
        map,
        "MonthNarrows",
        &["J", "F", "M", "A", "M", "J", "J", "A", "S", "O", "N", "D", ""],
    );
    put_arr(
        ctx,
        map,
        "standalone.MonthNames",
        &[
            "January", "February", "March", "April", "May", "June", "July",
            "August", "September", "October", "November", "December", "",
        ],
    );
    put_arr(
        ctx,
        map,
        "standalone.MonthAbbreviations",
        &[
            "Jan", "Feb", "Mar", "Apr", "May", "Jun", "Jul", "Aug", "Sep",
            "Oct", "Nov", "Dec", "",
        ],
    );
    put_arr(
        ctx,
        map,
        "standalone.MonthNarrows",
        &["J", "F", "M", "A", "M", "J", "J", "A", "S", "O", "N", "D", ""],
    );
    // 8 slots: index 0 unused, 1=Sunday..7=Saturday.
    put_arr(
        ctx,
        map,
        "DayNames",
        &[
            "", "Sunday", "Monday", "Tuesday", "Wednesday", "Thursday",
            "Friday", "Saturday",
        ],
    );
    put_arr(
        ctx,
        map,
        "DayAbbreviations",
        &["", "Sun", "Mon", "Tue", "Wed", "Thu", "Fri", "Sat"],
    );
    put_arr(
        ctx,
        map,
        "DayNarrows",
        &["", "S", "M", "T", "W", "T", "F", "S"],
    );
    put_arr(
        ctx,
        map,
        "standalone.DayNames",
        &[
            "", "Sunday", "Monday", "Tuesday", "Wednesday", "Thursday",
            "Friday", "Saturday",
        ],
    );
    put_arr(
        ctx,
        map,
        "standalone.DayAbbreviations",
        &["", "Sun", "Mon", "Tue", "Wed", "Thu", "Fri", "Sat"],
    );
    put_arr(
        ctx,
        map,
        "standalone.DayNarrows",
        &["", "S", "M", "T", "W", "T", "F", "S"],
    );
    put_arr(ctx, map, "AmPmMarkers", &["AM", "PM"]);
    put_arr(ctx, map, "narrow.AmPmMarkers", &["a", "p"]);
    put_arr(ctx, map, "Eras", &["BC", "AD"]);
    put_arr(ctx, map, "short.Eras", &["BC", "AD"]);
    put_arr(ctx, map, "narrow.Eras", &["B", "A"]);
    put_arr(ctx, map, "QuarterNames", &["1st quarter", "2nd quarter", "3rd quarter", "4th quarter"]);
    put_arr(ctx, map, "QuarterAbbreviations", &["Q1", "Q2", "Q3", "Q4"]);
    put_arr(ctx, map, "QuarterNarrows", &["1", "2", "3", "4"]);
    put_arr(ctx, map, "standalone.QuarterNames", &["1st quarter", "2nd quarter", "3rd quarter", "4th quarter"]);
    put_arr(ctx, map, "standalone.QuarterAbbreviations", &["Q1", "Q2", "Q3", "Q4"]);
    put_arr(ctx, map, "standalone.QuarterNarrows", &["1", "2", "3", "4"]);
    // Standard 9-element layout used by SimpleDateFormat:
    // 4 time patterns (FULL/LONG/MEDIUM/SHORT), 4 date patterns, 1 date-time combiner.
    put_arr(
        ctx,
        map,
        "DateTimePatterns",
        &[
            "h:mm:ss a zzzz",
            "h:mm:ss a z",
            "h:mm:ss a",
            "h:mm a",
            "EEEE, MMMM d, yyyy",
            "MMMM d, yyyy",
            "MMM d, yyyy",
            "M/d/yy",
            "{1} {0}",
        ],
    );
    // Calendar-keyed variant of DateTimePatterns used by some JDK paths.
    put_arr(
        ctx,
        map,
        "gregorian.DateTimePatterns",
        &[
            "h:mm:ss a zzzz",
            "h:mm:ss a z",
            "h:mm:ss a",
            "h:mm a",
            "EEEE, MMMM d, yyyy",
            "MMMM d, yyyy",
            "MMM d, yyyy",
            "M/d/yy",
            "{1} {0}",
        ],
    );
    put_arr(ctx, map, "DateTimePatternChars", &["GyMdkHmsSEDFwWahKzZYuXL"]);
    // Number format patterns: number / currency / percent / scientific.
    put_arr(
        ctx,
        map,
        "NumberPatterns",
        &["#,##0.###", "\u{00A4}#,##0.00;(\u{00A4}#,##0.00)", "#,##0%", "#E0"],
    );
    put_arr(
        ctx,
        map,
        "NumberElements",
        &[".", ",", ";", "%", "0", "#", "-", "E", "\u{2030}", "\u{221E}", "NaN"],
    );
    put_str(ctx, map, "TimePatternChars", "hHmsSaEcLkKzZ");
}

/// Populate a synthetic `sun.util.resources.LocaleNames` (English) bundle map.
fn populate_locale_names_en(ctx: &mut dyn NativeContext, map: ObjectRef) {
    // Minimal language/country names that cover the common queries; for any
    // missing key callers fall back to the locale code via getDisplayName
    // overrides we register elsewhere.
    let langs: &[(&str, &str)] = &[
        ("en", "English"), ("fr", "French"), ("de", "German"),
        ("es", "Spanish"), ("it", "Italian"), ("ja", "Japanese"),
        ("ko", "Korean"), ("zh", "Chinese"), ("ru", "Russian"),
        ("pt", "Portuguese"), ("nl", "Dutch"), ("sv", "Swedish"),
        ("ar", "Arabic"), ("hi", "Hindi"), ("tr", "Turkish"),
    ];
    let countries: &[(&str, &str)] = &[
        ("US", "United States"), ("GB", "United Kingdom"), ("CA", "Canada"),
        ("FR", "France"), ("DE", "Germany"), ("ES", "Spain"),
        ("IT", "Italy"), ("JP", "Japan"), ("CN", "China"),
        ("KR", "South Korea"), ("RU", "Russia"), ("BR", "Brazil"),
        ("AU", "Australia"), ("NL", "Netherlands"), ("SE", "Sweden"),
        ("MX", "Mexico"), ("IN", "India"), ("ZA", "South Africa"),
    ];
    for (k, v) in langs {
        put_str(ctx, map, k, v);
    }
    for (k, v) in countries {
        put_str(ctx, map, k, v);
    }
}

/// Populate a synthetic `sun.util.resources.CalendarData` (English) bundle map.
fn populate_calendar_data_en(ctx: &mut dyn NativeContext, map: ObjectRef) {
    put_str(ctx, map, "firstDayOfWeek", "1"); // Sunday
    put_str(ctx, map, "minimalDaysInFirstWeek", "1");
}

/// Populate a synthetic `sun.util.resources.CurrencyNames` bundle map.
fn populate_currency_names_en(ctx: &mut dyn NativeContext, map: ObjectRef) {
    put_str(ctx, map, "USD", "US Dollar");
    put_str(ctx, map, "EUR", "Euro");
    put_str(ctx, map, "GBP", "British Pound");
    put_str(ctx, map, "JPY", "Japanese Yen");
    put_str(ctx, map, "CNY", "Chinese Yuan");
    put_str(ctx, map, "usd", "$");
    put_str(ctx, map, "eur", "\u{20AC}");
    put_str(ctx, map, "gbp", "\u{00A3}");
    put_str(ctx, map, "jpy", "\u{00A5}");
}

/// Load a ResourceBundle from a .properties file on the classpath, with a
/// fallback synthetic English-US population for well-known JDK locale
/// bundles whose real class-based implementations live in the
/// `jdk.localedata` module that our jimage path does not surface.
fn resource_bundle_get_bundle(ctx: &mut dyn NativeContext, args: &[Value]) -> MethodCallResult {
    let bundle_name = match args.first() {
        Some(Value::Object(Some(s))) => ctx.read_string(*s).unwrap_or_default(),
        _ => String::new(),
    };
    let obj = alloc_concurrent_synthetic(ctx, "java/util/ResourceBundle", 2);
    let map = alloc_concurrent_synthetic(ctx, "java/util/HashMap", 3);
    rustjvm_native_collections::native_map_init(ctx, &[Value::Object(Some(map))]).ok();
    ctx.set_field(obj, 0, Value::Object(Some(map)));
    ctx.set_field(obj, 1, Value::Object(None));

    // Try to load the .properties file from classpath
    let resource_name = format!("{}.properties", bundle_name.replace('.', "/"));
    let mut populated_from_props = false;
    if let Some(bytes) = ctx.find_resource(&resource_name) {
        if let Ok(content) = String::from_utf8(bytes) {
            for line in content.lines() {
                let line = line.trim();
                if line.is_empty() || line.starts_with('#') || line.starts_with('!') {
                    continue;
                }
                // Split on '=' or ':'
                let sep_pos = line.find(|c: char| c == '=' || c == ':');
                if let Some(pos) = sep_pos {
                    let key = line[..pos].trim();
                    let value = line[pos + 1..].trim();
                    let k = ctx.create_string(key);
                    let v = ctx.create_string(value);
                    rustjvm_native_collections::native_map_put_pub(
                        ctx, &[Value::Object(Some(map)), Value::Object(Some(k)), Value::Object(Some(v))]
                    ).ok();
                    populated_from_props = true;
                }
            }
        }
    }

    // Synthetic fallback for locale-data bundles that the JDK loads from
    // class files inside `jdk.localedata` (not surfaced by our jimage path).
    // We always merge these in for the matching base names so callers get
    // sensible English-US defaults — Jackson's StdDateFormat needs
    // MonthNames / DayNames / AmPmMarkers / Eras / DateTimePatterns at
    // minimum.
    if !populated_from_props {
        let bn = bundle_name.as_str();
        if bn.starts_with("sun.text.resources.FormatData")
            || bn.starts_with("sun.text.resources.cldr.FormatData")
            || bn.starts_with("sun.text.resources.ext.FormatData")
        {
            populate_format_data_en(ctx, map);
        } else if bn.starts_with("sun.util.resources.LocaleNames")
            || bn.starts_with("sun.util.resources.cldr.LocaleNames")
            || bn.starts_with("sun.util.resources.ext.LocaleNames")
        {
            populate_locale_names_en(ctx, map);
        } else if bn.starts_with("sun.util.resources.CalendarData")
            || bn.starts_with("sun.util.resources.cldr.CalendarData")
        {
            populate_calendar_data_en(ctx, map);
        } else if bn.starts_with("sun.util.resources.CurrencyNames")
            || bn.starts_with("sun.util.resources.cldr.CurrencyNames")
        {
            populate_currency_names_en(ctx, map);
        }
    }

    Ok(Some(Value::Object(Some(obj))))
}

// =============================================================================
// java.util.ServiceLoader — basic service discovery
// ServiceLoader = 2-field (services=0 ArrayList, service_class=1 Class)
// =============================================================================

/// Static registry of known service provider implementations.
/// Maps service interface name → list of implementation class names.
fn service_provider_registry() -> &'static std::collections::HashMap<&'static str, &'static [&'static str]> {
    use std::sync::OnceLock;
    static REGISTRY: OnceLock<std::collections::HashMap<&str, &[&str]>> = OnceLock::new();
    REGISTRY.get_or_init(|| {
        let mut m = std::collections::HashMap::new();
        m.insert("java.nio.charset.spi.CharsetProvider", &["sun.nio.cs.StandardCharsets"][..]);
        m.insert("java.util.spi.ToolProvider", &[][..]);
        m.insert("java.util.logging.LogManager", &["java.util.logging.LogManager"][..]);
        m.insert("javax.xml.parsers.DocumentBuilderFactory", &["javax.xml.parsers.DocumentBuilderFactory"][..]);
        m.insert("javax.xml.parsers.SAXParserFactory", &["javax.xml.parsers.SAXParserFactory"][..]);
        m.insert("javax.xml.transform.TransformerFactory", &["javax.xml.transform.TransformerFactory"][..]);
        m.insert("java.security.Provider", &["SUN", "SunJCE", "SunRsaSign", "SunEC", "SunJSSE"][..]);
        m
    })
}

pub(crate) fn register_p63_service_loader(r: &mut NativeMethodRegistry) {
    let sl = "java/util/ServiceLoader";
    r.register(
        sl,
        "load",
        "(Ljava/lang/Class;)Ljava/util/ServiceLoader;",
        |ctx, args| {
            let class_ref = args.first().copied().unwrap_or(Value::Object(None));
            let obj = alloc_concurrent_synthetic(ctx, "java/util/ServiceLoader", 2);
            // Try to discover providers for this service class
            let class_name = match class_ref {
                Value::Object(Some(cls)) => {
                    match ctx.invoke_virtual(cls, "getName", "()Ljava/lang/String;", &[]) {
                        Ok(Some(Value::Object(Some(s)))) => ctx.read_string(s).unwrap_or_default(),
                        _ => String::new(),
                    }
                }
                _ => String::new(),
            };
            let providers = service_provider_registry()
                .get(class_name.as_str())
                .copied()
                .unwrap_or(&[]);
            let al = alloc_concurrent_synthetic(ctx, "java/util/ArrayList", 2);
            let arr = ctx.new_array(rustjvm_types::ArrayElementType::Reference, providers.len().max(1));
            for (i, &pname) in providers.iter().enumerate() {
                let s = ctx.create_string(pname);
                ctx.set_array_element(arr, i, Value::Object(Some(s)));
            }
            ctx.set_field(al, 0, Value::Object(Some(arr)));
            ctx.set_field(al, 1, Value::Int(providers.len() as i32));
            ctx.set_field(obj, 0, Value::Object(Some(al)));
            ctx.set_field(obj, 1, class_ref);
            Ok(Some(Value::Object(Some(obj))))
        },
    );
    r.register(
        sl,
        "load",
        "(Ljava/lang/Class;Ljava/lang/ClassLoader;)Ljava/util/ServiceLoader;",
        |ctx, args| {
            let class_ref = args.first().copied().unwrap_or(Value::Object(None));
            let obj = alloc_concurrent_synthetic(ctx, "java/util/ServiceLoader", 2);
            let class_name = match class_ref {
                Value::Object(Some(cls)) => {
                    match ctx.invoke_virtual(cls, "getName", "()Ljava/lang/String;", &[]) {
                        Ok(Some(Value::Object(Some(s)))) => ctx.read_string(s).unwrap_or_default(),
                        _ => String::new(),
                    }
                }
                _ => String::new(),
            };
            let providers = service_provider_registry()
                .get(class_name.as_str())
                .copied()
                .unwrap_or(&[]);
            let al = alloc_concurrent_synthetic(ctx, "java/util/ArrayList", 2);
            let arr = ctx.new_array(rustjvm_types::ArrayElementType::Reference, providers.len().max(1));
            for (i, &pname) in providers.iter().enumerate() {
                let s = ctx.create_string(pname);
                ctx.set_array_element(arr, i, Value::Object(Some(s)));
            }
            ctx.set_field(al, 0, Value::Object(Some(arr)));
            ctx.set_field(al, 1, Value::Int(providers.len() as i32));
            ctx.set_field(obj, 0, Value::Object(Some(al)));
            ctx.set_field(obj, 1, class_ref);
            Ok(Some(Value::Object(Some(obj))))
        },
    );
    r.register(sl, "iterator", "()Ljava/util/Iterator;", |ctx, args| {
        let this = obj_arg(args, 0)?;
        let services = ctx.get_field(this, 0);
        let itr = alloc_concurrent_synthetic(ctx, "java/util/ServiceLoader$Itr", 2);
        ctx.set_field(itr, 0, services); // the ArrayList
        ctx.set_field(itr, 1, Value::Int(0)); // current index
        Ok(Some(Value::Object(Some(itr))))
    });
    r.register(sl, "stream", "()Ljava/util/stream/Stream;", |ctx, args| {
        let this = obj_arg(args, 0)?;
        if let Value::Object(Some(al)) = ctx.get_field(this, 0) {
            if let Value::Object(Some(arr)) = ctx.get_field(al, 0) {
                let len = ctx.get_field(al, 1).as_int().unwrap_or(0) as usize;
                let stream_arr = ctx.new_array(rustjvm_types::ArrayElementType::Reference, len);
                for i in 0..len {
                    ctx.set_array_element(stream_arr, i, ctx.get_array_element(arr, i));
                }
                let stream = alloc_concurrent_synthetic(ctx, "java/util/stream/Stream", 1);
                ctx.set_field(stream, 0, Value::Object(Some(stream_arr)));
                return Ok(Some(Value::Object(Some(stream))));
            }
        }
        let arr = ctx.new_array(rustjvm_types::ArrayElementType::Reference, 0);
        let stream = alloc_concurrent_synthetic(ctx, "java/util/stream/Stream", 1);
        ctx.set_field(stream, 0, Value::Object(Some(arr)));
        Ok(Some(Value::Object(Some(stream))))
    });
    r.register(sl, "findFirst", "()Ljava/util/Optional;", |ctx, args| {
        let this = obj_arg(args, 0)?;
        let opt = alloc_concurrent_synthetic(ctx, "java/util/Optional", 1);
        if let Value::Object(Some(al)) = ctx.get_field(this, 0) {
            let len = ctx.get_field(al, 1).as_int().unwrap_or(0);
            if len > 0 {
                if let Value::Object(Some(arr)) = ctx.get_field(al, 0) {
                    let first = ctx.get_array_element(arr, 0);
                    ctx.set_field(opt, 0, first);
                    return Ok(Some(Value::Object(Some(opt))));
                }
            }
        }
        ctx.set_field(opt, 0, Value::Object(None));
        Ok(Some(Value::Object(Some(opt))))
    });
    r.register(sl, "reload", "()V", |ctx, args| {
        // Reset the iterator index and re-fetch providers on next iteration
        let this = obj_arg(args, 0)?;
        // ServiceLoader has at least 2 fields (services list, class)
        if ctx.object_num_fields(this) > 0 {
            // Re-allocate the services list by re-running load logic via the class reference
            // Simplest: just reset the list to empty — providers are re-created on iterator()
            if let Value::Object(Some(al)) = ctx.get_field(this, 0) {
                // Clear the ArrayList size
                if ctx.object_num_fields(al) > 1 {
                    ctx.set_field(al, 1, Value::Int(0));
                }
            }
        }
        Ok(None)
    });
    r.register(sl, "toString", "()Ljava/lang/String;", |ctx, _args| {
        let s = ctx.create_string("ServiceLoader[]");
        Ok(Some(Value::Object(Some(s))))
    });
}

// =============================================================================
// java.lang.invoke.MethodHandles.Lookup — factory + lookup methods
// Lookup = 2-field (lookupClass=0, allowedModes=1)
// =============================================================================

// =============================================================================
// java.util.concurrent.ScheduledExecutorService — real delayed execution
// ScheduledThreadPoolExecutor = 2-field (corePoolSize=0, shutdown=1)
// =============================================================================

/// Convert a time value + TimeUnit argument to milliseconds.
/// TimeUnit ordinals: 0=NANOSECONDS, 1=MICROSECONDS, 2=MILLISECONDS, 3=SECONDS, 4=MINUTES, 5=HOURS, 6=DAYS
fn scheduled_convert_to_millis(ctx: &mut dyn NativeContext, value: i64, unit_arg: Option<&Value>) -> i64 {
    let ordinal = match unit_arg {
        Some(Value::Object(Some(unit_obj))) => {
            // TimeUnit stores ordinal in field 0
            ctx.get_field(*unit_obj, 0).as_int().unwrap_or(2) // default MILLISECONDS
        }
        _ => 2, // MILLISECONDS
    };
    match ordinal {
        0 => value / 1_000_000,            // NANOSECONDS
        1 => value / 1_000,               // MICROSECONDS
        2 => value,                        // MILLISECONDS
        3 => value * 1_000,               // SECONDS
        4 => value * 60_000,              // MINUTES
        5 => value * 3_600_000,           // HOURS
        6 => value * 86_400_000,          // DAYS
        _ => value,
    }
}

pub(crate) fn register_p63_scheduled_executor(r: &mut NativeMethodRegistry) {
    fn stpe_ensure_work_queue(ctx: &mut dyn NativeContext, this: ObjectRef) {
        let has_queue = matches!(ctx.get_field_by_name(this, "workQueue"), Value::Object(Some(_)));
        if has_queue {
            return;
        }
        // Real JDK STPE expects a non-null workQueue before delayedExecute().
        // Prefer DelayedWorkQueue; fall back to PriorityBlockingQueue.
        let queue = match ctx.new_object("java/util/concurrent/ScheduledThreadPoolExecutor$DelayedWorkQueue") {
            Ok(Some(Value::Object(Some(q)))) => {
                let _ = ctx.invoke_special(
                    "java/util/concurrent/ScheduledThreadPoolExecutor$DelayedWorkQueue",
                    "<init>",
                    "()V",
                    &[Value::Object(Some(q))],
                );
                Some(q)
            }
            _ => match ctx.new_object("java/util/concurrent/PriorityBlockingQueue") {
                Ok(Some(Value::Object(Some(q)))) => {
                    let _ = ctx.invoke_special(
                        "java/util/concurrent/PriorityBlockingQueue",
                        "<init>",
                        "()V",
                        &[Value::Object(Some(q))],
                    );
                    Some(q)
                }
                _ => None,
            },
        };
        if let Some(q) = queue {
            ctx.set_field_by_name(this, "workQueue", Value::Object(Some(q)));
        }
    }
    fn stpe_init_common(ctx: &mut dyn NativeContext, this: ObjectRef, cores: i32) {
        let cores = cores.max(1);
        ctx.set_field(this, 0, Value::Int(cores));
        ctx.set_field(this, 1, Value::Int(0));
        ctx.set_field_by_name(this, "corePoolSize", Value::Int(cores));
        ctx.set_field_by_name(this, "maximumPoolSize", Value::Int(cores.max(1)));
        ctx.set_field_by_name(this, "largestPoolSize", Value::Int(cores.max(1)));
        ctx.set_field_by_name(this, "poolSize", Value::Int(cores.max(1)));
        stpe_ensure_work_queue(ctx, this);
    }
    fn stpe_new_executor(ctx: &mut dyn NativeContext, cores: i32) -> Option<ObjectRef> {
        let cores = cores.max(1);
        let obj = match ctx.new_object("java/util/concurrent/ScheduledThreadPoolExecutor") {
            Ok(Some(Value::Object(Some(o)))) => o,
            _ => return None,
        };
        let _ = ctx.invoke_special(
            "java/util/concurrent/ScheduledThreadPoolExecutor",
            "<init>",
            "(I)V",
            &[Value::Object(Some(obj)), Value::Int(cores)],
        );
        stpe_init_common(ctx, obj, cores);
        Some(obj)
    }

    let stpe = "java/util/concurrent/ScheduledThreadPoolExecutor";
    r.register(stpe, "<init>", "(I)V", |ctx, args| {
        let this = obj_arg(args, 0)?;
        let cores = match args.get(1) {
            Some(Value::Int(v)) => *v,
            _ => 1,
        };
        stpe_init_common(ctx, this, cores);
        Ok(None)
    });
    r.register(
        stpe,
        "<init>",
        "(ILjava/util/concurrent/ThreadFactory;)V",
        |ctx, args| {
            let this = obj_arg(args, 0)?;
            let cores = match args.get(1) {
                Some(Value::Int(v)) => *v,
                _ => 1,
            };
            stpe_init_common(ctx, this, cores);
            Ok(None)
        },
    );
    // WP4.5 — registry-driven scheduling. The pump in
    // `crate::scheduled_pump` invokes `runnable.run()` from the next
    // `Thread.sleep` / `awaitTermination` so periodic tasks observe the
    // configured cadence rather than firing exactly once inline.
    //
    // The synthetic `ScheduledFuture` stores the registry id in field 0
    // (cast to Long) and the done-flag in field 1 so `cancel(boolean)`
    // can look the task up and flip the cancelled flag. Field 0 used to
    // carry the result reference for `Future.get()` — we keep that
    // surface by routing `get()` through the pump's done-tracking.
    fn build_sf(ctx: &mut dyn rustjvm_native_api::NativeContext, id: u64) -> rustjvm_types::ObjectRef {
        let sf = alloc_concurrent_synthetic(ctx, "java/util/concurrent/ScheduledFuture", 2);
        ctx.set_field(sf, 0, Value::Long(id as i64));
        ctx.set_field(sf, 1, Value::Int(0));
        sf
    }

    r.register(stpe, "schedule", "(Ljava/lang/Runnable;JLjava/util/concurrent/TimeUnit;)Ljava/util/concurrent/ScheduledFuture;", |ctx, args| {
        let runnable = match args.get(1) {
            Some(Value::Object(Some(r))) => *r,
            _ => return Ok(Some(Value::Object(None))),
        };
        let delay = match args.get(2) {
            Some(Value::Long(v)) => *v,
            // WP4.5 — generic stack pop type-erases Long → Double bit-pattern.
            Some(Value::Double(d)) => d.to_bits() as i64,
            Some(Value::Int(v)) => *v as i64,
            _ => 0,
        };
        let delay_ms = scheduled_convert_to_millis(ctx, delay, args.get(3)).max(0) as u64;
        let task = crate::scheduled_pump::registry().register(runnable, delay_ms, 0, false);
        // Drive the pump immediately so callers that don't subsequently
        // sleep (e.g. zero-delay `schedule(r, 0, MILLIS)`) still get the
        // single fire they expect synchronously.
        crate::scheduled_pump::registry().pump(ctx);
        Ok(Some(Value::Object(Some(build_sf(ctx, task.id)))))
    });
    // scheduleAtFixedRate — periodic firing driven by the pump.
    r.register(stpe, "scheduleAtFixedRate", "(Ljava/lang/Runnable;JJLjava/util/concurrent/TimeUnit;)Ljava/util/concurrent/ScheduledFuture;", |ctx, args| {
        let runnable = match args.get(1) {
            Some(Value::Object(Some(r))) => *r,
            _ => return Ok(Some(Value::Object(None))),
        };
        let initial_delay = match args.get(2) {
            Some(Value::Long(v)) => *v,
            Some(Value::Double(d)) => d.to_bits() as i64,
            Some(Value::Int(v)) => *v as i64,
            _ => 0,
        };
        let period = match args.get(3) {
            Some(Value::Long(v)) => *v,
            Some(Value::Double(d)) => d.to_bits() as i64,
            Some(Value::Int(v)) => *v as i64,
            _ => 50,
        };
        let initial_ms = scheduled_convert_to_millis(ctx, initial_delay, args.get(4)).max(0) as u64;
        let period_ms = scheduled_convert_to_millis(ctx, period, args.get(4)).max(1) as u64;
        let task = crate::scheduled_pump::registry().register(runnable, initial_ms, period_ms, false);
        // Initial pump for zero-delay schedules so the first fire happens
        // before the caller's first `Thread.sleep`.
        crate::scheduled_pump::registry().pump(ctx);
        Ok(Some(Value::Object(Some(build_sf(ctx, task.id)))))
    });
    // scheduleWithFixedDelay — pump-driven, fixed-delay variant.
    r.register(stpe, "scheduleWithFixedDelay", "(Ljava/lang/Runnable;JJLjava/util/concurrent/TimeUnit;)Ljava/util/concurrent/ScheduledFuture;", |ctx, args| {
        let runnable = match args.get(1) {
            Some(Value::Object(Some(r))) => *r,
            _ => return Ok(Some(Value::Object(None))),
        };
        let initial_delay = match args.get(2) {
            Some(Value::Long(v)) => *v,
            Some(Value::Double(d)) => d.to_bits() as i64,
            Some(Value::Int(v)) => *v as i64,
            _ => 0,
        };
        let period = match args.get(3) {
            Some(Value::Long(v)) => *v,
            Some(Value::Double(d)) => d.to_bits() as i64,
            Some(Value::Int(v)) => *v as i64,
            _ => 50,
        };
        let initial_ms = scheduled_convert_to_millis(ctx, initial_delay, args.get(4)).max(0) as u64;
        let period_ms = scheduled_convert_to_millis(ctx, period, args.get(4)).max(1) as u64;
        let task = crate::scheduled_pump::registry().register(runnable, initial_ms, period_ms, true);
        crate::scheduled_pump::registry().pump(ctx);
        Ok(Some(Value::Object(Some(build_sf(ctx, task.id)))))
    });
    // ScheduledFuture.cancel(boolean) — flip the cancelled flag and
    // return whether this call performed the transition. The call is
    // registered against the synthetic ScheduledFuture class so the
    // probe's `sf.cancel(false)` resolves here regardless of which
    // scheduling overload built the future.
    r.register("java/util/concurrent/ScheduledFuture", "cancel", "(Z)Z", |ctx, args| {
        let this = obj_arg(args, 0)?;
        let id = match ctx.get_field(this, 0) {
            Value::Long(v) => v as u64,
            Value::Int(v) => v as u64,
            _ => 0,
        };
        if id == 0 {
            return Ok(Some(Value::Int(0)));
        }
        let cancelled = match crate::scheduled_pump::registry().find(id) {
            Some(t) => t.cancel(),
            None => false,
        };
        if cancelled {
            ctx.set_field(this, 1, Value::Int(1));
        }
        Ok(Some(Value::Int(if cancelled { 1 } else { 0 })))
    });
    r.register("java/util/concurrent/ScheduledFuture", "isCancelled", "()Z", |ctx, args| {
        let this = obj_arg(args, 0)?;
        let id = match ctx.get_field(this, 0) {
            Value::Long(v) => v as u64,
            Value::Int(v) => v as u64,
            _ => 0,
        };
        if id == 0 { return Ok(Some(Value::Int(0))); }
        Ok(Some(Value::Int(match crate::scheduled_pump::registry().find(id) {
            Some(t) if t.is_cancelled() => 1,
            _ => 0,
        })))
    });
    r.register("java/util/concurrent/ScheduledFuture", "isDone", "()Z", |ctx, args| {
        let this = obj_arg(args, 0)?;
        Ok(Some(ctx.get_field(this, 1)))
    });
    r.register(stpe, "shutdown", "()V", |ctx, args| {
        let this = obj_arg(args, 0)?;
        ctx.set_field(this, 1, Value::Int(1));
        // WP4.5 — drive any final pending fires before exiting and let
        // the cancelled tasks be GC'd by the registry on next pump.
        crate::scheduled_pump::registry().pump(ctx);
        crate::scheduled_pump::registry().gc();
        Ok(None)
    });
    r.register(stpe, "shutdownNow", "()Ljava/util/List;", |ctx, args| {
        let this = obj_arg(args, 0)?;
        ctx.set_field(this, 1, Value::Int(1));
        // shutdownNow cancels every pending periodic; the returned list
        // is empty in our synthetic model.
        crate::scheduled_pump::registry().cancel_all();
        crate::scheduled_pump::registry().gc();
        let al = alloc_concurrent_synthetic(ctx, "java/util/ArrayList", 2);
        ctx.set_field(al, 0, Value::Object(None));
        ctx.set_field(al, 1, Value::Int(0));
        Ok(Some(Value::Object(Some(al))))
    });
    r.register(stpe, "isShutdown", "()Z", |ctx, args| {
        let this = obj_arg(args, 0)?;
        Ok(Some(ctx.get_field(this, 1)))
    });
    r.register(stpe, "isTerminated", "()Z", |ctx, args| {
        let this = obj_arg(args, 0)?;
        Ok(Some(ctx.get_field(this, 1)))
    });
    r.register(stpe, "getPoolSize", "()I", |_ctx, _args| {
        Ok(Some(Value::Int(0)))
    });
    r.register(stpe, "getCorePoolSize", "()I", |ctx, args| {
        let this = obj_arg(args, 0)?;
        Ok(Some(ctx.get_field(this, 0)))
    });

    // ScheduledExecutorService interface
    let ses = "java/util/concurrent/ScheduledExecutorService";
    r.register(ses, "schedule", "(Ljava/lang/Runnable;JLjava/util/concurrent/TimeUnit;)Ljava/util/concurrent/ScheduledFuture;", |ctx, args| {
        let runnable = match args.get(1) {
            Some(Value::Object(Some(r))) => *r,
            _ => return Ok(Some(Value::Object(None))),
        };
        let delay = match args.get(2) {
            Some(Value::Long(v)) => *v,
            // WP4.5 — generic stack pop type-erases Long → Double bit-pattern.
            Some(Value::Double(d)) => d.to_bits() as i64,
            Some(Value::Int(v)) => *v as i64,
            _ => 0,
        };
        let delay_ms = scheduled_convert_to_millis(ctx, delay, args.get(3));
        if delay_ms > 0 {
            std::thread::sleep(std::time::Duration::from_millis(delay_ms as u64));
        }
        let _ = ctx.invoke_virtual(runnable, "run", "()V", &[]);
        let cf = p58_new_cf(ctx, Value::Object(None), true);
        Ok(Some(Value::Object(Some(cf))))
    });
    r.register(ses, "shutdown", "()V", |ctx, args| {
        let this = obj_arg(args, 0)?;
        ctx.set_field(this, 1, Value::Int(1));
        Ok(None)
    });

    // Executors factory
    let exs = "java/util/concurrent/Executors";
    r.register(
        exs,
        "newScheduledThreadPool",
        "(I)Ljava/util/concurrent/ScheduledExecutorService;",
        |ctx, args| {
            let cores = match args.first() {
                Some(Value::Int(v)) => *v,
                _ => 1,
            };
            let obj = stpe_new_executor(ctx, cores)
                .unwrap_or_else(|| alloc_concurrent_synthetic(ctx, "java/util/concurrent/ScheduledThreadPoolExecutor", 2));
            Ok(Some(Value::Object(Some(obj))))
        },
    );
    r.register(
        exs,
        "newSingleThreadScheduledExecutor",
        "()Ljava/util/concurrent/ScheduledExecutorService;",
        |ctx, _args| {
            let obj = stpe_new_executor(ctx, 1)
                .unwrap_or_else(|| alloc_concurrent_synthetic(ctx, "java/util/concurrent/ScheduledThreadPoolExecutor", 2));
            Ok(Some(Value::Object(Some(obj))))
        },
    );
}

