pub(crate) fn register_p66_file_visitor(r: &mut NativeMethodRegistry) {
    let sfv = "java/nio/file/SimpleFileVisitor";
    // SimpleFileVisitor has default methods that return CONTINUE
    r.register(sfv, "preVisitDirectory", "(Ljava/lang/Object;Ljava/nio/file/attribute/BasicFileAttributes;)Ljava/nio/file/FileVisitResult;", |ctx, _args| {
        let result = p57_alloc_enum(ctx, "java/nio/file/FileVisitResult", "CONTINUE", 0)?;
        Ok(result)
    });
    r.register(sfv, "visitFile", "(Ljava/lang/Object;Ljava/nio/file/attribute/BasicFileAttributes;)Ljava/nio/file/FileVisitResult;", |ctx, _args| {
        let result = p57_alloc_enum(ctx, "java/nio/file/FileVisitResult", "CONTINUE", 0)?;
        Ok(result)
    });
    r.register(
        sfv,
        "visitFileFailed",
        "(Ljava/lang/Object;Ljava/io/IOException;)Ljava/nio/file/FileVisitResult;",
        |ctx, _args| {
            let result = p57_alloc_enum(ctx, "java/nio/file/FileVisitResult", "CONTINUE", 0)?;
            Ok(result)
        },
    );
    r.register(
        sfv,
        "postVisitDirectory",
        "(Ljava/lang/Object;Ljava/io/IOException;)Ljava/nio/file/FileVisitResult;",
        |ctx, _args| {
            let result = p57_alloc_enum(ctx, "java/nio/file/FileVisitResult", "CONTINUE", 0)?;
            Ok(result)
        },
    );

    // FileVisitResult enum
    let fvr = "java/nio/file/FileVisitResult";
    r.register(
        fvr,
        "values",
        "()[Ljava/nio/file/FileVisitResult;",
        |ctx, _args| {
            let arr = ctx.new_array(rustjvm_types::ArrayElementType::Reference, 4);
            let names = ["CONTINUE", "TERMINATE", "SKIP_SUBTREE", "SKIP_SIBLINGS"];
            for (i, name) in names.iter().enumerate() {
                if let Ok(Some(e)) =
                    p57_alloc_enum(ctx, "java/nio/file/FileVisitResult", name, i as i32)
                {
                    ctx.set_array_element(arr, i, e);
                }
            }
            Ok(Some(Value::Object(Some(arr))))
        },
    );
    r.register(
        fvr,
        "valueOf",
        "(Ljava/lang/String;)Ljava/nio/file/FileVisitResult;",
        |ctx, args| {
            let name = match args.first() {
                Some(Value::Object(Some(r))) => ctx.read_string(*r).unwrap_or_default(),
                _ => "CONTINUE".to_string(),
            };
            let ordinal = match name.as_str() {
                "CONTINUE" => 0,
                "TERMINATE" => 1,
                "SKIP_SUBTREE" => 2,
                "SKIP_SIBLINGS" => 3,
                _ => 0,
            };
            p57_alloc_enum(ctx, "java/nio/file/FileVisitResult", &name, ordinal)
        },
    );

    // Files.walkFileTree — real directory walking with visitor callbacks
    r.register(
        "java/nio/file/Files",
        "walkFileTree",
        "(Ljava/nio/file/Path;Ljava/nio/file/FileVisitor;)Ljava/nio/file/Path;",
        p98_walk_file_tree,
    );
    r.register(
        "java/nio/file/Files",
        "walkFileTree",
        "(Ljava/nio/file/Path;Ljava/util/Set;ILjava/nio/file/FileVisitor;)Ljava/nio/file/Path;",
        |ctx, args| {
            let path_obj = args.first().copied().unwrap_or(Value::Object(None));
            let visitor = args.get(3).copied().unwrap_or(Value::Object(None));
            p98_walk_file_tree(ctx, &[path_obj, visitor])
        },
    );
}

fn p98_walk_file_tree(ctx: &mut dyn NativeContext, args: &[Value]) -> MethodCallResult {
    let path_val = args.first().copied().unwrap_or(Value::Object(None));
    let visitor = if let Some(Value::Object(Some(v))) = args.get(1) { *v } else {
        return Ok(Some(path_val));
    };
    let path_obj = if let Value::Object(Some(p)) = path_val { p } else {
        return Ok(Some(path_val));
    };
    let root_str = match ctx.get_field(path_obj, 0) {
        Value::Object(Some(s)) => ctx.read_string(s).unwrap_or_default(),
        _ => return Ok(Some(path_val)),
    };
    p98_walk_dir(ctx, &root_str, visitor, path_obj)?;
    Ok(Some(path_val))
}

fn p98_walk_dir(
    ctx: &mut dyn NativeContext,
    dir: &str,
    visitor: ObjectRef,
    dir_path_obj: ObjectRef,
) -> Result<bool, MethodCallFailed> {
    let attrs = alloc_concurrent_synthetic(ctx, "java/nio/file/attribute/BasicFileAttributes", 0);
    // preVisitDirectory
    let pre = ctx.invoke_virtual(visitor, "preVisitDirectory",
        "(Ljava/lang/Object;Ljava/nio/file/attribute/BasicFileAttributes;)Ljava/nio/file/FileVisitResult;",
        &[Value::Object(Some(dir_path_obj)), Value::Object(Some(attrs))])?;
    if let Some(Value::Object(Some(r))) = pre {
        let ord = ctx.get_field(r, 1).as_int().unwrap_or(0);
        if ord == 1 { return Ok(false); } // TERMINATE
        if ord == 2 { return Ok(true); }  // SKIP_SUBTREE
    }
    if let Ok(entries) = std::fs::read_dir(dir) {
        for entry in entries.flatten() {
            let ep = entry.path();
            let es = ep.to_string_lossy().to_string();
            let epo = alloc_concurrent_synthetic(ctx, "java/nio/file/Path", 1);
            let s = ctx.create_string(&es);
            ctx.set_field(epo, 0, Value::Object(Some(s)));
            if ep.is_dir() {
                if !p98_walk_dir(ctx, &es, visitor, epo)? { return Ok(false); }
            } else {
                let fa = alloc_concurrent_synthetic(ctx, "java/nio/file/attribute/BasicFileAttributes", 0);
                let vr = ctx.invoke_virtual(visitor, "visitFile",
                    "(Ljava/lang/Object;Ljava/nio/file/attribute/BasicFileAttributes;)Ljava/nio/file/FileVisitResult;",
                    &[Value::Object(Some(epo)), Value::Object(Some(fa))])?;
                if let Some(Value::Object(Some(r))) = vr {
                    if ctx.get_field(r, 1).as_int().unwrap_or(0) == 1 { return Ok(false); }
                }
            }
        }
    }
    let post = ctx.invoke_virtual(visitor, "postVisitDirectory",
        "(Ljava/lang/Object;Ljava/io/IOException;)Ljava/nio/file/FileVisitResult;",
        &[Value::Object(Some(dir_path_obj)), Value::Object(None)])?;
    if let Some(Value::Object(Some(r))) = post {
        if ctx.get_field(r, 1).as_int().unwrap_or(0) == 1 { return Ok(false); }
    }
    Ok(true)
}

// =============================================================================
// java.nio.file.WatchService stubs
// =============================================================================

pub(crate) fn register_p66_watch_service(r: &mut NativeMethodRegistry) {
    // WatchService = 2-field synthetic (dir_path=0 String, last_scan_time=1 Long)
    let ws = "java/nio/file/WatchService";
    r.register(ws, "close", "()V", |ctx, args| {
        // Mark as closed by clearing the dir_path field. Subsequent poll/take returns null.
        let this = obj_arg(args, 0)?;
        ctx.set_field(this, 0, Value::Object(None));
        Ok(None)
    });

    // poll() — non-blocking: scan directory for changes since last poll
    r.register(ws, "poll", "()Ljava/nio/file/WatchKey;", |ctx, args| {
        let this = obj_arg(args, 0)?;
        watch_service_poll(ctx, this, None)
    });

    // poll(timeout, unit) — blocking with timeout
    r.register(
        ws,
        "poll",
        "(JLjava/util/concurrent/TimeUnit;)Ljava/nio/file/WatchKey;",
        |ctx, args| {
            let this = obj_arg(args, 0)?;
            let timeout_ms = match args.get(1) {
                Some(Value::Long(t)) => Some(*t as u64),
                _ => Some(1000),
            };
            watch_service_poll(ctx, this, timeout_ms)
        },
    );

    // take() — blocking: wait for a change event (poll with 5s timeout)
    r.register(ws, "take", "()Ljava/nio/file/WatchKey;", |ctx, args| {
        let this = obj_arg(args, 0)?;
        watch_service_poll(ctx, this, Some(5000))
    });

    // StandardWatchEventKinds
    let swek = "java/nio/file/StandardWatchEventKinds";
    r.register(
        swek,
        "ENTRY_CREATE",
        "Ljava/nio/file/WatchEvent$Kind;",
        |ctx, _args| {
            let s = ctx.create_string("ENTRY_CREATE");
            Ok(Some(Value::Object(Some(s))))
        },
    );
    r.register(
        swek,
        "ENTRY_MODIFY",
        "Ljava/nio/file/WatchEvent$Kind;",
        |ctx, _args| {
            let s = ctx.create_string("ENTRY_MODIFY");
            Ok(Some(Value::Object(Some(s))))
        },
    );
    r.register(
        swek,
        "ENTRY_DELETE",
        "Ljava/nio/file/WatchEvent$Kind;",
        |ctx, _args| {
            let s = ctx.create_string("ENTRY_DELETE");
            Ok(Some(Value::Object(Some(s))))
        },
    );
    r.register(
        swek,
        "OVERFLOW",
        "Ljava/nio/file/WatchEvent$Kind;",
        |ctx, _args| {
            let s = ctx.create_string("OVERFLOW");
            Ok(Some(Value::Object(Some(s))))
        },
    );

    // Path.register for WatchService — store directory path in the WatchService
    r.register(
        "java/nio/file/Path",
        "register",
        "(Ljava/nio/file/WatchService;[Ljava/nio/file/WatchEvent$Kind;)Ljava/nio/file/WatchKey;",
        |ctx, args| {
            let path_obj = obj_arg(args, 0)?;
            let ws = obj_arg(args, 1)?;
            // Store the directory path in the WatchService's field 0
            let path_str = match ctx.get_field(path_obj, 0) {
                Value::Object(Some(s)) => Value::Object(Some(s)),
                _ => Value::Object(None),
            };
            ctx.set_field(ws, 0, path_str);
            // Set last scan time to now
            let now = std::time::SystemTime::now()
                .duration_since(std::time::UNIX_EPOCH)
                .unwrap_or_default()
                .as_millis() as i64;
            ctx.set_field(ws, 1, Value::Long(now));
            // Return a synthetic WatchKey
            let key = alloc_concurrent_synthetic(ctx, "java/nio/file/WatchKey", 2);
            ctx.set_field(key, 0, Value::Int(1)); // valid
            Ok(Some(Value::Object(Some(key))))
        },
    );

    // WatchKey methods
    let wk = "java/nio/file/WatchKey";
    r.register(wk, "isValid", "()Z", |ctx, args| {
        let this = obj_arg(args, 0)?;
        Ok(Some(ctx.get_field(this, 0)))
    });
    r.register(wk, "pollEvents", "()Ljava/util/List;", |ctx, _args| {
        // Return empty list (events are detected via poll)
        let list = alloc_concurrent_synthetic(ctx, "java/util/ArrayList", 2);
        let empty = ctx.new_array(rustjvm_types::ArrayElementType::Reference, 0);
        ctx.set_field(list, 0, Value::Object(Some(empty)));
        ctx.set_field(list, 1, Value::Int(0));
        Ok(Some(Value::Object(Some(list))))
    });
    r.register(wk, "reset", "()Z", |_ctx, _args| Ok(Some(Value::Int(1))));
    r.register(wk, "cancel", "()V", |ctx, args| {
        let this = obj_arg(args, 0)?;
        ctx.set_field(this, 0, Value::Int(0));
        Ok(None)
    });
}

/// Poll a WatchService's registered directory for changes.
/// Returns a WatchKey if changes detected, None otherwise.
fn watch_service_poll(
    ctx: &mut dyn NativeContext,
    ws: rustjvm_types::ObjectRef,
    timeout_ms: Option<u64>,
) -> MethodCallResult {
    let dir_path = match ctx.get_field(ws, 0) {
        Value::Object(Some(s)) => ctx.read_string(s).unwrap_or_default(),
        _ => return Ok(Some(Value::Object(None))),
    };
    let last_scan = match ctx.get_field(ws, 1) {
        Value::Long(t) => t,
        _ => 0,
    };

    if dir_path.is_empty() {
        return Ok(Some(Value::Object(None)));
    }

    // Check if any file in the directory was modified since last_scan
    let scan_time = std::time::UNIX_EPOCH + std::time::Duration::from_millis(last_scan as u64);
    let mut changed = false;

    if let Ok(entries) = std::fs::read_dir(&dir_path) {
        for entry in entries.flatten() {
            if let Ok(meta) = entry.metadata() {
                if let Ok(modified) = meta.modified() {
                    if modified > scan_time {
                        changed = true;
                        break;
                    }
                }
            }
        }
    }

    // If timeout specified and no change, sleep briefly and retry once
    if !changed && timeout_ms.is_some() {
        let wait = timeout_ms.unwrap().min(100);
        std::thread::sleep(std::time::Duration::from_millis(wait));
        // Don't loop — return null after single poll attempt
    }

    // Update scan time
    let now = std::time::SystemTime::now()
        .duration_since(std::time::UNIX_EPOCH)
        .unwrap_or_default()
        .as_millis() as i64;
    ctx.set_field(ws, 1, Value::Long(now));

    if changed {
        let key = alloc_concurrent_synthetic(ctx, "java/nio/file/WatchKey", 2);
        ctx.set_field(key, 0, Value::Int(1)); // valid
        Ok(Some(Value::Object(Some(key))))
    } else {
        Ok(Some(Value::Object(None)))
    }
}

