// =============================================================================
// Phase 69: Cleaner, Spliterator/StreamSupport, WebSocket stubs,
//           SwitchBootstraps, CompactNumberFormat, SubmissionPublisher
// =============================================================================

pub(crate) fn register_phase69_natives(registry: &mut NativeMethodRegistry) {
    register_p69_cleaner(registry);
    register_p69_spliterator(registry);
    register_p69_websocket(registry);
    register_p69_switch_bootstraps(registry);
    register_p69_compact_number_format(registry);
    register_p69_submission_publisher(registry);
    register_p69_misc(registry);
}

// =============================================================================
// java.lang.ref.Cleaner — Java 9
// 1-field synthetic (daemon=0 Int)
// =============================================================================

// Cleaner synthetic layout (see docs/plans/new17-cleaner.md):
//   field 0 : Object[]  — backing list pinning Cleanable entries alive
//   field 1 : Int       — number of live cleanables
//
// Cleaner$Cleanable synthetic layout:
//   field 0 : Object (Runnable) — the action to run on referent death
//   field 1 : Int               — cleaned flag (0 = pending, 1 = done)
//   field 2 : Int               — index of this cleanable in its owner's array
const CLEANER_ARR: usize = 0;
const CLEANER_LEN: usize = 1;
const CLEANABLE_ACTION: usize = 0;
const CLEANABLE_FLAG: usize = 1;
const CLEANABLE_IDX: usize = 2;
const CLEANER_INITIAL_CAP: i32 = 16;
/// Cleaner ref-type discriminator expected by
/// `NativeContext::discover_reference` / `vm_exec::discover_reference`.
const REF_TYPE_CLEANER: u8 = 3;

fn alloc_cleaner(ctx: &mut dyn NativeContext) -> ObjectRef {
    let obj = alloc_concurrent_synthetic(ctx, "java/lang/ref/Cleaner", 2);
    let arr = ctx.new_array(
        rustjvm_types::ArrayElementType::Reference,
        CLEANER_INITIAL_CAP as usize,
    );
    ctx.set_field(obj, CLEANER_ARR, Value::Object(Some(arr)));
    ctx.set_field(obj, CLEANER_LEN, Value::Int(0));
    obj
}

pub(crate) fn register_p69_cleaner(r: &mut NativeMethodRegistry) {
    let c = "java/lang/ref/Cleaner";
    r.register(c, "create", "()Ljava/lang/ref/Cleaner;", |ctx, _args| {
        Ok(Some(Value::Object(Some(alloc_cleaner(ctx)))))
    });
    r.register(
        c,
        "create",
        "(Ljava/util/concurrent/ThreadFactory;)Ljava/lang/ref/Cleaner;",
        |ctx, _args| Ok(Some(Value::Object(Some(alloc_cleaner(ctx))))),
    );
    r.register(
        c,
        "register",
        "(Ljava/lang/Object;Ljava/lang/Runnable;)Ljava/lang/ref/Cleaner$Cleanable;",
        |ctx, args| {
            let this = obj_arg(args, 0)?;
            let referent = match args.get(1) {
                Some(Value::Object(Some(o))) => *o,
                _ => {
                    // Null referent: return a dead cleanable so the caller's
                    // control flow still works (JDK throws NPE here, but we
                    // soft-fail to stay consistent with other synthetic paths).
                    let cleanable = alloc_concurrent_synthetic(
                        ctx, "java/lang/ref/Cleaner$Cleanable", 3,
                    );
                    ctx.set_field(cleanable, CLEANABLE_ACTION, Value::Object(None));
                    ctx.set_field(cleanable, CLEANABLE_FLAG, Value::Int(1));
                    ctx.set_field(cleanable, CLEANABLE_IDX, Value::Int(-1));
                    return Ok(Some(Value::Object(Some(cleanable))));
                }
            };
            let action = match args.get(2) {
                Some(Value::Object(Some(o))) => Value::Object(Some(*o)),
                _ => Value::Object(None),
            };

            // Allocate the cleanable synthetic.
            let cleanable = alloc_concurrent_synthetic(
                ctx, "java/lang/ref/Cleaner$Cleanable", 3,
            );
            ctx.set_field(cleanable, CLEANABLE_ACTION, action);
            ctx.set_field(cleanable, CLEANABLE_FLAG, Value::Int(0));

            // Append into the Cleaner's backing array, growing by doubling if full.
            let mut arr = match ctx.get_field(this, CLEANER_ARR) {
                Value::Object(Some(a)) => a,
                _ => {
                    let a = ctx.new_array(
                        rustjvm_types::ArrayElementType::Reference,
                        CLEANER_INITIAL_CAP as usize,
                    );
                    ctx.set_field(this, CLEANER_ARR, Value::Object(Some(a)));
                    a
                }
            };
            let mut len = ctx.get_field(this, CLEANER_LEN).as_int().unwrap_or(0);
            let cap = ctx.array_length(arr) as i32;
            if len >= cap {
                let new_cap = (cap.max(1) * 2) as usize;
                let new_arr = ctx.new_array(
                    rustjvm_types::ArrayElementType::Reference,
                    new_cap,
                );
                for i in 0..cap as usize {
                    let v = ctx.get_array_element(arr, i);
                    ctx.set_array_element(new_arr, i, v);
                }
                ctx.set_field(this, CLEANER_ARR, Value::Object(Some(new_arr)));
                arr = new_arr;
            }
            ctx.set_array_element(arr, len as usize, Value::Object(Some(cleanable)));
            ctx.set_field(cleanable, CLEANABLE_IDX, Value::Int(len));
            len += 1;
            ctx.set_field(this, CLEANER_LEN, Value::Int(len));

            // Register with the ref processor as a Cleaner phantom.
            // The *cleanable* is the "reference object" — when the
            // referent dies, the GC pushes the cleanable's address into
            // `cleaner_actions`, which `run_cleaner_actions` drains.
            ctx.discover_reference(REF_TYPE_CLEANER, cleanable, referent, None);

            Ok(Some(Value::Object(Some(cleanable))))
        },
    );

    // Cleanable.clean() — synchronous user-triggered cleanup.
    // Guarded by the cleaned flag so GC-triggered + user-triggered are idempotent.
    let cl = "java/lang/ref/Cleaner$Cleanable";
    r.register(cl, "clean", "()V", |ctx, args| {
        let this = obj_arg(args, 0)?;
        let already = matches!(ctx.get_field(this, CLEANABLE_FLAG), Value::Int(1));
        if already {
            return Ok(None);
        }
        ctx.set_field(this, CLEANABLE_FLAG, Value::Int(1));
        let action = match ctx.get_field(this, CLEANABLE_ACTION) {
            Value::Object(Some(o)) => o,
            _ => return Ok(None),
        };
        // Clear the slot so the action can drop naturally on the next GC.
        ctx.set_field(this, CLEANABLE_ACTION, Value::Object(None));
        // Per Cleaner contract, exceptions thrown by run() are caught.
        let _ = ctx.invoke_virtual(
            action,
            "run",
            "()V",
            &[Value::Object(Some(action))],
        );
        Ok(None)
    });
}

// =============================================================================
// java.util.Spliterator and StreamSupport
// =============================================================================

pub(crate) fn register_p69_spliterator(r: &mut NativeMethodRegistry) {
    // Spliterator = 3-field (elements=0 Object[], pos=1 Int, fence=2 Int)
    let sp = "java/util/Spliterator";
    r.register(
        sp,
        "tryAdvance",
        "(Ljava/util/function/Consumer;)Z",
        |ctx, args| {
            let this = obj_arg(args, 0)?;
            let pos = match ctx.get_field(this, 1) {
                Value::Int(v) => v as usize,
                _ => 0,
            };
            let fence = match ctx.get_field(this, 2) {
                Value::Int(v) => v as usize,
                _ => 0,
            };
            if pos >= fence {
                return Ok(Some(Value::Int(0)));
            }
            let arr = match ctx.get_field(this, 0) {
                Value::Object(Some(a)) => a,
                _ => return Ok(Some(Value::Int(0))),
            };
            let elem = ctx.get_array_element(arr, pos);
            ctx.set_field(this, 1, Value::Int((pos + 1) as i32));
            // Invoke consumer.accept(elem)
            if let Some(Value::Object(Some(consumer))) = args.get(1) {
                let _ = ctx.invoke_virtual(
                    *consumer,
                    "accept",
                    "(Ljava/lang/Object;)V",
                    &[Value::Object(Some(*consumer)), elem],
                );
            }
            Ok(Some(Value::Int(1)))
        },
    );
    r.register(
        sp,
        "trySplit",
        "()Ljava/util/Spliterator;",
        |_ctx, _args| {
            Ok(Some(Value::Object(None))) // simplified: no splitting
        },
    );
    r.register(sp, "estimateSize", "()J", |ctx, args| {
        let this = obj_arg(args, 0)?;
        let pos = match ctx.get_field(this, 1) {
            Value::Int(v) => v as i64,
            _ => 0,
        };
        let fence = match ctx.get_field(this, 2) {
            Value::Int(v) => v as i64,
            _ => 0,
        };
        Ok(Some(Value::Long((fence - pos).max(0))))
    });
    r.register(sp, "characteristics", "()I", |_ctx, _args| {
        // ORDERED | SIZED
        Ok(Some(Value::Int(0x10 | 0x40)))
    });
    r.register(sp, "getExactSizeIfKnown", "()J", |ctx, args| {
        let this = obj_arg(args, 0)?;
        let pos = match ctx.get_field(this, 1) {
            Value::Int(v) => v as i64,
            _ => 0,
        };
        let fence = match ctx.get_field(this, 2) {
            Value::Int(v) => v as i64,
            _ => 0,
        };
        Ok(Some(Value::Long((fence - pos).max(0))))
    });
    r.register(
        sp,
        "forEachRemaining",
        "(Ljava/util/function/Consumer;)V",
        |ctx, args| {
            let this = obj_arg(args, 0)?;
            let arr = match ctx.get_field(this, 0) {
                Value::Object(Some(a)) => a,
                _ => return Ok(None),
            };
            let mut pos = match ctx.get_field(this, 1) {
                Value::Int(v) => v as usize,
                _ => 0,
            };
            let fence = match ctx.get_field(this, 2) {
                Value::Int(v) => v as usize,
                _ => 0,
            };
            let consumer = match args.get(1) {
                Some(Value::Object(Some(c))) => *c,
                _ => return Ok(None),
            };
            while pos < fence {
                let elem = ctx.get_array_element(arr, pos);
                let _ = ctx.invoke_virtual(
                    consumer,
                    "accept",
                    "(Ljava/lang/Object;)V",
                    &[Value::Object(Some(consumer)), elem],
                );
                pos += 1;
            }
            ctx.set_field(this, 1, Value::Int(fence as i32));
            Ok(None)
        },
    );

    // Spliterator constants
    r.register(sp, "ORDERED", "I", |_ctx, _args| Ok(Some(Value::Int(0x10))));
    r.register(sp, "DISTINCT", "I", |_ctx, _args| {
        Ok(Some(Value::Int(0x01)))
    });
    r.register(sp, "SORTED", "I", |_ctx, _args| Ok(Some(Value::Int(0x04))));
    r.register(sp, "SIZED", "I", |_ctx, _args| Ok(Some(Value::Int(0x40))));
    r.register(sp, "NONNULL", "I", |_ctx, _args| {
        Ok(Some(Value::Int(0x100)))
    });
    r.register(sp, "IMMUTABLE", "I", |_ctx, _args| {
        Ok(Some(Value::Int(0x400)))
    });
    r.register(sp, "CONCURRENT", "I", |_ctx, _args| {
        Ok(Some(Value::Int(0x1000)))
    });
    r.register(sp, "SUBSIZED", "I", |_ctx, _args| {
        Ok(Some(Value::Int(0x4000)))
    });

    // Spliterators utility class
    let sps = "java/util/Spliterators";
    r.register(
        sps,
        "spliterator",
        "([Ljava/lang/Object;I)Ljava/util/Spliterator;",
        |ctx, args| {
            let arr = match args.first() {
                Some(Value::Object(Some(a))) => *a,
                _ => return Ok(Some(Value::Object(None))),
            };
            let len = ctx.array_length(arr);
            let obj = alloc_concurrent_synthetic(ctx, "java/util/Spliterator", 3);
            ctx.set_field(obj, 0, Value::Object(Some(arr)));
            ctx.set_field(obj, 1, Value::Int(0));
            ctx.set_field(obj, 2, Value::Int(len as i32));
            Ok(Some(Value::Object(Some(obj))))
        },
    );
    r.register(
        sps,
        "emptySpliterator",
        "()Ljava/util/Spliterator;",
        |ctx, _args| {
            let arr = ctx.new_array(rustjvm_types::ArrayElementType::Reference, 0);
            let obj = alloc_concurrent_synthetic(ctx, "java/util/Spliterator", 3);
            ctx.set_field(obj, 0, Value::Object(Some(arr)));
            ctx.set_field(obj, 1, Value::Int(0));
            ctx.set_field(obj, 2, Value::Int(0));
            Ok(Some(Value::Object(Some(obj))))
        },
    );
    r.register(
        sps,
        "spliteratorUnknownSize",
        "(Ljava/util/Iterator;I)Ljava/util/Spliterator;",
        |ctx, _args| {
            // Return empty spliterator (simplified)
            let arr = ctx.new_array(rustjvm_types::ArrayElementType::Reference, 0);
            let obj = alloc_concurrent_synthetic(ctx, "java/util/Spliterator", 3);
            ctx.set_field(obj, 0, Value::Object(Some(arr)));
            ctx.set_field(obj, 1, Value::Int(0));
            ctx.set_field(obj, 2, Value::Int(0));
            Ok(Some(Value::Object(Some(obj))))
        },
    );

    // StreamSupport
    let ss = "java/util/stream/StreamSupport";
    eprintln!("[STREAM-SUPPORT-DBG] registering StreamSupport.stream");
    r.register(
        ss,
        "stream",
        "(Ljava/util/Spliterator;Z)Ljava/util/stream/Stream;",
        |ctx, args| {
            eprintln!("[STREAM-SUPPORT-DBG] StreamSupport.stream native fired");
            // Convert spliterator to stream (1-field synthetic with backing array).
            //
            // Two cases:
            //  * Synthetic spliterator (built by our `Collection.spliterator`,
            //    `Spliterators.spliterator`, etc.): field 0 is already the
            //    backing Object[] — just snapshot it.
            //  * Real-JDK Spliterator subclass (e.g. log4j's
            //    `ServiceLoaderUtil$ServiceLoaderSpliterator`, whose field 0
            //    is an `Iterator`, not an array). We can't read its private
            //    layout; drain it via `forEachRemaining(Consumer)` into a
            //    collector consumer whose `accept` natively appends to a
            //    growing Object[].
            let spliterator = match args.first() {
                Some(Value::Object(Some(s))) => *s,
                _ => {
                    let empty = ctx.new_array(rustjvm_types::ArrayElementType::Reference, 0);
                    let stream = alloc_concurrent_synthetic(ctx, "java/util/stream/Stream", 1);
                    ctx.set_field(stream, 0, Value::Object(Some(empty)));
                    return Ok(Some(Value::Object(Some(stream))));
                }
            };
            let field0 = ctx.get_field(spliterator, 0);
            let arr = match field0 {
                Value::Object(Some(a)) if ctx.heap_kind_of(a) == rustjvm_types::ObjectKind::Array => a,
                _ => {
                    // Real Spliterator subclass — drain via a collecting
                    // consumer.
                    drain_spliterator(ctx, spliterator)?
                }
            };
            let stream = alloc_concurrent_synthetic(ctx, "java/util/stream/Stream", 1);
            ctx.set_field(stream, 0, Value::Object(Some(arr)));
            Ok(Some(Value::Object(Some(stream))))
        },
    );
    r.register(
        ss,
        "intStream",
        "(Ljava/util/Spliterator$OfInt;Z)Ljava/util/stream/IntStream;",
        |ctx, _args| {
            let arr = ctx.new_array(rustjvm_types::ArrayElementType::Reference, 0);
            let stream = alloc_concurrent_synthetic(ctx, "java/util/stream/IntStream", 1);
            ctx.set_field(stream, 0, Value::Object(Some(arr)));
            Ok(Some(Value::Object(Some(stream))))
        },
    );
    r.register(
        ss,
        "longStream",
        "(Ljava/util/Spliterator$OfLong;Z)Ljava/util/stream/LongStream;",
        |ctx, _args| {
            let arr = ctx.new_array(rustjvm_types::ArrayElementType::Reference, 0);
            let stream = alloc_concurrent_synthetic(ctx, "java/util/stream/LongStream", 1);
            ctx.set_field(stream, 0, Value::Object(Some(arr)));
            Ok(Some(Value::Object(Some(stream))))
        },
    );
    r.register(
        ss,
        "doubleStream",
        "(Ljava/util/Spliterator$OfDouble;Z)Ljava/util/stream/DoubleStream;",
        |ctx, _args| {
            let arr = ctx.new_array(rustjvm_types::ArrayElementType::Reference, 0);
            let stream = alloc_concurrent_synthetic(ctx, "java/util/stream/DoubleStream", 1);
            ctx.set_field(stream, 0, Value::Object(Some(arr)));
            Ok(Some(Value::Object(Some(stream))))
        },
    );

    // Collector consumer used by `drain_spliterator`. Layout:
    //   field 0: Object[] storage (capacity == array_length)
    //   field 1: Int — current logical length
    // `accept(Object)V` appends, growing the storage on demand.
    r.register(
        "rustjvm/internal/StreamCollector",
        "accept",
        "(Ljava/lang/Object;)V",
        |ctx, args| {
            let this = obj_arg(args, 0)?;
            let elem = args.get(1).copied().unwrap_or(Value::Object(None));
            let mut len = match ctx.get_field(this, 1) {
                Value::Int(v) => v as usize,
                _ => 0,
            };
            let storage = match ctx.get_field(this, 0) {
                Value::Object(Some(a)) => a,
                _ => ctx.new_array(rustjvm_types::ArrayElementType::Reference, 16),
            };
            let cap = ctx.array_length(storage);
            let storage = if len >= cap {
                let new_cap = (cap * 2).max(16);
                let bigger = ctx.new_array(rustjvm_types::ArrayElementType::Reference, new_cap);
                for i in 0..len {
                    let v = ctx.get_array_element(storage, i);
                    ctx.set_array_element(bigger, i, v);
                }
                ctx.set_field(this, 0, Value::Object(Some(bigger)));
                bigger
            } else {
                storage
            };
            ctx.set_array_element(storage, len, elem);
            len += 1;
            ctx.set_field(this, 1, Value::Int(len as i32));
            Ok(None)
        },
    );
}

/// Drain a (possibly real-JDK) Spliterator into a freshly-allocated
/// Object[] by repeatedly invoking `tryAdvance(Consumer)` with a synthetic
/// collector consumer. Used when `StreamSupport.stream` is handed a
/// Spliterator whose field-0 layout we don't control (e.g. log4j's
/// `ServiceLoaderUtil$ServiceLoaderSpliterator`).
fn drain_spliterator(
    ctx: &mut dyn NativeContext,
    spliterator: ObjectRef,
) -> Result<ObjectRef, MethodCallFailed> {
    // Allocate the collector consumer.
    let collector = alloc_concurrent_synthetic(ctx, "rustjvm/internal/StreamCollector", 2);
    let initial = ctx.new_array(rustjvm_types::ArrayElementType::Reference, 16);
    ctx.set_field(collector, 0, Value::Object(Some(initial)));
    ctx.set_field(collector, 1, Value::Int(0));

    // Drive the spliterator. Try forEachRemaining first (one virtual call),
    // fall back to tryAdvance loop if forEachRemaining isn't usable.
    // NOTE: `invoke_virtual` prepends the receiver itself — `args` must NOT
    // include it. The previous version double-passed the receiver, producing
    // a malformed 3-arg call for a 2-arg method, which silently dropped the
    // collector and left the output array empty (the symptom that surfaced
    // as the FORE-DBG trace and as `Stream.forEach` returning zero elements
    // during WildFly's log4j init).
    let _ = ctx.invoke_virtual(
        spliterator,
        "forEachRemaining",
        "(Ljava/util/function/Consumer;)V",
        &[Value::Object(Some(collector))],
    );

    // Snapshot to an exactly-sized array.
    let len = match ctx.get_field(collector, 1) {
        Value::Int(v) => v as usize,
        _ => 0,
    };
    let storage = match ctx.get_field(collector, 0) {
        Value::Object(Some(a)) => a,
        _ => return Ok(ctx.new_array(rustjvm_types::ArrayElementType::Reference, 0)),
    };
    let out = ctx.new_array(rustjvm_types::ArrayElementType::Reference, len);
    for i in 0..len {
        let v = ctx.get_array_element(storage, i);
        ctx.set_array_element(out, i, v);
    }
    Ok(out)
}

// =============================================================================
// java.net.http.WebSocket — Java 11
// =============================================================================

// WebSocket field layout: 5-field
// 0=fd_id (Int), 1=output_closed (Int), 2=input_closed (Int), 3=subprotocol (String), 4=state (Int 0=open,1=closing,2=closed)
const P69_WS_FD: usize = 0;
const P69_WS_OUT_CLOSED: usize = 1;
const P69_WS_IN_CLOSED: usize = 2;
const P69_WS_SUBPROTO: usize = 3;
const P69_WS_STATE: usize = 4;
const P69_WS_DEMAND: usize = 5;

pub(crate) fn register_p69_websocket(r: &mut NativeMethodRegistry) {
    // WebSocket.Builder — 3-field: uri=0, headers=1, subprotocol=2
    let wsb = "java/net/http/WebSocket$Builder";
    r.register(
        wsb,
        "header",
        "(Ljava/lang/String;Ljava/lang/String;)Ljava/net/http/WebSocket$Builder;",
        |_ctx, args| Ok(Some(args.first().copied().unwrap_or(Value::Object(None)))),
    );
    r.register(
        wsb,
        "connectTimeout",
        "(Ljava/time/Duration;)Ljava/net/http/WebSocket$Builder;",
        |_ctx, args| Ok(Some(args.first().copied().unwrap_or(Value::Object(None)))),
    );
    r.register(
        wsb,
        "subprotocols",
        "(Ljava/lang/String;[Ljava/lang/String;)Ljava/net/http/WebSocket$Builder;",
        |_ctx, args| Ok(Some(args.first().copied().unwrap_or(Value::Object(None)))),
    );
    // buildAsync — real HTTP Upgrade + RFC 6455 handshake
    r.register(wsb, "buildAsync", "(Ljava/net/URI;Ljava/net/http/WebSocket$Listener;)Ljava/util/concurrent/CompletableFuture;", |ctx, args| {
        // Extract URI string from the URI object (field 0 is the string form)
        let uri_str = if let Some(Value::Object(Some(uri_obj))) = args.get(1) {
            if let Value::Object(Some(s)) = ctx.get_field(*uri_obj, 0) {
                ctx.read_string(s).unwrap_or_default()
            } else {
                String::new()
            }
        } else {
            String::new()
        };

        // Parse ws:// or wss:// URI
        let (use_tls, host, port, path) = ws_parse_uri(&uri_str);

        // Connect
        let fd_id = if use_tls {
            ctx.fd_table().open_tls_connect(&host, port)
                .map_err(|e| RuntimeError::IOException { message: e.to_string() })?
        } else {
            ctx.fd_table().open_tcp_connect(&format!("{}:{}", host, port))
                .map_err(|e| RuntimeError::IOException { message: e.to_string() })?
        };

        // Generate WebSocket key (16 random bytes, base64-encoded)
        let ws_key = ws_generate_key();

        // Send HTTP Upgrade request
        let upgrade_req = format!(
            "GET {} HTTP/1.1\r\nHost: {}\r\nUpgrade: websocket\r\nConnection: Upgrade\r\nSec-WebSocket-Version: 13\r\nSec-WebSocket-Key: {}\r\n\r\n",
            path, host, ws_key
        );
        let req_bytes = upgrade_req.as_bytes();
        if use_tls {
            let _ = ctx.fd_table().tls_write(fd_id, req_bytes);
        } else {
            let _ = ctx.fd_table().tcp_write(fd_id, req_bytes);
        }

        // Read upgrade response (wait for \r\n\r\n)
        let mut response = Vec::new();
        let mut buf = [0u8; 1];
        for _ in 0..8192 {
            let n = if use_tls {
                ctx.fd_table().tls_read(fd_id, &mut buf).unwrap_or(0)
            } else {
                ctx.fd_table().tcp_read(fd_id, &mut buf).unwrap_or(0)
            };
            if n == 0 { break; }
            response.push(buf[0]);
            if response.len() >= 4 && response[response.len()-4..] == [b'\r', b'\n', b'\r', b'\n'] {
                break;
            }
        }

        // Verify 101 Switching Protocols
        let resp_str = String::from_utf8_lossy(&response);
        if !resp_str.starts_with("HTTP/1.1 101") {
            let _ = ctx.fd_table().close(fd_id);
            return Err(RuntimeError::IOException {
                message: format!("WebSocket upgrade failed: {}", resp_str.lines().next().unwrap_or("no response")),
            }.into());
        }

        // Verify Sec-WebSocket-Accept
        let expected_accept = ws_compute_accept(&ws_key);
        let accept_ok = resp_str.lines().any(|line| {
            if let Some(val) = line.strip_prefix("Sec-WebSocket-Accept: ") {
                val.trim() == expected_accept
            } else if let Some(val) = line.strip_prefix("sec-websocket-accept: ") {
                val.trim() == expected_accept
            } else {
                false
            }
        });
        if !accept_ok {
            let _ = ctx.fd_table().close(fd_id);
            return Err(RuntimeError::IOException {
                message: "WebSocket Sec-WebSocket-Accept mismatch".into(),
            }.into());
        }

        // Create WebSocket object
        let ws_obj = alloc_concurrent_synthetic(ctx, "java/net/http/WebSocket", 6);
        ctx.set_field(ws_obj, P69_WS_FD, Value::Int(fd_id as i32));
        ctx.set_field(ws_obj, P69_WS_OUT_CLOSED, Value::Int(0));
        ctx.set_field(ws_obj, P69_WS_IN_CLOSED, Value::Int(0));
        ctx.set_field(ws_obj, P69_WS_DEMAND, Value::Long(0));
        let sp = ctx.create_string("");
        ctx.set_field(ws_obj, P69_WS_SUBPROTO, Value::Object(Some(sp)));
        ctx.set_field(ws_obj, P69_WS_STATE, Value::Int(0)); // open

        // Store whether this is TLS in a way the send methods can use
        // We'll use the sign of fd_id: negative = TLS
        if use_tls {
            ctx.set_field(ws_obj, P69_WS_FD, Value::Int(-(fd_id as i32)));
        }

        let cf = p58_new_cf(ctx, Value::Object(Some(ws_obj)), true);
        Ok(Some(Value::Object(Some(cf))))
    });

    // WebSocket methods with real RFC 6455 framing
    let ws = "java/net/http/WebSocket";

    // sendText(CharSequence, boolean last) -> CompletableFuture<WebSocket>
    r.register(
        ws,
        "sendText",
        "(Ljava/lang/CharSequence;Z)Ljava/util/concurrent/CompletableFuture;",
        |ctx, args| {
            let this = obj_arg(args, 0)?;
            let text = match args.get(1) {
                Some(Value::Object(Some(s))) => ctx.read_string(*s).unwrap_or_default(),
                _ => String::new(),
            };
            let last = args.get(2).and_then(|v| v.as_int()).unwrap_or(1) != 0;
            let opcode = if last { 0x81 } else { 0x01 }; // FIN + text opcode, or continuation
            ws_send_frame(ctx, this, opcode, text.as_bytes())?;
            let cf = p58_new_cf(ctx, Value::Object(Some(this)), true);
            Ok(Some(Value::Object(Some(cf))))
        },
    );

    // sendBinary(ByteBuffer, boolean last) -> CompletableFuture<WebSocket>
    r.register(
        ws,
        "sendBinary",
        "(Ljava/nio/ByteBuffer;Z)Ljava/util/concurrent/CompletableFuture;",
        |ctx, args| {
            let this = obj_arg(args, 0)?;
            // Read ByteBuffer data (field 0 = backing array)
            let data = match args.get(1) {
                Some(Value::Object(Some(bb))) => match ctx.get_field(*bb, 0) {
                    Value::Object(Some(arr)) => {
                        let len = ctx.array_length(arr);
                        let mut bytes = Vec::with_capacity(len);
                        for i in 0..len {
                            if let Value::Int(b) = ctx.get_array_element(arr, i) {
                                bytes.push(b as u8);
                            }
                        }
                        bytes
                    }
                    _ => Vec::new(),
                },
                _ => Vec::new(),
            };
            let last = args.get(2).and_then(|v| v.as_int()).unwrap_or(1) != 0;
            let opcode = if last { 0x82 } else { 0x02 }; // FIN + binary opcode
            ws_send_frame(ctx, this, opcode, &data)?;
            let cf = p58_new_cf(ctx, Value::Object(Some(this)), true);
            Ok(Some(Value::Object(Some(cf))))
        },
    );

    // sendPing(ByteBuffer) -> CompletableFuture<WebSocket>
    r.register(
        ws,
        "sendPing",
        "(Ljava/nio/ByteBuffer;)Ljava/util/concurrent/CompletableFuture;",
        |ctx, args| {
            let this = obj_arg(args, 0)?;
            let data = match args.get(1) {
                Some(Value::Object(Some(bb))) => match ctx.get_field(*bb, 0) {
                    Value::Object(Some(arr)) => {
                        let len = std::cmp::min(ctx.array_length(arr), 125); // max 125 bytes for control frames
                        let mut bytes = Vec::with_capacity(len);
                        for i in 0..len {
                            if let Value::Int(b) = ctx.get_array_element(arr, i) {
                                bytes.push(b as u8);
                            }
                        }
                        bytes
                    }
                    _ => Vec::new(),
                },
                _ => Vec::new(),
            };
            ws_send_frame(ctx, this, 0x89, &data)?; // 0x89 = FIN + Ping
            let cf = p58_new_cf(ctx, Value::Object(Some(this)), true);
            Ok(Some(Value::Object(Some(cf))))
        },
    );

    // sendPong(ByteBuffer) -> CompletableFuture<WebSocket>
    r.register(
        ws,
        "sendPong",
        "(Ljava/nio/ByteBuffer;)Ljava/util/concurrent/CompletableFuture;",
        |ctx, args| {
            let this = obj_arg(args, 0)?;
            let data = match args.get(1) {
                Some(Value::Object(Some(bb))) => match ctx.get_field(*bb, 0) {
                    Value::Object(Some(arr)) => {
                        let len = std::cmp::min(ctx.array_length(arr), 125);
                        let mut bytes = Vec::with_capacity(len);
                        for i in 0..len {
                            if let Value::Int(b) = ctx.get_array_element(arr, i) {
                                bytes.push(b as u8);
                            }
                        }
                        bytes
                    }
                    _ => Vec::new(),
                },
                _ => Vec::new(),
            };
            ws_send_frame(ctx, this, 0x8A, &data)?; // 0x8A = FIN + Pong
            let cf = p58_new_cf(ctx, Value::Object(Some(this)), true);
            Ok(Some(Value::Object(Some(cf))))
        },
    );

    // sendClose(int statusCode, String reason) -> CompletableFuture<WebSocket>
    r.register(
        ws,
        "sendClose",
        "(ILjava/lang/String;)Ljava/util/concurrent/CompletableFuture;",
        |ctx, args| {
            let this = obj_arg(args, 0)?;
            let status = args.get(1).and_then(|v| v.as_int()).unwrap_or(1000) as u16;
            let reason = match args.get(2) {
                Some(Value::Object(Some(s))) => ctx.read_string(*s).unwrap_or_default(),
                _ => String::new(),
            };
            // Close frame payload: 2-byte status code + reason text
            let mut payload = Vec::with_capacity(2 + reason.len());
            payload.extend_from_slice(&status.to_be_bytes());
            payload.extend_from_slice(reason.as_bytes());
            ws_send_frame(ctx, this, 0x88, &payload)?; // 0x88 = FIN + Close
            ctx.set_field(this, P69_WS_OUT_CLOSED, Value::Int(1));
            ctx.set_field(this, P69_WS_STATE, Value::Int(1)); // closing
            let cf = p58_new_cf(ctx, Value::Object(Some(this)), true);
            Ok(Some(Value::Object(Some(cf))))
        },
    );

    // WebSocket.request(long n) — add to demand counter for backpressure
    r.register(ws, "request", "(J)V", |ctx, args| {
        let this = obj_arg(args, 0)?;
        let n = match args.get(1) { Some(Value::Long(v)) => *v, _ => 0 };
        if n < 0 {
            return Err(RuntimeError::IllegalArgumentException {
                message: "request count must be non-negative".into(),
            }.into());
        }
        if ctx.object_num_fields(this) > P69_WS_DEMAND {
            let current = match ctx.get_field(this, P69_WS_DEMAND) {
                Value::Long(v) => v,
                _ => 0,
            };
            // Saturating add
            let new_demand = current.saturating_add(n);
            ctx.set_field(this, P69_WS_DEMAND, Value::Long(new_demand));
        }
        Ok(None)
    });
    r.register(
        ws,
        "getSubprotocol",
        "()Ljava/lang/String;",
        |ctx, args| {
            let this = obj_arg(args, 0)?;
            Ok(Some(ctx.get_field(this, P69_WS_SUBPROTO)))
        },
    );
    r.register(ws, "isOutputClosed", "()Z", |ctx, args| {
        let this = obj_arg(args, 0)?;
        Ok(Some(ctx.get_field(this, P69_WS_OUT_CLOSED)))
    });
    r.register(ws, "isInputClosed", "()Z", |ctx, args| {
        let this = obj_arg(args, 0)?;
        Ok(Some(ctx.get_field(this, P69_WS_IN_CLOSED)))
    });
    r.register(ws, "abort", "()V", |ctx, args| {
        let this = obj_arg(args, 0)?;
        let fd_val = ctx.get_field(this, P69_WS_FD).as_int().unwrap_or(0);
        let fd_id = fd_val.unsigned_abs();
        if fd_id > 0 {
            let _ = ctx.fd_table().close(fd_id);
        }
        ctx.set_field(this, P69_WS_OUT_CLOSED, Value::Int(1));
        ctx.set_field(this, P69_WS_IN_CLOSED, Value::Int(1));
        ctx.set_field(this, P69_WS_STATE, Value::Int(2)); // closed
        Ok(None)
    });

    // WebSocket.Listener — default methods
    // Per JDK spec, Listener.onOpen default calls webSocket.request(1L) to start receiving.
    let wsl = "java/net/http/WebSocket$Listener";
    r.register(wsl, "onOpen", "(Ljava/net/http/WebSocket;)V", |ctx, args| {
        if let Some(Value::Object(Some(ws))) = args.get(1) {
            let _ = ctx.invoke_virtual(*ws, "request", "(J)V", &[Value::Long(1)]);
        }
        Ok(None)
    });
    r.register(wsl, "onText", "(Ljava/net/http/WebSocket;Ljava/lang/CharSequence;Z)Ljava/util/concurrent/CompletionStage;", |_ctx, _args| {
        Ok(Some(Value::Object(None)))
    });
    r.register(
        wsl,
        "onBinary",
        "(Ljava/net/http/WebSocket;Ljava/nio/ByteBuffer;Z)Ljava/util/concurrent/CompletionStage;",
        |_ctx, _args| Ok(Some(Value::Object(None))),
    );
    r.register(
        wsl,
        "onPing",
        "(Ljava/net/http/WebSocket;Ljava/nio/ByteBuffer;)Ljava/util/concurrent/CompletionStage;",
        |_ctx, _args| Ok(Some(Value::Object(None))),
    );
    r.register(
        wsl,
        "onPong",
        "(Ljava/net/http/WebSocket;Ljava/nio/ByteBuffer;)Ljava/util/concurrent/CompletionStage;",
        |_ctx, _args| Ok(Some(Value::Object(None))),
    );
    r.register(
        wsl,
        "onClose",
        "(Ljava/net/http/WebSocket;ILjava/lang/String;)Ljava/util/concurrent/CompletionStage;",
        |_ctx, _args| Ok(Some(Value::Object(None))),
    );
    r.register(
        wsl,
        "onError",
        "(Ljava/net/http/WebSocket;Ljava/lang/Throwable;)V",
        native_noop_with_this,
    );

    // HttpClient.newWebSocketBuilder
    r.register(
        "java/net/http/HttpClient",
        "newWebSocketBuilder",
        "()Ljava/net/http/WebSocket$Builder;",
        |ctx, _args| {
            let obj = alloc_concurrent_synthetic(ctx, "java/net/http/WebSocket$Builder", 3);
            Ok(Some(Value::Object(Some(obj))))
        },
    );
}

// ===========================================================================
// WebSocket RFC 6455 helper functions
// ===========================================================================

/// Parse a ws:// or wss:// URI into (use_tls, host, port, path)
fn ws_parse_uri(uri: &str) -> (bool, String, u16, String) {
    let (use_tls, rest) = if let Some(r) = uri.strip_prefix("wss://") {
        (true, r)
    } else if let Some(r) = uri.strip_prefix("ws://") {
        (false, r)
    } else {
        (false, uri)
    };
    let default_port = if use_tls { 443 } else { 80 };
    let (host_port, path) = match rest.find('/') {
        Some(idx) => (&rest[..idx], &rest[idx..]),
        None => (rest, "/"),
    };
    let (host, port) = if let Some(colon) = host_port.rfind(':') {
        let port_str = &host_port[colon + 1..];
        if let Ok(p) = port_str.parse::<u16>() {
            (host_port[..colon].to_string(), p)
        } else {
            (host_port.to_string(), default_port)
        }
    } else {
        (host_port.to_string(), default_port)
    };
    (use_tls, host, port, path.to_string())
}

/// Generate a random 16-byte WebSocket key, base64-encoded
fn ws_generate_key() -> String {
    let seed = std::time::SystemTime::now()
        .duration_since(std::time::UNIX_EPOCH)
        .unwrap_or_default()
        .as_nanos() as u64;
    let mut rng = seed;
    let mut key_bytes = [0u8; 16];
    for b in key_bytes.iter_mut() {
        rng = rng.wrapping_mul(6364136223846793005).wrapping_add(1442695040888963407);
        *b = (rng >> 33) as u8;
    }
    ws_base64_encode(&key_bytes)
}

/// Compute Sec-WebSocket-Accept value: base64(SHA-1(key + GUID))
fn ws_compute_accept(key: &str) -> String {
    use crate::real_sha1;
    let magic = "258EAFA5-E914-47DA-95CA-C5AB0DC85B11";
    let mut input = key.to_string();
    input.push_str(magic);
    let hash = real_sha1(input.as_bytes());
    ws_base64_encode(&hash)
}

/// Simple base64 encoder
fn ws_base64_encode(data: &[u8]) -> String {
    const ALPHABET: &[u8] = b"ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/";
    let mut result = String::new();
    let mut i = 0;
    while i + 2 < data.len() {
        let b0 = data[i] as u32;
        let b1 = data[i + 1] as u32;
        let b2 = data[i + 2] as u32;
        let triple = (b0 << 16) | (b1 << 8) | b2;
        result.push(ALPHABET[((triple >> 18) & 0x3F) as usize] as char);
        result.push(ALPHABET[((triple >> 12) & 0x3F) as usize] as char);
        result.push(ALPHABET[((triple >> 6) & 0x3F) as usize] as char);
        result.push(ALPHABET[(triple & 0x3F) as usize] as char);
        i += 3;
    }
    let remaining = data.len() - i;
    if remaining == 2 {
        let b0 = data[i] as u32;
        let b1 = data[i + 1] as u32;
        let triple = (b0 << 16) | (b1 << 8);
        result.push(ALPHABET[((triple >> 18) & 0x3F) as usize] as char);
        result.push(ALPHABET[((triple >> 12) & 0x3F) as usize] as char);
        result.push(ALPHABET[((triple >> 6) & 0x3F) as usize] as char);
        result.push('=');
    } else if remaining == 1 {
        let b0 = data[i] as u32;
        let triple = b0 << 16;
        result.push(ALPHABET[((triple >> 18) & 0x3F) as usize] as char);
        result.push(ALPHABET[((triple >> 12) & 0x3F) as usize] as char);
        result.push('=');
        result.push('=');
    }
    result
}

/// Send a WebSocket frame (RFC 6455 Section 5.2)
/// Client frames MUST be masked.
fn ws_send_frame(
    ctx: &mut dyn NativeContext,
    ws_obj: ObjectRef,
    first_byte: u8,
    payload: &[u8],
) -> Result<(), MethodCallFailed> {
    let fd_val = ctx.get_field(ws_obj, P69_WS_FD).as_int().unwrap_or(0);
    let use_tls = fd_val < 0;
    let fd_id = fd_val.unsigned_abs();

    if fd_id == 0 {
        return Err(RuntimeError::IOException {
            message: "WebSocket not connected".into(),
        }.into());
    }

    let mut frame = Vec::with_capacity(14 + payload.len());
    frame.push(first_byte);

    // Payload length + mask bit (0x80 = masked)
    let len = payload.len();
    if len < 126 {
        frame.push(0x80 | len as u8);
    } else if len < 65536 {
        frame.push(0x80 | 126);
        frame.push((len >> 8) as u8);
        frame.push(len as u8);
    } else {
        frame.push(0x80 | 127);
        let len64 = len as u64;
        frame.extend_from_slice(&len64.to_be_bytes());
    }

    // Masking key (4 random bytes)
    let seed = std::time::SystemTime::now()
        .duration_since(std::time::UNIX_EPOCH)
        .unwrap_or_default()
        .as_nanos() as u64;
    let mut rng = seed;
    let mut mask = [0u8; 4];
    for m in mask.iter_mut() {
        rng = rng.wrapping_mul(6364136223846793005).wrapping_add(1442695040888963407);
        *m = (rng >> 33) as u8;
    }
    frame.extend_from_slice(&mask);

    // Masked payload
    for (i, &b) in payload.iter().enumerate() {
        frame.push(b ^ mask[i % 4]);
    }

    // Write frame
    let write_result = if use_tls {
        ctx.fd_table().tls_write(fd_id, &frame)
    } else {
        ctx.fd_table().tcp_write(fd_id, &frame)
    };
    write_result.map_err(|e| RuntimeError::IOException { message: e.to_string() })?;
    Ok(())
}

