            let prop_name = args.get(1).copied().unwrap_or(Value::Object(None));
            let old_b = args.get(2).and_then(|v| v.as_int()).unwrap_or(0);
            let new_b = args.get(3).and_then(|v| v.as_int()).unwrap_or(0);
