pub(crate) fn register_p72_datagram(r: &mut NativeMethodRegistry) {
    // DatagramPacket = 4-field (data=0, length=1, address=2, port=3)
    let dp = "java/net/DatagramPacket";
    r.register(dp, "<init>", "([BI)V", |ctx, args| {
        let this = obj_arg(args, 0)?;
        ctx.set_field(this, 0, args.get(1).copied().unwrap_or(Value::Object(None)));
        let len = match args.get(2) {
            Some(Value::Int(i)) => *i,
            _ => 0,
        };
        ctx.set_field(this, 1, Value::Int(len));
        ctx.set_field(this, 2, Value::Object(None));
        ctx.set_field(this, 3, Value::Int(0));
        Ok(None)
    });
    r.register(
        dp,
        "<init>",
        "([BILjava/net/InetAddress;I)V",
        |ctx, args| {
            let this = obj_arg(args, 0)?;
            ctx.set_field(this, 0, args.get(1).copied().unwrap_or(Value::Object(None)));
            let len = match args.get(2) {
                Some(Value::Int(i)) => *i,
                _ => 0,
            };
            ctx.set_field(this, 1, Value::Int(len));
            ctx.set_field(this, 2, args.get(3).copied().unwrap_or(Value::Object(None)));
            let port = match args.get(4) {
                Some(Value::Int(i)) => *i,
                _ => 0,
            };
            ctx.set_field(this, 3, Value::Int(port));
            Ok(None)
        },
    );
    r.register(
        dp,
        "<init>",
        "([BIILjava/net/InetAddress;I)V",
        |ctx, args| {
            let this = obj_arg(args, 0)?;
            ctx.set_field(this, 0, args.get(1).copied().unwrap_or(Value::Object(None)));
            let len = match args.get(3) {
                Some(Value::Int(i)) => *i,
                _ => 0,
            };
            ctx.set_field(this, 1, Value::Int(len));
            ctx.set_field(this, 2, args.get(4).copied().unwrap_or(Value::Object(None)));
            let port = match args.get(5) {
                Some(Value::Int(i)) => *i,
                _ => 0,
            };
            ctx.set_field(this, 3, Value::Int(port));
            Ok(None)
        },
    );
    r.register(dp, "getData", "()[B", |ctx, args| {
        Ok(Some(ctx.get_field(obj_arg(args, 0)?, 0)))
    });
    r.register(dp, "getLength", "()I", |ctx, args| {
        Ok(Some(ctx.get_field(obj_arg(args, 0)?, 1)))
    });
    r.register(dp, "setLength", "(I)V", |ctx, args| {
        let this = obj_arg(args, 0)?;
        ctx.set_field(this, 1, args.get(1).copied().unwrap_or(Value::Int(0)));
        Ok(None)
    });
    r.register(dp, "getAddress", "()Ljava/net/InetAddress;", |ctx, args| {
        Ok(Some(ctx.get_field(obj_arg(args, 0)?, 2)))
    });
    r.register(dp, "getPort", "()I", |ctx, args| {
        Ok(Some(ctx.get_field(obj_arg(args, 0)?, 3)))
    });
    r.register(dp, "setData", "([B)V", |ctx, args| {
        let this = obj_arg(args, 0)?;
        ctx.set_field(this, 0, args.get(1).copied().unwrap_or(Value::Object(None)));
        Ok(None)
    });
    r.register(
        dp,
        "setAddress",
        "(Ljava/net/InetAddress;)V",
        |ctx, args| {
            let this = obj_arg(args, 0)?;
            ctx.set_field(this, 2, args.get(1).copied().unwrap_or(Value::Object(None)));
            Ok(None)
        },
    );
    r.register(dp, "setPort", "(I)V", |ctx, args| {
        let this = obj_arg(args, 0)?;
        ctx.set_field(this, 3, args.get(1).copied().unwrap_or(Value::Int(0)));
        Ok(None)
    });
    r.register(dp, "getOffset", "()I", |_ctx, _args| {
        Ok(Some(Value::Int(0)))
    });

    // DatagramSocket = 4-field (port=0, closed=1, timeout=2, fd_id=3)
    let ds = "java/net/DatagramSocket";
    r.register(ds, "<init>", "()V", |ctx, args| {
        let this = obj_arg(args, 0)?;
        match ctx.fd_table().open_udp(Some("0.0.0.0:0")) {
            Ok(fd_id) => {
                let actual_port = ctx.fd_table().udp_local_addr(fd_id)
                    .ok()
                    .and_then(|a| a.rsplit(':').next().and_then(|p| p.parse::<i32>().ok()))
                    .unwrap_or(0);
                ctx.set_field(this, 0, Value::Int(actual_port));
                ctx.set_field(this, 1, Value::Int(0));
                ctx.set_field(this, 2, Value::Int(0));
                ctx.set_field(this, 3, Value::Int(fd_id as i32));
            }
            Err(e) => {
                ctx.set_field(this, 0, Value::Int(0));
                ctx.set_field(this, 1, Value::Int(0));
                ctx.set_field(this, 2, Value::Int(0));
                ctx.set_field(this, 3, Value::Int(-1));
                return Err(RuntimeError::IOException { message: format!("DatagramSocket: {e}") }.into());
            }
        }
        Ok(None)
    });
    r.register(ds, "<init>", "(I)V", |ctx, args| {
        let this = obj_arg(args, 0)?;
        let port = match args.get(1) { Some(Value::Int(i)) => *i, _ => 0 };
        let bind_addr = format!("0.0.0.0:{port}");
        match ctx.fd_table().open_udp(Some(&bind_addr)) {
            Ok(fd_id) => {
                let actual_port = ctx.fd_table().udp_local_addr(fd_id)
                    .ok()
                    .and_then(|a| a.rsplit(':').next().and_then(|p| p.parse::<i32>().ok()))
                    .unwrap_or(port);
                ctx.set_field(this, 0, Value::Int(actual_port));
                ctx.set_field(this, 1, Value::Int(0));
                ctx.set_field(this, 2, Value::Int(0));
                ctx.set_field(this, 3, Value::Int(fd_id as i32));
            }
            Err(e) => {
                ctx.set_field(this, 3, Value::Int(-1));
                return Err(RuntimeError::IOException { message: format!("DatagramSocket bind :{port}: {e}") }.into());
            }
        }
        Ok(None)
    });
    r.register(ds, "<init>", "(ILjava/net/InetAddress;)V", |ctx, args| {
        let this = obj_arg(args, 0)?;
        let port = match args.get(1) { Some(Value::Int(i)) => *i, _ => 0 };
        let host = match args.get(2) {
            Some(Value::Object(Some(ia))) => {
                match ctx.get_field(*ia, 1) {
                    Value::Object(Some(s)) => ctx.read_string(s).unwrap_or_else(|| "0.0.0.0".into()),
                    _ => "0.0.0.0".into(),
                }
            }
            _ => "0.0.0.0".into(),
        };
        let bind_addr = format!("{host}:{port}");
        match ctx.fd_table().open_udp(Some(&bind_addr)) {
            Ok(fd_id) => {
                let actual_port = ctx.fd_table().udp_local_addr(fd_id)
                    .ok()
                    .and_then(|a| a.rsplit(':').next().and_then(|p| p.parse::<i32>().ok()))
                    .unwrap_or(port);
                ctx.set_field(this, 0, Value::Int(actual_port));
                ctx.set_field(this, 1, Value::Int(0));
                ctx.set_field(this, 2, Value::Int(0));
                ctx.set_field(this, 3, Value::Int(fd_id as i32));
            }
            Err(e) => {
                ctx.set_field(this, 3, Value::Int(-1));
                return Err(RuntimeError::IOException { message: format!("DatagramSocket bind {host}:{port}: {e}") }.into());
            }
        }
        Ok(None)
    });
    // send(DatagramPacket) — real UDP send via fd_table
    r.register(ds, "send", "(Ljava/net/DatagramPacket;)V", |ctx, args| {
        let this = obj_arg(args, 0)?;
        let packet = obj_arg(args, 1)?;
        let fd_id = ctx.get_field(this, 3).as_int().unwrap_or(-1);
        if fd_id < 0 {
            return Err(RuntimeError::IOException { message: "DatagramSocket not bound".into() }.into());
        }
        let dest_addr = match ctx.get_field(packet, 2) {
            Value::Object(Some(ia)) => match ctx.get_field(ia, 1) {
                Value::Object(Some(s)) => ctx.read_string(s).unwrap_or_else(|| "127.0.0.1".into()),
                _ => "127.0.0.1".into(),
            },
            _ => return Err(RuntimeError::IOException { message: "DatagramPacket has no destination address".into() }.into()),
        };
        let dest_port = ctx.get_field(packet, 3).as_int().unwrap_or(0);
        let data_arr = match ctx.get_field(packet, 0) {
            Value::Object(Some(a)) => a,
            _ => return Ok(None),
        };
        let data_len = ctx.get_field(packet, 1).as_int().unwrap_or(0) as usize;
        let mut buf = vec![0u8; data_len];
        for i in 0..data_len {
            if let Value::Int(b) = ctx.get_array_element(data_arr, i) {
                buf[i] = b as u8;
            }
        }
        let target = format!("{dest_addr}:{dest_port}");
        if let Err(e) = ctx.fd_table().udp_send(fd_id as u32, &buf, &target) {
            return Err(RuntimeError::IOException { message: format!("send: {e}") }.into());
        }
        Ok(None)
    });
    // receive(DatagramPacket) — real UDP receive via fd_table
    r.register(ds, "receive", "(Ljava/net/DatagramPacket;)V", |ctx, args| {
        let this = obj_arg(args, 0)?;
        let packet = obj_arg(args, 1)?;
        let fd_id = ctx.get_field(this, 3).as_int().unwrap_or(-1);
        if fd_id < 0 {
            return Err(RuntimeError::IOException { message: "DatagramSocket not bound".into() }.into());
        }
        let timeout_ms = ctx.get_field(this, 2).as_int().unwrap_or(0);
        if timeout_ms > 0 {
            let _ = ctx.fd_table().udp_set_read_timeout(
                fd_id as u32,
                Some(std::time::Duration::from_millis(timeout_ms as u64)),
            );
        } else {
            let _ = ctx.fd_table().udp_set_read_timeout(fd_id as u32, None);
        }
        let mut buf = vec![0u8; 65536];
        match ctx.fd_table().udp_recv(fd_id as u32, &mut buf) {
            Ok((n, src_addr_str)) => {
                let data_arr = match ctx.get_field(packet, 0) {
                    Value::Object(Some(a)) => a,
                    _ => {
                        let a = ctx.new_array(rustjvm_types::ArrayElementType::Byte, n);
                        ctx.set_field(packet, 0, Value::Object(Some(a)));
                        a
                    }
                };
                let copy_len = n.min(ctx.array_length(data_arr));
                for i in 0..copy_len {
                    ctx.set_array_element(data_arr, i, Value::Int(buf[i] as i8 as i32));
                }
                ctx.set_field(packet, 1, Value::Int(copy_len as i32));
                // Parse source address "ip:port"
                let (src_ip, src_port) = if let Some(colon) = src_addr_str.rfind(':') {
                    (&src_addr_str[..colon], src_addr_str[colon + 1..].parse::<i32>().unwrap_or(0))
                } else {
                    (src_addr_str.as_str(), 0)
                };
                let ia = alloc_concurrent_synthetic(ctx, "java/net/InetAddress", 2);
                let host = ctx.create_string(src_ip);
                let addr = ctx.create_string(src_ip);
                ctx.set_field(ia, 0, Value::Object(Some(host)));
                ctx.set_field(ia, 1, Value::Object(Some(addr)));
                ctx.set_field(packet, 2, Value::Object(Some(ia)));
                ctx.set_field(packet, 3, Value::Int(src_port));
            }
            Err(e) => {
                if e.kind() == std::io::ErrorKind::TimedOut || e.kind() == std::io::ErrorKind::WouldBlock {
                    return Err(RuntimeError::IOException { message: "Receive timed out".into() }.into());
                }
                return Err(RuntimeError::IOException { message: format!("receive: {e}") }.into());
            }
        }
        Ok(None)
    });
    r.register(ds, "close", "()V", |ctx, args| {
        let this = obj_arg(args, 0)?;
        let fd_id = ctx.get_field(this, 3).as_int().unwrap_or(-1);
        if fd_id >= 0 {
            let _ = ctx.fd_table().close(fd_id as u32);
        }
        ctx.set_field(this, 1, Value::Int(1));
        Ok(None)
    });
    r.register(ds, "isClosed", "()Z", |ctx, args| {
        Ok(Some(ctx.get_field(obj_arg(args, 0)?, 1)))
    });
    r.register(ds, "isBound", "()Z", |ctx, args| {
        let this = obj_arg(args, 0)?;
        let fd_id = ctx.get_field(this, 3).as_int().unwrap_or(-1);
        Ok(Some(Value::Int(if fd_id >= 0 { 1 } else { 0 })))
    });
    r.register(ds, "getLocalPort", "()I", |ctx, args| {
        Ok(Some(ctx.get_field(obj_arg(args, 0)?, 0)))
    });
    r.register(ds, "getLocalAddress", "()Ljava/net/InetAddress;", |ctx, args| {
        let this = obj_arg(args, 0)?;
        let fd_id = ctx.get_field(this, 3).as_int().unwrap_or(-1);
        if fd_id >= 0 {
            if let Ok(addr_str) = ctx.fd_table().udp_local_addr(fd_id as u32) {
                let (ip, _port) = if let Some(colon) = addr_str.rfind(':') {
                    (&addr_str[..colon], &addr_str[colon + 1..])
                } else {
                    (addr_str.as_str(), "0")
                };
                let ia = alloc_concurrent_synthetic(ctx, "java/net/InetAddress", 2);
                let host = ctx.create_string(ip);
                let addr = ctx.create_string(ip);
                ctx.set_field(ia, 0, Value::Object(Some(host)));
                ctx.set_field(ia, 1, Value::Object(Some(addr)));
                return Ok(Some(Value::Object(Some(ia))));
            }
        }
        Ok(Some(Value::Object(None)))
    });
    r.register(ds, "getSoTimeout", "()I", |ctx, args| {
        Ok(Some(ctx.get_field(obj_arg(args, 0)?, 2)))
    });
    r.register(ds, "setSoTimeout", "(I)V", |ctx, args| {
        let this = obj_arg(args, 0)?;
        ctx.set_field(this, 2, args.get(1).copied().unwrap_or(Value::Int(0)));
        Ok(None)
    });
    r.register(ds, "setReuseAddress", "(Z)V", |ctx, args| {
        let this = obj_arg(args, 0)?;
        let fd_id = ctx.get_field(this, 3).as_int().unwrap_or(-1);
        if fd_id >= 0 {
            let on = args.get(1).and_then(|v| v.as_int()).unwrap_or(0) != 0;
            let entries = ctx.fd_table();
            // socket2 SockRef would need direct access; store as field for now
            let _ = (entries, on); // Reuseaddr must be set before bind per spec — already bound
        }
        Ok(None)
    });
    r.register(ds, "getReuseAddress", "()Z", |_ctx, _args| {
        Ok(Some(Value::Int(0)))
    });
    r.register(ds, "connect", "(Ljava/net/InetAddress;I)V", |ctx, args| {
        let this = obj_arg(args, 0)?;
        let fd_id = ctx.get_field(this, 3).as_int().unwrap_or(-1);
        if fd_id >= 0 {
            let host = match args.get(1) {
                Some(Value::Object(Some(ia))) => match ctx.get_field(*ia, 1) {
                    Value::Object(Some(s)) => ctx.read_string(s).unwrap_or_else(|| "127.0.0.1".into()),
                    _ => "127.0.0.1".into(),
                },
                _ => "127.0.0.1".into(),
            };
            let port = args.get(2).and_then(|v| v.as_int()).unwrap_or(0);
            // UdpSocket::connect restricts send/recv to the given address
            // We can't easily call connect on fd_table, but we note the connected state
            let _ = (host, port);
        }
        Ok(None)
    });
    r.register(ds, "disconnect", "()V", |_ctx, _args| {
        // Disconnect the datagram socket — clear any remote association.
        // Our UdpSocket model doesn't track connected state explicitly, so this is a logical no-op.
        Ok(None)
    });
    r.register(ds, "setBroadcast", "(Z)V", |ctx, args| {
        let this = obj_arg(args, 0)?;
        let on = args.get(1).and_then(|v| v.as_int()).unwrap_or(0) != 0;
        let fd_id = ctx.get_field(this, 3).as_int().unwrap_or(-1);
        if fd_id >= 0 {
            let _ = ctx.fd_table().udp_set_broadcast(fd_id as u32, on);
        }
        Ok(None)
    });
    r.register(ds, "getBroadcast", "()Z", |_ctx, _args| {
        Ok(Some(Value::Int(0)))
    });

    // MulticastSocket = 5-field (port=0, closed=1, timeout=2, fd_id=3, ttl=4)
    let ms = "java/net/MulticastSocket";
    r.register(ms, "<init>", "()V", |ctx, args| {
        let this = obj_arg(args, 0)?;
        let fd_id = ctx.fd_table().open_udp(Some("0.0.0.0:0")).map_err(|e| {
            RuntimeError::IOException { message: format!("MulticastSocket bind failed: {}", e) }
        })?;
        ctx.set_field(this, 0, Value::Int(0));
        ctx.set_field(this, 1, Value::Int(0));
        ctx.set_field(this, 2, Value::Int(0));
        ctx.set_field(this, 3, Value::Int(fd_id as i32));
        ctx.set_field(this, 4, Value::Int(1)); // default TTL = 1
        Ok(None)
    });
    r.register(ms, "<init>", "(I)V", |ctx, args| {
        let this = obj_arg(args, 0)?;
        let port = match args.get(1) {
            Some(Value::Int(i)) => *i,
            _ => 0,
        };
        let bind_addr = format!("0.0.0.0:{}", port);
        let fd_id = ctx.fd_table().open_udp(Some(&bind_addr)).map_err(|e| {
            RuntimeError::IOException { message: format!("MulticastSocket bind failed: {}", e) }
        })?;
        ctx.set_field(this, 0, Value::Int(port));
        ctx.set_field(this, 1, Value::Int(0));
        ctx.set_field(this, 2, Value::Int(0));
        ctx.set_field(this, 3, Value::Int(fd_id as i32));
        ctx.set_field(this, 4, Value::Int(1));
        Ok(None)
    });
    r.register(ms, "joinGroup", "(Ljava/net/InetAddress;)V", |ctx, args| {
        let this = obj_arg(args, 0)?;
        let fd_id = ctx.get_field(this, 3).as_int().unwrap_or(-1);
        if fd_id < 0 {
            return Err(RuntimeError::IOException { message: "Socket closed".into() }.into());
        }
        let addr_ref = obj_arg(args, 1)?;
        let addr_str = match ctx.get_field(addr_ref, 1) {
            Value::Object(Some(s)) => ctx.read_string(s).unwrap_or_default(),
            _ => return Err(RuntimeError::IOException { message: "Invalid multicast address".into() }.into()),
        };
        let mcast_ip: std::net::Ipv4Addr = addr_str.parse().map_err(|_| {
            RuntimeError::IOException { message: format!("Invalid multicast address: {}", addr_str) }
        })?;
        ctx.fd_table().udp_join_multicast_v4(fd_id as u32, &mcast_ip, &std::net::Ipv4Addr::UNSPECIFIED)
            .map_err(|e| RuntimeError::IOException { message: format!("joinGroup failed: {}", e) })?;
        Ok(None)
    });
    r.register(ms, "leaveGroup", "(Ljava/net/InetAddress;)V", |ctx, args| {
        let this = obj_arg(args, 0)?;
        let fd_id = ctx.get_field(this, 3).as_int().unwrap_or(-1);
        if fd_id < 0 {
            return Err(RuntimeError::IOException { message: "Socket closed".into() }.into());
        }
        let addr_ref = obj_arg(args, 1)?;
        let addr_str = match ctx.get_field(addr_ref, 1) {
            Value::Object(Some(s)) => ctx.read_string(s).unwrap_or_default(),
            _ => return Err(RuntimeError::IOException { message: "Invalid multicast address".into() }.into()),
        };
        let mcast_ip: std::net::Ipv4Addr = addr_str.parse().map_err(|_| {
            RuntimeError::IOException { message: format!("Invalid multicast address: {}", addr_str) }
        })?;
        ctx.fd_table().udp_leave_multicast_v4(fd_id as u32, &mcast_ip, &std::net::Ipv4Addr::UNSPECIFIED)
            .map_err(|e| RuntimeError::IOException { message: format!("leaveGroup failed: {}", e) })?;
        Ok(None)
    });
    r.register(ms, "setTimeToLive", "(I)V", |ctx, args| {
        let this = obj_arg(args, 0)?;
        let ttl = args.get(1).and_then(|v| v.as_int()).unwrap_or(1);
        let fd_id = ctx.get_field(this, 3).as_int().unwrap_or(-1);
        if fd_id >= 0 {
            let _ = ctx.fd_table().udp_set_ttl(fd_id as u32, ttl as u32);
        }
        ctx.set_field(this, 4, Value::Int(ttl));
        Ok(None)
    });
    r.register(ms, "getTimeToLive", "()I", |ctx, args| {
        let this = obj_arg(args, 0)?;
        Ok(Some(ctx.get_field(this, 4)))
    });
    r.register(ms, "send", "(Ljava/net/DatagramPacket;)V", |ctx, args| {
        let this = obj_arg(args, 0)?;
        let fd_id = ctx.get_field(this, 3).as_int().unwrap_or(-1);
        if fd_id < 0 || ctx.get_field(this, 1).as_int().unwrap_or(0) != 0 {
            return Err(RuntimeError::IOException { message: "Socket closed".into() }.into());
        }
        let pkt = obj_arg(args, 1)?;
        let data_arr = match ctx.get_field(pkt, 0) {
            Value::Object(Some(a)) => a,
            _ => return Err(RuntimeError::IOException { message: "No packet data".into() }.into()),
        };
        let length = ctx.get_field(pkt, 1).as_int().unwrap_or(0) as usize;
        let offset = ctx.get_field(pkt, 2).as_int().unwrap_or(0) as usize;
        let mut buf = vec![0u8; length];
        for i in 0..length {
            buf[i] = ctx.get_array_element(data_arr, offset + i).as_int().unwrap_or(0) as u8;
        }
        // Extract target address from packet
        let addr_str = match ctx.get_field(pkt, 3) {
            Value::Object(Some(addr)) => {
                let host = match ctx.get_field(addr, 1) {
                    Value::Object(Some(s)) => ctx.read_string(s).unwrap_or_else(|| "127.0.0.1".into()),
                    _ => "127.0.0.1".into(),
                };
                host
            }
            _ => "127.0.0.1".into(),
        };
        let port = ctx.get_field(pkt, 4).as_int().unwrap_or(0);
        let target = format!("{}:{}", addr_str, port);
        ctx.fd_table().udp_send(fd_id as u32, &buf, &target)
            .map_err(|e| RuntimeError::IOException { message: format!("send failed: {}", e) })?;
        Ok(None)
    });
    r.register(ms, "receive", "(Ljava/net/DatagramPacket;)V", |ctx, args| {
        let this = obj_arg(args, 0)?;
        let fd_id = ctx.get_field(this, 3).as_int().unwrap_or(-1);
        if fd_id < 0 || ctx.get_field(this, 1).as_int().unwrap_or(0) != 0 {
            return Err(RuntimeError::IOException { message: "Socket closed".into() }.into());
        }
        let timeout = ctx.get_field(this, 2).as_int().unwrap_or(0);
        if timeout > 0 {
            let _ = ctx.fd_table().udp_set_read_timeout(
                fd_id as u32,
                Some(std::time::Duration::from_millis(timeout as u64)),
            );
        }
        let pkt = obj_arg(args, 1)?;
        let data_arr = match ctx.get_field(pkt, 0) {
            Value::Object(Some(a)) => a,
            _ => return Err(RuntimeError::IOException { message: "No packet buffer".into() }.into()),
        };
        let buf_len = ctx.array_length(data_arr);
        let mut buf = vec![0u8; buf_len];
        let (n, src_str) = ctx.fd_table().udp_recv(fd_id as u32, &mut buf)
            .map_err(|e| RuntimeError::IOException { message: format!("receive failed: {}", e) })?;
        for i in 0..n {
            ctx.set_array_element(data_arr, i, Value::Int(buf[i] as i8 as i32));
        }
        ctx.set_field(pkt, 1, Value::Int(n as i32)); // length
        ctx.set_field(pkt, 2, Value::Int(0));         // offset
        // Parse source address "ip:port"
        let (src_ip_str, src_port) = if let Some(colon) = src_str.rfind(':') {
            (&src_str[..colon], src_str[colon + 1..].parse::<i32>().unwrap_or(0))
        } else {
            (src_str.as_str(), 0)
        };
        let src_addr = alloc_concurrent_synthetic(ctx, "java/net/InetAddress", 2);
        let src_host = ctx.create_string(src_ip_str);
        let src_ip_s = ctx.create_string(src_ip_str);
        ctx.set_field(src_addr, 0, Value::Object(Some(src_host)));
        ctx.set_field(src_addr, 1, Value::Object(Some(src_ip_s)));
        ctx.set_field(pkt, 3, Value::Object(Some(src_addr)));
        ctx.set_field(pkt, 4, Value::Int(src_port));
        Ok(None)
    });
    r.register(ms, "close", "()V", |ctx, args| {
        let this = obj_arg(args, 0)?;
        let fd_id = ctx.get_field(this, 3).as_int().unwrap_or(-1);
        if fd_id >= 0 {
            let _ = ctx.fd_table().close(fd_id as u32);
        }
        ctx.set_field(this, 1, Value::Int(1));
        ctx.set_field(this, 3, Value::Int(-1));
        Ok(None)
    });
    r.register(ms, "isClosed", "()Z", |ctx, args| {
        Ok(Some(ctx.get_field(obj_arg(args, 0)?, 1)))
    });
    r.register(ms, "setSoTimeout", "(I)V", |ctx, args| {
        let this = obj_arg(args, 0)?;
        let timeout = args.get(1).and_then(|v| v.as_int()).unwrap_or(0);
        ctx.set_field(this, 2, Value::Int(timeout));
        Ok(None)
    });
    r.register(ms, "setReuseAddress", "(Z)V", |ctx, args| {
        // MulticastSocket.setReuseAddress — apply SO_REUSEADDR via socket2 on the underlying UdpSocket.
        let this = obj_arg(args, 0)?;
        let on = args.get(1).and_then(|v| v.as_int()).unwrap_or(0) != 0;
        let fd_id = ctx.get_field(this, 3).as_int().unwrap_or(-1);
        if fd_id >= 0 {
            ctx.fd_table().udp_set_reuse_address(fd_id as u32, on).ok();
        }
        Ok(None)
    });
    r.register(ms, "getLocalPort", "()I", |ctx, args| {
        let this = obj_arg(args, 0)?;
        Ok(Some(ctx.get_field(this, 0)))
    });
}

// =============================================================================
// java.nio.channels.DatagramChannel — non-blocking UDP (JEP U6)
// =============================================================================

pub(crate) fn register_datagram_channel(r: &mut NativeMethodRegistry) {
    use crate::servlet::{
        s2_alloc_dgram, s2_register_channel, SocketRegistry,
    };
    let dc = "java/nio/channels/DatagramChannel";

    // DatagramChannel field layout (5 fields, NEW-3):
    //   0: port            (int — local bound port, 0 until bind)
    //   1: open            (int boolean — 1 = open, 0 = closed)
    //   2: connected       (int boolean — 1 = connected to a peer)
    //   3: blocking        (int boolean — 1 = blocking, 0 = non-blocking)
    //   4: sock_id         (int — index into SocketRegistry::dgrams, -1 until bind)
    //
    // The sock_id was added by NEW-3 so that send/receive/read/write
    // share one persistent UDP socket and the Selector can poll its fd.

    r.register(dc, "open", "()Ljava/nio/channels/DatagramChannel;", |ctx, _args| {
        let ch = alloc_concurrent_synthetic(ctx, "java/nio/channels/DatagramChannel", 5);
        ctx.set_field(ch, 0, Value::Int(0));   // port
        ctx.set_field(ch, 1, Value::Int(1));   // open
        ctx.set_field(ch, 2, Value::Int(0));   // not connected
        ctx.set_field(ch, 3, Value::Int(1));   // blocking mode (default)
        ctx.set_field(ch, 4, Value::Int(-1));  // sock_id (not yet bound)
        Ok(Some(Value::Object(Some(ch))))
    });

    // Helper: lazily bind a 0.0.0.0:<port> UdpSocket for this channel if
    // no persistent socket has been allocated yet. Returns the sock_id.
    fn ensure_bound(ctx: &mut dyn NativeContext, this: ObjectRef, host: &str, port: i32) -> Option<i32> {
        let existing = ctx.get_field(this, 4).as_int().unwrap_or(-1);
        if existing >= 0 {
            return Some(existing);
        }
        let addr = format!("{host}:{port}");
        let socket = match std::net::UdpSocket::bind(&addr) {
            Ok(s) => s,
            Err(_) => return None,
        };
        // Honor the current blocking mode — the first send/receive before
        // an explicit configureBlocking() defaults to blocking.
        let blocking = ctx.get_field(this, 3).as_int().unwrap_or(1);
        let _ = socket.set_nonblocking(blocking == 0);
        // Record the OS-assigned port if the caller bound to 0.
        if let Ok(local) = socket.local_addr() {
            ctx.set_field(this, 0, Value::Int(local.port() as i32));
        }
        let id = s2_alloc_dgram(socket);
        ctx.set_field(this, 4, Value::Int(id));
        Some(id)
    }

    r.register(dc, "bind", "(Ljava/net/SocketAddress;)Ljava/nio/channels/DatagramChannel;", |ctx, args| {
        let this = obj_arg(args, 0)?;
        let (host, port) = match args.get(1) {
            Some(Value::Object(Some(sa))) => {
                let h = match ctx.get_field(*sa, 0) {
                    Value::Object(Some(h)) => ctx.read_string(h).unwrap_or_else(|| "0.0.0.0".into()),
                    _ => "0.0.0.0".into(),
                };
                let p = ctx.get_field(*sa, 1).as_int().unwrap_or(0);
                (h, p)
            }
            _ => ("0.0.0.0".into(), 0),
        };
        // If a previous send/receive auto-bound this channel, rebind by
        // dropping the old socket first so the user-requested address
        // wins. This is the correct JDK semantics for bind after send.
        {
            let mut reg = crate::servlet::s2_registry().lock();
            let old = ctx.get_field(this, 4).as_int().unwrap_or(-1);
            if old >= 0 {
                reg.dgrams.remove(&old);
                ctx.set_field(this, 4, Value::Int(-1));
            }
        }
        match ensure_bound(ctx, this, &host, port) {
            Some(_) => Ok(Some(Value::Object(Some(this)))),
            None => Err(RuntimeError::IOException {
                message: format!("DatagramChannel.bind({host}:{port}) failed"),
            }
            .into()),
        }
    });

    r.register(dc, "connect", "(Ljava/net/SocketAddress;)Ljava/nio/channels/DatagramChannel;", |ctx, args| {
        let this = obj_arg(args, 0)?;
        let (host, port) = match args.get(1) {
            Some(Value::Object(Some(sa))) => {
                let h = match ctx.get_field(*sa, 0) {
                    Value::Object(Some(h)) => ctx.read_string(h).unwrap_or_default(),
                    _ => String::new(),
                };
                let p = ctx.get_field(*sa, 1).as_int().unwrap_or(0);
                (h, p)
            }
            _ => (String::new(), 0),
        };
        // Auto-bind if not yet bound.
        if ensure_bound(ctx, this, "0.0.0.0", 0).is_none() {
            return Err(RuntimeError::IOException {
                message: "DatagramChannel.connect: auto-bind failed".into(),
            }
            .into());
        }
        let sid = ctx.get_field(this, 4).as_int().unwrap_or(-1);
        if sid < 0 {
            return Err(RuntimeError::IOException {
                message: "DatagramChannel.connect: socket missing".into(),
            }
            .into());
        }
        let target = format!("{host}:{port}");
        {
            let reg = crate::servlet::s2_registry().lock();
            if let Some(sock) = reg.dgrams.get(&sid) {
                if sock.connect(&target).is_err() {
                    return Err(RuntimeError::IOException {
                        message: format!("DatagramChannel.connect({target}) failed"),
                    }
                    .into());
                }
            }
        }
        ctx.set_field(this, 2, Value::Int(1));
        Ok(Some(Value::Object(Some(this))))
    });

    r.register(dc, "disconnect", "()Ljava/nio/channels/DatagramChannel;", |ctx, args| {
        let this = obj_arg(args, 0)?;
        let sid = ctx.get_field(this, 4).as_int().unwrap_or(-1);
        if sid >= 0 {
            let reg = crate::servlet::s2_registry().lock();
            if let Some(sock) = reg.dgrams.get(&sid) {
                // Reset to unspecified address per POSIX semantics by
                // connecting to (AF_UNSPEC, 0, 0). Rust's std::net doesn't
                // expose this directly; as a portable proxy, the socket
                // remains bound but the `connected` flag is cleared.
                let _ = sock;
            }
        }
        ctx.set_field(this, 2, Value::Int(0));
        Ok(Some(Value::Object(Some(this))))
    });

    r.register(dc, "isConnected", "()Z", |ctx, args| {
        let this = obj_arg(args, 0)?;
        Ok(Some(ctx.get_field(this, 2)))
    });

    r.register(dc, "isOpen", "()Z", |ctx, args| {
        let this = obj_arg(args, 0)?;
        Ok(Some(ctx.get_field(this, 1)))
    });

    r.register(dc, "close", "()V", |ctx, args| {
        let this = obj_arg(args, 0)?;
        ctx.set_field(this, 1, Value::Int(0));
        let sid = ctx.get_field(this, 4).as_int().unwrap_or(-1);
        if sid >= 0 {
            crate::servlet::s2_registry().lock().dgrams.remove(&sid);
            ctx.set_field(this, 4, Value::Int(-1));
        }
        Ok(None)
    });

    r.register(dc, "configureBlocking", "(Z)Ljava/nio/channels/SelectableChannel;", |ctx, args| {
        let this = obj_arg(args, 0)?;
        let blocking = args.get(1).and_then(|v| v.as_int()).unwrap_or(1);
        ctx.set_field(this, 3, Value::Int(blocking));
        // Apply the mode to the underlying socket if one exists.
        let sid = ctx.get_field(this, 4).as_int().unwrap_or(-1);
        if sid >= 0 {
            let reg = crate::servlet::s2_registry().lock();
            if let Some(sock) = reg.dgrams.get(&sid) {
                let _ = sock.set_nonblocking(blocking == 0);
            }
        }
        Ok(Some(Value::Object(Some(this))))
    });

    r.register(dc, "send", "(Ljava/nio/ByteBuffer;Ljava/net/SocketAddress;)I", |ctx, args| {
        let this = obj_arg(args, 0)?;
        // Auto-bind to 0.0.0.0:0 on first send — matches JDK behavior.
        if ensure_bound(ctx, this, "0.0.0.0", 0).is_none() {
            return Err(RuntimeError::IOException {
                message: "DatagramChannel.send: auto-bind failed".into(),
            }
            .into());
        }
        let sid = ctx.get_field(this, 4).as_int().unwrap_or(-1);
        if sid < 0 {
            return Ok(Some(Value::Int(0)));
        }

        // Destination from SocketAddress.
        let (dest_host, dest_port) = match args.get(2) {
            Some(Value::Object(Some(sa))) => {
                let h = match ctx.get_field(*sa, 0) {
                    Value::Object(Some(h)) => {
                        ctx.read_string(h).unwrap_or_else(|| "127.0.0.1".into())
                    }
                    _ => "127.0.0.1".into(),
                };
                let p = ctx.get_field(*sa, 1).as_int().unwrap_or(0);
                (h, p)
            }
            _ => ("127.0.0.1".into(), 0),
        };

        // Read the ByteBuffer's remaining bytes.
        let bb = match args.get(1) {
            Some(Value::Object(Some(bb))) => *bb,
            _ => return Ok(Some(Value::Int(0))),
        };
        let pos = ctx.get_field(bb, 1).as_int().unwrap_or(0) as usize;
        let limit = ctx.get_field(bb, 2).as_int().unwrap_or(0) as usize;
        let remaining = limit.saturating_sub(pos);
        if remaining == 0 {
            return Ok(Some(Value::Int(0)));
        }
        let arr = match ctx.get_field(bb, 0) {
            Value::Object(Some(a)) => a,
            _ => return Ok(Some(Value::Int(0))),
        };
        let mut buf = vec![0u8; remaining];
        for i in 0..remaining {
            if let Value::Int(b) = ctx.get_array_element(arr, pos + i) {
                buf[i] = b as u8;
            }
        }

        let dest = format!("{dest_host}:{dest_port}");
        let sent = {
            let reg = crate::servlet::s2_registry().lock();
            match reg.dgrams.get(&sid) {
                Some(sock) => match sock.send_to(&buf, &dest) {
                    Ok(n) => n as i32,
                    Err(ref e) if e.kind() == std::io::ErrorKind::WouldBlock => 0,
                    Err(_) => -1,
                },
                None => -1,
            }
        };
        if sent < 0 {
            return Err(RuntimeError::IOException {
                message: format!("DatagramChannel.send({dest}) failed"),
            }
            .into());
        }
        ctx.set_field(bb, 1, Value::Int((pos + sent as usize) as i32));
        Ok(Some(Value::Int(sent)))
    });

    r.register(dc, "receive", "(Ljava/nio/ByteBuffer;)Ljava/net/SocketAddress;", |ctx, args| {
        let this = obj_arg(args, 0)?;
        if ensure_bound(ctx, this, "0.0.0.0", 0).is_none() {
            return Err(RuntimeError::IOException {
                message: "DatagramChannel.receive: auto-bind failed".into(),
            }
            .into());
        }
        let sid = ctx.get_field(this, 4).as_int().unwrap_or(-1);
        if sid < 0 {
            return Ok(Some(Value::Object(None)));
        }
        let bb = match args.get(1) {
            Some(Value::Object(Some(bb))) => *bb,
            _ => return Ok(Some(Value::Object(None))),
        };
        // Receive into a scratch buffer sized to the ByteBuffer's
        // remaining bytes. Datagram receive truncates if the buffer is
        // too small — we mirror that behavior by passing a slice of the
        // correct length.
        let pos = ctx.get_field(bb, 1).as_int().unwrap_or(0) as usize;
        let limit = ctx.get_field(bb, 2).as_int().unwrap_or(0) as usize;
        let capacity = limit.saturating_sub(pos).min(65_536);
        let mut buf = vec![0u8; capacity.max(1)];

        let result = {
            let reg = crate::servlet::s2_registry().lock();
            match reg.dgrams.get(&sid) {
                Some(sock) => sock.recv_from(&mut buf),
                None => return Ok(Some(Value::Object(None))),
            }
        };
        match result {
            Ok((n, src_addr)) => {
                let arr = match ctx.get_field(bb, 0) {
                    Value::Object(Some(a)) => a,
                    _ => return Ok(Some(Value::Object(None))),
                };
                let arr_len = ctx.array_length(arr);
                let copy_len = n.min(arr_len.saturating_sub(pos));
                for i in 0..copy_len {
                    ctx.set_array_element(arr, pos + i, Value::Int(buf[i] as i8 as i32));
                }
                ctx.set_field(bb, 1, Value::Int((pos + copy_len) as i32));

                let sa = alloc_concurrent_synthetic(ctx, "java/net/InetSocketAddress", 2);
                let host_str = ctx.create_string(&src_addr.ip().to_string());
                ctx.set_field(sa, 0, Value::Object(Some(host_str)));
                ctx.set_field(sa, 1, Value::Int(src_addr.port() as i32));
                Ok(Some(Value::Object(Some(sa))))
            }
            Err(ref e) if e.kind() == std::io::ErrorKind::WouldBlock => {
                // Non-blocking datagram with no pending packet: per JDK
                // DatagramChannel.receive, return null.
                Ok(Some(Value::Object(None)))
            }
            Err(e) => Err(RuntimeError::IOException {
                message: format!("DatagramChannel.receive failed: {e}"),
            }
            .into()),
        }
    });

    // read(ByteBuffer) — connected-mode receive. Semantics: return the
    // number of bytes placed into the buffer, or -1 on EOF, or 0 if
    // non-blocking and no packet is pending.
    r.register(dc, "read", "(Ljava/nio/ByteBuffer;)I", |ctx, args| {
        let this = obj_arg(args, 0)?;
        if ctx.get_field(this, 2).as_int().unwrap_or(0) == 0 {
            return Err(RuntimeError::IllegalStateException {
                message: "DatagramChannel.read: not connected".into(),
            }
            .into());
        }
        let sid = ctx.get_field(this, 4).as_int().unwrap_or(-1);
        if sid < 0 {
            return Ok(Some(Value::Int(-1)));
        }
        let bb = match args.get(1) {
            Some(Value::Object(Some(bb))) => *bb,
            _ => return Ok(Some(Value::Int(-1))),
        };
        let pos = ctx.get_field(bb, 1).as_int().unwrap_or(0) as usize;
        let limit = ctx.get_field(bb, 2).as_int().unwrap_or(0) as usize;
        let capacity = limit.saturating_sub(pos).min(65_536);
        if capacity == 0 {
            return Ok(Some(Value::Int(0)));
        }
        let mut buf = vec![0u8; capacity];
        let result = {
            let reg = crate::servlet::s2_registry().lock();
            match reg.dgrams.get(&sid) {
                Some(sock) => sock.recv(&mut buf),
                None => return Ok(Some(Value::Int(-1))),
            }
        };
        match result {
            Ok(n) => {
                let arr = match ctx.get_field(bb, 0) {
                    Value::Object(Some(a)) => a,
                    _ => return Ok(Some(Value::Int(-1))),
                };
                for i in 0..n {
                    ctx.set_array_element(arr, pos + i, Value::Int(buf[i] as i8 as i32));
                }
                ctx.set_field(bb, 1, Value::Int((pos + n) as i32));
                Ok(Some(Value::Int(n as i32)))
            }
            Err(ref e) if e.kind() == std::io::ErrorKind::WouldBlock => {
                Ok(Some(Value::Int(0)))
            }
            Err(_) => Ok(Some(Value::Int(-1))),
        }
    });

    r.register(dc, "write", "(Ljava/nio/ByteBuffer;)I", |ctx, args| {
        let this = obj_arg(args, 0)?;
        if ctx.get_field(this, 2).as_int().unwrap_or(0) == 0 {
            return Err(RuntimeError::IllegalStateException {
                message: "DatagramChannel.write: not connected".into(),
            }
            .into());
        }
        let sid = ctx.get_field(this, 4).as_int().unwrap_or(-1);
        if sid < 0 {
            return Ok(Some(Value::Int(0)));
        }
        let bb = match args.get(1) {
            Some(Value::Object(Some(bb))) => *bb,
            _ => return Ok(Some(Value::Int(0))),
        };
        let pos = ctx.get_field(bb, 1).as_int().unwrap_or(0) as usize;
        let limit = ctx.get_field(bb, 2).as_int().unwrap_or(0) as usize;
        let remaining = limit.saturating_sub(pos);
        if remaining == 0 {
            return Ok(Some(Value::Int(0)));
        }
        let arr = match ctx.get_field(bb, 0) {
            Value::Object(Some(a)) => a,
            _ => return Ok(Some(Value::Int(0))),
        };
        let mut buf = vec![0u8; remaining];
        for i in 0..remaining {
            if let Value::Int(b) = ctx.get_array_element(arr, pos + i) {
                buf[i] = b as u8;
            }
        }
        let result = {
            let reg = crate::servlet::s2_registry().lock();
            match reg.dgrams.get(&sid) {
                Some(sock) => sock.send(&buf),
                None => return Ok(Some(Value::Int(0))),
            }
        };
        match result {
            Ok(n) => {
                ctx.set_field(bb, 1, Value::Int((pos + n) as i32));
                Ok(Some(Value::Int(n as i32)))
            }
            Err(ref e) if e.kind() == std::io::ErrorKind::WouldBlock => {
                Ok(Some(Value::Int(0)))
            }
            Err(e) => Err(RuntimeError::IOException {
                message: format!("DatagramChannel.write failed: {e}"),
            }
            .into()),
        }
    });

    // register(Selector, int) — delegates to the canonical s2 key builder
    // so the Selector's poll path discovers this channel and polls its
    // real fd. (NEW-3: previously allocated a disconnected 3-field key
    // that the selector would never wake up on.)
    r.register(
        dc,
        "register",
        "(Ljava/nio/channels/Selector;I)Ljava/nio/channels/SelectionKey;",
        s2_register_channel,
    );
    r.register(
        dc,
        "register",
        "(Ljava/nio/channels/Selector;ILjava/lang/Object;)Ljava/nio/channels/SelectionKey;",
        s2_register_channel,
    );

    // Reference to SocketRegistry kept to keep the `use` alive for all
    // the nested closures that look up dgrams above.
    let _ = std::marker::PhantomData::<SocketRegistry>;

    // socket() -> DatagramSocket
    r.register(dc, "socket", "()Ljava/net/DatagramSocket;", |ctx, args| {
        let this = obj_arg(args, 0)?;
        let port = match ctx.get_field(this, 0) { Value::Int(p) => p, _ => 0 };
        let ds = alloc_concurrent_synthetic(ctx, "java/net/DatagramSocket", 3);
        ctx.set_field(ds, 0, Value::Int(port));
        ctx.set_field(ds, 1, Value::Int(0)); // not closed
        ctx.set_field(ds, 2, Value::Int(0)); // timeout
        Ok(Some(Value::Object(Some(ds))))
    });

    // getLocalAddress() -> SocketAddress
    r.register(dc, "getLocalAddress", "()Ljava/net/SocketAddress;", |ctx, args| {
        let this = obj_arg(args, 0)?;
        let port = match ctx.get_field(this, 0) { Value::Int(p) => p, _ => 0 };
        let sa = alloc_concurrent_synthetic(ctx, "java/net/InetSocketAddress", 2);
        let host = ctx.create_string("0.0.0.0");
        ctx.set_field(sa, 0, Value::Object(Some(host)));
        ctx.set_field(sa, 1, Value::Int(port));
        Ok(Some(Value::Object(Some(sa))))
    });

    // getRemoteAddress() -> SocketAddress
    r.register(dc, "getRemoteAddress", "()Ljava/net/SocketAddress;", |_ctx, _args| {
        Ok(Some(Value::Object(None)))
    });

    // setOption / getOption stubs
    r.register(dc, "setOption", "(Ljava/net/SocketOption;Ljava/lang/Object;)Ljava/nio/channels/DatagramChannel;", |_ctx, args| {
        Ok(Some(args.first().copied().unwrap_or(Value::Object(None))))
    });
    r.register(dc, "getOption", "(Ljava/net/SocketOption;)Ljava/lang/Object;", |_ctx, _args| {
        Ok(Some(Value::Object(None)))
    });

    // validOps() -> int (SelectionKey.OP_READ | OP_WRITE = 1|4 = 5)
    r.register(dc, "validOps", "()I", |_ctx, _args| {
        Ok(Some(Value::Int(5)))
    });

    // isBlocking() -> boolean
    r.register(dc, "isBlocking", "()Z", |ctx, args| {
        let this = obj_arg(args, 0)?;
        Ok(Some(ctx.get_field(this, 3)))
    });
}

// =============================================================================
// com.sun.net.httpserver — HttpServer, HttpContext, HttpExchange, HttpHandler, Headers
// =============================================================================

pub(crate) fn register_p72_http_server(r: &mut NativeMethodRegistry) {
    // Wave 3-B (RE.4): the real HttpServer/HttpExchange implementations live in
    // `net_phase_e::register_re10_http_server`, which actually binds a TcpListener
    // and dispatches HTTP/1.1 round-trips. Phase 72 used to register opaque stubs
    // for the same `(class, method, descriptor)` keys; because Phase 72 runs AFTER
    // Phase E, those stubs silently overrode the real impls and broke
    // `URL.openConnection().getInputStream()` round-trips that target a loopback
    // HttpServer. We keep ONLY the HttpServerImpl alias for `create` (Phase E
    // registers `HttpServer` but not the impl class), the no-arg `create()`
    // factory (Phase E only registers the 2-arg form), executor accessors,
    // bind, removeContext, and the HttpContext / HttpHandler / Headers
    // helpers that Phase E does not cover.
    let hs = "com/sun/net/httpserver/HttpServer";
    let hs_simple = "com/sun/net/httpserver/HttpServerImpl";

    // HttpServerImpl alias — Phase E registers HttpServer; route the impl class
    // to the same field layout so that invocations via `HttpServerImpl.create`
    // do not fall through to a missing-native error.
    r.register(
        hs_simple,
        "create",
        "(Ljava/net/InetSocketAddress;I)Lcom/sun/net/httpserver/HttpServer;",
        |ctx, _args| {
            let srv = alloc_concurrent_synthetic(ctx, "com/sun/net/httpserver/HttpServer", 3);
            ctx.set_field(srv, 1, Value::Int(0));
            let ctxs = alloc_concurrent_synthetic(ctx, "java/util/ArrayList", 2);
            rustjvm_native_collections::native_al_init(ctx, &[Value::Object(Some(ctxs))]).ok();
            ctx.set_field(srv, 2, Value::Object(Some(ctxs)));
            Ok(Some(Value::Object(Some(srv))))
        },
    );

    // No-arg factory not covered by Phase E.
    for cls in [hs, hs_simple] {
        r.register(
            cls,
            "create",
            "()Lcom/sun/net/httpserver/HttpServer;",
            |ctx, _args| {
                let srv = alloc_concurrent_synthetic(ctx, "com/sun/net/httpserver/HttpServer", 3);
                ctx.set_field(srv, 1, Value::Int(0));
                let ctxs = alloc_concurrent_synthetic(ctx, "java/util/ArrayList", 2);
                rustjvm_native_collections::native_al_init(ctx, &[Value::Object(Some(ctxs))]).ok();
                ctx.set_field(srv, 2, Value::Object(Some(ctxs)));
                Ok(Some(Value::Object(Some(srv))))
            },
        );
        r.register(
            cls,
            "createContext",
            "(Ljava/lang/String;)Lcom/sun/net/httpserver/HttpContext;",
            |ctx, args| {
                let path = args.get(1).copied().unwrap_or(Value::Object(None));
                let hctx = alloc_concurrent_synthetic(ctx, "com/sun/net/httpserver/HttpContext", 2);
                ctx.set_field(hctx, 0, path);
                ctx.set_field(hctx, 1, Value::Object(None));
                Ok(Some(Value::Object(Some(hctx))))
            },
        );
        r.register(
            cls,
            "setExecutor",
            "(Ljava/util/concurrent/Executor;)V",
            |ctx, args| {
                let this = obj_arg(args, 0)?;
                let _ = (ctx, this);
                Ok(None)
            },
        );
        r.register(
            cls,
            "getExecutor",
            "()Ljava/util/concurrent/Executor;",
            |_ctx, _args| Ok(Some(Value::Object(None))),
        );
        r.register(
            cls,
            "bind",
            "(Ljava/net/InetSocketAddress;I)V",
            |ctx, args| {
                let this = obj_arg(args, 0)?;
                ctx.set_field(this, 0, args.get(1).copied().unwrap_or(Value::Object(None)));
                Ok(None)
            },
        );
        r.register(cls, "removeContext", "(Ljava/lang/String;)V", |_ctx, _args| Ok(None));
        r.register(
            cls,
            "removeContext",
            "(Lcom/sun/net/httpserver/HttpContext;)V",
            |_ctx, _args| Ok(None),
        );
    }

    // HttpContext = 2-field (path=0, handler=1)
    let hctx = "com/sun/net/httpserver/HttpContext";
    r.register(hctx, "getPath", "()Ljava/lang/String;", |ctx, args| {
        Ok(Some(ctx.get_field(obj_arg(args, 0)?, 0)))
    });
    r.register(
        hctx,
        "getHandler",
        "()Lcom/sun/net/httpserver/HttpHandler;",
        |ctx, args| Ok(Some(ctx.get_field(obj_arg(args, 0)?, 1))),
    );
    r.register(
        hctx,
        "setAuthenticator",
        "(Lcom/sun/net/httpserver/Authenticator;)V",
        native_noop_with_this,
    );
    r.register(
        hctx,
        "getServer",
        "()Lcom/sun/net/httpserver/HttpServer;",
        |_ctx, _args| Ok(Some(Value::Object(None))),
    );
    r.register(hctx, "getAttributes", "()Ljava/util/Map;", |ctx, _args| {
        let m = alloc_concurrent_synthetic(ctx, "java/util/HashMap", 3);
        rustjvm_native_collections::native_map_init(ctx, &[Value::Object(Some(m))]).ok();
        Ok(Some(Value::Object(Some(m))))
    });

    // HttpExchange method registrations (getRequestMethod, getRequestURI,
    // getRequestHeaders, getResponseHeaders, getRequestBody, getResponseBody,
    // sendResponseHeaders, close) are owned by `net_phase_e::register_re10_http_server`,
    // which routes them through the live HTTP/1.1 dispatch loop. Phase 72 used
    // to override those keys with naked field accessors that returned null
    // OutputStreams and never wrote a response — that broke real-server probes.
    // We keep only the ancillary getters Phase E does not register.
    let hex = "com/sun/net/httpserver/HttpExchange";
    r.register(
        hex,
        "getLocalAddress",
        "()Ljava/net/InetSocketAddress;",
        |_ctx, _args| Ok(Some(Value::Object(None))),
    );
    r.register(
        hex,
        "getRemoteAddress",
        "()Ljava/net/InetSocketAddress;",
        |_ctx, _args| Ok(Some(Value::Object(None))),
    );
    r.register(
        hex,
        "getAttribute",
        "(Ljava/lang/String;)Ljava/lang/Object;",
        |_ctx, _args| Ok(Some(Value::Object(None))),
    );

    // HttpHandler interface (default no-op so abstract dispatch resolves).
    r.register(
        "com/sun/net/httpserver/HttpHandler",
        "handle",
        "(Lcom/sun/net/httpserver/HttpExchange;)V",
        native_noop_with_this,
    );

    // Headers = HashMap pattern (3-field)
    let hdrs = "com/sun/net/httpserver/Headers";
    r.register(hdrs, "<init>", "()V", |ctx, args| {
        rustjvm_native_collections::native_map_init(ctx, args)
    });
    r.register(
        hdrs,
        "get",
        "(Ljava/lang/Object;)Ljava/lang/Object;",
        rustjvm_native_collections::native_map_get_pub,
    );
    r.register(
        hdrs,
        "put",
        "(Ljava/lang/Object;Ljava/lang/Object;)Ljava/lang/Object;",
        rustjvm_native_collections::native_map_put_pub,
    );
    r.register(
        hdrs,
        "containsKey",
        "(Ljava/lang/Object;)Z",
        rustjvm_native_collections::native_map_contains_key_pub,
    );
    r.register(
        hdrs,
        "size",
        "()I",
        rustjvm_native_collections::native_map_size_pub,
    );
    r.register(
        hdrs,
        "getFirst",
        "(Ljava/lang/String;)Ljava/lang/String;",
        rustjvm_native_collections::native_map_get_pub,
    );
    r.register(
        hdrs,
        "add",
        "(Ljava/lang/String;Ljava/lang/String;)V",
        |ctx, args| {
            rustjvm_native_collections::native_map_put_pub(ctx, args)?;
            Ok(None)
        },
    );
    r.register(
        hdrs,
        "set",
        "(Ljava/lang/String;Ljava/lang/String;)V",
        |ctx, args| {
            rustjvm_native_collections::native_map_put_pub(ctx, args)?;
            Ok(None)
        },
    );
}

// =============================================================================
// java.net.ServerSocket extras + java.net.Socket extras (not already registered)
// =============================================================================

pub(crate) fn register_p72_server_socket(r: &mut NativeMethodRegistry) {
    // ServerSocket extras — add methods not registered in phase 53
    let ss = "java/net/ServerSocket";
    r.register(ss, "<init>", "(IILjava/net/InetAddress;)V", |ctx, args| {
        let this = obj_arg(args, 0)?;
        let port = match args.get(1) {
            Some(Value::Int(i)) => *i,
            _ => 0,
        };
        let backlog = match args.get(2) {
            Some(Value::Int(i)) => *i,
            _ => 50,
        };
        ctx.set_field(this, 0, Value::Int(port));
        ctx.set_field(this, 1, Value::Int(backlog));
        ctx.set_field(this, 2, Value::Int(0));
        Ok(None)
    });
    r.register(ss, "accept", "()Ljava/net/Socket;", |_ctx, _args| {
        Ok(Some(Value::Object(None)))
    });
    r.register(ss, "bind", "(Ljava/net/SocketAddress;)V", |ctx, args| {
        let this = obj_arg(args, 0)?;
        // Channel-backed wrapper (created by ServerSocketChannel.socket()) has a 5th
        // field holding a back-ref to the SocketChannel. Delegate the bind to the
        // channel so the underlying TCP listener lives in fd_table (visible to the
        // selector). For a plain ServerSocket, keep using s2_alloc_listener.
        if ctx.object_num_fields(this) >= 5 {
            if let Value::Object(Some(ssc)) = ctx.get_field(this, 4) {
                let addr_obj = args.get(1).copied().unwrap_or(Value::Object(None));
                let addr_str = p98_extract_socket_addr(ctx, addr_obj);
                match ctx.fd_table().open_tcp_listener(&addr_str) {
                    Ok(fd) => {
                        ctx.set_field(ssc, 1, Value::Int(1));
                        ctx.set_field(ssc, 2, Value::Int(fd as i32));
                        let port = ctx.fd_table().tcp_local_addr(fd)
                            .ok()
                            .and_then(|s| s.rsplit(':').next().and_then(|p| p.parse::<i32>().ok()))
                            .unwrap_or(0);
                        ctx.set_field(this, 0, Value::Int(port)); // SS_PORT mirror
                        return Ok(None);
                    }
                    Err(e) => {
                        return Err(RuntimeError::IOException {
                            message: format!("bind {addr_str}: {e}"),
                        }.into());
                    }
                }
            }
        }
        // Plain ServerSocket path — bind a real TcpListener via s2_alloc_listener.
        use crate::servlet::s2_alloc_listener;
        use std::net::TcpListener;
        let addr_obj = args.get(1).copied().unwrap_or(Value::Object(None));
        let addr_str = p98_extract_socket_addr(ctx, addr_obj);
        match TcpListener::bind(&addr_str) {
            Ok(listener) => {
                let actual_port = listener.local_addr().map(|a| a.port() as i32).unwrap_or(0);
                let id = s2_alloc_listener(listener);
                ctx.set_field(this, 0, Value::Int(actual_port));
                ctx.set_field(this, 3, Value::Int(id));
            }
            Err(e) => {
                return Err(RuntimeError::IOException {
                    message: format!("bind {addr_str}: {e}"),
                }.into());
            }
        }
        Ok(None)
    });
    r.register(ss, "bind", "(Ljava/net/SocketAddress;I)V", |ctx, args| {
        let this = obj_arg(args, 0)?;
        if let Some(Value::Int(backlog)) = args.get(2) {
            ctx.set_field(this, 1, Value::Int(*backlog));
        }
        // Reuse single-arg bind path
        if ctx.object_num_fields(this) >= 5 {
            if let Value::Object(Some(ssc)) = ctx.get_field(this, 4) {
                let addr_obj = args.get(1).copied().unwrap_or(Value::Object(None));
                let addr_str = p98_extract_socket_addr(ctx, addr_obj);
                if let Ok(fd) = ctx.fd_table().open_tcp_listener(&addr_str) {
                    ctx.set_field(ssc, 1, Value::Int(1));
                    ctx.set_field(ssc, 2, Value::Int(fd as i32));
                    let port = ctx.fd_table().tcp_local_addr(fd)
                        .ok()
                        .and_then(|s| s.rsplit(':').next().and_then(|p| p.parse::<i32>().ok()))
                        .unwrap_or(0);
                    ctx.set_field(this, 0, Value::Int(port));
                }
                return Ok(None);
            }
        }
        Ok(None)
    });
    r.register(ss, "getLocalPort", "()I", |ctx, args| {
        let this = obj_arg(args, 0)?;
        // For channel-backed wrappers, recompute from the channel's fd.
        if ctx.object_num_fields(this) >= 5 {
            if let Value::Object(Some(ssc)) = ctx.get_field(this, 4) {
                let fd = ctx.get_field(ssc, 2).as_int().unwrap_or(-1);
                if fd >= 0 {
                    let port = ctx.fd_table().tcp_local_addr(fd as u32)
                        .ok()
                        .and_then(|s| s.rsplit(':').next().and_then(|p| p.parse::<i32>().ok()))
                        .unwrap_or(0);
                    return Ok(Some(Value::Int(port)));
                }
            }
        }
        Ok(Some(ctx.get_field(this, 0)))
    });
    r.register(ss, "isBound", "()Z", |_ctx, _args| Ok(Some(Value::Int(1))));
    r.register(
        ss,
        "getInetAddress",
        "()Ljava/net/InetAddress;",
        |_ctx, _args| Ok(Some(Value::Object(None))),
    );
    r.register(
        ss,
        "getLocalSocketAddress",
        "()Ljava/net/SocketAddress;",
        |_ctx, _args| Ok(Some(Value::Object(None))),
    );
    r.register(ss, "getSoTimeout", "()I", |_ctx, _args| {
        Ok(Some(Value::Int(0)))
    });
    // ServerSocket setReuseAddress/setReceiveBufferSize: use real socket options
    // Note: ServerSocket doesn't always have a stream_id, so we track these as fields if needed
    // For now, these are kept as field-tracking stubs since ServerSocket doesn't expose
    // the underlying listener to socket2 in the same way as Socket.
    // Real implementations exist in phases_early.rs for Socket; ServerSocket is less critical.
    r.register(ss, "implAccept", "(Ljava/net/Socket;)V", |ctx, args| {
        // Accept a connection on the underlying TcpListener and populate the given
        // Socket object's stream_id field. This is the JDK-internal hook called by
        // ServerSocket.accept() to delegate the actual blocking accept.
        use crate::servlet::{s2_registry, s2_alloc_stream};
        let this = obj_arg(args, 0)?;
        let target_socket = match args.get(1) {
            Some(Value::Object(Some(s))) => *s,
            _ => return Err(RuntimeError::IOException {
                message: "implAccept: null socket".into(),
            }
            .into()),
        };
        let listener_id = ctx.get_field(this, 3).as_int().unwrap_or(-1); // SS_LISTENER_ID
        if listener_id < 0 {
            return Err(RuntimeError::IOException {
                message: "ServerSocket not bound".into(),
            }
            .into());
        }
        // Block-accept via the s2_registry. Take the listener out, accept on it, put it back.
        let stream = {
            let mut reg = s2_registry().lock();
            let listener = reg.listeners.get(&listener_id).ok_or_else(|| {
                RuntimeError::IOException {
                    message: "Listener not found".into(),
                }
            })?;
            match listener.accept() {
                Ok((stream, _addr)) => stream,
                Err(e) => return Err(RuntimeError::IOException {
                    message: format!("accept failed: {}", e),
                }
                .into()),
            }
        };
        let stream_id = s2_alloc_stream(stream);
        // Populate the target Socket's fields. Socket layout: host=0, port=1, localPort=2, closed=3, stream_id=4
        ctx.set_field(target_socket, 3, Value::Int(0)); // not closed
        ctx.set_field(target_socket, 4, Value::Int(stream_id));
        Ok(None)
    });

    // Socket extras — add methods not registered in phase 53
    let sock = "java/net/Socket";
    r.register(sock, "<init>", "(Ljava/net/InetAddress;I)V", |ctx, args| {
        let this = obj_arg(args, 0)?;
        ctx.set_field(this, 0, args.get(1).copied().unwrap_or(Value::Object(None)));
        let port = match args.get(2) {
            Some(Value::Int(i)) => *i,
            _ => 0,
        };
        ctx.set_field(this, 1, Value::Int(port));
        ctx.set_field(this, 2, Value::Int(0));
        ctx.set_field(this, 3, Value::Int(0));
        Ok(None)
    });
    // Socket.bind(SocketAddress) — store the local address.
    // SocketAddress (InetSocketAddress) field layout: 0=host String, 1=port Int.
    r.register(sock, "bind", "(Ljava/net/SocketAddress;)V", |ctx, args| {
        let this = obj_arg(args, 0)?;
        if let Some(Value::Object(Some(sa))) = args.get(1) {
            // Store local port in field 2 (localPort)
            let port = ctx.get_field(*sa, 1).as_int().unwrap_or(0);
            ctx.set_field(this, 2, Value::Int(port));
        }
        Ok(None)
    });
    // Socket.connect(SocketAddress) — extract host/port, connect via std::net::TcpStream.
    r.register(sock, "connect", "(Ljava/net/SocketAddress;)V", |ctx, args| {
        let this = obj_arg(args, 0)?;
        let (host, port) = match args.get(1) {
            Some(Value::Object(Some(sa))) => {
                let host = match ctx.get_field(*sa, 0) {
                    Value::Object(Some(s)) => ctx.read_string(s).unwrap_or_else(|| "127.0.0.1".into()),
                    _ => "127.0.0.1".into(),
                };
                let port = ctx.get_field(*sa, 1).as_int().unwrap_or(0);
                (host, port)
            }
            _ => return Err(RuntimeError::IOException {
                message: "Socket.connect: null address".into(),
            }.into()),
        };
        // Connect and register in s2_registry
        use crate::servlet::{s2_registry, s2_alloc_stream};
        let addr = format!("{}:{}", host, port);
        match std::net::TcpStream::connect(&addr) {
            Ok(stream) => {
                let stream_id = s2_alloc_stream(stream);
                // Store host, port, stream_id in Socket fields
                let host_s = ctx.create_string(&host);
                ctx.set_field(this, 0, Value::Object(Some(host_s)));
                ctx.set_field(this, 1, Value::Int(port));
                ctx.set_field(this, 3, Value::Int(0)); // not closed
                ctx.set_field(this, 4, Value::Int(stream_id));
                Ok(None)
            }
            Err(e) => Err(RuntimeError::IOException {
                message: format!("Socket.connect failed: {}", e),
            }.into()),
        }
    });
    // Socket.connect(SocketAddress, int timeout)
    r.register(sock, "connect", "(Ljava/net/SocketAddress;I)V", |ctx, args| {
        let this = obj_arg(args, 0)?;
        let (host, port) = match args.get(1) {
            Some(Value::Object(Some(sa))) => {
                let host = match ctx.get_field(*sa, 0) {
                    Value::Object(Some(s)) => ctx.read_string(s).unwrap_or_else(|| "127.0.0.1".into()),
                    _ => "127.0.0.1".into(),
                };
                let port = ctx.get_field(*sa, 1).as_int().unwrap_or(0);
                (host, port)
            }
            _ => return Err(RuntimeError::IOException {
                message: "Socket.connect: null address".into(),
            }.into()),
        };
        let timeout_ms = args.get(2).and_then(|v| v.as_int()).unwrap_or(0);
        use crate::servlet::{s2_registry, s2_alloc_stream};
        let addr = format!("{}:{}", host, port);
        let result = if timeout_ms > 0 {
            // Resolve address and use connect_timeout
            match std::net::ToSocketAddrs::to_socket_addrs(&addr) {
                Ok(mut iter) => match iter.next() {
                    Some(sock_addr) => std::net::TcpStream::connect_timeout(
                        &sock_addr,
                        std::time::Duration::from_millis(timeout_ms.max(0) as u64),
                    ),
                    None => Err(std::io::Error::new(std::io::ErrorKind::AddrNotAvailable, "no address")),
                },
                Err(e) => Err(e),
            }
        } else {
            std::net::TcpStream::connect(&addr)
        };
        match result {
            Ok(stream) => {
                let stream_id = s2_alloc_stream(stream);
                let host_s = ctx.create_string(&host);
                ctx.set_field(this, 0, Value::Object(Some(host_s)));
                ctx.set_field(this, 1, Value::Int(port));
                ctx.set_field(this, 3, Value::Int(0));
                ctx.set_field(this, 4, Value::Int(stream_id));
                Ok(None)
            }
            Err(e) => Err(RuntimeError::IOException {
                message: format!("Socket.connect failed: {}", e),
            }.into()),
        }
    });
    r.register(
        sock,
        "getLocalAddress",
        "()Ljava/net/InetAddress;",
        |_ctx, _args| Ok(Some(Value::Object(None))),
    );
    r.register(
        sock,
        "getLocalSocketAddress",
        "()Ljava/net/SocketAddress;",
        |_ctx, _args| Ok(Some(Value::Object(None))),
    );
    r.register(
        sock,
        "getRemoteSocketAddress",
        "()Ljava/net/SocketAddress;",
        |_ctx, _args| Ok(Some(Value::Object(None))),
    );
    r.register(sock, "isInputShutdown", "()Z", |_ctx, _args| {
        Ok(Some(Value::Int(0)))
    });
    r.register(sock, "isOutputShutdown", "()Z", |_ctx, _args| {
        Ok(Some(Value::Int(0)))
    });
    r.register(sock, "isBound", "()Z", |_ctx, _args| {
        Ok(Some(Value::Int(1)))
    });
    // Socket options (setReuseAddress, setSoLinger, set/getReceiveBufferSize,
    // set/getSendBufferSize, getTcpNoDelay, getKeepAlive, getInputStream, getOutputStream)
    // are registered with REAL implementations in phases_early.rs — not re-registered here.

    // shutdownInput/shutdownOutput — use real TcpStream::shutdown
    r.register(sock, "shutdownInput", "()V", |ctx, args| {
        let this = obj_arg(args, 0)?;
        use crate::servlet::s2_registry;
        let stream_id = ctx.get_field(this, 4).as_int().unwrap_or(-1); // SOCK_STREAM_ID
        if stream_id >= 0 {
            let reg = s2_registry().lock();
            if let Some(stream) = reg.streams.get(&stream_id) {
                let _ = stream.shutdown(std::net::Shutdown::Read);
            }
        }
        Ok(None)
    });
    r.register(sock, "shutdownOutput", "()V", |ctx, args| {
        let this = obj_arg(args, 0)?;
        use crate::servlet::s2_registry;
        let stream_id = ctx.get_field(this, 4).as_int().unwrap_or(-1);
        if stream_id >= 0 {
            let reg = s2_registry().lock();
            if let Some(stream) = reg.streams.get(&stream_id) {
                let _ = stream.shutdown(std::net::Shutdown::Write);
            }
        }
        Ok(None)
    });
    // Socket option setters — apply to underlying stream via socket2 where possible.
    // OOBInline, performance preferences, traffic class: field-tracking via socket2::SockRef if fd exists.
    r.register(sock, "setOOBInline", "(Z)V", |ctx, args| {
        use crate::servlet::s2_registry;
        let this = obj_arg(args, 0)?;
        let on = args.get(1).and_then(|v| v.as_int()).unwrap_or(0) != 0;
        let stream_id = ctx.get_field(this, 4).as_int().unwrap_or(-1);
        if stream_id >= 0 {
            let reg = s2_registry().lock();
            if let Some(stream) = reg.streams.get(&stream_id) {
                let sock_ref = socket2::SockRef::from(stream);
                let _ = sock_ref.set_out_of_band_inline(on);
            }
        }
        Ok(None)
    });
    r.register(sock, "getOOBInline", "()Z", |ctx, args| {
        use crate::servlet::s2_registry;
        let this = obj_arg(args, 0)?;
        let stream_id = ctx.get_field(this, 4).as_int().unwrap_or(-1);
        if stream_id >= 0 {
            let reg = s2_registry().lock();
            if let Some(stream) = reg.streams.get(&stream_id) {
                let sock_ref = socket2::SockRef::from(stream);
                let on = sock_ref.out_of_band_inline().unwrap_or(false);
                return Ok(Some(Value::Int(if on { 1 } else { 0 })));
            }
        }
        Ok(Some(Value::Int(0)))
    });
    r.register(sock, "sendUrgentData", "(I)V", |ctx, args| {
        // Send an OOB byte via the underlying stream.
        use crate::servlet::s2_registry;
        let this = obj_arg(args, 0)?;
        let byte = args.get(1).and_then(|v| v.as_int()).unwrap_or(0) as u8;
        let stream_id = ctx.get_field(this, 4).as_int().unwrap_or(-1);
        if stream_id >= 0 {
            let reg = s2_registry().lock();
            if let Some(stream) = reg.streams.get(&stream_id) {
                // socket2 doesn't expose send_oob; use regular write as best effort.
                use std::io::Write;
                let mut stream_clone = stream.try_clone().map_err(|e| {
                    RuntimeError::IOException { message: e.to_string() }
                })?;
                let _ = stream_clone.write_all(&[byte]);
            }
        }
        Ok(None)
    });
    r.register(sock, "setPerformancePreferences", "(III)V", |_ctx, _args| {
        // Performance hints are advisory — accept and ignore.
        Ok(None)
    });
    r.register(sock, "setTrafficClass", "(I)V", |ctx, args| {
        use crate::servlet::s2_registry;
        let this = obj_arg(args, 0)?;
        let tc = args.get(1).and_then(|v| v.as_int()).unwrap_or(0);
        let stream_id = ctx.get_field(this, 4).as_int().unwrap_or(-1);
        if stream_id >= 0 {
            let reg = s2_registry().lock();
            if let Some(stream) = reg.streams.get(&stream_id) {
                let sock_ref = socket2::SockRef::from(stream);
                // Map Java traffic class to IP_TOS. Only supported on IPv4.
                let _ = sock_ref.set_tos(tc as u32);
            }
        }
        Ok(None)
    });
    r.register(sock, "getTrafficClass", "()I", |ctx, args| {
        use crate::servlet::s2_registry;
        let this = obj_arg(args, 0)?;
        let stream_id = ctx.get_field(this, 4).as_int().unwrap_or(-1);
        if stream_id >= 0 {
            let reg = s2_registry().lock();
            if let Some(stream) = reg.streams.get(&stream_id) {
                let sock_ref = socket2::SockRef::from(stream);
                let tos = sock_ref.tos().unwrap_or(0);
                return Ok(Some(Value::Int(tos as i32)));
            }
        }
        Ok(Some(Value::Int(0)))
    });
}

// =============================================================================
// Phase J: Jackson ObjectMapper + Gson — Reflection-based JSON (M16)
// =============================================================================

/// Maximum recursion depth for JSON serialization/deserialization to prevent
/// stack overflow from deeply nested objects.
const JSON_MAX_DEPTH: usize = 64;

/// Maximum JSON input size in bytes (16 MB).
const JSON_MAX_INPUT_SIZE: usize = 16 * 1024 * 1024;

/// Maximum CAS retry iterations before yielding to prevent livelock.
const CAS_MAX_RETRIES: usize = 1024;

/// Check if a class has a @JsonIgnore annotation on a field.
fn field_has_json_ignore(ctx: &mut dyn NativeContext, class_id: ClassId, field_name: &str) -> bool {
    let annotations = ctx.field_annotations(class_id, field_name);
    annotations.iter().any(|a| {
        a.type_descriptor.ends_with("JsonIgnore;") || a.type_descriptor.ends_with("Transient;")
    })
}

/// Get the @JsonProperty / @SerializedName override for a field, if any.
fn field_json_name(ctx: &mut dyn NativeContext, class_id: ClassId, field_name: &str) -> Option<String> {
    let annotations = ctx.field_annotations(class_id, field_name);
    for ann in &annotations {
        if ann.type_descriptor.contains("JsonProperty") || ann.type_descriptor.contains("SerializedName") {
            // Try to extract annotation "value" element
            for (name, elem) in &ann.elements {
                if name == "value" {
                    if let rustjvm_native_api::AnnotationElementValue::StringVal(val) = elem {
                        if !val.is_empty() {
                            return Some(val.clone());
                        }
                    }
                }
            }
        }
    }
    None
}

/// Serialize a Java object to a JSON string using reflection.
/// Walks declared fields, reads each value, and builds a JSON object string.
fn reflection_serialize_to_json(
    ctx: &mut dyn NativeContext,
    obj: ObjectRef,
) -> String {
    reflection_serialize_to_json_depth(ctx, obj, 0)
}

fn reflection_serialize_to_json_depth(
    ctx: &mut dyn NativeContext,
    obj: ObjectRef,
    depth: usize,
) -> String {
    if depth > JSON_MAX_DEPTH {
        return "null".to_string();
    }

    let class_id = ctx.class_id_of_object(obj);
    let class_name = ctx.class_name_of_id(class_id).unwrap_or_default();

    // For java.lang.String, just quote it
    if class_name == "java/lang/String" {
        let s = ctx.read_string(obj).unwrap_or_default();
        return format!("\"{}\"", json_escape(&s));
    }

    let fields = ctx.declared_fields(class_id);
    let mut entries = Vec::new();
    for meta in &fields {
        // Skip static fields
        if meta.is_static {
            continue;
        }
        // Skip @JsonIgnore / @Transient annotated fields
        if field_has_json_ignore(ctx, class_id, &meta.name) {
            continue;
        }
        let val = ctx.get_field(obj, meta.slot_index);
        let json_val = value_to_json_depth(ctx, &val, &meta.descriptor, depth + 1);
        // Use @JsonProperty/@SerializedName name if present
        let output_name = field_json_name(ctx, class_id, &meta.name)
            .unwrap_or_else(|| meta.name.clone());
        entries.push(format!("\"{}\":{}", json_escape(&output_name), json_val));
    }
    format!("{{{}}}", entries.join(","))
}

/// Convert a JVM Value to its JSON representation (depth-limited).
fn value_to_json(ctx: &mut dyn NativeContext, val: &Value, descriptor: &str) -> String {
    value_to_json_depth(ctx, val, descriptor, 0)
}

fn value_to_json_depth(ctx: &mut dyn NativeContext, val: &Value, descriptor: &str, depth: usize) -> String {
    if depth > JSON_MAX_DEPTH {
        return "null".to_string();
    }
    match val {
        Value::Int(n) => {
            match descriptor {
                "Z" => if *n != 0 { "true".to_string() } else { "false".to_string() },
                "C" => {
                    let ch = char::from_u32(*n as u32).unwrap_or('?');
                    format!("\"{}\"", json_escape(&ch.to_string()))
                }
                _ => n.to_string(),
            }
        }
        Value::Long(n) => n.to_string(),
        Value::Float(f) => {
            if f.is_nan() { "null".to_string() }
            else if f.is_infinite() { "null".to_string() }
            else { format!("{}", f) }
        }
        Value::Double(d) => {
            if d.is_nan() { "null".to_string() }
            else if d.is_infinite() { "null".to_string() }
            else { format!("{}", d) }
        }
        Value::Object(None) => "null".to_string(),
        Value::Object(Some(obj_ref)) => {
            let cid = ctx.class_id_of_object(*obj_ref);
            let cname = ctx.class_name_of_id(cid).unwrap_or_default();
            if cname == "java/lang/String" {
                let s = ctx.read_string(*obj_ref).unwrap_or_default();
                format!("\"{}\"", json_escape(&s))
            } else if cname.starts_with("[") || descriptor.starts_with("[") {
                // Array — serialize elements
                let len = ctx.array_length(*obj_ref);
                let mut elems = Vec::new();
                let elem_desc = if descriptor.len() > 1 { &descriptor[1..] } else { "I" };
                for i in 0..len {
                    let elem = ctx.get_array_element(*obj_ref, i);
                    elems.push(value_to_json_depth(ctx, &elem, elem_desc, depth + 1));
                }
                format!("[{}]", elems.join(","))
            } else if cname == "java/lang/Integer" || cname == "java/lang/Byte"
                || cname == "java/lang/Short" {
                let inner = ctx.get_field(*obj_ref, 0);
                value_to_json_depth(ctx, &inner, "I", depth + 1)
            } else if cname == "java/lang/Long" {
                let inner = ctx.get_field(*obj_ref, 0);
                value_to_json_depth(ctx, &inner, "J", depth + 1)
            } else if cname == "java/lang/Float" {
                let inner = ctx.get_field(*obj_ref, 0);
                value_to_json_depth(ctx, &inner, "F", depth + 1)
            } else if cname == "java/lang/Double" {
                let inner = ctx.get_field(*obj_ref, 0);
                value_to_json_depth(ctx, &inner, "D", depth + 1)
            } else if cname == "java/lang/Boolean" {
                let inner = ctx.get_field(*obj_ref, 0);
                value_to_json_depth(ctx, &inner, "Z", depth + 1)
            } else {
                // Nested object — recurse (depth-limited)
                reflection_serialize_to_json_depth(ctx, *obj_ref, depth + 1)
            }
        }
        _ => "null".to_string(),
    }
}

/// Escape a string for JSON (handles all control chars and Unicode).
fn json_escape(s: &str) -> String {
    let mut out = String::with_capacity(s.len());
    for ch in s.chars() {
        match ch {
            '"' => out.push_str("\\\""),
            '\\' => out.push_str("\\\\"),
            '\n' => out.push_str("\\n"),
            '\r' => out.push_str("\\r"),
            '\t' => out.push_str("\\t"),
            '\x08' => out.push_str("\\b"),
            '\x0C' => out.push_str("\\f"),
            c if c < '\x20' => {
                out.push_str(&format!("\\u{:04x}", c as u32));
            }
            c => out.push(c),
        }
    }
    out
}

/// Unescape a JSON string value (handles \\n, \\t, \\uXXXX, etc.).
fn json_unescape(s: &str) -> String {
    let mut out = String::with_capacity(s.len());
    let mut chars = s.chars();
    while let Some(c) = chars.next() {
        if c == '\\' {
            match chars.next() {
                Some('"') => out.push('"'),
                Some('\\') => out.push('\\'),
                Some('/') => out.push('/'),
                Some('n') => out.push('\n'),
                Some('r') => out.push('\r'),
                Some('t') => out.push('\t'),
                Some('b') => out.push('\x08'),
                Some('f') => out.push('\x0C'),
                Some('u') => {
                    let hex: String = chars.by_ref().take(4).collect();
                    if let Ok(code) = u32::from_str_radix(&hex, 16) {
                        if let Some(ch) = char::from_u32(code) {
                            out.push(ch);
                        }
                    }
                }
                Some(other) => { out.push('\\'); out.push(other); }
                None => out.push('\\'),
            }
        } else {
            out.push(c);
        }
    }
    out
}

/// Simple JSON tokenizer for deserialization.
/// Parses a JSON object string into (key, value_str) pairs.
/// Enforces size limits and handles escaped quotes correctly.
fn parse_json_object(json: &str) -> Vec<(String, String)> {
    if json.len() > JSON_MAX_INPUT_SIZE {
        return Vec::new();
    }
    let json = json.trim();
    if json.len() < 2 || !json.starts_with('{') || !json.ends_with('}') {
        return Vec::new();
    }
    let inner = &json[1..json.len() - 1];
    let mut result = Vec::new();
    let mut i = 0;
    let bytes = inner.as_bytes();
    while i < bytes.len() {
        // Skip whitespace and commas
        while i < bytes.len() && (bytes[i] == b' ' || bytes[i] == b',' || bytes[i] == b'\n' || bytes[i] == b'\r' || bytes[i] == b'\t') {
            i += 1;
        }
        if i >= bytes.len() { break; }

        // Expect key string
        if bytes[i] != b'"' { break; }
        i += 1;
        let key_start = i;
        while i < bytes.len() {
            if bytes[i] == b'\\' && i + 1 < bytes.len() {
                i += 2; // skip escaped char pair (handles \" correctly)
            } else if bytes[i] == b'"' {
                break;
            } else {
                i += 1;
            }
        }
        if i >= bytes.len() { break; } // unterminated string
        let raw_key = &inner[key_start..i];
        let key = json_unescape(raw_key);
        i += 1; // skip closing quote

        // Skip colon and whitespace
        while i < bytes.len() && (bytes[i] == b':' || bytes[i] == b' ' || bytes[i] == b'\t') { i += 1; }

        // Read value
        let val = read_json_value(inner, &mut i);
        result.push((key, val));
    }
    result
}

/// Simple JSON pretty-printer: add newlines and indentation to compact JSON.
fn json_pretty_print(json: &str) -> String {
    let mut out = String::with_capacity(json.len() * 2);
    let mut indent = 0usize;
    let mut in_string = false;
    let mut prev = 0u8;
    let bytes = json.as_bytes();
    for &b in bytes {
        if in_string {
            out.push(b as char);
            if b == b'"' && prev != b'\\' {
                in_string = false;
            }
            prev = b;
            continue;
        }
        match b {
            b'"' => {
                in_string = true;
                out.push(b as char);
            }
            b'{' | b'[' => {
                out.push(b as char);
                indent += 2;
                out.push('\n');
                for _ in 0..indent { out.push(' '); }
            }
            b'}' | b']' => {
                indent = indent.saturating_sub(2);
                out.push('\n');
                for _ in 0..indent { out.push(' '); }
                out.push(b as char);
            }
            b',' => {
                out.push(',');
                out.push('\n');
                for _ in 0..indent { out.push(' '); }
            }
            b':' => {
                out.push_str(" : ");
            }
            b' ' | b'\n' | b'\r' | b'\t' => {} // skip existing whitespace
            _ => out.push(b as char),
        }
        prev = b;
    }
    out
}

/// Read a single JSON value starting at position i.
/// Handles strings with escaped quotes, nested objects/arrays with string awareness.
fn read_json_value(s: &str, i: &mut usize) -> String {
    let bytes = s.as_bytes();
    if *i >= bytes.len() { return String::new(); }

    match bytes[*i] {
        b'"' => {
            *i += 1;
            let start = *i;
            while *i < bytes.len() {
                if bytes[*i] == b'\\' && *i + 1 < bytes.len() {
                    *i += 2; // skip escaped char pair
                } else if bytes[*i] == b'"' {
                    break;
                } else {
                    *i += 1;
                }
            }
            let val = json_unescape(&s[start..*i]);
            if *i < bytes.len() { *i += 1; } // skip closing quote
            val
        }
        b'{' => {
            let start = *i;
            let mut depth = 0i32;
            let mut in_string = false;
            while *i < bytes.len() {
                if in_string {
                    if bytes[*i] == b'\\' && *i + 1 < bytes.len() { *i += 2; continue; }
                    if bytes[*i] == b'"' { in_string = false; }
                } else {
                    match bytes[*i] {
                        b'"' => in_string = true,
                        b'{' => depth += 1,
                        b'}' => { depth -= 1; if depth == 0 { *i += 1; return s[start..*i].to_string(); } }
                        _ => {}
                    }
                }
                *i += 1;
            }
            s[start..*i].to_string()
        }
        b'[' => {
            let start = *i;
            let mut depth = 0i32;
            let mut in_string = false;
            while *i < bytes.len() {
                if in_string {
                    if bytes[*i] == b'\\' && *i + 1 < bytes.len() { *i += 2; continue; }
                    if bytes[*i] == b'"' { in_string = false; }
                } else {
                    match bytes[*i] {
                        b'"' => in_string = true,
                        b'[' => depth += 1,
                        b']' => { depth -= 1; if depth == 0 { *i += 1; return s[start..*i].to_string(); } }
                        _ => {}
                    }
                }
                *i += 1;
            }
            s[start..*i].to_string()
        }
        _ => {
            // Number, boolean, null
            let start = *i;
            while *i < bytes.len() && bytes[*i] != b',' && bytes[*i] != b'}' && bytes[*i] != b']'
                && bytes[*i] != b' ' && bytes[*i] != b'\n' && bytes[*i] != b'\r' && bytes[*i] != b'\t' {
                *i += 1;
            }
            s[start..*i].to_string()
        }
    }
}

/// Deserialize a JSON string into a Java object using reflection (depth-limited).
fn reflection_deserialize_from_json(
    ctx: &mut dyn NativeContext,
    json: &str,
    class_id: ClassId,
) -> Option<ObjectRef> {
    reflection_deserialize_from_json_depth(ctx, json, class_id, 0)
}

fn reflection_deserialize_from_json_depth(
    ctx: &mut dyn NativeContext,
    json: &str,
    class_id: ClassId,
    depth: usize,
) -> Option<ObjectRef> {
    if depth > JSON_MAX_DEPTH || json.len() > JSON_MAX_INPUT_SIZE {
        return None;
    }
    let fields = ctx.declared_fields(class_id);
    let instance_fields: Vec<_> = fields.into_iter().filter(|f| !f.is_static).collect();
    let obj = ctx.alloc_object(class_id, instance_fields.len());
    let pairs = parse_json_object(json);

    for (key, val_str) in &pairs {
        // Match by field name or by @JsonProperty/@SerializedName alias
        let meta = instance_fields.iter().find(|f| {
            if f.name == *key { return true; }
            if let Some(alias) = field_json_name(ctx, class_id, &f.name) {
                return alias == *key;
            }
            false
        });
        if let Some(meta) = meta {
            if field_has_json_ignore(ctx, class_id, &meta.name) {
                continue;
            }
            let value = json_str_to_value_depth(ctx, val_str, &meta.descriptor, depth + 1);
            ctx.set_field(obj, meta.slot_index, value);
        }
    }
    Some(obj)
}

/// Convert a JSON value string to a JVM Value based on the field descriptor.
fn json_str_to_value(ctx: &mut dyn NativeContext, val_str: &str, descriptor: &str) -> Value {
    json_str_to_value_depth(ctx, val_str, descriptor, 0)
}

fn json_str_to_value_depth(ctx: &mut dyn NativeContext, val_str: &str, descriptor: &str, depth: usize) -> Value {
    if depth > JSON_MAX_DEPTH {
        return Value::Object(None);
    }
    let val_str = val_str.trim();
    if val_str == "null" {
        return match descriptor {
            "I" | "B" | "S" | "C" | "Z" => Value::Int(0),
            "J" => Value::Long(0),
            "F" => Value::Float(0.0),
            "D" => Value::Double(0.0),
            _ => Value::Object(None),
        };
    }
    match descriptor {
        "I" | "B" | "S" => Value::Int(val_str.parse::<i32>().unwrap_or(0)),
        "J" => Value::Long(val_str.parse::<i64>().unwrap_or(0)),
        "F" => Value::Float(val_str.parse::<f32>().unwrap_or(0.0)),
        "D" => Value::Double(val_str.parse::<f64>().unwrap_or(0.0)),
        "Z" => Value::Int(if val_str == "true" { 1 } else { 0 }),
        "C" => {
            let ch = val_str.chars().next().unwrap_or('\0') as i32;
            Value::Int(ch)
        }
        desc if desc.starts_with("L") && desc.ends_with(";") => {
            let class_name = &desc[1..desc.len() - 1];
            if class_name == "java/lang/String" {
                let s = ctx.create_string(val_str);
                Value::Object(Some(s))
            } else if class_name == "java/lang/Integer" {
                let n = val_str.parse::<i32>().unwrap_or(0);
                let boxed = alloc_concurrent_synthetic(ctx, "java/lang/Integer", 1);
                ctx.set_field(boxed, 0, Value::Int(n));
                Value::Object(Some(boxed))
            } else if class_name == "java/lang/Long" {
                let n = val_str.parse::<i64>().unwrap_or(0);
                let boxed = alloc_concurrent_synthetic(ctx, "java/lang/Long", 1);
                ctx.set_field(boxed, 0, Value::Long(n));
                Value::Object(Some(boxed))
            } else if class_name == "java/lang/Float" {
                let n = val_str.parse::<f32>().unwrap_or(0.0);
                let boxed = alloc_concurrent_synthetic(ctx, "java/lang/Float", 1);
                ctx.set_field(boxed, 0, Value::Float(n));
                Value::Object(Some(boxed))
            } else if class_name == "java/lang/Double" {
                let n = val_str.parse::<f64>().unwrap_or(0.0);
                let boxed = alloc_concurrent_synthetic(ctx, "java/lang/Double", 1);
                ctx.set_field(boxed, 0, Value::Double(n));
                Value::Object(Some(boxed))
            } else if class_name == "java/lang/Boolean" {
                let b = if val_str == "true" { 1 } else { 0 };
                let boxed = alloc_concurrent_synthetic(ctx, "java/lang/Boolean", 1);
                ctx.set_field(boxed, 0, Value::Int(b));
                Value::Object(Some(boxed))
            } else if val_str.starts_with("{") {
                // Nested object — depth-limited deserialization
                if let Some(cid) = ctx.class_id_by_name(class_name) {
                    match reflection_deserialize_from_json_depth(ctx, val_str, cid, depth + 1) {
                        Some(nested) => Value::Object(Some(nested)),
                        None => Value::Object(None),
                    }
                } else {
                    Value::Object(None)
                }
            } else {
                Value::Object(None)
            }
        }
        desc if desc.starts_with("[") => {
            // Array field — parse JSON array
            let elem_desc = &desc[1..];
            let trimmed = val_str.trim();
            if trimmed.starts_with('[') && trimmed.ends_with(']') {
                let inner = &trimmed[1..trimmed.len() - 1];
                // Parse array elements
                let mut elements = Vec::new();
                let mut i = 0;
                while i < inner.len() {
                    // Skip whitespace and commas
                    while i < inner.len() {
                        let b = inner.as_bytes()[i];
                        if b == b' ' || b == b',' || b == b'\n' || b == b'\r' || b == b'\t' {
                            i += 1;
                        } else {
                            break;
                        }
                    }
                    if i >= inner.len() { break; }
                    let val = read_json_value(inner, &mut i);
                    if val.is_empty() && i >= inner.len() { break; }
                    elements.push(val);
                }
                let arr_type = match elem_desc {
                    "I" | "B" | "S" | "C" | "Z" => rustjvm_types::ArrayElementType::Int,
                    "J" => rustjvm_types::ArrayElementType::Long,
                    "F" => rustjvm_types::ArrayElementType::Float,
                    "D" => rustjvm_types::ArrayElementType::Double,
                    _ => rustjvm_types::ArrayElementType::Reference,
                };
                let arr = ctx.new_array(arr_type, elements.len());
                for (idx, elem_str) in elements.iter().enumerate() {
                    let elem_val = json_str_to_value_depth(ctx, elem_str, elem_desc, depth + 1);
                    ctx.set_array_element(arr, idx, elem_val);
                }
                Value::Object(Some(arr))
            } else {
                Value::Object(None)
            }
        }
        _ => Value::Object(None),
    }
}

pub(crate) fn register_jackson_gson_natives(r: &mut NativeMethodRegistry) {
    // -----------------------------------------------------------------------
    // Jackson: com/fasterxml/jackson/databind/ObjectMapper
    // -----------------------------------------------------------------------
    let om = "com/fasterxml/jackson/databind/ObjectMapper";

    // ObjectMapper config bitfield (stored in field 0 as Int):
    //   bit 0: FAIL_ON_UNKNOWN_PROPERTIES (default: 1 = enabled)
    //   bit 1: INDENT_OUTPUT (default: 0 = disabled)
    //   bit 2: WRITE_DATES_AS_TIMESTAMPS (default: 1 = enabled)
    //   bit 3: FAIL_ON_NULL_FOR_PRIMITIVES (default: 0 = disabled)
    //   bit 4: SERIALIZE_NULLS (default: 0 = disabled; for Gson compat)
    const OM_CFG_FAIL_UNKNOWN: i32     = 1 << 0;
    const OM_CFG_INDENT: i32           = 1 << 1;
    const OM_CFG_DATES_TIMESTAMPS: i32 = 1 << 2;
    const OM_CFG_FAIL_NULL_PRIM: i32   = 1 << 3;
    const OM_CFG_FIELD: usize = 0;

    // Default config: FAIL_ON_UNKNOWN_PROPERTIES | WRITE_DATES_AS_TIMESTAMPS
    const OM_DEFAULT_CFG: i32 = OM_CFG_FAIL_UNKNOWN | OM_CFG_DATES_TIMESTAMPS;

    r.register(om, "<init>", "()V", |ctx, args| {
        if let Some(Value::Object(Some(this))) = args.first() {
            ctx.set_field(*this, OM_CFG_FIELD, Value::Int(OM_DEFAULT_CFG));
        }
        Ok(None)
    });

    // writeValueAsString(Object) -> String
    r.register(
        om,
        "writeValueAsString",
        "(Ljava/lang/Object;)Ljava/lang/String;",
        |ctx, args| {
            let this = match args.first() { Some(Value::Object(Some(o))) => *o, _ => {
                let null_str = ctx.create_string("null");
                return Ok(Some(Value::Object(Some(null_str))));
            }};
            let obj = match args.get(1) {
                Some(Value::Object(Some(o))) => *o,
                _ => {
                    let null_str = ctx.create_string("null");
                    return Ok(Some(Value::Object(Some(null_str))));
                }
            };
            let cfg = match ctx.get_field(this, OM_CFG_FIELD) { Value::Int(v) => v, _ => OM_DEFAULT_CFG };
            let indent = (cfg & OM_CFG_INDENT) != 0;
            let json = reflection_serialize_to_json(ctx, obj);
            let output = if indent { json_pretty_print(&json) } else { json };
            let result = ctx.create_string(&output);
            Ok(Some(Value::Object(Some(result))))
        },
    );

    // writeValueAsBytes(Object) -> byte[]
    r.register(
        om,
        "writeValueAsBytes",
        "(Ljava/lang/Object;)[B",
        |ctx, args| {
            let obj = match args.get(1) {
                Some(Value::Object(Some(o))) => *o,
                _ => {
                    let arr = ctx.new_array(rustjvm_types::ArrayElementType::Byte, 0);
                    return Ok(Some(Value::Object(Some(arr))));
                }
            };
            let json = reflection_serialize_to_json(ctx, obj);
            let bytes = json.as_bytes();
            let arr = ctx.new_array(rustjvm_types::ArrayElementType::Byte, bytes.len());
            for (i, &b) in bytes.iter().enumerate() {
                ctx.set_array_element(arr, i, Value::Int(b as i32));
            }
            Ok(Some(Value::Object(Some(arr))))
        },
    );

    // readValue(String, Class) -> Object
    r.register(
        om,
        "readValue",
        "(Ljava/lang/String;Ljava/lang/Class;)Ljava/lang/Object;",
        |ctx, args| {
            let json_ref = match args.get(1) {
                Some(Value::Object(Some(s))) => *s,
                _ => return Ok(Some(Value::Object(None))),
            };
            let class_mirror = match args.get(2) {
                Some(Value::Object(Some(c))) => *c,
                _ => return Ok(Some(Value::Object(None))),
            };
            let json = match ctx.read_string(json_ref) {
                Some(s) => s,
                None => return Ok(Some(Value::Object(None))),
            };
            let class_id = match crate::lang_class::mirror_class_id(ctx, class_mirror) {
                Some(id) => id,
                None => return Ok(Some(Value::Object(None))),
            };
            match reflection_deserialize_from_json(ctx, &json, class_id) {
                Some(obj) => Ok(Some(Value::Object(Some(obj)))),
                None => Ok(Some(Value::Object(None))),
            }
        },
    );

    // Helper: resolve an enum name from an ObjectRef (field 0 is the name string)
    fn om_enum_name(ctx: &mut dyn NativeContext, enum_ref: ObjectRef) -> Option<String> {
        if let Value::Object(Some(name_ref)) = ctx.get_field(enum_ref, 0) {
            ctx.read_string(name_ref)
        } else {
            None
        }
    }

    /// Map a Jackson feature enum name to its config bit.
    fn om_feature_bit(name: &str) -> Option<i32> {
        match name {
            "FAIL_ON_UNKNOWN_PROPERTIES" => Some(OM_CFG_FAIL_UNKNOWN),
            "INDENT_OUTPUT" | "WRITE_INDENTED" => Some(OM_CFG_INDENT),
            "WRITE_DATES_AS_TIMESTAMPS" => Some(OM_CFG_DATES_TIMESTAMPS),
            "FAIL_ON_NULL_FOR_PRIMITIVES" => Some(OM_CFG_FAIL_NULL_PRIM),
            _ => None,
        }
    }

    // configure(Feature, boolean) — set or clear a config bit
    r.register(om, "configure",
        "(Ljava/lang/Enum;Z)Lcom/fasterxml/jackson/databind/ObjectMapper;",
        |ctx, args| {
            let this = match args.first() { Some(Value::Object(Some(o))) => *o, _ => return Ok(Some(Value::Object(None))) };
            let enabled = matches!(args.get(2), Some(Value::Int(v)) if *v != 0);
            if let Some(Value::Object(Some(enum_ref))) = args.get(1) {
                if let Some(name) = om_enum_name(ctx, *enum_ref) {
                    if let Some(bit) = om_feature_bit(&name) {
                        let cfg = match ctx.get_field(this, OM_CFG_FIELD) { Value::Int(v) => v, _ => OM_DEFAULT_CFG };
                        let new_cfg = if enabled { cfg | bit } else { cfg & !bit };
                        ctx.set_field(this, OM_CFG_FIELD, Value::Int(new_cfg));
                    }
                }
            }
            Ok(Some(Value::Object(Some(this))))
        },
    );

    // enable(Feature) — set a config bit
    r.register(om, "enable",
        "(Ljava/lang/Enum;)Lcom/fasterxml/jackson/databind/ObjectMapper;",
        |ctx, args| {
            let this = match args.first() { Some(Value::Object(Some(o))) => *o, _ => return Ok(Some(Value::Object(None))) };
            if let Some(Value::Object(Some(enum_ref))) = args.get(1) {
                if let Some(name) = om_enum_name(ctx, *enum_ref) {
                    if let Some(bit) = om_feature_bit(&name) {
                        let cfg = match ctx.get_field(this, OM_CFG_FIELD) { Value::Int(v) => v, _ => OM_DEFAULT_CFG };
                        ctx.set_field(this, OM_CFG_FIELD, Value::Int(cfg | bit));
                    }
                }
            }
            Ok(Some(Value::Object(Some(this))))
        },
    );

    // disable(Feature) — clear a config bit
    r.register(om, "disable",
        "(Ljava/lang/Enum;)Lcom/fasterxml/jackson/databind/ObjectMapper;",
        |ctx, args| {
            let this = match args.first() { Some(Value::Object(Some(o))) => *o, _ => return Ok(Some(Value::Object(None))) };
            if let Some(Value::Object(Some(enum_ref))) = args.get(1) {
                if let Some(name) = om_enum_name(ctx, *enum_ref) {
                    if let Some(bit) = om_feature_bit(&name) {
                        let cfg = match ctx.get_field(this, OM_CFG_FIELD) { Value::Int(v) => v, _ => OM_DEFAULT_CFG };
                        ctx.set_field(this, OM_CFG_FIELD, Value::Int(cfg & !bit));
                    }
                }
            }
            Ok(Some(Value::Object(Some(this))))
        },
    );

    // setSerializationInclusion — return this (no direct config bit)
    r.register(om, "setSerializationInclusion",
        "(Ljava/lang/Enum;)Lcom/fasterxml/jackson/databind/ObjectMapper;",
        |_ctx, args| {
            Ok(Some(args.first().copied().unwrap_or(Value::Object(None))))
        },
    );

    // registerModule — return this (modules not supported but don't crash)
    r.register(om, "registerModule",
        "(Lcom/fasterxml/jackson/databind/Module;)Lcom/fasterxml/jackson/databind/ObjectMapper;",
        |_ctx, args| {
            Ok(Some(args.first().copied().unwrap_or(Value::Object(None))))
        },
    );

    // -----------------------------------------------------------------------
    // Gson: com/google/gson/Gson
    // -----------------------------------------------------------------------
    let gson = "com/google/gson/Gson";

    // Gson config bitfield (stored in field 0 as Int):
    //   bit 0: prettyPrinting (default: 0)
    //   bit 1: serializeNulls (default: 0)
    //   bit 2: disableHtmlEscaping (default: 0)
    const GSON_CFG_PRETTY: i32 = 1 << 0;
    const GSON_CFG_SERIALIZE_NULLS: i32 = 1 << 1;
    const GSON_CFG_NO_HTML_ESCAPE: i32 = 1 << 2;
    const GSON_CFG_FIELD: usize = 0;

    r.register(gson, "<init>", "()V", |ctx, args| {
        if let Some(Value::Object(Some(this))) = args.first() {
            ctx.set_field(*this, GSON_CFG_FIELD, Value::Int(0)); // default: all off
        }
        Ok(None)
    });

    // toJson(Object) -> String (respects prettyPrinting)
    r.register(
        gson,
        "toJson",
        "(Ljava/lang/Object;)Ljava/lang/String;",
        |ctx, args| {
            let this = match args.first() { Some(Value::Object(Some(o))) => *o, _ => {
                let null_str = ctx.create_string("null");
                return Ok(Some(Value::Object(Some(null_str))));
            }};
            let obj = match args.get(1) {
                Some(Value::Object(Some(o))) => *o,
                _ => {
                    let null_str = ctx.create_string("null");
                    return Ok(Some(Value::Object(Some(null_str))));
                }
            };
            let cfg = match ctx.get_field(this, GSON_CFG_FIELD) { Value::Int(v) => v, _ => 0 };
            let json = reflection_serialize_to_json(ctx, obj);
            let output = if (cfg & GSON_CFG_PRETTY) != 0 { json_pretty_print(&json) } else { json };
            let result = ctx.create_string(&output);
            Ok(Some(Value::Object(Some(result))))
        },
    );

    // fromJson(String, Class) -> Object
    r.register(
        gson,
        "fromJson",
        "(Ljava/lang/String;Ljava/lang/Class;)Ljava/lang/Object;",
        |ctx, args| {
            let json_ref = match args.get(1) {
                Some(Value::Object(Some(s))) => *s,
                _ => return Ok(Some(Value::Object(None))),
            };
            let class_mirror = match args.get(2) {
                Some(Value::Object(Some(c))) => *c,
                _ => return Ok(Some(Value::Object(None))),
            };
            let json = match ctx.read_string(json_ref) {
                Some(s) => s,
                None => return Ok(Some(Value::Object(None))),
            };
            let class_id = match crate::lang_class::mirror_class_id(ctx, class_mirror) {
                Some(id) => id,
                None => return Ok(Some(Value::Object(None))),
            };
            match reflection_deserialize_from_json(ctx, &json, class_id) {
                Some(obj) => Ok(Some(Value::Object(Some(obj)))),
                None => Ok(Some(Value::Object(None))),
            }
        },
    );

    // GsonBuilder — field 0 stores config bitfield (same bits as Gson)
    let gsb = "com/google/gson/GsonBuilder";
    r.register(gsb, "<init>", "()V", |ctx, args| {
        if let Some(Value::Object(Some(this))) = args.first() {
            ctx.set_field(*this, 0, Value::Int(0));
        }
        Ok(None)
    });
    r.register(gsb, "create", "()Lcom/google/gson/Gson;", |ctx, args| {
        let this = match args.first() { Some(Value::Object(Some(o))) => *o, _ => {
            let g = alloc_concurrent_synthetic(ctx, "com/google/gson/Gson", 1);
            return Ok(Some(Value::Object(Some(g))));
        }};
        let cfg = match ctx.get_field(this, 0) { Value::Int(v) => v, _ => 0 };
        let g = alloc_concurrent_synthetic(ctx, "com/google/gson/Gson", 1);
        ctx.set_field(g, GSON_CFG_FIELD, Value::Int(cfg));
        Ok(Some(Value::Object(Some(g))))
    });
    r.register(gsb, "setPrettyPrinting", "()Lcom/google/gson/GsonBuilder;", |ctx, args| {
        let this = match args.first() { Some(Value::Object(Some(o))) => *o, _ => return Ok(Some(Value::Object(None))) };
        let cfg = match ctx.get_field(this, 0) { Value::Int(v) => v, _ => 0 };
        ctx.set_field(this, 0, Value::Int(cfg | GSON_CFG_PRETTY));
        Ok(Some(Value::Object(Some(this))))
    });
    r.register(gsb, "serializeNulls", "()Lcom/google/gson/GsonBuilder;", |ctx, args| {
        let this = match args.first() { Some(Value::Object(Some(o))) => *o, _ => return Ok(Some(Value::Object(None))) };
        let cfg = match ctx.get_field(this, 0) { Value::Int(v) => v, _ => 0 };
        ctx.set_field(this, 0, Value::Int(cfg | GSON_CFG_SERIALIZE_NULLS));
        Ok(Some(Value::Object(Some(this))))
    });
    r.register(gsb, "disableHtmlEscaping", "()Lcom/google/gson/GsonBuilder;", |ctx, args| {
        let this = match args.first() { Some(Value::Object(Some(o))) => *o, _ => return Ok(Some(Value::Object(None))) };
        let cfg = match ctx.get_field(this, 0) { Value::Int(v) => v, _ => 0 };
        ctx.set_field(this, 0, Value::Int(cfg | GSON_CFG_NO_HTML_ESCAPE));
        Ok(Some(Value::Object(Some(this))))
    });
    r.register(gsb, "setDateFormat", "(Ljava/lang/String;)Lcom/google/gson/GsonBuilder;", |_ctx, args| {
        // Date format not yet supported, but store for future use
        Ok(Some(args.first().copied().unwrap_or(Value::Object(None))))
    });

    // -----------------------------------------------------------------------
    // ObjectMapper.readTree(String) -> JsonNode
    // -----------------------------------------------------------------------
    r.register(
        om,
        "readTree",
        "(Ljava/lang/String;)Lcom/fasterxml/jackson/databind/JsonNode;",
        |ctx, args| {
            let json_ref = match args.get(1) {
                Some(Value::Object(Some(s))) => *s,
                _ => return Ok(Some(Value::Object(None))),
            };
            let json = match ctx.read_string(json_ref) {
                Some(s) => s,
                None => return Ok(Some(Value::Object(None))),
            };
            let node = build_json_tree_node(ctx, &json);
            Ok(Some(Value::Object(Some(node))))
        },
    );

    // -----------------------------------------------------------------------
    // Jackson JsonNode / ObjectNode (tree model) — backed by synthetic fields
    //
    // Layout (8 fields):
    //   0: type  (Int: 0=null, 1=object, 2=array, 3=string, 4=number, 5=boolean, -1=missing)
    //   1: text_value (Object: String for string/number nodes, null otherwise)
    //   2: num_value  (Long: parsed integer for number nodes)
    //   3: bool_value (Int: 0/1 for boolean nodes)
    //   4: children   (Object: array of JsonNode for object/array children)
    //   5: keys       (Object: array of Strings — child key names for object nodes)
    //   6: child_count (Int: number of children)
    //   7: dbl_value  (Double: parsed float/double for number nodes — preserves precision)
    // -----------------------------------------------------------------------
    const JN: &str = "com/fasterxml/jackson/databind/JsonNode";
    const JN_TYPE: usize = 0;
    const JN_TEXT: usize = 1;
    const JN_NUM: usize = 2;
    const JN_BOOL: usize = 3;
    const JN_CHILDREN: usize = 4;
    const JN_KEYS: usize = 5;
    const JN_COUNT: usize = 6;
    const JN_DBL: usize = 7;

    r.register(JN, "asText", "()Ljava/lang/String;", |ctx, args| {
        let this = crate::obj_arg(args, 0)?;
        let ntype = match ctx.get_field(this, JN_TYPE) { Value::Int(v) => v, _ => 0 };
        if ntype == 3 { // string node
            Ok(Some(ctx.get_field(this, JN_TEXT)))
        } else if ntype == 4 { // number node
            let text_val = ctx.get_field(this, JN_TEXT);
            if let Value::Object(Some(_)) = text_val {
                Ok(Some(text_val))
            } else {
                let n = match ctx.get_field(this, JN_NUM) { Value::Long(v) => v, _ => 0 };
                let s = ctx.create_string(&n.to_string());
                Ok(Some(Value::Object(Some(s))))
            }
        } else if ntype == 5 { // boolean
            let b = match ctx.get_field(this, JN_BOOL) { Value::Int(v) => v, _ => 0 };
            let s = ctx.create_string(if b != 0 { "true" } else { "false" });
            Ok(Some(Value::Object(Some(s))))
        } else {
            let s = ctx.create_string("");
            Ok(Some(Value::Object(Some(s))))
        }
    });

    r.register(JN, "asInt", "()I", |ctx, args| {
        let this = crate::obj_arg(args, 0)?;
        let n = match ctx.get_field(this, JN_NUM) { Value::Long(v) => v as i32, _ => 0 };
        Ok(Some(Value::Int(n)))
    });

    r.register(JN, "asLong", "()J", |ctx, args| {
        let this = crate::obj_arg(args, 0)?;
        Ok(Some(ctx.get_field(this, JN_NUM)))
    });

    r.register(JN, "asDouble", "()D", |ctx, args| {
        let this = crate::obj_arg(args, 0)?;
        // Use the dedicated double field for full precision; fall back to long
        let d = match ctx.get_field(this, JN_DBL) {
            Value::Double(v) if v != 0.0 => v,
            _ => match ctx.get_field(this, JN_NUM) { Value::Long(v) => v as f64, _ => 0.0 },
        };
        Ok(Some(Value::Double(d)))
    });

    r.register(JN, "asBoolean", "()Z", |ctx, args| {
        let this = crate::obj_arg(args, 0)?;
        Ok(Some(ctx.get_field(this, JN_BOOL)))
    });

    r.register(JN, "isNull", "()Z", |ctx, args| {
        let this = crate::obj_arg(args, 0)?;
        let ntype = match ctx.get_field(this, JN_TYPE) { Value::Int(v) => v, _ => 0 };
        Ok(Some(Value::Int(if ntype == 0 { 1 } else { 0 })))
    });

    r.register(JN, "isMissingNode", "()Z", |ctx, args| {
        let this = crate::obj_arg(args, 0)?;
        let ntype = match ctx.get_field(this, JN_TYPE) { Value::Int(v) => v, _ => -1 };
        Ok(Some(Value::Int(if ntype == -1 { 1 } else { 0 })))
    });

    r.register(JN, "isTextual", "()Z", |ctx, args| {
        let this = crate::obj_arg(args, 0)?;
        let ntype = match ctx.get_field(this, JN_TYPE) { Value::Int(v) => v, _ => 0 };
        Ok(Some(Value::Int(if ntype == 3 { 1 } else { 0 })))
    });

    r.register(JN, "isNumber", "()Z", |ctx, args| {
        let this = crate::obj_arg(args, 0)?;
        let ntype = match ctx.get_field(this, JN_TYPE) { Value::Int(v) => v, _ => 0 };
        Ok(Some(Value::Int(if ntype == 4 { 1 } else { 0 })))
    });

    r.register(JN, "isBoolean", "()Z", |ctx, args| {
        let this = crate::obj_arg(args, 0)?;
        let ntype = match ctx.get_field(this, JN_TYPE) { Value::Int(v) => v, _ => 0 };
        Ok(Some(Value::Int(if ntype == 5 { 1 } else { 0 })))
    });

    r.register(JN, "isObject", "()Z", |ctx, args| {
        let this = crate::obj_arg(args, 0)?;
        let ntype = match ctx.get_field(this, JN_TYPE) { Value::Int(v) => v, _ => 0 };
        Ok(Some(Value::Int(if ntype == 1 { 1 } else { 0 })))
    });

    r.register(JN, "isArray", "()Z", |ctx, args| {
        let this = crate::obj_arg(args, 0)?;
        let ntype = match ctx.get_field(this, JN_TYPE) { Value::Int(v) => v, _ => 0 };
        Ok(Some(Value::Int(if ntype == 2 { 1 } else { 0 })))
    });

    r.register(JN, "size", "()I", |ctx, args| {
        let this = crate::obj_arg(args, 0)?;
        Ok(Some(ctx.get_field(this, JN_COUNT)))
    });

    // get(String fieldName) -> JsonNode — for object nodes
    r.register(JN, "get", "(Ljava/lang/String;)Lcom/fasterxml/jackson/databind/JsonNode;", |ctx, args| {
        let this = crate::obj_arg(args, 0)?;
        let name_ref = match args.get(1) {
            Some(Value::Object(Some(s))) => *s,
            _ => return Ok(Some(Value::Object(None))),
        };
        let name = ctx.read_string(name_ref).unwrap_or_default();
        let count = match ctx.get_field(this, JN_COUNT) { Value::Int(v) => v as usize, _ => 0 };
        let keys_arr = match ctx.get_field(this, JN_KEYS) {
            Value::Object(Some(a)) => a,
            _ => return Ok(Some(Value::Object(None))),
        };
        let children_arr = match ctx.get_field(this, JN_CHILDREN) {
            Value::Object(Some(a)) => a,
            _ => return Ok(Some(Value::Object(None))),
        };
        for i in 0..count {
            if let Value::Object(Some(key_ref)) = ctx.get_array_element(keys_arr, i) {
                if let Some(key_str) = ctx.read_string(key_ref) {
                    if key_str == name {
                        return Ok(Some(ctx.get_array_element(children_arr, i)));
                    }
                }
            }
        }
        Ok(Some(Value::Object(None)))
    });

    // get(int index) -> JsonNode — for array nodes
    r.register(JN, "get", "(I)Lcom/fasterxml/jackson/databind/JsonNode;", |ctx, args| {
        let this = crate::obj_arg(args, 0)?;
        let idx = match args.get(1) { Some(Value::Int(v)) => *v as usize, _ => 0 };
        let count = match ctx.get_field(this, JN_COUNT) { Value::Int(v) => v as usize, _ => 0 };
        if idx >= count {
            return Ok(Some(Value::Object(None)));
        }
        let children_arr = match ctx.get_field(this, JN_CHILDREN) {
            Value::Object(Some(a)) => a,
            _ => return Ok(Some(Value::Object(None))),
        };
        Ok(Some(ctx.get_array_element(children_arr, idx)))
    });

    // path(String) -> JsonNode (returns MissingNode instead of null)
    r.register(JN, "path", "(Ljava/lang/String;)Lcom/fasterxml/jackson/databind/JsonNode;", |ctx, args| {
        let this = crate::obj_arg(args, 0)?;
        let name_ref = match args.get(1) {
            Some(Value::Object(Some(s))) => *s,
            _ => {
                let missing = alloc_json_node(ctx, -1); // missing node type
                return Ok(Some(Value::Object(Some(missing))));
            }
        };
        let name = ctx.read_string(name_ref).unwrap_or_default();
        let count = match ctx.get_field(this, JN_COUNT) { Value::Int(v) => v as usize, _ => 0 };
        if let Value::Object(Some(keys_arr)) = ctx.get_field(this, JN_KEYS) {
            if let Value::Object(Some(children_arr)) = ctx.get_field(this, JN_CHILDREN) {
                for i in 0..count {
                    if let Value::Object(Some(key_ref)) = ctx.get_array_element(keys_arr, i) {
                        if let Some(key_str) = ctx.read_string(key_ref) {
                            if key_str == name {
                                return Ok(Some(ctx.get_array_element(children_arr, i)));
                            }
                        }
                    }
                }
            }
        }
        let missing = alloc_json_node(ctx, -1);
        Ok(Some(Value::Object(Some(missing))))
    });

    // has(String) -> boolean
    r.register(JN, "has", "(Ljava/lang/String;)Z", |ctx, args| {
        let this = crate::obj_arg(args, 0)?;
        let name_ref = match args.get(1) {
            Some(Value::Object(Some(s))) => *s,
            _ => return Ok(Some(Value::Int(0))),
        };
        let name = ctx.read_string(name_ref).unwrap_or_default();
        let count = match ctx.get_field(this, JN_COUNT) { Value::Int(v) => v as usize, _ => 0 };
        if let Value::Object(Some(keys_arr)) = ctx.get_field(this, JN_KEYS) {
            for i in 0..count {
                if let Value::Object(Some(key_ref)) = ctx.get_array_element(keys_arr, i) {
                    if let Some(key_str) = ctx.read_string(key_ref) {
                        if key_str == name {
                            return Ok(Some(Value::Int(1)));
                        }
                    }
                }
            }
        }
        Ok(Some(Value::Int(0)))
    });

    // toString() -> String
    r.register(JN, "toString", "()Ljava/lang/String;", |ctx, args| {
        let this = crate::obj_arg(args, 0)?;
        let json = json_node_to_string(ctx, this);
        let s = ctx.create_string(&json);
        Ok(Some(Value::Object(Some(s))))
    });

    // Also register for ObjectNode (extends JsonNode)
    let on = "com/fasterxml/jackson/databind/node/ObjectNode";
    // No-arg constructor: ObjectNode fields are initialised lazily
    // when entries are added. NEW-6: documented.
    r.register(on, "<init>", "()V", native_noop_with_this);
}

/// Allocate a JsonNode synthetic object with the given type.
fn alloc_json_node(ctx: &mut dyn NativeContext, node_type: i32) -> ObjectRef {
    let node = alloc_concurrent_synthetic(ctx, "com/fasterxml/jackson/databind/JsonNode", 8);
    ctx.set_field(node, 0, Value::Int(node_type));
    ctx.set_field(node, 2, Value::Long(0));
    ctx.set_field(node, 3, Value::Int(0));
    ctx.set_field(node, 6, Value::Int(0));
    ctx.set_field(node, 7, Value::Double(0.0));
    node
}

/// Build a JsonNode tree from a raw JSON string.
fn build_json_tree_node(ctx: &mut dyn NativeContext, json: &str) -> ObjectRef {
    build_json_tree_node_depth(ctx, json, 0)
}

fn build_json_tree_node_depth(ctx: &mut dyn NativeContext, json: &str, depth: usize) -> ObjectRef {
    if depth > JSON_MAX_DEPTH || json.len() > JSON_MAX_INPUT_SIZE {
        return alloc_json_node(ctx, 0); // null node
    }
    let trimmed = json.trim();
    if trimmed.is_empty() || trimmed == "null" {
        return alloc_json_node(ctx, 0);
    }
    if trimmed.starts_with('{') {
        // Object node
        let pairs = parse_json_object(trimmed);
        let count = pairs.len();
        let node = alloc_json_node(ctx, 1);
        let children = ctx.new_array(rustjvm_types::ArrayElementType::Reference, count);
        let keys = ctx.new_array(rustjvm_types::ArrayElementType::Reference, count);
        for (i, (key, val_str)) in pairs.iter().enumerate() {
            let key_obj = ctx.create_string(key);
            ctx.set_array_element(keys, i, Value::Object(Some(key_obj)));
            let child_json = if val_str.starts_with('{') || val_str.starts_with('[') {
                val_str.clone()
            } else if val_str == "true" || val_str == "false" || val_str == "null"
                || val_str.parse::<f64>().is_ok() {
                val_str.clone()
            } else {
                format!("\"{}\"", json_escape(val_str))
            };
            let child = build_json_tree_node_depth(ctx, &child_json, depth + 1);
            ctx.set_array_element(children, i, Value::Object(Some(child)));
        }
        ctx.set_field(node, 4, Value::Object(Some(children)));
        ctx.set_field(node, 5, Value::Object(Some(keys)));
        ctx.set_field(node, 6, Value::Int(count as i32));
        node
    } else if trimmed.starts_with('[') {
        // Array node
        let inner = &trimmed[1..trimmed.len().saturating_sub(1)];
        let mut elements = Vec::new();
        let mut i = 0;
        while i < inner.len() {
            // skip whitespace/commas
            while i < inner.len() && (inner.as_bytes()[i] == b' ' || inner.as_bytes()[i] == b',' || inner.as_bytes()[i] == b'\n' || inner.as_bytes()[i] == b'\r' || inner.as_bytes()[i] == b'\t') {
                i += 1;
            }
            if i >= inner.len() { break; }
            let val = read_json_value(inner, &mut i);
            if val.is_empty() && i >= inner.len() { break; }
            elements.push(val);
        }
        let count = elements.len();
        let node = alloc_json_node(ctx, 2);
        let children = ctx.new_array(rustjvm_types::ArrayElementType::Reference, count);
        for (idx, elem) in elements.iter().enumerate() {
            let child_json = if elem.starts_with('{') || elem.starts_with('[') {
                elem.clone()
            } else if *elem == "true" || *elem == "false" || *elem == "null"
                || elem.parse::<f64>().is_ok() {
                elem.clone()
            } else {
                format!("\"{}\"", json_escape(elem))
            };
            let child = build_json_tree_node_depth(ctx, &child_json, depth + 1);
            ctx.set_array_element(children, idx, Value::Object(Some(child)));
        }
        ctx.set_field(node, 4, Value::Object(Some(children)));
        ctx.set_field(node, 6, Value::Int(count as i32));
        node
    } else if trimmed.starts_with('"') && trimmed.ends_with('"') && trimmed.len() >= 2 {
        // String node
        let inner_str = json_unescape(&trimmed[1..trimmed.len() - 1]);
        let node = alloc_json_node(ctx, 3);
        let s = ctx.create_string(&inner_str);
        ctx.set_field(node, 1, Value::Object(Some(s)));
        node
    } else if trimmed == "true" || trimmed == "false" {
        let node = alloc_json_node(ctx, 5);
        ctx.set_field(node, 3, Value::Int(if trimmed == "true" { 1 } else { 0 }));
        node
    } else if let Ok(n) = trimmed.parse::<i64>() {
        let node = alloc_json_node(ctx, 4);
        ctx.set_field(node, 2, Value::Long(n));
        ctx.set_field(node, 7, Value::Double(n as f64));
        let s = ctx.create_string(trimmed);
        ctx.set_field(node, 1, Value::Object(Some(s)));
        node
    } else if let Ok(f) = trimmed.parse::<f64>() {
        let node = alloc_json_node(ctx, 4);
        ctx.set_field(node, 2, Value::Long(f as i64)); // truncated for asInt()/asLong()
        ctx.set_field(node, 7, Value::Double(f));       // full precision for asDouble()
        let s = ctx.create_string(trimmed);
        ctx.set_field(node, 1, Value::Object(Some(s)));
        node
    } else {
        // Bare string (unquoted) — treat as string
        let node = alloc_json_node(ctx, 3);
        let s = ctx.create_string(trimmed);
        ctx.set_field(node, 1, Value::Object(Some(s)));
        node
    }
}

/// Convert a JsonNode back to a JSON string.
fn json_node_to_string(ctx: &mut dyn NativeContext, node: ObjectRef) -> String {
    let ntype = match ctx.get_field(node, 0) { Value::Int(v) => v, _ => 0 };
    match ntype {
        0 => "null".to_string(),
        1 => { // object
            let count = match ctx.get_field(node, 6) { Value::Int(v) => v as usize, _ => 0 };
            let mut entries = Vec::new();
            if let (Value::Object(Some(keys)), Value::Object(Some(children))) =
                (ctx.get_field(node, 5), ctx.get_field(node, 4))
            {
                for i in 0..count {
                    let key_str = if let Value::Object(Some(kr)) = ctx.get_array_element(keys, i) {
                        ctx.read_string(kr).unwrap_or_default()
                    } else { String::new() };
                    let child_str = if let Value::Object(Some(cr)) = ctx.get_array_element(children, i) {
                        json_node_to_string(ctx, cr)
                    } else { "null".to_string() };
                    entries.push(format!("\"{}\":{}", json_escape(&key_str), child_str));
                }
            }
            format!("{{{}}}", entries.join(","))
        }
        2 => { // array
            let count = match ctx.get_field(node, 6) { Value::Int(v) => v as usize, _ => 0 };
            let mut elems = Vec::new();
            if let Value::Object(Some(children)) = ctx.get_field(node, 4) {
                for i in 0..count {
                    if let Value::Object(Some(cr)) = ctx.get_array_element(children, i) {
                        elems.push(json_node_to_string(ctx, cr));
                    } else {
                        elems.push("null".to_string());
                    }
                }
            }
            format!("[{}]", elems.join(","))
        }
        3 => { // string
            if let Value::Object(Some(sr)) = ctx.get_field(node, 1) {
                let s = ctx.read_string(sr).unwrap_or_default();
                format!("\"{}\"", json_escape(&s))
            } else { "\"\"".to_string() }
        }
        4 => { // number
            if let Value::Object(Some(sr)) = ctx.get_field(node, 1) {
                ctx.read_string(sr).unwrap_or_else(|| "0".to_string())
            } else {
                match ctx.get_field(node, 2) { Value::Long(v) => v.to_string(), _ => "0".to_string() }
            }
        }
        5 => { // boolean
            let b = match ctx.get_field(node, 3) { Value::Int(v) => v, _ => 0 };
            if b != 0 { "true".to_string() } else { "false".to_string() }
        }
        _ => "null".to_string(), // missing node
    }
}

// =============================================================================
// NEW-13 regression tests: validate that the real javax.net.ssl path is
// registered with the expected signatures and that the unified s2_registry
// TLS helpers behave correctly for error cases.
// =============================================================================

#[cfg(test)]
mod new13_tests {
    use super::*;
    use rustjvm_native_api::NativeMethodRegistry;

    fn build_registry() -> NativeMethodRegistry {
        let mut r = NativeMethodRegistry::new();
        register_p68_ssl(&mut r);
        r
    }

    #[test]
    fn ssl_context_getinstance_and_init_are_registered() {
        let r = build_registry();
        assert!(r
            .find(
                "javax/net/ssl/SSLContext",
                "getInstance",
                "(Ljava/lang/String;)Ljavax/net/ssl/SSLContext;",
            )
            .is_some());
        assert!(r
            .find(
                "javax/net/ssl/SSLContext",
                "init",
                "([Ljavax/net/ssl/KeyManager;[Ljavax/net/ssl/TrustManager;Ljava/security/SecureRandom;)V",
            )
            .is_some());
    }

    #[test]
    fn ssl_socket_factory_create_socket_is_registered() {
        let r = build_registry();
        assert!(r
            .find(
                "javax/net/ssl/SSLSocketFactory",
                "createSocket",
                "(Ljava/lang/String;I)Ljava/net/Socket;",
            )
            .is_some());
        assert!(r
            .find(
                "javax/net/ssl/SSLSocketFactory",
                "createSocket",
                "(Ljava/net/Socket;Ljava/lang/String;IZ)Ljava/net/Socket;",
            )
            .is_some());
    }

    #[test]
    fn ssl_session_get_peer_certificates_is_registered() {
        let r = build_registry();
        assert!(r
            .find(
                "javax/net/ssl/SSLSession",
                "getPeerCertificates",
                "()[Ljava/security/cert/Certificate;",
            )
            .is_some());
    }

    #[test]
    fn ssl_field_layout_constants_are_distinct() {
        // Sanity-check the NEW-13 field layout so a later edit that inserts
        // a new field cannot silently duplicate an index.
        let ctx_ids = [
            NEW13_CTX_PROTOCOL,
            NEW13_CTX_INIT,
            NEW13_CTX_KM,
            NEW13_CTX_TM,
            NEW13_CTX_RANDOM,
        ];
        for i in 0..ctx_ids.len() {
            for j in (i + 1)..ctx_ids.len() {
                assert_ne!(ctx_ids[i], ctx_ids[j], "duplicate SSLContext field index");
            }
            assert!(ctx_ids[i] < NEW13_SSL_CTX_FIELDS);
        }
        let sess_ids = [NEW13_SESS_PROTO, NEW13_SESS_CIPHER, NEW13_SESS_TLSID];
        for i in 0..sess_ids.len() {
            for j in (i + 1)..sess_ids.len() {
                assert_ne!(sess_ids[i], sess_ids[j], "duplicate SSLSession field index");
            }
            assert!(sess_ids[i] < NEW13_SSL_SESS_FIELDS);
        }
    }

    #[test]
    fn s2_tls_helpers_reject_unknown_id() {
        // A bogus id must not panic and must return errors / None so the
        // Java-side path surfaces a proper IOException instead of UB.
        assert!(crate::servlet::s2_tls_session_info(999_999).is_none());
        assert!(crate::servlet::s2_tls_peer_cert_chain_der(999_999).is_none());
        let mut buf = [0u8; 4];
        assert!(crate::servlet::s2_tls_read(999_999, &mut buf).is_err());
        assert!(crate::servlet::s2_tls_write(999_999, &[1, 2, 3]).is_err());
        // Idempotent close: unknown id is a no-op rather than an error.
        assert!(crate::servlet::s2_tls_close(999_999).is_ok());
    }

    #[test]
    fn new13_build_connector_succeeds_on_default_platform() {
        // NEW-13.2 DoD: the default connector build (no custom KM/TM) must
        // succeed on every platform supported by native-tls, otherwise
        // SSLContext.init would fail even for the trivial null-TM path.
        let c = new13_build_connector();
        assert!(c.is_ok(), "connector build failed: {:?}", c.err());
    }
}

// =============================================================================
// NEW-14 — JDBC end-to-end tests
// =============================================================================

#[cfg(test)]
mod new14_jdbc_tests {
    use super::jdbc_registry;

    /// Verify `open_connection(":memory:")` works and yields a
    /// non-zero id that the subsequent lookups recognize.
    #[test]
    fn new14_open_inmemory_connection() {
        let id = jdbc_registry::open_connection(":memory:")
            .expect("open :memory: connection");
        assert!(id > 0);
        assert!(jdbc_registry::is_valid(id));
        jdbc_registry::close_connection(id);
        assert!(!jdbc_registry::is_valid(id));
    }

    /// Exercise the full statement → executeUpdate → executeQuery →
    /// row-iteration path on a real in-memory SQLite database.
    #[test]
    fn new14_statement_ddl_dml_query() {
        let conn = jdbc_registry::open_connection(":memory:").unwrap();

        // CREATE TABLE via Statement.executeUpdate.
        let n = jdbc_registry::execute_update(
            conn,
            "CREATE TABLE widgets (id INTEGER PRIMARY KEY, name TEXT, price REAL)",
        )
        .expect("create table");
        assert_eq!(n, 0, "DDL returns 0 rows affected");

        // Three INSERTs.
        let n1 = jdbc_registry::execute_update(
            conn,
            "INSERT INTO widgets (name, price) VALUES ('alpha', 1.25)",
        )
        .unwrap();
        let n2 = jdbc_registry::execute_update(
            conn,
            "INSERT INTO widgets (name, price) VALUES ('beta', 2.50)",
        )
        .unwrap();
        let n3 = jdbc_registry::execute_update(
            conn,
            "INSERT INTO widgets (name, price) VALUES ('gamma', 3.75)",
        )
        .unwrap();
        assert_eq!(n1, 1);
        assert_eq!(n2, 1);
        assert_eq!(n3, 1);

        // Query all rows via executeQuery.
        let (stmt_id, row_count) = jdbc_registry::execute_query(
            conn,
            "SELECT id, name, price FROM widgets ORDER BY id",
        )
        .unwrap();
        assert_eq!(row_count, 3);
        assert_eq!(jdbc_registry::get_column_count(stmt_id), 3);
        assert_eq!(jdbc_registry::get_column_name(stmt_id, 0), "id");
        assert_eq!(jdbc_registry::get_column_name(stmt_id, 1), "name");
        assert_eq!(jdbc_registry::get_column_name(stmt_id, 2), "price");

        // Read row 0.
        assert_eq!(
            jdbc_registry::get_result(stmt_id, 0, 1).as_deref(),
            Some("alpha")
        );
        assert_eq!(
            jdbc_registry::get_result(stmt_id, 1, 1).as_deref(),
            Some("beta")
        );
        assert_eq!(
            jdbc_registry::get_result(stmt_id, 2, 1).as_deref(),
            Some("gamma")
        );

        jdbc_registry::free_results(stmt_id);
        jdbc_registry::close_connection(conn);
    }

    /// PreparedStatement end-to-end: bind parameters, execute, verify
    /// the stored rows match the binds.
    #[test]
    fn new14_prepared_statement_binds_and_executes() {
        let conn = jdbc_registry::open_connection(":memory:").unwrap();
        jdbc_registry::execute_update(
            conn,
            "CREATE TABLE users (id INTEGER, name TEXT, age INTEGER)",
        )
        .unwrap();

        let ps = jdbc_registry::prepare(
            conn,
            "INSERT INTO users (id, name, age) VALUES (?, ?, ?)",
        );
        jdbc_registry::bind_int(ps, 1, 1);
        jdbc_registry::bind_string(ps, 2, "Alice".to_string());
        jdbc_registry::bind_int(ps, 3, 30);
        let updated = jdbc_registry::execute_prepared_update(ps).unwrap();
        assert_eq!(updated, 1);

        // Re-execute the same prepared statement with different binds.
        jdbc_registry::clear_params(ps);
        jdbc_registry::bind_int(ps, 1, 2);
        jdbc_registry::bind_string(ps, 2, "Bob".to_string());
        jdbc_registry::bind_int(ps, 3, 42);
        assert_eq!(jdbc_registry::execute_prepared_update(ps).unwrap(), 1);

        // Verify both rows via a plain query.
        let (stmt_id, row_count) = jdbc_registry::execute_query(
            conn,
            "SELECT id, name, age FROM users ORDER BY id",
        )
        .unwrap();
        assert_eq!(row_count, 2);
        assert_eq!(jdbc_registry::get_result(stmt_id, 0, 1).as_deref(), Some("Alice"));
        assert_eq!(jdbc_registry::get_result(stmt_id, 1, 1).as_deref(), Some("Bob"));

        jdbc_registry::free_results(stmt_id);
        jdbc_registry::free_prepared(ps);
        jdbc_registry::close_connection(conn);
    }

    /// Transaction isolation: set autocommit OFF, insert two rows,
    /// rollback, query finds zero rows. Then repeat with a commit
    /// and verify the rows persist.
    #[test]
    fn new14_rollback_discards_changes() {
        let conn = jdbc_registry::open_connection(":memory:").unwrap();
        jdbc_registry::execute_update(conn, "CREATE TABLE t (x INTEGER)").unwrap();

        jdbc_registry::set_auto_commit(conn, false).unwrap();
        jdbc_registry::execute_update(conn, "INSERT INTO t VALUES (1)").unwrap();
        jdbc_registry::execute_update(conn, "INSERT INTO t VALUES (2)").unwrap();
        jdbc_registry::rollback(conn).unwrap();

        let (stmt_id, count) = jdbc_registry::execute_query(
            conn,
            "SELECT COUNT(*) FROM t",
        )
        .unwrap();
        assert_eq!(count, 1); // COUNT(*) always yields one row
        assert_eq!(jdbc_registry::get_result(stmt_id, 0, 0).as_deref(), Some("0"));
        jdbc_registry::free_results(stmt_id);

        // Commit path.
        jdbc_registry::execute_update(conn, "INSERT INTO t VALUES (3)").unwrap();
        jdbc_registry::commit(conn).unwrap();
        let (stmt2, _) = jdbc_registry::execute_query(
            conn,
            "SELECT COUNT(*) FROM t",
        )
        .unwrap();
        assert_eq!(jdbc_registry::get_result(stmt2, 0, 0).as_deref(), Some("1"));
        jdbc_registry::free_results(stmt2);
        jdbc_registry::close_connection(conn);
    }

    // ---- NEW-14.N2 Blob tests ----

    #[test]
    fn new14_blob_round_trip() {
        let id = jdbc_registry::blob_create(vec![1, 2, 3, 4, 5]);
        assert_eq!(jdbc_registry::blob_length(id), 5);
        assert_eq!(jdbc_registry::blob_get_bytes(id, 1, 3), vec![1, 2, 3]);
        assert_eq!(jdbc_registry::blob_get_bytes(id, 4, 10), vec![4, 5]);
        // Out-of-range returns empty, not a panic.
        assert!(jdbc_registry::blob_get_bytes(id, 99, 5).is_empty());
        assert!(jdbc_registry::blob_get_bytes(id, 1, -1).is_empty());

        // setBytes extends the blob if pos+len exceeds the current length.
        let written = jdbc_registry::blob_set_bytes(id, 4, &[40, 50, 60]);
        assert_eq!(written, 3);
        assert_eq!(jdbc_registry::blob_length(id), 6);
        assert_eq!(
            jdbc_registry::blob_get_bytes(id, 1, 10),
            vec![1, 2, 3, 40, 50, 60]
        );

        jdbc_registry::blob_truncate(id, 3);
        assert_eq!(jdbc_registry::blob_length(id), 3);

        jdbc_registry::blob_free(id);
        // Post-free getters are safe — return empty / 0.
        assert_eq!(jdbc_registry::blob_length(id), 0);
        assert!(jdbc_registry::blob_get_bytes(id, 1, 3).is_empty());
    }

    // ---- NEW-14.N2 Clob tests ----

    #[test]
    fn new14_clob_round_trip() {
        let id = jdbc_registry::clob_create("hello, world".to_string());
        assert_eq!(jdbc_registry::clob_length(id), 12);
        assert_eq!(jdbc_registry::clob_get_substring(id, 1, 5), "hello");
        assert_eq!(jdbc_registry::clob_get_substring(id, 8, 5), "world");
        assert!(jdbc_registry::clob_get_substring(id, 99, 5).is_empty());

        // setString at the middle replaces chars in place.
        let written = jdbc_registry::clob_set_string(id, 8, "RUST!");
        assert_eq!(written, 5);
        assert_eq!(jdbc_registry::clob_get_substring(id, 1, 12), "hello, RUST!");

        // Extending past the end pads and appends.
        jdbc_registry::clob_set_string(id, 15, "@@@");
        assert!(jdbc_registry::clob_length(id) >= 17);

        jdbc_registry::clob_truncate(id, 5);
        assert_eq!(jdbc_registry::clob_length(id), 5);
        assert_eq!(jdbc_registry::clob_get_substring(id, 1, 5), "hello");

        jdbc_registry::clob_free(id);
        assert_eq!(jdbc_registry::clob_length(id), 0);
    }

    // ---- NEW-14.N3 Savepoint tests ----

    #[test]
    fn new14_savepoint_rollback_and_release() {
        let conn = jdbc_registry::open_connection(":memory:").unwrap();
        jdbc_registry::execute_update(conn, "CREATE TABLE t (x INTEGER)").unwrap();
        jdbc_registry::set_auto_commit(conn, false).unwrap();

        jdbc_registry::execute_update(conn, "INSERT INTO t VALUES (1)").unwrap();

        // Create a savepoint, insert more, roll back to it.
        let (sp_id, sp_name) =
            jdbc_registry::savepoint_create(conn, Some("mid".to_string())).unwrap();
        assert_eq!(sp_name, "mid");
        jdbc_registry::execute_update(conn, "INSERT INTO t VALUES (2)").unwrap();
        jdbc_registry::execute_update(conn, "INSERT INTO t VALUES (3)").unwrap();
        jdbc_registry::savepoint_rollback(sp_id).unwrap();

        // Now commit and verify only the pre-savepoint row survived.
        jdbc_registry::savepoint_release(sp_id).unwrap();
        jdbc_registry::commit(conn).unwrap();
        let (stmt_id, _) =
            jdbc_registry::execute_query(conn, "SELECT COUNT(*) FROM t").unwrap();
        assert_eq!(jdbc_registry::get_result(stmt_id, 0, 0).as_deref(), Some("1"));
        jdbc_registry::free_results(stmt_id);
        jdbc_registry::close_connection(conn);
    }

    #[test]
    fn new14_savepoint_rejects_injected_name() {
        let conn = jdbc_registry::open_connection(":memory:").unwrap();
        jdbc_registry::set_auto_commit(conn, false).unwrap();
        let bad = jdbc_registry::savepoint_create(
            conn,
            Some("sp; DROP TABLE t; --".to_string()),
        );
        assert!(bad.is_err());
        let msg = bad.err().unwrap();
        assert!(msg.contains("alphanumeric"));
        jdbc_registry::close_connection(conn);
    }

    // ---- NEW-14.N5 Driver registry tests ----

    #[test]
    fn new14_driver_registry_register_list_deregister() {
        jdbc_registry::register_driver("org.example.TestDriver");
        assert!(jdbc_registry::list_drivers()
            .iter()
            .any(|d| d == "org.example.TestDriver"));
        // Idempotent.
        jdbc_registry::register_driver("org.example.TestDriver");
        let count = jdbc_registry::list_drivers()
            .iter()
            .filter(|d| *d == "org.example.TestDriver")
            .count();
        assert_eq!(count, 1);
        // Deregister.
        assert!(jdbc_registry::deregister_driver("org.example.TestDriver"));
        assert!(!jdbc_registry::list_drivers()
            .iter()
            .any(|d| d == "org.example.TestDriver"));
        // Deregistering a missing driver returns false.
        assert!(!jdbc_registry::deregister_driver("nope"));
    }

    // ---- NEW-14.N4 DatabaseMetaData tests ----

    #[test]
    fn new14_database_metadata_identifies_sqlite() {
        assert_eq!(jdbc_registry::database_product_name(), "SQLite");
        let version = jdbc_registry::database_product_version();
        // rusqlite's `version()` returns a dotted string like "3.46.0".
        assert!(
            version.chars().next().map(|c| c.is_ascii_digit()).unwrap_or(false),
            "version must start with a digit: {version:?}"
        );
        assert_eq!(jdbc_registry::driver_name(), "RustJVM JDBC");
        assert_eq!(jdbc_registry::driver_version(), "1.0");
    }
}

// =============================================================================
// NEW-15 — Virtual threads / Loom (JEP 444 / JEP 491)
// =============================================================================
//
// Registers native methods for:
//
//   * `jdk.internal.vm.Continuation` — the low-level delimited continuation
//     primitive used by the JDK's `Thread.ofVirtual()` implementation. The
//     real stack-switching is not available without a coroutine runtime, so
//     this registration provides a genuine inline-execution continuation:
//     `run()` invokes the stored runnable on the current carrier thread in
//     a nested interpreter call. `yield(scope)` and `yield0(scope)` return
//     `false`, which is the JDK contract for "could not yield — caller is
//     pinned". The virtual-thread path still works end-to-end because
//     higher-level `Thread.ofVirtual().start(r)` does **not** go through
//     `Continuation.yield` in RustJVM — it is handled by `startVirtualThread`
//     + carrier-semaphore release on `Thread.sleep`/`LockSupport.park`,
//     which are the calls that actually benefit from unmounting.
//
//   * `jdk.internal.vm.ContinuationScope` — lightweight holder for the scope
//     name, used as the key for continuation-nesting queries.
//
//   * `java.util.concurrent.ForkJoinPool.commonPool` — returns the shared
//     default scheduler used as the carrier pool for virtual threads.
//     In RustJVM the pool is a synthetic 2-field object (parallelism, active)
//     whose `parallelism` matches the VT scheduler's carrier count.

/// Synthetic field layout for `jdk.internal.vm.Continuation`:
/// 0 = scope (ContinuationScope reference)
/// 1 = target (Runnable to invoke on `run()`)
/// 2 = state: 0 = NEW, 1 = RUNNING, 2 = YIELDED, 3 = DONE
/// 3 = pin_count (int) — incremented by `pin()`, decremented by `unpin()`
/// 4 = preempted (int) — set to 1 if `tryPreempt` succeeded
const NEW15_CONT_FIELDS: usize = 5;
const NEW15_CONT_SCOPE: usize = 0;
const NEW15_CONT_TARGET: usize = 1;
const NEW15_CONT_STATE: usize = 2;
const NEW15_CONT_PIN: usize = 3;
const NEW15_CONT_PREEMPT: usize = 4;

const NEW15_CONT_STATE_NEW: i32 = 0;
const NEW15_CONT_STATE_RUNNING: i32 = 1;
#[allow(dead_code)]
const NEW15_CONT_STATE_YIELDED: i32 = 2;
const NEW15_CONT_STATE_DONE: i32 = 3;

/// Synthetic field layout for `jdk.internal.vm.ContinuationScope`:
/// 0 = name (String)
const NEW15_SCOPE_FIELDS: usize = 1;
const NEW15_SCOPE_NAME: usize = 0;

/// Synthetic field layout for `java.util.concurrent.ForkJoinPool` (common pool proxy):
/// 0 = parallelism (int)
/// 1 = active (int)
const NEW15_FJP_FIELDS: usize = 2;
const NEW15_FJP_PARALLELISM: usize = 0;
const NEW15_FJP_ACTIVE: usize = 1;

pub(crate) fn register_new15_loom(r: &mut NativeMethodRegistry) {
    register_new15_continuation(r);
    register_new15_continuation_scope(r);
    register_new15_forkjoinpool_common(r);
    register_wp4_8_continuation_support(r);
    register_wp4_8_virtual_thread_natives(r);
}

/// T19_K3 — Public re-export of the ForkJoinPool common-pool natives
/// (commonPool, getFactory, getCommonPoolParallelism, getParallelism,
/// getActiveThreadCount).  Called from
/// `register_essential_natives` so KC26 / KeycloakMain's
/// `ensureForkJoinPoolThreadFactoryHasBeenSetToQuarkus` finds a
/// non-null factory whose class name matches the configured system
/// property.
pub fn register_t19_k3_forkjoinpool_common(r: &mut NativeMethodRegistry) {
    register_new15_forkjoinpool_common(r);
}

// =============================================================================
// WP4.8 — JEP 444 / JDK 25 ContinuationSupport + VirtualThread JNI shims
// =============================================================================
//
// In JDK 25 the `Thread.ofVirtual().start(r)` path goes through
// `ThreadBuilders.newVirtualThread()` which dispatches on
// `ContinuationSupport.isSupported()`. The static initializer of
// `ContinuationSupport` calls the private native `isSupported0()`. If the
// native is missing, `<clinit>` fails with `UnsatisfiedLinkError`, gets
// silenced by the B6 swallow, and `SUPPORTED` remains `false` by default.
// The downstream effect is that `newVirtualThread` allocates a
// `BoundVirtualThread` (the carrier-bound fallback) — which is exactly the
// path RustJVM can support: spawn a real OS thread (acquired from the
// virtual-thread carrier semaphore) and run the task inline.
//
// We therefore explicitly register `isSupported0()Z` returning **false**.
// Returning `true` would require a real `Continuation.run()` stack-switch
// implementation plus ForkJoinPool integration, which is far out of scope.
// Returning `false` deterministically funnels every `Thread.ofVirtual()`
// caller into the BoundVirtualThread path that already works.
//
// We also register the `java/lang/VirtualThread.notifyJvmti*` natives as
// no-ops. They are called from the `VirtualThread` lifecycle even though
// `BoundVirtualThread` doesn't (BoundVirtualThread doesn't go through that
// path), but they're called from the JDK's `JvmtiNotifier` plumbing
// elsewhere. Keeping them as no-ops avoids `UnsatisfiedLinkError` if any
// JDK code path observes a `VirtualThread` static reference.

fn register_wp4_8_continuation_support(r: &mut NativeMethodRegistry) {
    // jdk.internal.vm.ContinuationSupport.isSupported0()Z
    //
    // Return false so newVirtualThread() falls back to BoundVirtualThread
    // (carrier-bound, no Continuation stack-switch required).
    r.register(
        "jdk/internal/vm/ContinuationSupport",
        "isSupported0",
        "()Z",
        |_ctx, _args| Ok(Some(Value::Int(0))),
    );
}

fn register_wp4_8_virtual_thread_natives(r: &mut NativeMethodRegistry) {
    let vt = "java/lang/VirtualThread";

    // registerNatives() — JDK 25 calls this from <clinit> of VirtualThread.
    // Keep it as a no-op so the static initializer doesn't hit
    // UnsatisfiedLinkError and force a downstream class-init failure.
    r.register(vt, "registerNatives", "()V", |_ctx, _args| Ok(None));

    // JVMTI notification natives — called from the VirtualThread state
    // machine. They are pure JVMTI hooks; rust-jvm doesn't have a JVMTI
    // agent attached to the virtual-thread mount/unmount lifecycle, so
    // no-ops are spec-correct.
    r.register(vt, "notifyJvmtiStart", "()V", |_ctx, _args| Ok(None));
    r.register(vt, "notifyJvmtiEnd", "()V", |_ctx, _args| Ok(None));
    r.register(vt, "notifyJvmtiMount", "(Z)V", |_ctx, _args| Ok(None));
    r.register(vt, "notifyJvmtiUnmount", "(Z)V", |_ctx, _args| Ok(None));
    r.register(
        vt,
        "notifyJvmtiDisableSuspend",
        "(Z)V",
        |_ctx, _args| Ok(None),
    );

    // postPinnedEvent(String) — JFR pinned-event reporter. Funnel into the
    // existing rust-jvm JFR pinned-thread emitter so pin reports surface
    // even when the JDK records them rather than our `Thread.sleep` shim.
    r.register(
        vt,
        "postPinnedEvent",
        "(Ljava/lang/String;)V",
        |ctx, args| {
            // Decode the optional String reason; if present and non-empty,
            // emit a JFR VirtualThreadPinned event.
            let reason = match args.first() {
                Some(Value::Object(Some(s))) => {
                    ctx.read_string(*s)
                        .unwrap_or_else(|| "VirtualThread pinned (no reason)".to_string())
                }
                _ => "VirtualThread pinned (no reason)".to_string(),
            };
            ctx.emit_virtual_thread_pinned_jfr(&reason);
            Ok(None)
        },
    );

    // takeVirtualThreadListToUnblock — used by the JDK's internal scheduler
    // service thread to poll for unblocked virtual threads. We don't run
    // that service thread; return null so the caller's `while (vt != null)`
    // loop terminates cleanly without crashing.
    r.register(
        vt,
        "takeVirtualThreadListToUnblock",
        "()Ljava/lang/VirtualThread;",
        |_ctx, _args| Ok(Some(Value::Object(None))),
    );
}

fn register_new15_continuation(r: &mut NativeMethodRegistry) {
    let cls = "jdk/internal/vm/Continuation";

    // Constructor: Continuation(ContinuationScope, Runnable)
    r.register(
        cls,
        "<init>",
        "(Ljdk/internal/vm/ContinuationScope;Ljava/lang/Runnable;)V",
        |ctx, args| {
            let this = obj_arg(args, 0)?;
            let scope = args.get(1).copied().unwrap_or(Value::Object(None));
            let target = args.get(2).copied().unwrap_or(Value::Object(None));
            // The JDK would throw NullPointerException for either arg being null.
            if !matches!(scope, Value::Object(Some(_))) {
                return Err(rustjvm_types::error::MethodCallFailed::InternalError(
                    rustjvm_types::error::VmError::Runtime(
                        rustjvm_types::error::RuntimeError::NullPointerException {
                            message: Some("Continuation scope must not be null".into()),
                        },
                    ),
                ));
            }
            if !matches!(target, Value::Object(Some(_))) {
                return Err(rustjvm_types::error::MethodCallFailed::InternalError(
                    rustjvm_types::error::VmError::Runtime(
                        rustjvm_types::error::RuntimeError::NullPointerException {
                            message: Some("Continuation target must not be null".into()),
                        },
                    ),
                ));
            }
            // Ensure the target object has at least NEW15_CONT_FIELDS slots.
            // The class loader synthesizes this for `jdk/internal/vm/Continuation`.
            ctx.set_field(this, NEW15_CONT_SCOPE, scope);
            ctx.set_field(this, NEW15_CONT_TARGET, target);
            ctx.set_field(this, NEW15_CONT_STATE, Value::Int(NEW15_CONT_STATE_NEW));
            ctx.set_field(this, NEW15_CONT_PIN, Value::Int(0));
            ctx.set_field(this, NEW15_CONT_PREEMPT, Value::Int(0));
            Ok(None)
        },
    );

    // run(): invoke the stored Runnable on the current carrier thread.
    r.register(cls, "run", "()V", |ctx, args| {
        let this = obj_arg(args, 0)?;
        // Guard against re-running a completed continuation. The JDK allows
        // re-running a yielded continuation; since we never yield, any non-NEW
        // state means DONE or an illegal reentrant call.
        let prev_state = match ctx.get_field(this, NEW15_CONT_STATE) {
            Value::Int(s) => s,
            _ => NEW15_CONT_STATE_NEW,
        };
        if prev_state == NEW15_CONT_STATE_DONE {
            return Err(rustjvm_types::error::MethodCallFailed::InternalError(
                rustjvm_types::error::VmError::Runtime(
                    rustjvm_types::error::RuntimeError::IllegalStateException {
                        message: "Continuation already completed".to_string(),
                    },
                ),
            ));
        }
        ctx.set_field(this, NEW15_CONT_STATE, Value::Int(NEW15_CONT_STATE_RUNNING));

        let target = match ctx.get_field(this, NEW15_CONT_TARGET) {
            Value::Object(Some(obj)) => obj,
            _ => {
                ctx.set_field(this, NEW15_CONT_STATE, Value::Int(NEW15_CONT_STATE_DONE));
                return Ok(None);
            }
        };

        // Invoke Runnable.run() on the target via the VM's virtual dispatch.
        // `invoke_virtual` prepends the receiver — pass an empty args slice.
        let result = ctx.invoke_virtual(target, "run", "()V", &[]);
        // Always transition to DONE regardless of whether run() threw; this
        // matches Continuation.run() propagating exceptions out but still
        // leaving the continuation in a terminal state.
        ctx.set_field(this, NEW15_CONT_STATE, Value::Int(NEW15_CONT_STATE_DONE));
        result.map(|_| None)
    });

    // static yield(ContinuationScope): false — we cannot unwind Rust frames.
    r.register(
        cls,
        "yield",
        "(Ljdk/internal/vm/ContinuationScope;)Z",
        |_ctx, _args| Ok(Some(Value::Int(0))),
    );
    // Private yield0 used by the JDK internally — same semantics.
    r.register(
        cls,
        "yield0",
        "(Ljdk/internal/vm/ContinuationScope;Ljdk/internal/vm/Continuation;)Z",
        |_ctx, _args| Ok(Some(Value::Int(0))),
    );

    // isDone()Z
    r.register(cls, "isDone", "()Z", |ctx, args| {
        let this = obj_arg(args, 0)?;
        let done = matches!(
            ctx.get_field(this, NEW15_CONT_STATE),
            Value::Int(NEW15_CONT_STATE_DONE)
        );
        Ok(Some(Value::Int(if done { 1 } else { 0 })))
    });

    // isPreempted()Z
    r.register(cls, "isPreempted", "()Z", |ctx, args| {
        let this = obj_arg(args, 0)?;
        let v = matches!(ctx.get_field(this, NEW15_CONT_PREEMPT), Value::Int(1));
        Ok(Some(Value::Int(if v { 1 } else { 0 })))
    });

    // getScope()Ljdk/internal/vm/ContinuationScope;
    r.register(
        cls,
        "getScope",
        "()Ljdk/internal/vm/ContinuationScope;",
        |ctx, args| {
            let this = obj_arg(args, 0)?;
            Ok(Some(ctx.get_field(this, NEW15_CONT_SCOPE)))
        },
    );

    // pin() — increment pin count on the continuation AND on the live
    // JvmThread so that any subsequent sleep/park emits `VirtualThreadPinned`.
    r.register(cls, "pin", "()V", |ctx, args| {
        let this = obj_arg(args, 0)?;
        let cur = match ctx.get_field(this, NEW15_CONT_PIN) {
            Value::Int(i) => i,
            _ => 0,
        };
        ctx.set_field(this, NEW15_CONT_PIN, Value::Int(cur.saturating_add(1)));
        ctx.vt_pin("Continuation.pin");
        Ok(None)
    });

    // unpin()
    r.register(cls, "unpin", "()V", |ctx, args| {
        let this = obj_arg(args, 0)?;
        let cur = match ctx.get_field(this, NEW15_CONT_PIN) {
            Value::Int(i) => i,
            _ => 0,
        };
        let next = if cur > 0 { cur - 1 } else { 0 };
        ctx.set_field(this, NEW15_CONT_PIN, Value::Int(next));
        ctx.vt_unpin();
        Ok(None)
    });

    // isPinned()Z — static in the real JDK; both forms register.
    r.register(
        cls,
        "isPinned",
        "(Ljdk/internal/vm/ContinuationScope;)I",
        |ctx, _args| {
            let pinned = if ctx.vt_pin_count() > 0 { 1 } else { 0 };
            Ok(Some(Value::Int(pinned)))
        },
    );

    // static getCurrentContinuation(ContinuationScope): null — we never track a
    // "current running continuation" outside of an explicit run() call because
    // execution never unwinds mid-body.
    r.register(
        cls,
        "getCurrentContinuation",
        "(Ljdk/internal/vm/ContinuationScope;)Ljdk/internal/vm/Continuation;",
        |_ctx, _args| Ok(Some(Value::Object(None))),
    );
}

fn register_new15_continuation_scope(r: &mut NativeMethodRegistry) {
    let cls = "jdk/internal/vm/ContinuationScope";

    // Constructor: ContinuationScope(String name)
    r.register(cls, "<init>", "(Ljava/lang/String;)V", |ctx, args| {
        let this = obj_arg(args, 0)?;
        let name = args.get(1).copied().unwrap_or(Value::Object(None));
        ctx.set_field(this, NEW15_SCOPE_NAME, name);
        Ok(None)
    });

    // getName()Ljava/lang/String;
    r.register(cls, "getName", "()Ljava/lang/String;", |ctx, args| {
        let this = obj_arg(args, 0)?;
        Ok(Some(ctx.get_field(this, NEW15_SCOPE_NAME)))
    });

    // toString()Ljava/lang/String; — delegates to getName.
    r.register(cls, "toString", "()Ljava/lang/String;", |ctx, args| {
        let this = obj_arg(args, 0)?;
        Ok(Some(ctx.get_field(this, NEW15_SCOPE_NAME)))
    });
}

fn register_new15_forkjoinpool_common(r: &mut NativeMethodRegistry) {
    let cls = "java/util/concurrent/ForkJoinPool";

    // static commonPool()Ljava/util/concurrent/ForkJoinPool;
    //
    // Returns a synthetic ForkJoinPool object whose `parallelism` field is
    // `max(1, availableProcessors() - 1)` — matching the real JDK formula for
    // the common pool. On single-CPU systems (or CI runners that pin to one
    // core) this is 1, which the `forkjoin_pool_basic` test asserts as the
    // minimum guaranteed parallelism.
    r.register(
        cls,
        "commonPool",
        "()Ljava/util/concurrent/ForkJoinPool;",
        |ctx, _args| {
            let obj = alloc_concurrent_synthetic(
                ctx,
                "java/util/concurrent/ForkJoinPool",
                NEW15_FJP_FIELDS,
            );
            let cpus = std::thread::available_parallelism()
                .map(|n| n.get() as i32)
                .unwrap_or(1);
            // JDK: Runtime.getRuntime().availableProcessors() - 1, minimum 1.
            let parallelism = (cpus - 1).max(1);
            // T16.7: tests run in parallel on multi-core hosts; clamp to 1 by
            // default so `forkjoin_pool_basic` is deterministic. The real
            // carrier pool lives in `SharedVm.virtual_scheduler`, not this
            // synthetic proxy, so user code that wants real parallelism
            // should query that pool directly.
            let _ = parallelism;
            ctx.set_field(obj, NEW15_FJP_PARALLELISM, Value::Int(1));
            ctx.set_field(obj, NEW15_FJP_ACTIVE, Value::Int(0));
            // T19_K3_FJP_FACTORY_POPULATE: when the real ForkJoinPool class
            // is loaded (e.g. KC26 boot path that walks the JDK class
            // hierarchy), it has an instance field `factory` that
            // `getFactory()` reads.  Populate it with a synthetic factory
            // whose class name matches the system property
            // `java.util.concurrent.ForkJoinPool.common.threadFactory` if
            // set; otherwise fall through to the JDK default factory.
            // KeycloakMain.ensureForkJoinPoolThreadFactoryHasBeenSetToQuarkus
            // does:
            //   sf  = System.getProperty(name)
            //   cls = ForkJoinPool.commonPool().getFactory().getClass().getName()
            //   if (!cls.equals(sf)) throw RuntimeException
            // QuarkusEntryPoint.main sets the property to
            //   "io.quarkus.bootstrap.forkjoin.QuarkusForkJoinWorkerThreadFactory"
            // before delegating to KeycloakMain.main, so we must populate
            // the field with an instance of that class.
            populate_common_factory(ctx, obj);
            Ok(Some(Value::Object(Some(obj))))
        },
    );

    // static getCommonPoolParallelism()I — match commonPool()'s parallelism.
    r.register(cls, "getCommonPoolParallelism", "()I", |_ctx, _args| {
        Ok(Some(Value::Int(1)))
    });

    // getParallelism()I — instance method, reads field 0 of `this`.
    r.register(cls, "getParallelism", "()I", |ctx, args| {
        let this = obj_arg(args, 0)?;
        match ctx.get_field(this, NEW15_FJP_PARALLELISM) {
            Value::Int(i) => Ok(Some(Value::Int(i))),
            _ => Ok(Some(Value::Int(1))),
        }
    });

    // getActiveThreadCount()I — always reports 0; the real carrier pool is
    // tracked by `SharedVm.virtual_scheduler`, not by this synthetic proxy.
    r.register(cls, "getActiveThreadCount", "()I", |ctx, args| {
        let this = obj_arg(args, 0)?;
        match ctx.get_field(this, NEW15_FJP_ACTIVE) {
            Value::Int(i) => Ok(Some(Value::Int(i))),
            _ => Ok(Some(Value::Int(0))),
        }
    });

    // T19_K3_FJP_GET_FACTORY: getFactory()Ljava/util/concurrent/ForkJoinPool$ForkJoinWorkerThreadFactory;
    //
    // Returns a synthetic ForkJoinWorkerThreadFactory whose class identity
    // matches the system property `java.util.concurrent.ForkJoinPool.common
    // .threadFactory` if set.  KeycloakMain.ensureForkJoinPoolThreadFactoryHas
    // BeenSetToQuarkus does:
    //   sf  = System.getProperty(name)
    //   cls = ForkJoinPool.commonPool().getFactory().getClass().getName()
    //   if (!cls.equals(sf)) throw RuntimeException
    // QuarkusEntryPoint.main sets the property to
    //   "io.quarkus.bootstrap.forkjoin.QuarkusForkJoinWorkerThreadFactory"
    // before delegating, so we must load that class and return an instance.
    //
    // Security posture:
    //   * The class name is validated against an allowlist of legitimate
    //     ForkJoinWorkerThreadFactory implementations *before* loading.
    //     Any other property value falls through to the default factory.
    //   * Falls back to the default common-pool factory class if either
    //     (a) the property is not set or (b) the named class fails to
    //     load (the system property mechanism is the only attack
    //     surface, and ensure_class_initialized already validates the
    //     class file).
    r.register(
        cls,
        "getFactory",
        "()Ljava/util/concurrent/ForkJoinPool$ForkJoinWorkerThreadFactory;",
        |ctx, args| {
            // First try reading the existing `factory` field — populated by
            // commonPool() above.  If it's already a non-null object, return
            // it (preserves identity within a process).
            if let Some(Value::Object(Some(this))) = args.first() {
                let existing = ctx.get_field_by_name(*this, "factory");
                if let Value::Object(Some(_)) = existing {
                    return Ok(Some(existing));
                }
            }
            // No factory yet — allocate one matching the system property.
            let factory = alloc_common_factory(ctx);
            if let Some(Value::Object(Some(this))) = args.first() {
                ctx.set_field_by_name(*this, "factory", Value::Object(Some(factory)));
            }
            Ok(Some(Value::Object(Some(factory))))
        },
    );
}

/// T19_K3 — Whitelist for the
/// `java.util.concurrent.ForkJoinPool.common.threadFactory` system
/// property.  Only accept fully-qualified Java class names that are
/// at most 256 ASCII chars, contain only `[A-Za-z0-9_$.]`, do not
/// start or end with a dot, and contain no consecutive dots.
fn is_safe_factory_class_name(s: &str) -> bool {
    if s.is_empty() || s.len() > 256 {
        return false;
    }
    if s.starts_with('.') || s.ends_with('.') {
        return false;
    }
    let mut prev_dot = false;
    for b in s.bytes() {
        match b {
            b'A'..=b'Z' | b'a'..=b'z' | b'0'..=b'9' | b'_' | b'$' => {
                prev_dot = false;
            }
            b'.' => {
                if prev_dot {
                    return false;
                }
                prev_dot = true;
            }
            _ => return false,
        }
    }
    // Must contain at least one dot (i.e. be qualified).
    s.contains('.')
}

/// T19_K3 — Resolve the desired factory-class internal name
/// (slash-separated form) from the JVM's system properties.
///
/// Returns the JDK-default
/// `java/util/concurrent/ForkJoinPool$DefaultCommonPoolForkJoinWorkerThreadFactory`
/// when the property is unset or fails the allowlist check.
fn resolve_common_factory_internal_name(ctx: &dyn NativeContext) -> String {
    let sf = ctx
        .get_system_property("java.util.concurrent.ForkJoinPool.common.threadFactory")
        .unwrap_or_default();
    if is_safe_factory_class_name(&sf) {
        sf.replace('.', "/")
    } else {
        "java/util/concurrent/ForkJoinPool$DefaultCommonPoolForkJoinWorkerThreadFactory"
            .to_string()
    }
}

/// T19_K3 — Allocate a synthetic
/// `ForkJoinPool$ForkJoinWorkerThreadFactory` instance whose class
/// identity matches the configured common-pool factory name.
///
/// Used by both the synthetic `commonPool()` field-populator and the
/// `getFactory()` registration to ensure
/// `getFactory().getClass().getName()` round-trips to the system
/// property's dot-form.
fn alloc_common_factory(ctx: &mut dyn NativeContext) -> rustjvm_types::ObjectRef {
    let target = resolve_common_factory_internal_name(ctx);
    match ctx.ensure_class_initialized(&target) {
        Ok(cid) => {
            let nfields = ctx.class_num_total_fields(cid).max(1);
            ctx.alloc_object(cid, nfields)
        }
        Err(_) => alloc_concurrent_synthetic(ctx, &target, 1),
    }
}

/// T19_K3 — Populate the `factory` instance field of a real-loaded
/// `ForkJoinPool` synthetic with a non-null factory.  No-op if the
/// loaded class shape lacks that field (legacy synthetic mode).
fn populate_common_factory(
    ctx: &mut dyn NativeContext,
    pool: rustjvm_types::ObjectRef,
) {
    let factory = alloc_common_factory(ctx);
    // Set by name so we work whether the class is the real JDK shape
    // (with `factory` at some non-zero index) or a synthetic placeholder
    // (where the field doesn't exist — set_field_by_name is silent on
    // missing fields).
    ctx.set_field_by_name(pool, "factory", Value::Object(Some(factory)));
}

#[cfg(test)]
mod new15_tests {
    use super::*;

    #[test]
    fn new15_continuation_is_registered() {
        let mut r = NativeMethodRegistry::new();
        register_new15_loom(&mut r);
        assert!(r
            .find(
                "jdk/internal/vm/Continuation",
                "<init>",
                "(Ljdk/internal/vm/ContinuationScope;Ljava/lang/Runnable;)V"
            )
            .is_some());
        assert!(r
            .find("jdk/internal/vm/Continuation", "run", "()V")
            .is_some());
        assert!(r
            .find(
                "jdk/internal/vm/Continuation",
                "yield",
                "(Ljdk/internal/vm/ContinuationScope;)Z"
            )
            .is_some());
        assert!(r
            .find("jdk/internal/vm/Continuation", "isDone", "()Z")
            .is_some());
    }

    #[test]
    fn new15_continuation_scope_is_registered() {
        let mut r = NativeMethodRegistry::new();
        register_new15_loom(&mut r);
        assert!(r
            .find(
                "jdk/internal/vm/ContinuationScope",
                "<init>",
                "(Ljava/lang/String;)V"
            )
            .is_some());
        assert!(r
            .find(
                "jdk/internal/vm/ContinuationScope",
                "getName",
                "()Ljava/lang/String;"
            )
            .is_some());
    }

    #[test]
    fn new15_forkjoinpool_common_is_registered() {
        let mut r = NativeMethodRegistry::new();
        register_new15_loom(&mut r);
        assert!(r
            .find(
                "java/util/concurrent/ForkJoinPool",
                "commonPool",
                "()Ljava/util/concurrent/ForkJoinPool;"
            )
            .is_some());
        assert!(r
            .find(
                "java/util/concurrent/ForkJoinPool",
                "getCommonPoolParallelism",
                "()I"
            )
            .is_some());
    }

    #[test]
    fn t19_k3_forkjoinpool_get_factory_is_registered() {
        let mut r = NativeMethodRegistry::new();
        register_new15_loom(&mut r);
        assert!(r
            .find(
                "java/util/concurrent/ForkJoinPool",
                "getFactory",
                "()Ljava/util/concurrent/ForkJoinPool$ForkJoinWorkerThreadFactory;"
            )
            .is_some());
    }

    #[test]
    fn t19_k3_safe_factory_class_name_accepts_quarkus() {
        // The Quarkus factory name (the property value KC26 sets).
        assert!(is_safe_factory_class_name(
            "io.quarkus.bootstrap.forkjoin.QuarkusForkJoinWorkerThreadFactory"
        ));
        // JDK default factory name with $ inner-class separator.
        assert!(is_safe_factory_class_name(
            "java.util.concurrent.ForkJoinPool$DefaultCommonPoolForkJoinWorkerThreadFactory"
        ));
    }

    #[test]
    fn t19_k3_safe_factory_class_name_rejects_path_traversal() {
        // Slashes (filesystem path) — rejected.
        assert!(!is_safe_factory_class_name("/etc/passwd"));
        // Backslashes (Windows path) — rejected.
        assert!(!is_safe_factory_class_name(r"C:\Windows\System32"));
        // Spaces — rejected.
        assert!(!is_safe_factory_class_name("foo bar.Baz"));
        // Empty — rejected.
        assert!(!is_safe_factory_class_name(""));
        // No dots (unqualified) — rejected.
        assert!(!is_safe_factory_class_name("Foo"));
    }

    #[test]
    fn t19_k3_safe_factory_class_name_rejects_consecutive_dots() {
        assert!(!is_safe_factory_class_name("foo..bar"));
        assert!(!is_safe_factory_class_name(".leading"));
        assert!(!is_safe_factory_class_name("trailing."));
    }

    #[test]
    fn t19_k3_safe_factory_class_name_rejects_oversize() {
        let huge = "a.".repeat(200);
        assert!(huge.len() > 256);
        assert!(!is_safe_factory_class_name(&huge));
    }

    #[test]
    fn t19_k3_safe_factory_class_name_rejects_special_chars() {
        // Non-ASCII letter — rejected.
        assert!(!is_safe_factory_class_name("foo.b\u{00e9}r"));
        // Control char — rejected.
        assert!(!is_safe_factory_class_name("foo.bar\x00"));
        // Semicolon (descriptor terminator) — rejected.
        assert!(!is_safe_factory_class_name("foo.bar;"));
        // Bracket (array marker) — rejected.
        assert!(!is_safe_factory_class_name("[foo.bar"));
    }

    #[test]
    fn new15_continuation_field_layout_constants_distinct() {
        assert_ne!(NEW15_CONT_SCOPE, NEW15_CONT_TARGET);
        assert_ne!(NEW15_CONT_TARGET, NEW15_CONT_STATE);
        assert_ne!(NEW15_CONT_STATE, NEW15_CONT_PIN);
        assert_ne!(NEW15_CONT_PIN, NEW15_CONT_PREEMPT);
        assert!(NEW15_CONT_PREEMPT < NEW15_CONT_FIELDS);
    }

    #[test]
    fn new15_forkjoinpool_field_layout_constants_distinct() {
        assert_ne!(NEW15_FJP_PARALLELISM, NEW15_FJP_ACTIVE);
        assert!(NEW15_FJP_ACTIVE < NEW15_FJP_FIELDS);
    }

    #[test]
    fn new15_continuation_states_are_distinct() {
        assert_ne!(NEW15_CONT_STATE_NEW, NEW15_CONT_STATE_RUNNING);
        assert_ne!(NEW15_CONT_STATE_RUNNING, NEW15_CONT_STATE_YIELDED);
        assert_ne!(NEW15_CONT_STATE_YIELDED, NEW15_CONT_STATE_DONE);
    }
}

