// =============================================================================
// RA.1 regression: CharBuffer allocate/put/flip/get round-trip
//
// Pins the synthetic-CharBuffer field layout used by `register_p62_char_buffer`
// so a later edit that renumbers CB_FIELD_* (position=1, limit=2, capacity=3)
// cannot silently reintroduce the `java.nio.Buffer.checkIndex` AIOOBE that
// blocked KC16 MXParser bootstrap.
// =============================================================================

#[cfg(test)]
mod ra1_char_buffer_roundtrip_tests {
    use super::*;
    use crate::test_utils::mock_ctx;
    use rustjvm_native_api::{NativeContext, NativeMethodRegistry};

    #[test]
    fn char_buffer_capacity10_put5_flip_get5_round_trip() {
        // Wire up just the CharBuffer natives the production code registers.
        let mut reg = NativeMethodRegistry::new();
        register_p62_char_buffer(&mut reg);

        let mut ctx = mock_ctx();

        // allocate(10) — mirrors `CharBuffer.allocate(10)`.
        let allocate = reg
            .find("java/nio/CharBuffer", "allocate", "(I)Ljava/nio/CharBuffer;")
            .expect("CharBuffer.allocate(I) must be registered");
        let buf = match allocate(&mut ctx, &[Value::Int(10)]).expect("allocate ok") {
            Some(Value::Object(Some(b))) => b,
            other => panic!("allocate returned {other:?}"),
        };

        // Freshly-allocated buffer must have capacity=10, limit=10, position=0,
        // mark=-1 — this is the invariant that Buffer.checkIndex relies on.
        assert_eq!(ctx.get_field(buf, CB_FIELD_CAPACITY), Value::Int(10));
        assert_eq!(ctx.get_field(buf, CB_FIELD_LIMIT), Value::Int(10));
        assert_eq!(ctx.get_field(buf, CB_FIELD_POS), Value::Int(0));
        assert_eq!(ctx.get_field(buf, CB_FIELD_MARK), Value::Int(-1));

        // put(C) five times — values 'A'..'E'.
        let put = reg
            .find("java/nio/CharBuffer", "put", "(C)Ljava/nio/CharBuffer;")
            .expect("CharBuffer.put(C) must be registered");
        for ch in b'A'..=b'E' {
            put(&mut ctx, &[Value::Object(Some(buf)), Value::Int(ch as i32)])
                .expect("put ok");
        }
        assert_eq!(ctx.get_field(buf, CB_FIELD_POS), Value::Int(5));

        // flip() — limit := pos, pos := 0.
        let flip = reg
            .find("java/nio/CharBuffer", "flip", "()Ljava/nio/CharBuffer;")
            .expect("CharBuffer.flip() must be registered");
        flip(&mut ctx, &[Value::Object(Some(buf))]).expect("flip ok");
        assert_eq!(ctx.get_field(buf, CB_FIELD_LIMIT), Value::Int(5));
        assert_eq!(ctx.get_field(buf, CB_FIELD_POS), Value::Int(0));

        // get() five times — must return 'A'..'E' in order.
        let get = reg
            .find("java/nio/CharBuffer", "get", "()C")
            .expect("CharBuffer.get() must be registered");
        let mut out = Vec::with_capacity(5);
        for _ in 0..5 {
            match get(&mut ctx, &[Value::Object(Some(buf))]).expect("get ok") {
                Some(Value::Int(v)) => out.push(v as u8),
                other => panic!("get returned {other:?}"),
            }
        }
        assert_eq!(out, b"ABCDE".to_vec());
        // Position advanced to limit; a further get() would underflow.
        assert_eq!(ctx.get_field(buf, CB_FIELD_POS), Value::Int(5));
    }
}

// =============================================================================
// T10: Manifest(InputStream) synthetic constructor tests
//
// Covers the fix for the `JarFile.getManifest()` regression where
// native-io/src/zip_real_jar.rs called Manifest.<init>(InputStream) but
// only Manifest.<init>()V was registered in synthetic-jdk mode. These
// tests pin the parser's handling of CRLF, continuation lines, blank
// separators, and empty streams so the bug cannot silently reappear.
// =============================================================================

#[cfg(test)]
mod t10_manifest_input_stream_tests {
    use super::*;
    use crate::test_utils::mock_ctx;
    use rustjvm_native_api::{NativeContext, NativeMethodRegistry};

    /// Build a synthetic java/io/ByteArrayInputStream holding the given
    /// bytes. Mirrors the 4-field layout (buf=0, pos=1, mark=2, count=3)
    /// that the p59 fast path in `p59_read_input_stream_fully` reads.
    fn make_bais(ctx: &mut crate::test_utils::MockNativeContext, data: &[u8]) -> ObjectRef {
        let arr = ctx.new_array(rustjvm_types::ArrayElementType::Byte, data.len());
        for (i, b) in data.iter().enumerate() {
            ctx.set_array_element(arr, i, Value::Int(*b as i8 as i32));
        }
        let cid = ctx
            .ensure_class_initialized("java/io/ByteArrayInputStream")
            .expect("register BAIS class");
        let bais = ctx.alloc_object(cid, 4);
        ctx.set_field(bais, 0, Value::Object(Some(arr)));
        ctx.set_field(bais, 1, Value::Int(0));
        ctx.set_field(bais, 2, Value::Int(0));
        ctx.set_field(bais, 3, Value::Int(data.len() as i32));
        bais
    }

    /// Drive the Manifest(InputStream) native against a given byte buffer.
    /// Returns the constructed Manifest object.
    fn call_manifest_init(
        reg: &NativeMethodRegistry,
        ctx: &mut crate::test_utils::MockNativeContext,
        bytes: &[u8],
    ) -> ObjectRef {
        let bais = make_bais(ctx, bytes);
        let mf_cid = ctx
            .ensure_class_initialized("java/util/jar/Manifest")
            .expect("register Manifest class");
        let mf = ctx.alloc_object(mf_cid, 2);
        let init = reg
            .find(
                "java/util/jar/Manifest",
                "<init>",
                "(Ljava/io/InputStream;)V",
            )
            .expect("Manifest.<init>(InputStream) must be registered");
        init(
            ctx,
            &[Value::Object(Some(mf)), Value::Object(Some(bais))],
        )
        .expect("Manifest.<init>(InputStream) ok");
        mf
    }

    /// Helper: resolve Attributes.getValue(String) on an Attributes object.
    fn get_value(
        reg: &NativeMethodRegistry,
        ctx: &mut crate::test_utils::MockNativeContext,
        attrs: ObjectRef,
        key: &str,
    ) -> Option<String> {
        let get = reg
            .find(
                "java/util/jar/Attributes",
                "getValue",
                "(Ljava/lang/String;)Ljava/lang/String;",
            )
            .expect("Attributes.getValue must be registered");
        let k = ctx.create_string(key);
        let out = get(ctx, &[Value::Object(Some(attrs)), Value::Object(Some(k))])
            .expect("getValue ok");
        match out {
            Some(Value::Object(Some(s))) => ctx.read_string(s),
            _ => None,
        }
    }

    #[test]
    fn t10_manifest_init_from_input_stream_parses_main_attributes() {
        let mut reg = NativeMethodRegistry::new();
        register_p59_jar(&mut reg);
        let mut ctx = mock_ctx();

        // Manifest with three main attributes (CRLF line endings, as real
        // MANIFEST.MF files use), no per-entry sections.
        let mf_bytes = b"Manifest-Version: 1.0\r\nMain-Class: com.example.Foo\r\nCreated-By: rustjvm\r\n\r\n";
        let mf = call_manifest_init(&reg, &mut ctx, mf_bytes);

        // Drive getMainAttributes() to retrieve the Attributes object.
        let get_main = reg
            .find(
                "java/util/jar/Manifest",
                "getMainAttributes",
                "()Ljava/util/jar/Attributes;",
            )
            .expect("getMainAttributes registered");
        let attrs_val = get_main(&mut ctx, &[Value::Object(Some(mf))])
            .expect("getMainAttributes ok")
            .expect("getMainAttributes returns Some");
        let attrs = match attrs_val {
            Value::Object(Some(a)) => a,
            other => panic!("expected Object, got {other:?}"),
        };

        assert_eq!(
            get_value(&reg, &mut ctx, attrs, "Main-Class"),
            Some("com.example.Foo".to_string()),
            "Main-Class must round-trip through the parser"
        );
        assert_eq!(
            get_value(&reg, &mut ctx, attrs, "Manifest-Version"),
            Some("1.0".to_string())
        );
        assert_eq!(
            get_value(&reg, &mut ctx, attrs, "Created-By"),
            Some("rustjvm".to_string())
        );
        // Case-insensitive key lookup, per manifest spec.
        assert_eq!(
            get_value(&reg, &mut ctx, attrs, "main-class"),
            Some("com.example.Foo".to_string())
        );
        // Unknown key must return null.
        assert_eq!(get_value(&reg, &mut ctx, attrs, "Nonexistent"), None);
    }

    #[test]
    fn t10_manifest_init_from_input_stream_handles_empty_stream() {
        let mut reg = NativeMethodRegistry::new();
        register_p59_jar(&mut reg);
        let mut ctx = mock_ctx();

        // Empty stream — parser must produce a Manifest with empty main
        // attributes and empty entries, not throw.
        let mf = call_manifest_init(&reg, &mut ctx, b"");

        let get_main = reg
            .find(
                "java/util/jar/Manifest",
                "getMainAttributes",
                "()Ljava/util/jar/Attributes;",
            )
            .unwrap();
        let attrs = match get_main(&mut ctx, &[Value::Object(Some(mf))])
            .unwrap()
            .unwrap()
        {
            Value::Object(Some(a)) => a,
            other => panic!("expected Object, got {other:?}"),
        };
        let size = reg
            .find("java/util/jar/Attributes", "size", "()I")
            .unwrap();
        let n = match size(&mut ctx, &[Value::Object(Some(attrs))])
            .unwrap()
            .unwrap()
        {
            Value::Int(v) => v,
            other => panic!("expected Int, got {other:?}"),
        };
        assert_eq!(n, 0, "empty stream must yield zero main attributes");

        let get_entries = reg
            .find("java/util/jar/Manifest", "getEntries", "()Ljava/util/Map;")
            .unwrap();
        let entries = match get_entries(&mut ctx, &[Value::Object(Some(mf))])
            .unwrap()
            .unwrap()
        {
            Value::Object(Some(m)) => m,
            other => panic!("expected Object, got {other:?}"),
        };
        let entries_size = match ctx.get_field(entries, 1) {
            Value::Int(v) => v,
            other => panic!("expected Int size, got {other:?}"),
        };
        assert_eq!(entries_size, 0, "empty stream must yield zero entries");
    }

    #[test]
    fn t10_manifest_init_from_input_stream_handles_entries_and_continuations() {
        let mut reg = NativeMethodRegistry::new();
        register_p59_jar(&mut reg);
        let mut ctx = mock_ctx();

        // Manifest with a continuation line in the main section, plus one
        // per-entry section. Mixed CRLF + LF on purpose.
        let mf_bytes = b"Manifest-Version: 1.0\r\nMain-Class: com.example\r\n .Very.Long.Class.Name\r\n\r\nName: pkg/Foo.class\nSHA-256-Digest: abc123\n\n";
        let mf = call_manifest_init(&reg, &mut ctx, mf_bytes);

        // Main attributes: continuation line must be appended.
        let get_main = reg
            .find(
                "java/util/jar/Manifest",
                "getMainAttributes",
                "()Ljava/util/jar/Attributes;",
            )
            .unwrap();
        let attrs = match get_main(&mut ctx, &[Value::Object(Some(mf))])
            .unwrap()
            .unwrap()
        {
            Value::Object(Some(a)) => a,
            _ => panic!(),
        };
        assert_eq!(
            get_value(&reg, &mut ctx, attrs, "Main-Class"),
            Some("com.example.Very.Long.Class.Name".to_string()),
            "continuation line must be appended to previous value"
        );

        // Entry section must materialise one entry whose Attributes
        // carry SHA-256-Digest = abc123.
        let get_entries = reg
            .find("java/util/jar/Manifest", "getEntries", "()Ljava/util/Map;")
            .unwrap();
        let entries = match get_entries(&mut ctx, &[Value::Object(Some(mf))])
            .unwrap()
            .unwrap()
        {
            Value::Object(Some(m)) => m,
            _ => panic!(),
        };
        // Entries layout: buckets=field0, size=field1. One entry => size=1.
        assert_eq!(ctx.get_field(entries, 1), Value::Int(1));
        let buckets = match ctx.get_field(entries, 0) {
            Value::Object(Some(b)) => b,
            _ => panic!("entries missing buckets"),
        };
        let entry_name = match ctx.get_array_element(buckets, 0) {
            Value::Object(Some(k)) => ctx.read_string(k),
            _ => None,
        };
        assert_eq!(entry_name.as_deref(), Some("pkg/Foo.class"));
        let entry_attrs = match ctx.get_array_element(buckets, 1) {
            Value::Object(Some(a)) => a,
            _ => panic!("entry value must be Attributes"),
        };
        assert_eq!(
            get_value(&reg, &mut ctx, entry_attrs, "SHA-256-Digest"),
            Some("abc123".to_string())
        );
    }

    #[test]
    fn t10_jar_file_get_manifest_roundtrip() {
        use std::io::Write;

        // Build a minimal JAR on disk with a real MANIFEST.MF so the
        // synthetic `p59_jar_file_init` can open it via the zip crate
        // and the `getValue("Main-Class")` lookup now hits the updated
        // Attributes.getValue native (previously a no-op stub that
        // returned null even when the manifest was parsed).
        let tmp_dir = std::env::temp_dir().join("rustjvm_t10_manifest_roundtrip");
        let _ = std::fs::create_dir_all(&tmp_dir);
        let jar_path = tmp_dir.join("t10.jar");
        {
            let file = std::fs::File::create(&jar_path).expect("create jar");
            let mut zw = zip::ZipWriter::new(file);
            let opts = zip::write::FileOptions::default()
                .compression_method(zip::CompressionMethod::Stored);
            zw.start_file("META-INF/MANIFEST.MF", opts).unwrap();
            zw.write_all(b"Manifest-Version: 1.0\r\nMain-Class: com.example.Bar\r\n\r\n")
                .unwrap();
            zw.finish().unwrap();
        }

        let mut reg = NativeMethodRegistry::new();
        register_p59_jar(&mut reg);
        let mut ctx = mock_ctx();

        // Open the JAR via JarFile(String) — the synthetic init reads and
        // parses the manifest from disk using the zip crate.
        let jf_cid = ctx
            .ensure_class_initialized("java/util/jar/JarFile")
            .unwrap();
        let jf = ctx.alloc_object(jf_cid, 2);
        let path_str = ctx.create_string(jar_path.to_string_lossy().as_ref());
        let init = reg
            .find("java/util/jar/JarFile", "<init>", "(Ljava/lang/String;)V")
            .expect("JarFile.<init>(String) registered");
        init(
            &mut ctx,
            &[Value::Object(Some(jf)), Value::Object(Some(path_str))],
        )
        .expect("JarFile.<init> ok");

        // getManifest() — must return a non-null Manifest.
        let get_mf = reg
            .find(
                "java/util/jar/JarFile",
                "getManifest",
                "()Ljava/util/jar/Manifest;",
            )
            .unwrap();
        let mf = match get_mf(&mut ctx, &[Value::Object(Some(jf))])
            .unwrap()
            .unwrap()
        {
            Value::Object(Some(m)) => m,
            other => panic!("getManifest returned {other:?}"),
        };

        // getMainAttributes().getValue("Main-Class") — this is the
        // regression point: before the Attributes.getValue fix this
        // returned null even though p98_read_jar_manifest had parsed
        // the value into the buckets array.
        let get_main = reg
            .find(
                "java/util/jar/Manifest",
                "getMainAttributes",
                "()Ljava/util/jar/Attributes;",
            )
            .unwrap();
        let attrs = match get_main(&mut ctx, &[Value::Object(Some(mf))])
            .unwrap()
            .unwrap()
        {
            Value::Object(Some(a)) => a,
            other => panic!("getMainAttributes returned {other:?}"),
        };
        assert_eq!(
            get_value(&reg, &mut ctx, attrs, "Main-Class"),
            Some("com.example.Bar".to_string()),
            "Main-Class attribute must round-trip from JAR on disk"
        );

        let _ = std::fs::remove_file(&jar_path);
    }
}

// =============================================================================
// Spring Framework ApplicationStartup / StartupStep no-op natives
//
// Spring Boot 2.x / Spring Framework 5.3.x: `AbstractApplicationContext`
// has a field `applicationStartup = ApplicationStartup.DEFAULT`. The DEFAULT
// constant is set by the interface's clinit (`new DefaultApplicationStartup()`).
// When `DefaultApplicationStartup` can't be loaded from nested JARs (because
// the classloader isn't fully wired yet), the interface clinit fails and
// DEFAULT stays null. This causes an NPE at
//   `AnnotationConfigApplicationContext.<init>` line 68:
//   `this.getApplicationStartup().start("spring.context.annotated-bean-reader.create")`
//
// Fix: provide native overrides for `getApplicationStartup()` and the
// `ApplicationStartup.start(String)` / `StartupStep` methods so they
// return cheap synthetic no-op objects instead of requiring the real classes.
// =============================================================================

/// Register no-op natives for Spring's ApplicationStartup / StartupStep.
/// The StartupStep synthetic object uses 1 field (slot 0 = parent StartupStep ref, unused).
pub fn register_spring_application_startup_natives(r: &mut NativeMethodRegistry) {
    let abs_ctx = "org/springframework/context/support/AbstractApplicationContext";
    let app_startup = "org/springframework/core/metrics/ApplicationStartup";
    let startup_step = "org/springframework/core/metrics/StartupStep";
    let default_startup = "org/springframework/core/metrics/DefaultApplicationStartup";
    let default_step = "org/springframework/core/metrics/DefaultApplicationStartup$DefaultStartupStep";

    // AbstractApplicationContext.getApplicationStartup() — always return a
    // synthetic no-op ApplicationStartup so downstream .start(...) never NPEs.
    r.register(
        abs_ctx,
        "getApplicationStartup",
        "()Lorg/springframework/core/metrics/ApplicationStartup;",
        |ctx, _args| {
            let obj = alloc_concurrent_synthetic(ctx, "org/springframework/core/metrics/DefaultApplicationStartup", 1);
            Ok(Some(Value::Object(Some(obj))))
        },
    );

    // ApplicationStartup.start(String) → no-op StartupStep
    for cls in &[app_startup, default_startup] {
        r.register(
            cls,
            "start",
            "(Ljava/lang/String;)Lorg/springframework/core/metrics/StartupStep;",
            |ctx, _args| {
                let step = alloc_concurrent_synthetic(ctx, "org/springframework/core/metrics/DefaultApplicationStartup$DefaultStartupStep", 1);
                Ok(Some(Value::Object(Some(step))))
            },
        );
    }

    // StartupStep.tag(String, String) → return this (chaining)
    for cls in &[startup_step, default_step] {
        r.register(
            cls,
            "tag",
            "(Ljava/lang/String;Ljava/lang/String;)Lorg/springframework/core/metrics/StartupStep;",
            |_ctx, args| Ok(Some(args.first().copied().unwrap_or(Value::Object(None)))),
        );
        // StartupStep.tag(String, Supplier) → return this (chaining)
        r.register(
            cls,
            "tag",
            "(Ljava/lang/String;Ljava/util/function/Supplier;)Lorg/springframework/core/metrics/StartupStep;",
            |_ctx, args| Ok(Some(args.first().copied().unwrap_or(Value::Object(None)))),
        );
        // StartupStep.end() → void
        r.register(cls, "end", "()V", |_ctx, _args| Ok(None));
        // StartupStep.getName() → empty string
        r.register(cls, "getName", "()Ljava/lang/String;", |ctx, _args| {
            Ok(Some(Value::Object(Some(ctx.create_string("")))))
        });
        // StartupStep.getTags() → empty Iterable
        r.register(
            cls,
            "getTags",
            "()Ljava/lang/Iterable;",
            |ctx, _args| {
                let arr = ctx.new_array(rustjvm_types::ArrayElementType::Reference, 0);
                let list = alloc_concurrent_synthetic(ctx, "java/util/ArrayList", 2);
                ctx.set_field(list, 0, Value::Object(Some(arr)));
                ctx.set_field(list, 1, Value::Int(0));
                Ok(Some(Value::Object(Some(list))))
            },
        );
    }
}
